/// The patch document version.
pub const SCHEMA_VERSION: u32 = 1;

/// The provenance tag of every [`RuleFix`] row born of [`from_lints`]:
/// the dartq-lints layer's wired rules (the semantic rows carry
/// [`BUILTIN_SEMANTIC_SOURCE`]; the plugin rows carry the plugin's
/// manifest name instead).
pub const BUILTIN_SOURCE: &str = "builtin-lint";

/// The provenance tag of every [`RuleFix`] row born of [`from_semantic`]:
/// the engine's semantic diagnostics — the mirror of [`BUILTIN_SOURCE`].
pub const BUILTIN_SEMANTIC_SOURCE: &str = "builtin-semantic";

/// The provenance tag of every [`RuleFix`] row born of [`from_parser`]:
/// the engine's syntax diagnostics, served against the official parser
/// fix producers.
pub const BUILTIN_PARSER_SOURCE: &str = "builtin-parser";

/// The provenance tag of the ignore-diagnostic rows (the `// ignore:`
/// comment insertions and the analysis-options entries): text surgery
/// offered for every diagnostic, official `dart fix`'s ignore producers.
pub const BUILTIN_IGNORE_SOURCE: &str = "builtin-ignore";

/// Context characters captured on each side of an edit. the example
/// shows eight before and five after; eight covers a keyword plus its
/// neighbor and the exact budget is ours to pick.
const ANCHOR_CONTEXT: usize = 8;

/// The planner fuse's base operation budget (one walk's fixed work: per-run
/// setup, the engine pass, the per-file parse and options loads).
const PLANNER_FUSE_BASE: u64 = 1 << 20;

/// The planner fuse's per-target operation budget: one file's planner
/// steps are its lint hits + engine diagnostics + the doubled ignore
/// offers + the plugin dispatches + the assist/evidence trials — a
/// diagnostic-dense file plans in the hundreds of steps, and the parser's
/// own 10,000-diagnostic cap bounds the parser-sourced rows, so 16,384 is
/// orders of magnitude above any legitimate file.
const PLANNER_FUSE_PER_FILE: u64 = 1 << 14;

/// The planner walk's monotone operation counter — the fix engine's global
/// termination backstop (zero-hang audit 2026-10-17, top risk 1). Every
/// planner loop family — the per-file walk, the per-hit and
/// per-diagnostic expansions, the ignore offers, the plugin dispatch, the
/// evidence rows, the assist trials — routes one counted [`PlannerFuse::step`]
/// per iteration and stops consuming input on `false`, so a walk whose
/// loops stopped advancing ends bounded with a recorded trip instead of
/// spinning a worker thread forever (the #1687 class: the daemon's fix
/// budget answers the client but does not kill the worker, so the single
/// fix slot would stall for the session's life).
///
/// The budget scales with the input the walk actually consumes —
/// [`PLANNER_FUSE_BASE`] plus [`PLANNER_FUSE_PER_FILE`] per discovered
/// target — so every legitimate run fits with wide headroom while any
/// non-advancing family burns its share without consuming input and trips
/// in bounded time. Arm-internal loops keep their audited
/// advance-or-`?`-abort discipline; this fuse is the reachable global
/// backstop those arms never had.
pub(crate) struct PlannerFuse {
    /// Counted steps so far (interior mutability: one walk's fuse is
    /// shared by `&` across its nested loop families).
    steps: Cell<u64>,
    /// The walk's step budget.
    budget: u64,
    /// Latched once: past the budget every further [`PlannerFuse::step`]
    /// answers `false`.
    tripped: Cell<bool>,
}

impl PlannerFuse {
    /// One walk's budget over `targets` discovered files.
    fn new(targets: usize) -> Self {
        Self {
            steps: Cell::new(0),
            budget: PLANNER_FUSE_BASE.saturating_add(PLANNER_FUSE_PER_FILE * targets as u64),
            tripped: Cell::new(false),
        }
    }

    /// A pin's fuse over an explicit budget (the production walks derive
    /// theirs from the discovered target count).
    #[cfg(test)]
    fn with_budget(budget: u64) -> Self {
        Self {
            steps: Cell::new(0),
            budget,
            tripped: Cell::new(false),
        }
    }

    /// Counts one planner operation; `false` once the budget is spent —
    /// the caller stops consuming input and the walk answers partial.
    fn step(&self) -> bool {
        let steps = self.steps.get() + 1;
        self.steps.set(steps);
        if steps <= self.budget {
            return true;
        }
        self.tripped.set(true);
        false
    }

    /// Whether the budget was spent (latched for the walk's remainder).
    fn tripped(&self) -> bool {
        self.tripped.get()
    }
}

/// The edit's secondary locator: 1-based line/column of the edit start
/// plus the source context flanking it (empty at line boundaries, where
/// the machine document omits the field).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Anchor {
    pub line: u32,
    pub column: u32,
    pub context_before: String,
    pub context_after: String,
}

/// One anchored replacement over the UTF-16 span `[offset, offset +
/// length)`. `source` is the verified original slice — internal drift
/// matching, deliberately not part of the document.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Edit {
    pub offset: u32,
    pub length: u32,
    pub source: String,
    pub replacement: String,
    pub anchor: Anchor,
}

/// One materialized fix: the anchored edit plus the human-facing row.
/// `source` is the row's provenance tag ([`BUILTIN_SOURCE`] or
/// [`BUILTIN_SEMANTIC_SOURCE`] by construction — the plugin source emits
/// [`PluginFix`]es).
#[derive(Debug, Clone)]
pub struct RuleFix {
    pub rule: &'static str,
    pub message: String,
    pub source: &'static str,
    pub edit: Edit,
}

/// One plugin-proposed change: a titled proposal (the analyzer's
/// prioritized-change shape) whose edits anchor against the file's
/// current text and ride the same drift-correction applier as the
/// built-in rows. `plugin` is the provenance tag (the manifest name).
#[derive(Debug, Clone)]
pub struct PluginFix {
    pub plugin: String,
    pub message: String,
    /// Lower sorts first (analyzer convention), the reply's own order on
    /// ties.
    pub priority: i32,
    pub edits: Vec<Edit>,
}

/// One file's fix set: the built-in rows plus the plugin-proposed
/// changes. Files without any row never enter a set.
#[derive(Debug, Clone)]
pub struct FileFixSet {
    pub path: String,
    pub fixes: Vec<RuleFix>,
    pub plugin: Vec<PluginFix>,
}

/// A plugin's terminal failure for this run (spawn refusal, or the first
/// surfaced runtime error — the isolation contract ends the plugin's
/// session). Surfaced in the answer's `errors` list, never silently.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PluginHostError {
    pub plugin: String,
    pub message: String,
}

/// The location-directed assist answer: the plugin source's rows for one
/// file plus the hosts that could not serve the request.
#[derive(Debug, Clone)]
pub struct AssistAnswer {
    pub file: String,
    pub assists: Vec<PluginFix>,
    pub errors: Vec<PluginHostError>,
}

/// Outcome of one edit against the file's current text.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EditOutcome {
    /// Written at the claimed offset or re-located by its anchor.
    Applied,
    /// The anchor is gone or ambiguous — skipped.
    Stale,
}

/// One entry of the governing options file's `plugins:` section: the
/// declared package name plus the source the value pins. Upstream
/// `_parsePluginSource` (analysis_options_parse_model.dart:1639) resolves
/// the entry's source kind in a fixed order — a scalar is a version
/// constraint, a mapping prefers `version`/`hosted`, then `git`, then
/// `path`, first match wins — and only `path` carries a filesystem location
/// dartq resolves itself: a `path:`-valued declaration names the plugin
/// package's directory directly (relative to the options file's parent,
/// normalized — the parity corpora's own layout), while `version`/`hosted`/
/// `git` resolve through pub's `package_config.json` like a bare scalar.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeclaredPlugin {
    /// The package name (the section key).
    pub name: String,
    /// The `path:` source's package directory — absolute already, or
    /// resolved against the options file's parent and lexically normalized
    /// (upstream `pathContext.join` + `normalize`, _parsePluginSource).
    /// `None` for every other source kind — pub resolves those.
    pub path: Option<PathBuf>,
}

/// The `path:` source of one plugin mapping value, when it selects `path`:
/// upstream checks `version`/`hosted`/`git` first — a mapping carrying any
/// of them never reaches the `path` arm (first match wins; the options
/// validator reports the surplus). A `path` scalar resolves against the
/// options file's parent and normalizes (upstream's `_parsePluginSource`
/// `join`/`normalize`); a non-string `path` is no source at all.
fn declared_plugin_path(value: &Yaml, options_dir: &Path) -> Option<PathBuf> {
    let Yaml::Mapping(mapping) = value else {
        return None;
    };
    // The upstream arm order: `version`/`hosted` and `git` shadow `path`
    // (first match wins) — only their absence lets `path` select.
    if mapping.contains_key("version")
        || mapping.contains_key("hosted")
        || mapping.contains_key("git")
    {
        return None;
    }
    let Yaml::String(path) = mapping.get("path")? else {
        return None;
    };
    let path = PathBuf::from(path);
    Some(if path.is_relative() {
        dartq_pub::normalize(&options_dir.join(path))
    } else {
        dartq_pub::normalize(&path)
    })
}

/// The governing root options file of `workspace_root` (the engine's
/// locator) and the plugin packages its top-level `plugins:` section
/// declares, in declaration order — or `None` when the workspace declares
/// nothing: no options file, unreadable, malformed YAML, no `plugins:`
/// section, or a section whose keys name no plugin (only
/// `dependency_overrides` — a hosting face, never a plugin entry — or keys
/// that are not strings). This is the single discovery face of the
/// section — pub-native plugin packages, resolved by pub into
/// `package_config.json` — shared by the fix/assist dispatch here and the
/// daemon's session launch; rule configuration is a separate face read
/// elsewhere: a bare version-constraint entry (`my_plugin: ^1.0.0`)
/// declares a plugin without configuring rules.
///
/// The `None` shape is the absent path of the core-first invariant: it
/// allocates nothing (no path clone, no vec), so a plugin-free
/// workspace's only launch cost is the locator walk plus this one
/// read-and-parse, the minimum needed to establish absence. A broken
/// declaration reports through the engine's options face and never takes
/// the launch down.
pub fn declared_plugins(workspace_root: &Path) -> Option<(PathBuf, Vec<String>)> {
    let (file, declared) = declared_plugin_sources(workspace_root)?;
    Some((file, declared.into_iter().map(|decl| decl.name).collect()))
}

/// [`declared_plugins`] with each declaration's resolved `path:` source —
/// the launch faces' full form: `path`-valued entries resolve against that
/// directory directly (pub never sees them), while every other source
/// stays pub-resolved through `package_config.json`. The name projection
/// ([`declared_plugins`]) is what the pub-native discovery face consumes;
/// the richer face is where the `path:` entries augment the config the
/// discovery resolves through.
pub fn declared_plugin_sources(workspace_root: &Path) -> Option<(PathBuf, Vec<DeclaredPlugin>)> {
    let file = AnalysisOptions::find_for_dir(workspace_root)?;
    let text = std::fs::read_to_string(&file).ok()?;
    let Ok(Yaml::Mapping(root)) = serde_yaml::from_str::<Yaml>(&text) else {
        return None;
    };
    let Some(Yaml::Mapping(plugins)) = root.get("plugins") else {
        return None;
    };
    let options_dir = file.parent().unwrap_or(Path::new(""));
    let declared: Vec<DeclaredPlugin> = plugins
        .iter()
        .filter_map(|(key, value)| {
            let name = key.as_str()?;
            if name.eq_ignore_ascii_case("dependency_overrides") {
                return None;
            }
            Some(DeclaredPlugin {
                name: name.to_owned(),
                path: declared_plugin_path(value, options_dir),
            })
        })
        .collect();
    // A section that names no plugin (only `dependency_overrides`, or keys
    // that are not strings) is the absent shape.
    if declared.is_empty() {
        None
    } else {
        Some((file, declared))
    }
}

/// The `path:`-augmented package config the pub-native discovery resolves
/// through: one synthetic entry per `path:`-declared name absent from the
/// real `package_config.json` (a pub-resolved entry always wins — pub's
/// resolution is the artifact of record), so `discover`'s unchanged
/// pub-native arm resolves the declaration to its directory. The synthetic
/// entry's `root_uri` is the `file:` URI of the (absolute or
/// options-file-anchored) plugin directory; `package_uri` is `lib/` — the
/// derived-manifest convention (`lib/main.dart`) then applies like any
/// pub-native hit. Only called when `path:` declarations exist — the
/// plugin-free workspace never reaches it.
pub fn plugin_package_config(
    pub_config: &PackageConfig,
    declared: &[DeclaredPlugin],
) -> PackageConfig {
    let mut config = pub_config.clone();
    for decl in declared {
        let Some(path) = &decl.path else {
            continue;
        };
        if config.entry(&decl.name).is_some() {
            continue;
        }
        config.packages.push(PackageConfigEntry {
            name: decl.name.clone(),
            root_uri: format!("file://{}", path.display()),
            package_uri: "lib/".to_owned(),
            language_version: None,
            additional_properties: BTreeMap::new(),
        });
    }
    config
}

/// The plugin dispatch face: every plugin discovered under
/// `<workspace_root>/plugins/` with a live runtime, answering
/// `request/fixes` on the fix and assist faces' behalf.
///
/// [`PluginHosts::launch`] spawns eagerly and completes each handshake
/// before returning — the caller pays up to the manifest's
/// `request_ms × (retries + 1)` per plugin (defaults 10 s × 4). Spawn
/// failures log and surface once through [`PluginHosts::take_errors`];
/// they never fail the face. Dropping the set without
/// [`PluginHosts::shutdown`] kills the children without the graceful
/// handshake.
pub struct PluginHosts {
    hosts: Vec<Host>,
}

/// One plugin's dispatch state. `runtime: None` marks the plugin dead for
/// this run: the first surfaced runtime error means the runtime already
/// spent its restart budget reaching it, and further requests would burn
/// the manifest's budget on a plugin that cannot come back.
struct Host {
    name: String,
    runtime: Option<PluginRuntime>,
    error: Option<String>,
}

impl PluginHosts {
    /// Discovers plugins from the explicit sources — the `<root>/plugins/`
    /// convention and the governing `analysis_options`' pub-native `plugins:`
    /// section resolved through `pub_config` (the parsed
    /// `package_config.json` in `config_dir`; no overrides) — and spawns
    /// each hit. The daemon passes its workspace root plus the resolution
    /// its engine runs on, the CLI its process working directory.
    #[must_use]
    pub fn launch(root: &Path, pub_config: &PackageConfig, config_dir: &Path) -> Self {
        let declared = declared_plugin_sources(root);
        // The absent shape: an empty path borrow and an empty slice — the
        // pub-native source contributes nothing and allocates nothing.
        let (options_file, names, decls): (&Path, Vec<String>, &[DeclaredPlugin]) =
            match declared.as_ref() {
                Some((file, decls)) => (
                    file.as_path(),
                    decls.iter().map(|decl| decl.name.clone()).collect(),
                    decls.as_slice(),
                ),
                None => (Path::new(""), Vec::new(), &[]),
            };
        // `path:`-declared names absent from pub's resolution get a
        // synthetic config entry — the unchanged discovery arm then resolves
        // them like any pub-native hit. The clone costs only when `path:`
        // declarations exist (the plugin-free workspace never reaches it).
        let augmented;
        let config = if decls.iter().any(|decl| decl.path.is_some()) {
            augmented = plugin_package_config(pub_config, decls);
            &augmented
        } else {
            pub_config
        };
        let report = discover_plugins(
            root,
            &[],
            &PubNative {
                declared: &names,
                config,
                config_dir,
                options_file,
            },
        );
        for issue in &report.skipped {
            eprintln!(
                "dartq: skipping plugin manifest `{}`: {}",
                issue.path.display(),
                issue.error
            );
        }
        let hosts = report
            .plugins
            .into_iter()
            .map(|plugin| {
                let name = plugin.manifest.name.clone();
                match PluginRuntime::spawn(SpawnSpec::dart(&plugin.dir, plugin.manifest)) {
                    Ok(runtime) => Host {
                        name,
                        runtime: Some(runtime),
                        error: None,
                    },
                    Err(error) => {
                        eprintln!("dartq: plugin `{name}` failed to launch: {error}");
                        Host {
                            name,
                            runtime: None,
                            error: Some(error.to_string()),
                        }
                    }
                }
            })
            .collect();
        Self { hosts }
    }

    /// A host set with no plugins: the no-dispatch posture (tests, and
    /// callers that resolved their plugin posture before reaching here).
    #[must_use]
    pub fn empty() -> Self {
        Self { hosts: Vec::new() }
    }

    /// True when no plugin was discovered — the faces skip their dispatch
    /// entirely.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.hosts.is_empty()
    }

    /// Asks every live host for fixes at the UTF-16 span
    /// `[offset, offset + length)` of `file`, converting each reply to
    /// [`PluginFix`] rows anchored against `text` (see [`from_plugin`]).
    /// Protocol v1 carries the assists work on the same request; a host
    /// whose negotiated capability set lacks `fix` cannot serve it and is
    /// skipped. A host's first surfaced runtime error ends its session
    /// (the isolation contract) and surfaces through
    /// [`PluginHosts::take_errors`].
    pub fn fixes(
        &mut self,
        file: &str,
        offset: u64,
        length: u64,
        text: &str,
        lines: &LineIndex,
    ) -> Vec<PluginFix> {
        let mut rows = Vec::new();
        for host in &mut self.hosts {
            let Some(runtime) = host.runtime.as_mut() else {
                continue;
            };
            if !runtime
                .negotiated()
                .is_some_and(|caps| caps.contains(Capability::Fix))
            {
                continue;
            }
            match runtime.request_fixes(file, offset, length) {
                Ok(reply) => rows.extend(from_plugin(&host.name, &reply, text, lines)),
                Err(error) => {
                    host.runtime = None;
                    host.error = Some(error.to_string());
                }
            }
        }
        rows
    }

    /// Drains the hosts' terminal failures recorded so far (spawn
    /// refusals and first runtime errors), one per plugin.
    pub fn take_errors(&mut self) -> Vec<PluginHostError> {
        self.hosts
            .iter_mut()
            .filter_map(|host| {
                host.error.take().map(|message| PluginHostError {
                    plugin: host.name.clone(),
                    message,
                })
            })
            .collect()
    }

    /// The graceful teardown (`shutdown` per live runtime). Errors log;
    /// teardown quality does not affect the run's outcome.
    pub fn shutdown(self) {
        for host in self.hosts {
            if let Some(runtime) = host.runtime
                && let Err(error) = runtime.shutdown()
            {
                eprintln!("dartq: plugin `{}` shutdown failed: {error}", host.name);
            }
        }
    }
}

/// The fix source stage: validates the targets through discovery, then
/// parses each file once through the lints layer's production entry and
/// runs its governing-options lint set; every hit the mechanical
/// rewrites can materialize (and whose source slice verifies) becomes an
/// anchored edit, and every lint hit is a `request/fixes` location for
/// the plugin hosts (one request per hit per live host — the protocol's
/// only query granularity). One fix set per patched file — files without
/// rows never enter the set. Each file runs under its containing package's
/// language version (`unit_features`).
///
/// The semantic source rides the same stage: one engine check pass over
/// the discovered targets (`semantic_fix_diagnostics`, assembled with
/// `sdk` — the CLI passes none and falls back to the `DART_SDK`
/// environment, the daemon passes its session's resolved root) contributes
/// the drop-family rows, merged into each file's set. A pass that cannot
/// run degrades to no rows and the run answers from the other sources.
///
/// The lint set is per-subtree, the analyze face's resolution
/// ([`crate::lints::analyze_lints`]): each file runs under the options
/// entry its own ancestry governs ([`AnalysisOptions::find_for_dir`]),
/// loaded once per distinct options file and keyed once per distinct
/// directory. No options file in the ancestry is the official
/// options-less posture — the empty set, and the file skips the lint run
/// (the opt-in cost ruling) unless the semantic pass holds rows for it.
/// The governing options' `cannot-ignore` set feeds [`run`]'s unignorable
/// gate, the analyze face's resolution — a code listed there survives
/// every ignore comment exactly as it does in the engine pass.
///
/// # Errors
///
/// [`DiscoverError`] from target discovery.
pub fn collect_set(
    paths: &[PathBuf],
    hosts: &mut PluginHosts,
    sdk: Option<&Path>,
) -> Result<Vec<FileFixSet>, DiscoverError> {
    collect_set_with_evidence(paths, hosts, sdk).map(|(sets, _)| sets)
}

/// [`collect_set`] with the declaration-synthesis evidence face: the same
/// single engine pass also answers the per-file evidence rows the
/// create-family producers compose their edits from (see [`FileEvidence`]
/// — and [`crate::fix_table::synthesis_arm`] for the code set). The
/// patch-document consumers keep [`collect_set`]; the producer wave and
/// the evidence document face take the richer answer.
///
/// # Errors
///
/// [`DiscoverError`] from target discovery.
pub fn collect_set_with_evidence(
    paths: &[PathBuf],
    hosts: &mut PluginHosts,
    sdk: Option<&Path>,
) -> Result<(Vec<FileFixSet>, Vec<FileEvidence>), DiscoverError> {
    let files = discover::discover(paths)?;
    // The walk's global progress fuse (#1687-class backstop): every
    // planner loop family below routes through its counted step.
    let fuse = PlannerFuse::new(files.len());
    // One workspace assembly per run, seeded from the first discovered
    // file, best-effort: a target set with no pub context around it — the
    // face's historical shape — stays at the default-version posture
    // instead of failing. Neither degrade leg is silent: the assembly's
    // advisory (stale/missing/corrupt config) prints its one-line message
    // on stderr like the analyze face's INFO row, and an assembly that
    // cannot run at all logs at the same "unavailable" tier as the
    // semantic pass below — the rows' semantic source degrades either
    // way, never silently.
    let assembly = files
        .iter()
        .next()
        .and_then(|first| first.parent())
        .and_then(|dir| match crate::workspace::package_assembly(dir) {
            Ok(assembly) => Some(assembly),
            Err(error) => {
                eprintln!("dartq: fix workspace assembly unavailable: {error}");
                None
            }
        });
    // The options-include faces: the assembly's package resolution when it
    // succeeded; a failed assembly degrades to the empty resolution — a
    // `package:` include then contributes nothing (the official
    // unresolvable-include posture) while the options file's own rules
    // still load.
    let (table, packages, config_dir, advisory) = match assembly {
        Some((table, packages, config_dir, _, advisory)) => {
            (Some(table), packages, config_dir, advisory)
        }
        None => (
            None,
            Arc::new(PackageConfig {
                packages: Vec::new(),
                generator: None,
                generator_version: None,
                additional_properties: BTreeMap::new(),
            }),
            PathBuf::new(),
            None,
        ),
    };
    if let Some(advisory) = advisory {
        eprintln!("dartq: {}: {}", advisory.code().name, advisory.message());
    }
    // The semantic source's engine check pass, before the per-file loop;
    // the synthesis evidence face rides the same pass.
    let (semantic, evidence) = semantic_fix_diagnostics(&files, sdk, &fuse);
    // The ignore-diagnostic face's dedup sets (one line row per line and
    // code, one file row per code) and the per-options-file codes the
    // third producer groups into its own file sets after the walk.
    let mut offered_line: FxHashSet<(u32, &'static str)> = FxHashSet::default();
    let mut offered_file: FxHashSet<&'static str> = FxHashSet::default();
    let mut options_codes: FxHashMap<PathBuf, Vec<&'static str>> = FxHashMap::default();
    // The per-directory enable sets and cannot-ignore sets (governance is
    // by ancestry, so one directory always maps to one entry) and the
    // per-file loaded options (shared through the map, workspace members
    // under one repo-root options file parse it once) — the analyze face's
    // serial precompute, hoisted into the walk's cold path.
    let mut governed: FxHashMap<
        PathBuf,
        (EnableSet, rustc_hash::FxHashSet<String>, Option<PathBuf>),
    > = FxHashMap::default();
    let mut loaded: FxHashMap<PathBuf, Arc<AnalysisOptions>> = FxHashMap::default();
    let mut out = Vec::new();
    'files: for path in &files {
        if !fuse.step() {
            break 'files;
        }
        let Some(dir) = path.parent() else {
            continue;
        };
        let (set, unignorable, options_file) =
            governed.entry(dir.to_path_buf()).or_insert_with(|| {
                let options = AnalysisOptions::find_for_dir(dir).map(|file| {
                    let path = file.clone();
                    let options = loaded
                        .entry(file)
                        .or_insert_with(|| {
                            Arc::new(AnalysisOptions::load(&path, &packages, &config_dir))
                        })
                        .clone();
                    (path, options)
                });
                let (path, options) = match options {
                    Some((path, options)) => (Some(path), Some(options)),
                    None => (None, None),
                };
                let rules = options.as_ref().map(|options| options.lint_rules.clone());
                (
                    crate::lints::enable_set(rules.as_deref()),
                    options
                        .map(|options| options.unignorable().clone())
                        .unwrap_or_default(),
                    path,
                )
            });
        // map_or(&[], Vec::as_slice) breaks inference (E0271); the explicit
        // unwrap_or form is the compiling spelling.
        #[expect(clippy::map_unwrap_or)]
        let semantic_rows = semantic.get(path).map(Vec::as_slice).unwrap_or(&[]);
        if *set == EnableSet::none() && semantic_rows.is_empty() {
            continue;
        }
        // Span-capacity gates (#1543 bypass face): the parse builds its
        // `LineIndex` outside the engine's intake gates, so the stat
        // refuses before the read and the byte length is authoritative.
        // Either rejection skips the file with the analyze face's
        // rejection notice — the fix set loses the file, the run
        // continues over its siblings.
        if stat_capacity_error(path).is_some() {
            eprintln!("{}", rejection_notice(path));
            continue;
        }
        let Ok(text) = std::fs::read_to_string(path) else {
            // Unreadable or non-UTF-8 target: nothing to patch — the apply
            // face re-reads and reports on its own terms.
            continue;
        };
        if text.len() > MAX_SOURCE_BYTES {
            eprintln!("{}", rejection_notice(path));
            continue;
        }
        let parsed = parse_unit(&text, unit_features(table.as_ref(), path));
        let hits: Vec<Lint> = if *set == EnableSet::none() {
            Vec::new()
        } else {
            run(&parsed.unit(Some(path)), set, unignorable)
        };
        let mut applied = from_lints(&hits, &text, &parsed.lines, &fuse);
        if fuse.tripped() {
            break 'files;
        }
        applied.extend(from_semantic(semantic_rows, &text, &parsed.lines, &fuse));
        applied.extend(from_parser(semantic_rows, &text, &parsed.lines, &fuse));
        if fuse.tripped() {
            break 'files;
        }
        // The ignore-diagnostic face: every diagnostic gets the line and
        // file offers (deduped; a `cannot-ignore` code gets none), and
        // its code groups into the governing options file's set.
        let mut offers: Vec<(&'static str, core::ops::Range<u32>)> = hits
            .iter()
            .map(|hit| (RULES[hit.rule.0 as usize].name, hit.range.clone()))
            .collect();
        offers.extend(
            semantic_rows
                .iter()
                .map(|d| (d.code.name, d.range.offset..d.range.offset + d.range.length)),
        );
        for (code, range) in offers {
            if !fuse.step() {
                break 'files;
            }
            if unignorable.contains(code) {
                continue;
            }
            let (line, _) = parsed.lines.line_col_utf16(&text, range.start);
            if offered_line.insert((line, code))
                && let Some(fix) = ignore_line_fix(code, range, &text, &parsed.lines)
            {
                applied.push(fix);
            }
            if offered_file.insert(code)
                && let Some(fix) = ignore_file_fix(code, &text, &parsed.lines)
            {
                applied.push(fix);
            }
            if let Some(file) = options_file.as_ref() {
                let codes = options_codes.entry(file.clone()).or_default();
                if !codes.contains(&code) {
                    codes.push(code);
                }
            }
        }
        let plugin = dispatch_fixes(hosts, path, &text, &parsed.lines, &hits, &fuse);
        if fuse.tripped() {
            break 'files;
        }
        if !applied.is_empty() || !plugin.is_empty() {
            out.push(FileFixSet {
                path: path.display().to_string(),
                fixes: applied,
                plugin,
            });
        }
    }
    // The analysis-options sets: one per governing options file, the
    // codes in a deterministic order, each row's edit anchored against
    // the options file's own text.
    let mut options: Vec<(PathBuf, Vec<&'static str>)> = options_codes.into_iter().collect();
    options.sort_unstable();
    'options: for (file, mut codes) in options {
        codes.sort_unstable();
        if !fuse.step() {
            break 'options;
        }
        let Ok(options_text) = std::fs::read_to_string(&file) else {
            continue;
        };
        if options_text.len() > MAX_SOURCE_BYTES {
            continue;
        }
        let lines = LineIndex::new(&options_text);
        let fixes: Vec<RuleFix> = codes
            .into_iter()
            .filter_map(|code| {
                if !fuse.step() {
                    return None;
                }
                let (offset, length, replacement) = ignore_options_edit(code, &options_text)?;
                Some(RuleFix {
                    rule: code,
                    message: format!("Ignore '{code}' in `analysis_options.yaml`"),
                    source: BUILTIN_IGNORE_SOURCE,
                    edit: anchored_edit(&options_text, &lines, offset, length, &replacement),
                })
            })
            .collect();
        if !fixes.is_empty() {
            out.push(FileFixSet {
                path: file.display().to_string(),
                fixes,
                plugin: Vec::new(),
            });
        }
    }
    if fuse.tripped() {
        // The bounded structured trip record (never a panic): the run
        // answers its partial fix sets, the note names the spent budget —
        // a planner loop family stopped advancing and the walk cut it.
        eprintln!(
            "dartq: fix planner fuse tripped after {} operations; the run answers its partial fix sets",
            fuse.budget
        );
    }
    Ok((out, evidence))
}

/// The engine sources' check pass: one throwaway engine over the
/// discovered targets (`sdk` assembles it; `None` falls back to the
/// `DART_SDK` environment), one discover + analyze run — no lint stage,
/// [`collect_set`] runs the lint face itself — and the semantic drop-family
/// and parser-face diagnostics grouped under the discovery spelling of
/// each target file. Files the engine's context never interned (targets
/// outside the assembled workspace) carry no rows.
///
/// The declaration-synthesis evidence face rides the same pass: the target
/// files whose rows carry a synthesis-arm code also answer
/// [`FileEvidence`] rows (built while the engine — the capture rows and
/// the per-file Analysis seam — is still alive; the rest of the targets
/// never pay the build). The answer's evidence vec is path-sorted, the
/// machine face's deterministic order.
///
/// Best-effort by contract: an assembly or analysis failure prints one
/// stderr note and yields an empty map — the fix run answers from the
/// other sources, never fails on the engine faces' account.
fn semantic_fix_diagnostics(
    files: &std::collections::BTreeSet<PathBuf>,
    sdk: Option<&Path>,
    fuse: &PlannerFuse,
) -> (FxHashMap<PathBuf, Vec<Diagnostic>>, Vec<FileEvidence>) {
    let mut rows = FxHashMap::default();
    // The synthesis arm's codes are by definition outside the mechanical
    // table (the table never claims them), so they group separately — the
    // evidence face's input.
    let mut synthesis_rows: FxHashMap<PathBuf, Vec<Diagnostic>> = FxHashMap::default();
    let mut evidence = Vec::new();
    let Some(seed) = files.iter().next().and_then(|first| first.parent()) else {
        return (rows, evidence);
    };
    // The advisory-taking opener, not [`crate::workspace::open_engine`]:
    // the query-family opener disarms the semantic diagnoser (`semdiag:
    // None`), and this pass exists to carry the semantic families — the
    // #236 analyze contract the diagnoser fills. The advisory (stale or
    // missing config) is the assembly's stderr note below, not a row.
    let Ok((mut engine, _, _)) = crate::workspace::open_engine_with_advisory(seed, sdk) else {
        eprintln!("dartq: semantic fix pass unavailable: no usable workspace or SDK");
        return (rows, evidence);
    };
    let run = match crate::analyze::run_overlaid(&mut engine, &[], &[]) {
        Ok(run) => run,
        Err(error) => {
            eprintln!("dartq: semantic fix pass unavailable: {error}");
            return (rows, evidence);
        }
    };
    // The owned diagnostics out of the run — its layout borrows the
    // engine, and the target resolution below reads the engine again.
    let crate::analyze::AnalyzeRun { diagnostics, .. } = run;
    // Discovery spelling per interned target: the rows key the same
    // spellings the per-file loop walks.
    let mut targets: FxHashMap<dartq_source::FileId, PathBuf> = FxHashMap::default();
    for path in files {
        if let Some(file) = engine.file_table().try_file_id(path)
            && !targets.contains_key(&file)
        {
            targets.insert(file, path.clone());
        }
    }
    if targets.is_empty() {
        return (rows, evidence);
    }
    'grouping: for diagnostic in diagnostics {
        if !fuse.step() {
            break 'grouping;
        }
        let Some(path) = targets.get(&diagnostic.file) else {
            continue;
        };
        if crate::fix_table::is_engine_fix_code(diagnostic.code.name) {
            rows.entry(path.clone())
                .or_insert_with(Vec::new)
                .push(diagnostic.clone());
        }
        if crate::fix_table::synthesis_arm(diagnostic.code.name).is_some() {
            synthesis_rows
                .entry(path.clone())
                .or_insert_with(Vec::new)
                .push(diagnostic);
        }
    }
    'evidence: for (file, path) in &targets {
        if !fuse.step() {
            break 'evidence;
        }
        let Some(file_rows) = synthesis_rows.get(path) else {
            continue;
        };
        let built = synthesis_evidence(&engine, path, *file, file_rows, fuse);
        if !built.is_empty() {
            evidence.push(FileEvidence {
                path: path.display().to_string(),
                rows: built,
            });
        }
    }
    evidence.sort_unstable_by(|a, b| a.path.cmp(&b.path));
    (rows, evidence)
}

// ---------------------------------------------------------------------------
// Declaration-synthesis evidence face (the D2 evidence rows)
// ---------------------------------------------------------------------------

/// The miss shape one synthesis evidence row carries: the name row the
/// diagnoser recorded at the diagnostic's offset, carried verbatim (the
/// spelling, the reference shape, the qualified flag) — never re-derived
/// from the text or the message at fix time.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EvidenceName {
    /// The miss's spelling.
    pub name: String,
    /// The recorded reference shape.
    pub use_kind: dartq_semantic::NameUse,
    /// Whether the reference was member- or prefix-qualified — the
    /// static-vs-instance posture a callable producer keys on.
    pub qualified: bool,
}

/// One declaration-synthesis evidence row: the facts a create-family
/// producer composes its edit from, keyed to the diagnostic that decided
/// the face. The diagnostic's code and span are the **decision of record**
/// — the diagnoser's `take_context_miss` routing already chose which code
/// a miss reports (the type-argument, creation, catch, and clause faces
/// replace the `undefined_class` fallthrough), and this face never
/// re-derives that choice: a re-routed code rides its own arm exactly as
/// emitted. The position facts come from the capture's positional columns
/// (#1635), the shape columns resolve through the container row and the
/// per-file Analysis at producer time (#1637's substrate; not re-encoded
/// here).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FixEvidence {
    /// The decision-of-record code name (`undefined_class`,
    /// `non_type_as_type_argument`, ...).
    pub code: &'static str,
    /// The diagnostic's UTF-16 span, verbatim.
    pub range: core::ops::Range<u32>,
    /// The miss's taken name row. `None` for the container-keyed arms
    /// (override and constructor/field synthesis read no miss name).
    pub name: Option<EvidenceName>,
    /// The synthesis insertion point, byte offset: the enclosing
    /// container's `body_open` (member synthesis) or the enclosing
    /// compilation-unit member's `decl_end` (top-level synthesis — the
    /// upstream `enclosingMember.end` convention). [`DeclRow::UNKNOWN`]
    /// where the capture supplies no honest position — the producer drops
    /// the synthesis rather than insert at a fabricated offset.
    pub insertion: u32,
    /// The enclosing container's row index in the file's capture
    /// ([`DeclRow::NONE`] for a top-level synthesis target); the shape
    /// columns resolve through it and the per-file Analysis at producer
    /// time.
    pub container: u32,
}

/// One file's evidence set: the synthesis rows keyed by the engine pass's
/// diagnostics. Files without rows never enter a set — the mirror of
/// [`FileFixSet`].
#[derive(Debug, Clone)]
pub struct FileEvidence {
    /// The file's discovery spelling (the fix set's key convention).
    pub path: String,
    /// The rows in their total key order: offset, code, span length, then
    /// the insertion facts (the determinism audit's R3 total-order ruling).
    pub rows: Vec<FixEvidence>,
}

/// Builds one file's synthesis evidence rows over the engine pass's
/// diagnostics for that file. The position facts read the engine's
/// capture; the miss names take the per-file Analysis seam's recorded
/// rows (the resolved assist face's isolated-context posture — the
/// owning library's member files under-report, the established M1
/// stance). Any file the pass cannot serve (no capture, unreadable text)
/// answers no rows — the face's under-report posture, never a fabricated
/// target.
fn synthesis_evidence(
    engine: &dartq_engine::Engine,
    path: &Path,
    file: FileId,
    diagnostics: &[Diagnostic],
    fuse: &PlannerFuse,
) -> Vec<FixEvidence> {
    if !diagnostics
        .iter()
        .any(|d| crate::fix_table::synthesis_arm(d.code.name).is_some())
    {
        return Vec::new();
    }
    let Some(capture) = engine.file_capture(file) else {
        return Vec::new();
    };
    let Ok(text) = std::fs::read_to_string(path) else {
        return Vec::new();
    };
    let members = [file];
    let context = crate::lints::build_semantic_context(engine, &text, file, &members);
    let analysis = dartq_semantic::analyze_unit(
        &text,
        &context.scanned.tokens,
        crate::lints::SEMANTIC_PARSE_FEATURES,
        engine.strings(),
        file,
        context.lib,
        &context.graph,
        &context.namespaces,
        &context.index,
        dartq_semantic::StrictModes::default(),
        &dartq_resolution::LibraryClassModifiers::default(),
    );
    let mut names: Vec<dartq_semantic::NameRow> = analysis.names().to_vec();
    evidence_rows(
        &text,
        capture,
        &mut names,
        analysis.strings(),
        diagnostics,
        fuse,
    )
}

/// The evidence face's pure core: the rows over one file's text, capture,
/// and recorded miss rows. The arm dispatch keys on the diagnostic's code
/// (the decision of record); the miss rows take-once per offset. Each
/// row's build routes through the planner fuse's counted step.
fn evidence_rows(
    text: &str,
    capture: &FileCapture,
    names: &mut Vec<dartq_semantic::NameRow>,
    strings: &dartq_source::StringTable,
    diagnostics: &[Diagnostic],
    fuse: &PlannerFuse,
) -> Vec<FixEvidence> {
    let mut rows: Vec<FixEvidence> = diagnostics
        .iter()
        .filter_map(|d| {
            if !fuse.step() {
                return None;
            }
            let arm = crate::fix_table::synthesis_arm(d.code.name)?;
            let name = match arm {
                crate::fix_table::SynthesisArm::TypeName
                | crate::fix_table::SynthesisArm::Callable => take_name_row(names, d.range.offset)
                    .map(|row| EvidenceName {
                        name: strings.resolve(row.name).to_owned(),
                        use_kind: row.use_kind,
                        qualified: row.qualified,
                    }),
                crate::fix_table::SynthesisArm::Override
                | crate::fix_table::SynthesisArm::Container => None,
            };

            // A miss-keyed row without its recorded name is an incomplete
            // synthesis target — dropped, never fabricated around (the
            // under-report posture: no edit beats a wrong edit).
            if name.is_none()
                && matches!(
                    arm,
                    crate::fix_table::SynthesisArm::TypeName
                        | crate::fix_table::SynthesisArm::Callable
                )
            {
                return None;
            }
            let (insertion, container) = insertion_point(&text, &capture, d.range.offset, arm);
            Some(FixEvidence {
                code: d.code.name,
                range: d.range.offset..d.range.offset + d.range.length,
                name,
                insertion,
                container,
            })
        })
        .collect();
    // The total order (determinism audit R3): source position, then the
    // decision-of-record code, then the span length, then the remaining
    // position facts — two rows tying on (start, code) (two diagnostics
    // over one span) keep a key-imposed order instead of the unstable
    // sort's internal one. A `message` leg has no counterpart here: the
    // evidence row carries the code and span as its decision of record,
    // and the insertion/container legs totalize what spans cannot.
    rows.sort_unstable_by(|a, b| {
        a.range
            .start
            .cmp(&b.range.start)
            .then_with(|| a.code.cmp(b.code))
            .then_with(|| a.range.end.cmp(&b.range.end))
            .then_with(|| a.insertion.cmp(&b.insertion))
            .then_with(|| a.container.cmp(&b.container))
            .then_with(|| name_order(&a.name, &b.name))
    });
    rows
}

/// The evidence rows' final tiebreak over the taken miss names: `None`
/// (the container-keyed arms) sorts first, two names order by spelling,
/// then shape, then qualification — the comparator's last leg, reachable
/// only for rows identical on code, span, and insertion facts.
fn name_order(a: &Option<EvidenceName>, b: &Option<EvidenceName>) -> core::cmp::Ordering {
    match (a, b) {
        (None, None) => core::cmp::Ordering::Equal,
        (None, Some(_)) => core::cmp::Ordering::Less,
        (Some(_), None) => core::cmp::Ordering::Greater,
        (Some(a), Some(b)) => a
            .name
            .cmp(&b.name)
            .then_with(|| use_rank(a.use_kind).cmp(&use_rank(b.use_kind)))
            .then_with(|| a.qualified.cmp(&b.qualified)),
    }
}

/// The recorded reference shape's stable rank (the [`use_label`] order).
fn use_rank(use_kind: dartq_semantic::NameUse) -> u8 {
    match use_kind {
        dartq_semantic::NameUse::Read => 0,
        dartq_semantic::NameUse::Write => 1,
        dartq_semantic::NameUse::Invoke => 2,
        dartq_semantic::NameUse::Type => 3,
        dartq_semantic::NameUse::Annotation => 4,
        dartq_semantic::NameUse::NamedArgument => 5,
    }
}

/// Consumes the name row recorded at `offset` — the fix-side mirror of the
/// diagnoser's `take_context_miss`: the rows ascend with source order, a
/// binary hit removes exactly the matching reference, and a taken row can
/// never feed a second decision at the same offset (exactly one consumer
/// per recorded miss — the drift guard).
fn take_name_row(
    rows: &mut Vec<dartq_semantic::NameRow>,
    offset: u32,
) -> Option<dartq_semantic::NameRow> {
    let index = rows.partition_point(|row| row.range.offset < offset);
    let hit = *rows.get(index).filter(|row| row.range.offset == offset)?;
    rows.remove(index);
    Some(hit)
}

/// The synthesis insertion point for a diagnostic at UTF-16 `offset16`,
/// per the arm's producer shape: a callable miss inside a container body
/// inserts at that container's `body_open` (the container's row index
/// carried); every other insertion targets the tightest enclosing
/// compilation-unit member — its `decl_end` for a top-level synthesis
/// (type-name and library-callable arms, [`DeclRow::NONE`] carried) or its
/// `body_open` when the diagnostic anchors on that member itself (the
/// override and constructor arms synthesize into their own container, and
/// answer the unknown when no container covers them). No covering row — a
/// directive position, or a declaration the parse never closed — answers
/// the honest unknown.
fn insertion_point(
    text: &str,
    capture: &FileCapture,
    offset16: u32,
    arm: crate::fix_table::SynthesisArm,
) -> (u32, u32) {
    let at = utf16_offset_to_byte(text, offset16);
    let decls = capture.index.decls();
    let covers = |row: &DeclRow| {
        row.decl_end != DeclRow::UNKNOWN
            && utf16_offset_to_byte(text, row.range.offset) <= at
            && at < row.decl_end as usize
    };
    // The arm's container: for a callable miss, the one container body
    // holding the offset (container extents do not nest); for the
    // override and constructor arms, the diagnostic's own container — the
    // tightest covering unit member.
    let container = match arm {
        crate::fix_table::SynthesisArm::Callable => decls
            .iter()
            .enumerate()
            .find(|(_, row)| row.body_open != DeclRow::UNKNOWN && covers(row)),
        crate::fix_table::SynthesisArm::Override | crate::fix_table::SynthesisArm::Container => {
            decls
                .iter()
                .enumerate()
                .filter(|(_, row)| row.is_library_face() && covers(row))
                .max_by_key(|(_, row)| row.range.offset)
        }
        crate::fix_table::SynthesisArm::TypeName => None,
    };
    if let Some((index, row)) = container {
        if row.body_open != DeclRow::UNKNOWN {
            return (row.body_open, index as u32);
        }
        // The member-synthesis container exists but carries no honest body
        // position — keep its row identity, withhold the offset.
        return (DeclRow::UNKNOWN, index as u32);
    }
    // Without the arm's container: the callable arm falls through to the
    // top-level synthesis (a library callable beside the enclosing unit
    // member); the override and constructor arms have no honest target at
    // all — their producers synthesize into a container only.
    if matches!(
        arm,
        crate::fix_table::SynthesisArm::Override | crate::fix_table::SynthesisArm::Container
    ) {
        return (DeclRow::UNKNOWN, DeclRow::NONE);
    }
    // Top-level synthesis: the tightest covering unit member's end.
    let unit = decls
        .iter()
        .filter(|row| row.is_library_face() && covers(row))
        .max_by_key(|row| row.range.offset);
    match unit {
        Some(row) => (row.decl_end, DeclRow::NONE),
        None => (DeclRow::UNKNOWN, DeclRow::NONE),
    }
}

/// The machine document for one file's evidence rows — `file`,
/// `schema_version`, and the `evidence` rows in their emission order: the
/// decision-of-record code and span, the taken miss name (`name` omitted
/// for the container-keyed arms), and the byte insertion point (omitted
/// where the capture supplies no honest position — a consumer never sees
/// a fabricated offset). The container's row index stays on the struct:
/// it dereferences only against the capture, which the document does not
/// carry. Deterministic bytes: the serializer's map keys sort, the rows
/// arrive offset-ordered.
#[must_use]
pub fn evidence_json(file: &FileEvidence) -> serde_json::Value {
    let rows: Vec<serde_json::Value> = file
        .rows
        .iter()
        .map(|row| {
            let mut json = serde_json::json!({
                "code": row.code,
                "offset": row.range.start,
                "length": row.range.end - row.range.start,
            });
            let object = json.as_object_mut().expect("evidence row object");
            if let Some(name) = &row.name {
                object.insert(
                    "name".into(),
                    serde_json::json!({
                        "spelling": name.name,
                        "use": use_label(name.use_kind),
                        "qualified": name.qualified,
                    }),
                );
            }
            if row.insertion != DeclRow::UNKNOWN {
                object.insert("insertion".into(), row.insertion.into());
            }
            json
        })
        .collect();
    serde_json::json!({
        "file": file.path,
        "schema_version": SCHEMA_VERSION,
        "evidence": rows,
    })
}

/// The JSON label of a recorded reference shape.
fn use_label(use_kind: dartq_semantic::NameUse) -> &'static str {
    match use_kind {
        dartq_semantic::NameUse::Read => "read",
        dartq_semantic::NameUse::Write => "write",
        dartq_semantic::NameUse::Invoke => "invoke",
        dartq_semantic::NameUse::Type => "type",
        dartq_semantic::NameUse::Annotation => "annotation",
        dartq_semantic::NameUse::NamedArgument => "named_argument",
    }
}

/// The file's unit features: its containing package's language version
/// through the package table's attribution walk (the engine's
/// `language_version_for` chain), the default
/// version where no table or no package attributes the file. `table` is
/// `None` when the run's workspace assembly failed — every file then runs
/// at the default posture, the face's pre-wiring behavior. This is the
/// package-version fallback the lint face also uses for unsettled files
/// (#722): `collect_set` discovers and parses engine-free, so the
/// engine's settled `@dart`/grant face cannot reach here — a `@dart`-pinned
/// file parses at its package posture, not its pinned one.
fn unit_features(table: Option<&PackageTable>, path: &Path) -> Features {
    // The query joins the table's spelling universe before the walk: the
    // attribution is purely lexical over the table's canonicalized roots
    // (the build's one normalize rule), while this face's paths come raw
    // off discovery — a user-spelled alias (`/var` vs `/private/var`, a
    // symlinked root) would strand at the walk's bound, attribute to no
    // package, and silently run the file at the default posture.
    let version = table
        .and_then(|table| table.containing(&normalize_path(path)))
        .and_then(|identity| identity.language_version)
        .map_or(
            DEFAULT_LANGUAGE_VERSION,
            dartq_pub::LanguageVersion::into_inner,
        );
    features_for(version)
}

/// One `request/fixes` per lint hit against the hosts. The request names
/// the file the way the plugin knows it — the absolute path, since the
/// engine's own diagnostic feed uses the file table's absolute paths.
fn dispatch_fixes(
    hosts: &mut PluginHosts,
    path: &Path,
    text: &str,
    lines: &LineIndex,
    hits: &[Lint],
    fuse: &PlannerFuse,
) -> Vec<PluginFix> {
    if hosts.is_empty() {
        return Vec::new();
    }
    let file = host_path(path);
    let mut rows = Vec::new();
    for hit in hits {
        if !fuse.step() {
            break;
        }
        rows.extend(hosts.fixes(
            &file,
            u64::from(hit.range.start),
            u64::from(hit.range.end - hit.range.start),
            text,
            lines,
        ));
    }
    rows
}

/// The path string a plugin request carries: absolute when the discovery
/// yielded a relative argument (the CLI resolves against the process cwd,
/// the daemon's faces already resolve against the workspace root).
fn host_path(path: &Path) -> String {
    if path.is_absolute() {
        return path.display().to_string();
    }
    let joined = std::env::current_dir().map_or_else(|_| path.to_path_buf(), |cwd| cwd.join(path));
    joined.display().to_string()
}

// ---------------------------------------------------------------------------
// Anchoring substrate
// ---------------------------------------------------------------------------

/// Anchors an edit over the UTF-16 span `[offset16, offset16 + length16)`.
#[must_use]
pub fn anchored_edit(
    text: &str,
    lines: &LineIndex,
    offset16: u32,
    length16: u32,
    replacement: &str,
) -> Edit {
    let (line, column) = lines.line_col_utf16(text, offset16);
    let start = utf16_offset_to_byte(text, offset16);
    let end = utf16_offset_to_byte(text, offset16 + length16);
    Edit {
        offset: offset16,
        length: length16,
        source: text[start..end].to_owned(),
        replacement: replacement.to_owned(),
        anchor: Anchor {
            line,
            column,
            context_before: line_context_before(text, start),
            context_after: line_context_after(text, end),
        },
    }
}

/// Up to [`ANCHOR_CONTEXT`] characters before `start`, never crossing the
/// line start.
fn line_context_before(text: &str, start: usize) -> String {
    let line_start = text[..start].rfind('\n').map_or(0, |i| i + 1);
    let taken: Vec<char> = text[line_start..start]
        .chars()
        .rev()
        .take(ANCHOR_CONTEXT)
        .collect();
    taken.into_iter().rev().collect()
}

/// Up to [`ANCHOR_CONTEXT`] characters after `end`, never crossing the
/// line end.
fn line_context_after(text: &str, end: usize) -> String {
    let line_end = text[end..].find('\n').map_or(text.len(), |i| end + i);
    text[end..line_end].chars().take(ANCHOR_CONTEXT).collect()
}

/// Whether `text` still holds `edit` at byte span `[start, end)`: the
/// original slice intact and the anchor context flanking it.
fn holds_at(text: &str, edit: &Edit, start: usize, end: usize) -> bool {
    text.get(start..end) == Some(edit.source.as_str())
        && text[..start].ends_with(edit.anchor.context_before.as_str())
        && text[end..].starts_with(edit.anchor.context_after.as_str())
}

/// The byte position to write `edit` at in `text`, or `None` for stale:
/// the claimed offset when the original slice still sits there flanked by
/// the anchor context, else the unique re-location — the drift-correction
/// pass. More than one candidate (on the anchor line, or anywhere
/// when no candidate sits on it) is ambiguous and goes stale.
#[must_use]
fn locate(text: &str, edit: &Edit) -> Option<usize> {
    // Exact position first, guarded against offsets drifted past the end.
    if edit.offset + edit.length <= utf16_len_of(text) {
        let start = utf16_offset_to_byte(text, edit.offset);
        let end = start + edit.source.len();
        if holds_at(text, edit, start, end) {
            return Some(start);
        }
    }
    // Re-location: every position where the original slice survives with
    // the anchor context flanking it. Line numbers come from a fresh
    // [`LineIndex`] of the current text — the same index the anchor was
    // born from in [`anchored_edit`], so both faces agree on what "the
    // anchor line" means (the applier's text mutates per write, so an
    // index shared across edits would read stale line starts).
    let lines = LineIndex::new(text);
    let mut line_match: Option<usize> = None;
    let mut line_matches = 0;
    let mut any_match: Option<usize> = None;
    let mut total = 0;
    for (start, _) in text.match_indices(edit.source.as_str()) {
        let end = start + edit.source.len();
        if !holds_at(text, edit, start, end) {
            continue;
        }
        total += 1;
        if any_match.is_none() {
            any_match = Some(start);
        }
        let (line, _) = lines.byte_to_line_col(u32::try_from(start).expect("offset exceeds u32"));
        if line == edit.anchor.line {
            line_matches += 1;
            line_match = Some(start);
        }
    }
    match (line_matches, total) {
        (1, _) => line_match,
        (0, 1) => any_match,
        _ => None,
    }
}

/// Applies `edits` to `text`: exact-position validation, then anchor
/// re-location; overlapping edits and stale anchors are skipped. Returns
/// the patched text plus one outcome per edit, in input order.
///
/// Edits apply in descending offset order, and every locator runs against
/// the *snapshot* text — the buffer as it stood when the fixes were born.
/// A sibling write higher up never disturbs a lower edit's proof (its
/// slice and anchor context still read as they did at birth), which is
/// what keeps a multi-edit change from stranding half of itself: located
/// snapshot spans translate into the patched buffer through the writes
/// already placed below them (each contributes its byte delta). The
/// overlap guard runs in snapshot coordinates too, so a re-located write
/// never shifts a later edit's decision about its own original span.
#[must_use]
pub fn apply(text: &str, edits: &[Edit]) -> (String, Vec<EditOutcome>) {
    let mut order: Vec<usize> = (0..edits.len()).collect();
    order.sort_by(|&a, &b| edits[b].offset.cmp(&edits[a].offset));
    let mut patched = text.to_owned();
    let mut outcomes: Vec<EditOutcome> = vec![EditOutcome::Stale; edits.len()];
    // Snapshot UTF-16 start of the lowest already-placed edit above.
    let mut applied_floor = u32::MAX;
    // Writes already placed, in snapshot byte coordinates: the pristine
    // span each replaced, and the byte delta its replacement contributes
    // to every position above it.
    let mut placed: Vec<(usize, usize, i64)> = Vec::new();
    for &i in &order {
        let edit = &edits[i];
        if edit.offset.saturating_add(edit.length) > applied_floor {
            continue; // overlaps a write already placed above it
        }
        let Some(start) = locate(text, edit) else {
            continue;
        };
        let end = start + edit.source.len();
        // Translate the snapshot span into the patched buffer's
        // coordinates; a span reaching into (not merely touching) a
        // placed write is unplaceable — stale.
        let shifted = |pos: usize| -> Option<usize> {
            let mut shifted = i64::try_from(pos).ok()?;
            for &(placed_start, placed_end, delta) in &placed {
                if placed_end <= pos {
                    shifted += delta;
                } else if placed_start < pos {
                    return None;
                }
            }
            usize::try_from(shifted).ok()
        };
        let (Some(start), Some(end)) = (shifted(start), shifted(end)) else {
            continue;
        };
        let delta = i64::try_from(edit.replacement.len()).unwrap_or(i64::MAX)
            - i64::try_from(edit.source.len()).unwrap_or(i64::MAX);
        patched.replace_range(start..end, &edit.replacement);
        placed.push((start, end, delta));
        applied_floor = edit.offset;
        outcomes[i] = EditOutcome::Applied;
    }
    (patched, outcomes)
}

// ---------------------------------------------------------------------------
// Fix source: the dartq-lints layer's diagnostic rows
// ---------------------------------------------------------------------------

/// Maps the lints layer's rows to anchored edits — the table-driven
/// dispatch ([`crate::fix_table`]): every wired rule whose official fix is
/// a single-span mechanical rewrite has a [`crate::fix_table::FixSpec`]
/// row, and rules without one never produce an edit; a wired hit whose
/// slice no longer verifies is dropped rather than patched on faith.
/// Each hit's expansion routes through the planner fuse's counted step
/// and the walk stops consuming hits on a spent budget.
#[must_use]
pub(crate) fn from_lints(
    hits: &[Lint],
    text: &str,
    lines: &LineIndex,
    fuse: &PlannerFuse,
) -> Vec<RuleFix> {
    // The structural rewriters verify against the token stream (keyword
    // positions are quote-safe only there); the parse is paid once per
    // call, and only when a hit's family needs it.
    let needs_tokens = hits.iter().any(|hit| {
        crate::fix_table::spec_for(RULES[hit.rule.0 as usize].name)
            .is_some_and(|spec| spec.source == FixSource::Lint && spec.needs_tokens)
    });
    let tokens = needs_tokens.then(|| parse_unit(text, Features::default()).tokens);
    let mut rows = Vec::new();
    for hit in hits {
        if !fuse.step() {
            break;
        }
        let rule = RULES[hit.rule.0 as usize].name;
        let Some(spec) = crate::fix_table::spec_for(rule) else {
            continue;
        };
        if spec.source != FixSource::Lint {
            continue;
        }
        let Some((offset, length, replacement)) = crate::fix_table::expand(
            spec,
            &FixInput {
                text,
                range: hit.range.clone(),
                message: &hit.message,
                tokens: tokens.as_ref(),
            },
        ) else {
            continue;
        };
        rows.push(RuleFix {
            rule,
            message: hit.message.clone(),
            source: BUILTIN_SOURCE,
            edit: anchored_edit(text, lines, offset, length, &replacement),
        });
    }
    rows
}

/// Maps the engine's semantic diagnostics to anchored edits — the fix
/// source of the drop family and the null-check family (module docs). The
/// table lookup ([`crate::fix_table`]) is flat: every row is a mechanical
/// rewrite through the same verify-then-anchor pipeline as [`from_lints`],
/// and a hit whose slice does not verify its shape drops rather than
/// patches. Diagnostics outside the two families never produce an edit.
///
/// The token-verified rows (the `unused_local_variable` removal variant
/// and the whole null-check family) pay one parse per call, and only when
/// one of their hits is present.
#[must_use]
pub(crate) fn from_semantic(
    diagnostics: &[Diagnostic],
    text: &str,
    lines: &LineIndex,
    fuse: &PlannerFuse,
) -> Vec<RuleFix> {
    engine_rows(
        diagnostics,
        text,
        lines,
        FixSource::Semantic,
        BUILTIN_SEMANTIC_SOURCE,
        fuse,
    )
}

/// Maps the engine's syntax diagnostics to anchored edits — the parser
/// source (module docs): the [`crate::fix_table`]'s parser rows mirror the
/// official registry's mechanical parser producers shape for shape, and a
/// report whose surroundings do not verify the producer's precondition
/// drops. The token-verified rows pay one parse per call, only when one
/// of their hits is present. Identical consecutive edits collapse: the
/// scanner reports a number literal's separators once per run, the
/// official producer rewrites the literal once.
#[must_use]
pub(crate) fn from_parser(
    diagnostics: &[Diagnostic],
    text: &str,
    lines: &LineIndex,
    fuse: &PlannerFuse,
) -> Vec<RuleFix> {
    let mut rows = engine_rows(
        diagnostics,
        text,
        lines,
        FixSource::Parser,
        BUILTIN_PARSER_SOURCE,
        fuse,
    );
    rows.dedup_by(|a, b| {
        a.edit.offset == b.edit.offset
            && a.edit.length == b.edit.length
            && a.edit.replacement == b.edit.replacement
    });
    rows
}

/// The engine-sourced executor behind [`from_semantic`] and
/// [`from_parser`]: the rows of `source` among `diagnostics`, expanded
/// through the table and anchored, tagged `provenance`. Each diagnostic's
/// expansion routes through the planner fuse's counted step and the walk
/// stops consuming diagnostics on a spent budget.
fn engine_rows(
    diagnostics: &[Diagnostic],
    text: &str,
    lines: &LineIndex,
    source: FixSource,
    provenance: &'static str,
    fuse: &PlannerFuse,
) -> Vec<RuleFix> {
    let needs_tokens = diagnostics.iter().any(|d| {
        crate::fix_table::spec_for(d.code.name)
            .is_some_and(|spec| spec.source == source && spec.needs_tokens)
    });
    let tokens = needs_tokens.then(|| parse_unit(text, Features::default()).tokens);
    let mut rows = Vec::new();
    for d in diagnostics {
        if !fuse.step() {
            break;
        }
        let Some(spec) = crate::fix_table::spec_for(d.code.name) else {
            continue;
        };
        if spec.source != source {
            continue;
        }
        let Some((offset, length, replacement)) = crate::fix_table::expand(
            spec,
            &FixInput {
                text,
                range: d.range.offset..d.range.offset + d.range.length,
                message: &d.message,
                tokens: tokens.as_ref(),
            },
        ) else {
            continue;
        };
        rows.push(RuleFix {
            rule: d.code.name,
            message: d.message.to_string(),
            source: provenance,
            edit: anchored_edit(text, lines, offset, length, &replacement),
        });
    }
    rows
}

/// Maps one plugin's `request/fixes` reply to anchored rows, priority
/// first (the reply's own order on ties — the sort is stable). Every edit
/// is bounds-checked against `text` before anchoring — plugin offsets are
/// untrusted wire data and [`anchored_edit`]'s converter panics on
/// out-of-range offsets — and one bad edit drops the whole change: a
/// proposal is applied atomically or not at all, never half-applied.
#[must_use]
pub fn from_plugin(
    plugin: &str,
    reply: &FixesReply,
    text: &str,
    lines: &LineIndex,
) -> Vec<PluginFix> {
    let len16 = utf16_len_of(text);
    let mut order: Vec<&PrioritizedChange> = reply.fixes.iter().collect();
    order.sort_by_key(|change| change.priority);
    order
        .into_iter()
        .filter_map(|change| {
            let mut edits = Vec::with_capacity(change.edits.len());
            for edit in &change.edits {
                let offset = u32::try_from(edit.offset).ok()?;
                let length = u32::try_from(edit.length).ok()?;
                if offset.checked_add(length)? > len16 {
                    return None;
                }
                edits.push(anchored_edit(
                    text,
                    lines,
                    offset,
                    length,
                    &edit.replacement,
                ));
            }
            Some(PluginFix {
                plugin: plugin.to_owned(),
                message: change.message.clone(),
                priority: change.priority,
                edits,
            })
        })
        .collect()
}

/// The resolved-light assist transport (the `collect_set` semantic-stage
/// posture): one throwaway workspace engine assembles the unit's
/// semantic fold ([`dartq_semantic::Analysis`]), the dispatch runs once
/// with the face mounted, and the engine is dropped. Any failure — no
/// workspace, the file outside the assembled engine, a fold the context
/// cannot build — degrades to the engine-free dispatch, never an error:
/// the resolved producers go silent and the rows answer from the
/// engine-free kinds. The face is the single-file posture (the owning
/// library's member files under-report to this file), the semantic
/// tier's established isolated-context stance — cross-file names
/// under-report `None` and the producers decline. `sdk` is the engine's
/// SDK root: the callers without one pass `None` and the assembly falls
/// back to `DART_SDK` discovery; the resolved tests pin the fixture SDK.
fn resolved_assist_rows(
    text: &str,
    path: &Path,
    offset: u64,
    length: u64,
    sdk: Option<&Path>,
    fuse: &PlannerFuse,
) -> Vec<PluginFix> {
    let Some(seed) = path.parent() else {
        return builtin_assists(text, path, offset, length, fuse);
    };
    let Ok((mut engine, _)) = crate::workspace::open_engine(seed, sdk) else {
        return builtin_assists(text, path, offset, length, fuse);
    };
    // The file table fills at discovery — without it the target file has
    // no id and the face degrades to the engine-free dispatch.
    let _ = engine.discover_workspace();
    let file_path = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
    let Some(file) = engine
        .file_table()
        .try_file_id(&file_path)
        .or_else(|| engine.file_table().try_file_id(path))
    else {
        return builtin_assists(text, path, offset, length, fuse);
    };
    let members = [file];
    let context = crate::lints::build_semantic_context(&engine, text, file, &members);
    let analysis = dartq_semantic::analyze_unit(
        text,
        &context.scanned.tokens,
        crate::lints::SEMANTIC_PARSE_FEATURES,
        engine.strings(),
        file,
        context.lib,
        &context.graph,
        &context.namespaces,
        &context.index,
        dartq_semantic::StrictModes::default(),
        &dartq_resolution::LibraryClassModifiers::default(),
    );
    builtin_assists_with(text, path, offset, length, Some(&analysis), fuse)
}

/// The location-directed assist face: the built-in producers' proposals
/// for the UTF-16 span `[offset, offset + length)` followed by the plugin
/// hosts' proposals for one file, all anchored against the file's on-disk
/// text. The built-in rows lead (priority order), the plugin rows follow
/// (the hosts' own priority order); the built-in parse is paid once per
/// request.
///
/// `sdk` backs the resolved-light assist mount's engine assembly — the
/// CLI passes none and falls back to the `DART_SDK` environment, the
/// daemon passes its session's resolved root.
///
/// # Errors
///
/// [`DiscoverError::Missing`] when the target does not exist (the usage
/// tier, the fix face's message body), [`DiscoverError::Io`] for any
/// other read failure, including the span-capacity rejection (#1543
/// bypass face: the message carries the path and both sizes).
pub fn assists(
    path: &Path,
    offset: u64,
    length: u64,
    hosts: &mut PluginHosts,
    sdk: Option<&Path>,
) -> Result<AssistAnswer, DiscoverError> {
    // Span-capacity gates: the stat refuses before the read, the byte
    // length is authoritative — the text never reaches `LineIndex::new`
    // over the capacity bound.
    if let Some(error) = stat_capacity_error(path) {
        return Err(DiscoverError::Io(error));
    }
    let text = std::fs::read_to_string(path).map_err(|error| {
        if error.kind() == std::io::ErrorKind::NotFound {
            DiscoverError::Missing(path.display().to_string())
        } else {
            DiscoverError::Io(error)
        }
    })?;
    if text.len() > MAX_SOURCE_BYTES {
        return Err(DiscoverError::Io(capacity_error(path, text.len() as u64)));
    }
    let lines = LineIndex::new(&text);
    // The assist walk's planner fuse (#1687-class backstop): one request
    // plans one file, and every trial routes through the counted step. A
    // spent budget answers the partial rows with a structured error row —
    // the client sees the trip in `errors`, never a hang, never a panic.
    let fuse = PlannerFuse::new(1);
    let mut assists = resolved_assist_rows(&text, path, offset, length, sdk, &fuse);
    assists.extend(hosts.fixes(&host_path(path), offset, length, &text, &lines));
    let mut errors = hosts.take_errors();
    if fuse.tripped() {
        errors.push(PluginHostError {
            plugin: BUILTIN_ASSIST_SOURCE.to_owned(),
            message: format!(
                "the assist planner fuse tripped after {} operations; the answer carries the partial rows",
                fuse.budget
            ),
        });
    }
    Ok(AssistAnswer {
        file: path.display().to_string(),
        assists,
        errors,
    })
}

/// A width-0 keyword hit (`new`, `late`): the rewrite drops the keyword
/// plus its trailing horizontal whitespace (a newline stays — joining
/// lines is a formatting decision, not a fix). The keyword is ASCII, so
/// its lexeme length is its UTF-16 length.
pub(crate) fn drop_keyword(text: &str, offset16: u32, keyword: &str) -> Option<(u32, u32, String)> {
    debug_assert_eq!(
        keyword.len(),
        keyword.chars().map(char::len_utf16).sum::<usize>()
    );
    let start = utf16_offset_to_byte(text, offset16);
    let rest = text.get(start..)?.strip_prefix(keyword)?;
    let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
    let length = u32::try_from(keyword.len() + ws).ok()?;
    Some((offset16, length, String::new()))
}

/// A span-exact rewrite: the hit span must slice to exactly `expect`.
pub(crate) fn replace_exact(
    text: &str,
    range: &core::ops::Range<u32>,
    expect: &str,
    replacement: &str,
) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, range.start);
    let end = utf16_offset_to_byte(text, range.end);
    text.get(start..end).filter(|slice| *slice == expect)?;
    Some((range.start, range.end - range.start, replacement.to_owned()))
}

/// `${id}` → `$id`: the hit span is the whole interpolation group (the
/// rule reports it exactly); the `${…}` shape and a bare ASCII identifier
/// body are verified before rewriting.
pub(crate) fn unbrace(text: &str, range: &core::ops::Range<u32>) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, range.start);
    let end = utf16_offset_to_byte(text, range.end);
    let slice = text.get(start..end)?;
    let inner = slice.strip_prefix("${")?.strip_suffix('}')?;
    if inner.is_empty() || !inner.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return None;
    }
    Some((range.start, range.end - range.start, format!("${inner}")))
}

/// The UTF-16 length of a string slice (the edits' currency).
fn utf16_count(slice: &str) -> u32 {
    u32::try_from(slice.chars().map(char::len_utf16).sum::<usize>()).unwrap_or(u32::MAX)
}

/// The byte slice of `text` under the UTF-16 `range`.
fn slice16<'s>(text: &'s str, range: &core::ops::Range<u32>) -> Option<&'s str> {
    text.get(utf16_offset_to_byte(text, range.start)..utf16_offset_to_byte(text, range.end))
}

/// The leading (or trailing) run of `quote` bytes.
fn quote_run(bytes: &[u8], quote: u8, trailing: bool) -> usize {
    if trailing {
        bytes.iter().rev().take_while(|&&b| b == quote).count()
    } else {
        bytes.iter().take_while(|&&b| b == quote).count()
    }
}

/// A width-0 `this` hit: the rewrite drops the `this.` qualifier — the
/// keyword plus horizontal whitespace and the dot (the official
/// `RemoveThisExpression` deletes from the keyword through the operator;
/// a newline never joins).
pub(crate) fn drop_this_qualifier(text: &str, offset16: u32) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, offset16);
    let rest = text.get(start..)?.strip_prefix("this")?;
    let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
    if !rest[ws..].starts_with('.') {
        return None;
    }
    Some((offset16, 4 + u32::try_from(ws).ok()? + 1, String::new()))
}

/// The whole-literal hit of an interpolation of one string literal
/// (`''${'x'}''`): the rewrite keeps the inner literal verbatim (the
/// official producer deletes the wrapper ranges around it). The empty
/// quote-run wrappers and the `${…}` group are verified first.
pub(crate) fn unwrap_string_interpolation(
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let bytes = slice16(text, range)?.as_bytes();
    let quote = *bytes.first()?;
    if quote != b'\'' && quote != b'"' {
        return None;
    }
    let lead = quote_run(bytes, quote, false);
    let trail = quote_run(bytes, quote, true);
    // 1/3 quotes: the plain and triple-quote wrappers; 2: the empty
    // adjacent-string face (`''${'x'}''`). The runs must match.
    if lead != trail || !matches!(lead, 1..=3) {
        return None;
    }
    let body = bytes.get(lead..bytes.len() - trail)?.strip_prefix(b"${")?;
    if body.last() != Some(&b'}') {
        return None;
    }
    // The kept expression is the string literal between `${` and the
    // final `}`: it opens with its own quote (optionally raw) and closes
    // with the matching one.
    let inner = &body[..body.len() - 1];
    let open = match inner.first()? {
        b'\'' | b'"' => inner.first()?,
        b'r' => inner.get(1)?,
        _ => return None,
    };
    if *open != b'\'' && *open != b'"' {
        return None;
    }
    if inner.last() != Some(open) || inner.len() < 2 {
        return None;
    }
    let start = utf16_offset_to_byte(text, range.start);
    let first = start + lead + 2;
    let last = start + bytes.len() - trail - 1;
    Some((
        range.start,
        range.end - range.start,
        text[first..last].to_owned(),
    ))
}

/// A `null`-operand hit under `??`: the rewrite drops the operator with
/// the operand (`a ?? null` → `a`, `null ?? a` → `a`; the official
/// deletion spans operator and operand together). The intervening
/// whitespace is horizontal only — a newline stays.
pub(crate) fn drop_if_null_null(
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    replace_exact(text, range, "null", "")?;
    let start = utf16_offset_to_byte(text, range.start);
    let end = utf16_offset_to_byte(text, range.end);
    // Right operand (`a ?? null`): the deletion starts at the whitespace
    // before the operator — the official span runs from the left operand's
    // end through the null.
    if let Some(head) = text.get(..start) {
        let op_ws = head.len() - head.trim_end_matches([' ', '\t']).len();
        if head[..head.len() - op_ws].ends_with("??") {
            let before = &head[..head.len() - op_ws - 2];
            let lead = before.len() - before.trim_end_matches([' ', '\t']).len();
            let at = u32::try_from(start - op_ws - 2 - lead).ok()?;
            return Some((at, range.end - at, String::new()));
        }
    }
    // Left operand (`null ?? a`): the text after opens with the operator.
    let rest = text.get(end..)?;
    let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
    let after = &rest[ws..];
    if let Some(tail) = after.strip_prefix("??") {
        let tail_ws = tail.len() - tail.trim_start_matches([' ', '\t']).len();
        return Some((
            range.start,
            4 + u32::try_from(ws + 2 + tail_ws).ok()?,
            String::new(),
        ));
    }
    None
}

/// The whole-assignment hit of `x ??= null`: a lone expression-statement
/// line loses the whole line (the official `getLinesRange` face); any
/// other context loses `??= null`.
pub(crate) fn remove_null_aware_assignment(
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let slice = slice16(text, range)?;
    let eq = u32::try_from(slice.find("??=")?).ok()?;
    let rhs = slice.get(eq as usize + 3..)?;
    if rhs.trim() != "null" || slice[..eq as usize].trim().is_empty() {
        return None;
    }
    let start = utf16_offset_to_byte(text, range.start);
    let end = utf16_offset_to_byte(text, range.end);
    // The statement-line face: nothing but whitespace before the hit on
    // its line, and `;` plus horizontal whitespace to the line end after.
    // The whole line goes — the official `getLinesRange` includes the
    // line's own indentation — through the line terminator.
    let line_start = text[..start].rfind('\n').map_or(0, |i| i + 1);
    if text[line_start..start].trim().is_empty()
        && let Some(rest) = text.get(end..)
    {
        let after = rest.trim_start_matches([' ', '\t']);
        if let Some(after_semi) = after.strip_prefix(';') {
            let trailing = after_semi.len() - after_semi.trim_start_matches([' ', '\t']).len();
            let tail = &after_semi[trailing..];
            let eol = if tail.starts_with("\r\n") {
                2
            } else if tail.starts_with('\n') {
                1
            } else {
                tail.is_empty().then_some(0)?
            };
            let deleted = utf16_count(&text[line_start..end + 1 + trailing + eol]);
            return Some((utf16_count(&text[..line_start]), deleted, String::new()));
        }
    }
    // The expression face: the official deletion runs from the left-hand
    // side's end through the value's — the whitespace before the operator
    // goes with it.
    let head = &slice[..eq as usize];
    let ws = head.len() - head.trim_end_matches([' ', '\t']).len();
    let at = range.start + eq - u32::try_from(ws).ok()?;
    Some((at, range.end - at, String::new()))
}

pub(crate) fn drop_null_initializer(
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let slice = slice16(text, range)?;
    let eq = u32::try_from(slice.rfind('=')?).ok()?;
    // The initializer is exactly `null` and nothing before the `=` reads
    // as an assignment of its own. The deletion carries the whitespace
    // before the `=` (the official deletion runs from the name's end).
    if slice.get(eq as usize + 1..)?.trim() != "null" || slice[..eq as usize].contains('=') {
        return None;
    }
    let head = &slice[..eq as usize];
    let ws = head.len() - head.trim_end_matches([' ', '\t']).len();
    let at = range.start + eq - u32::try_from(ws).ok()?;
    Some((at, range.end - at, String::new()))
}

/// A width-0 variable-name hit under a final/const declaration with a
/// nullable written type: the rewrite deletes the type's trailing `?`
/// (the official `RemoveQuestionMark` deletes the question token of the
/// written type, never a type argument's).
pub(crate) fn drop_type_question_mark(text: &str, offset16: u32) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, offset16);
    let head = text.get(..start)?;
    let ws = head.len() - head.trim_end_matches([' ', '\t']).len();
    if !head[..head.len() - ws].ends_with('?') {
        return None;
    }
    Some((offset16 - u32::try_from(ws).ok()? - 1, 1, String::new()))
}

/// A width-0 `new` hit: the rewrite drops the `.new` (the official
/// `RemoveConstructorName` deletes from the period through the name).
pub(crate) fn drop_dot_new(text: &str, offset16: u32) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, offset16);
    let rest = text.get(start..)?.strip_prefix("new")?;
    if rest
        .chars()
        .next()
        .is_some_and(|c| c.is_alphanumeric() || c == '_')
    {
        return None;
    }
    let head = text.get(..start)?;
    let ws = head.len() - head.trim_end_matches([' ', '\t']).len();
    if !head[..head.len() - ws].ends_with('.') {
        return None;
    }
    let at = u32::try_from(start - ws - 1).ok()?;
    Some((at, u32::try_from(ws + 4).ok()?, String::new()))
}

// ---------------------------------------------------------------------------
// Semantic source: the engine's drop-family diagnostics
//
// Each rewriter expands the diagnostic's span into the mechanical edit
// and re-verifies the shape the code reports — an unverifiable hit drops,
// never patches on faith. Every drop stays within one line, and the
// whitespace arithmetic runs over ASCII-only regions (byte counts equal
// UTF-16 counts there).
// ---------------------------------------------------------------------------

/// The identifier shape the drop-family rewrites verify: a non-empty,
/// non-digit-led slice of Dart word characters. Returns the slice with its
/// byte span.
fn word_slice(text: &str, range: SourceRange) -> Option<(&str, usize, usize)> {
    let start = utf16_offset_to_byte(text, range.offset);
    let end = utf16_offset_to_byte(text, range.offset + range.length);
    let slice = text.get(start..end)?;
    word_shape(slice).then_some((slice, start, end))
}

/// The one-line bounds of the byte span `[start, end)`: `None` when the
/// span crosses a newline, else `(line_start, line_end)` with `line_end`
/// excluding the terminator.
fn line_bounds(text: &str, start: usize, end: usize) -> Option<(usize, usize)> {
    if text.get(start..end)?.contains('\n') {
        return None;
    }
    let line_start = text[..start].rfind('\n').map_or(0, |i| i + 1);
    let line_end = text[end..].find('\n').map_or(text.len(), |i| end + i);
    Some((line_start, line_end))
}

/// Cuts `[line_start, line_end)` plus its terminator (CRLF aware; the
/// last line has none) — the whole-line drop shape, in UTF-16.
fn cut_line(text: &str, line_start: usize, line_end: usize) -> (u32, u32) {
    let eol = if text[line_end..].starts_with("\r\n") {
        2
    } else {
        usize::from(text[line_end..].starts_with('\n'))
    };
    (
        utf16_count(&text[..line_start]),
        utf16_count(&text[line_start..line_end + eol]),
    )
}

/// `unused_import`: the URI literal's span expands to its directive. A
/// directive alone on its line — `import` with nothing but whitespace
/// before it, one terminating `;` with nothing but whitespace after it —
/// drops the whole line, terminator with it; an adjacent comment, a
/// trailing sibling, or a crossed newline refuses the cut. A directive
/// whose line opens with a sibling's `;` drops exactly itself, from the
/// keyword through the `;`, leaving every surrounding byte intact — the
/// same-line deletion upstream's import-removal edit lands (upstream Dart
/// SDK source, pkg/analysis_server, remove_unused_import).
pub(crate) fn drop_import_directive(text: &str, range: SourceRange) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, range.offset);
    let end = utf16_offset_to_byte(text, range.offset + range.length);
    let (line_start, line_end) = line_bounds(text, start, end)?;
    // The directive's `import` keyword sits right before the URI — only
    // horizontal whitespace between them, and the keyword is a word of its
    // own, not an identifier's tail.
    let head = text[line_start..start].trim_end_matches([' ', '\t']);
    let keyword = head.strip_suffix("import")?;
    if keyword.ends_with(|c: char| c.is_alphanumeric() || c == '_' || c == '$') {
        return None;
    }
    let keyword_start = line_start + keyword.len();
    // One `;` closes the directive: the line's tail past the URI carries
    // it as its only semicolon, at the whitespace-trimmed end.
    let tail = &text[end..line_end];
    let tail_t = tail.trim_matches([' ', '\t', '\r']);
    if !tail_t.ends_with(';') || tail_t[..tail_t.len() - 1].contains(';') {
        return None;
    }
    let directive_end = line_end - (tail.len() - tail.trim_end_matches([' ', '\t', '\r']).len());
    // The directive owns its line: the whole line goes, terminator with it.
    let before = &text[line_start..keyword_start];
    if before.bytes().all(|b| b == b' ' || b == b'\t')
        && text[directive_end..line_end]
            .bytes()
            .all(|b| matches!(b, b' ' | b'\t' | b'\r'))
    {
        let (offset, length) = cut_line(text, line_start, line_end);
        return Some((offset, length, String::new()));
    }
    // A sibling's `;` closes right before the keyword: the cut takes
    // exactly this directive and leaves the line's other bytes alone.
    if before.trim_end_matches([' ', '\t', '\r']).ends_with(';') {
        return Some((
            utf16_count(&text[..keyword_start]),
            utf16_count(&text[keyword_start..directive_end]),
            String::new(),
        ));
    }
    None
}

/// `unused_local_variable`: the name renames to `_{name}` — the wildcard
/// posture silencing the row. The whole declaration line drops only when
/// it is a bare single declarator whose initializer is trivially pure
/// (literal-shaped tokens, [`pure_single_declarator`]); anything else
/// keeps the rename.
pub(crate) fn rewrite_unused_local(
    tokens: Option<&TokenTable>,
    text: &str,
    range: SourceRange,
) -> Option<(u32, u32, String)> {
    let (name, start, end) = word_slice(text, range)?;
    if name.starts_with('_') {
        return None;
    }
    if let Some(tokens) = tokens
        && let Some((first, _)) = hit_tokens(tokens, &(range.offset..range.offset + range.length))
        && let Some(semicolon_end) = pure_single_declarator(tokens, first)
        && let Some((line_start, line_end)) = line_bounds(text, start, end)
        && let Some(owns_head) = declaration_owns_line_head(tokens, text, first, line_start)
        && owns_head
        && text[semicolon_end..line_end]
            .trim_matches([' ', '\t', '\r'])
            .is_empty()
    {
        let (offset, length) = cut_line(text, line_start, line_end);
        return Some((offset, length, String::new()));
    }
    Some((range.offset, range.length, format!("_{name}")))
}

/// Whether the declaration holding token `first` owns its line's head:
/// the declaration's first token — the one after the previous `;` / `{` /
/// `}` walking back from `first` — has only horizontal whitespace between
/// the line start and itself. A statement or sibling sharing the line
/// keeps the rename, and a declaration opened on an earlier line (`int`
/// over `int\nx = 1;`) never owns this line's head.
fn declaration_owns_line_head(
    tokens: &TokenTable,
    text: &str,
    first: usize,
    line_start: usize,
) -> Option<bool> {
    let mut head = 0;
    for index in (0..first).rev() {
        if matches!(
            kind_of(tokens, index)?,
            TokenKind::Semicolon | TokenKind::OpenCurly | TokenKind::CloseCurly
        ) {
            head = index + 1;
            break;
        }
    }
    let decl_start = utf16_offset_to_byte(text, tokens.get(head)?.utf16_offset);
    Some(
        text.get(line_start..decl_start)
            .is_some_and(|lead| lead.trim_matches([' ', '\t']).is_empty()),
    )
}

/// Whether the declaration holding token `name_index` is one declarator
/// with a trivially-pure initializer — every token between the name and
/// the statement's depth-0 `;` is literal-shaped (numbers, plain strings,
/// `true`/`false`/`null`/`const`, the collection punctuation) — and the
/// `;`'s byte end when it is. A call, a closure, a name interpolation, or
/// a second declarator refuses.
fn pure_single_declarator(tokens: &TokenTable, name_index: usize) -> Option<usize> {
    let mut depth: u32 = 0;
    let mut index = name_index + 1;
    loop {
        let token = tokens.get(index)?;
        match token.kind {
            TokenKind::Semicolon if depth == 0 => return Some(token_end(token)),
            TokenKind::Comma if depth == 0 => return None,
            TokenKind::Eq if depth == 0 => {}
            TokenKind::Int
            | TokenKind::Double
            | TokenKind::Hexadecimal
            | TokenKind::String
            | TokenKind::Minus
            | TokenKind::Index
            | TokenKind::Colon
            | TokenKind::Comma
            | TokenKind::Keyword(Keyword::Null | Keyword::True | Keyword::False | Keyword::Const) =>
                {}
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ => return None,
        }
        index += 1;
    }
}

/// `unused_shown_name`: the name leaves its `show` combinator — with its
/// following comma when it is not last, the preceding comma when it is,
/// and the whole `show` clause (leading whitespace with it) when it is
/// the only name.
pub(crate) fn drop_shown_name(text: &str, range: SourceRange) -> Option<(u32, u32, String)> {
    let (_, start, end) = word_slice(text, range)?;
    let (line_start, line_end) = line_bounds(text, start, end)?;
    let head = &text[line_start..start];
    let tail = &text[end..line_end];
    let head_t = head.trim_end_matches([' ', '\t']);
    let tail_t = tail.trim_start_matches([' ', '\t']);
    // Not the last name: `show A, B` loses `A, `.
    if let Some(rest) = tail_t.strip_prefix(',') {
        let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
        let cut = (tail.len() - tail_t.len()) + 1 + ws;
        return Some((
            range.offset,
            range.length + u32::try_from(cut).ok()?,
            String::new(),
        ));
    }
    // The last name but not the only one: `show B, A` loses `, A`.
    if head_t.ends_with(',') {
        let drop = (head.len() - head_t.len()) + 1;
        return Some((
            range.offset - u32::try_from(drop).ok()?,
            range.length + u32::try_from(drop).ok()?,
            String::new(),
        ));
    }
    // The only name: the whole `show` clause goes,
    // `import 'u' show A;` → `import 'u';`.
    if head_t.len() >= 4
        && head_t.ends_with("show")
        && !head_t[..head_t.len() - 4]
            .ends_with(|c: char| c.is_alphanumeric() || c == '_' || c == '$')
    {
        let lead = (head.len() - head_t.len()) + 4;
        let before = &text[line_start..start - lead];
        let drop = lead + (before.len() - before.trim_end_matches([' ', '\t']).len());
        return Some((
            range.offset - u32::try_from(drop).ok()?,
            range.length + u32::try_from(drop).ok()?,
            String::new(),
        ));
    }
    None
}

/// `unused_catch_clause`: the `catch (e)` part of an `on T catch (e)`
/// leaves — the whitespace before the keyword, the keyword, its
/// parentheses, and the flanking whitespace (the code only fires without
/// a stack sibling, so nothing trails the name but `)`). An `on` type
/// must sit before the keyword — the shape the code reports.
pub(crate) fn drop_catch_clause(text: &str, range: SourceRange) -> Option<(u32, u32, String)> {
    let (_, start, end) = word_slice(text, range)?;
    let (line_start, line_end) = line_bounds(text, start, end)?;
    let head = &text[line_start..start];
    let head_t = head.trim_end_matches([' ', '\t']);
    let keyword = head.strip_suffix('(')?.trim_end_matches([' ', '\t']);
    if !keyword.ends_with("catch")
        || keyword[..keyword.len() - 5]
            .ends_with(|c: char| c.is_alphanumeric() || c == '_' || c == '$')
        || !text[end..line_end]
            .trim_start_matches([' ', '\t'])
            .starts_with(')')
    {
        return None;
    }
    // The code only fires on `on T catch (e)`: an identifier tail — the
    // `on` type's last word — must sit before the keyword (a bare
    // `catch (e)` has none and is auto-used upstream anyway).
    let before = keyword[..keyword.len() - 5].trim_end();
    if !before.ends_with(|c: char| c.is_ascii_alphanumeric() || c == '_' || c == '$') {
        return None;
    }
    let catch_start = line_start + head.rfind("catch")?;
    let lead = text[line_start..catch_start].len()
        - text[line_start..catch_start]
            .trim_end_matches([' ', '\t'])
            .len();
    let ws = text[end..line_end].len() - text[end..line_end].trim_start_matches([' ', '\t']).len();
    // The drop reaches from the whitespace before `catch` through `)`:
    // lead + `catch` + the gap to `(` + `(` + the gap to the name.
    let trailing = head.len() - head_t.len();
    let paren_gap = (head_t.len() - 1) - keyword.len();
    let drop = lead + 5 + paren_gap + 1 + trailing;
    Some((
        range.offset - u32::try_from(drop).ok()?,
        range.length + u32::try_from(drop + ws + 1).ok()?,
        String::new(),
    ))
}

/// `unused_catch_stack`: the stack-trace parameter leaves with its
/// preceding comma (`catch (e, s)` → `catch (e)`).
pub(crate) fn drop_catch_stack(text: &str, range: SourceRange) -> Option<(u32, u32, String)> {
    let (_, start, end) = word_slice(text, range)?;
    let (line_start, line_end) = line_bounds(text, start, end)?;
    let head = &text[line_start..start];
    let head_t = head.trim_end_matches([' ', '\t']);
    if !head_t.ends_with(',')
        || !text[end..line_end]
            .trim_start_matches([' ', '\t'])
            .starts_with(')')
    {
        return None;
    }
    let drop = (head.len() - head_t.len()) + 1;
    Some((
        range.offset - u32::try_from(drop).ok()?,
        range.length + u32::try_from(drop).ok()?,
        String::new(),
    ))
}

/// `unused_label`: the label declaration leaves with its colon and the
/// whitespace run after it — the code's own proof that no `break` or
/// `continue` targets the name.
pub(crate) fn drop_label(text: &str, range: SourceRange) -> Option<(u32, u32, String)> {
    let (_, start, end) = word_slice(text, range)?;
    let (line_start, line_end) = line_bounds(text, start, end)?;
    let head_t = text[line_start..start].trim_end_matches([' ', '\t']);
    if !head_t.is_empty() && !head_t.ends_with(':') {
        return None;
    }
    let tail = &text[end..line_end];
    let tail_t = tail.trim_start_matches([' ', '\t']);
    let rest = tail_t.strip_prefix(':')?;
    let cut =
        (tail.len() - tail_t.len()) + 1 + (rest.len() - rest.trim_start_matches([' ', '\t']).len());
    Some((
        range.offset,
        range.length + u32::try_from(cut).ok()?,
        String::new(),
    ))
}

// ---------------------------------------------------------------------------
// Semantic source: the F6 written-surface family
//
// The semantic codes whose official fix is a single-span mechanical rewrite
// provable from the diagnostic's span, the file text, and the token stream —
// upstream Dart SDK source, `pkg/analysis_server/.../dart/`, producers named
// per row. The spans the engine emits anchor the rewrite: a keyword row
// carries the keyword's own range, an operator row the operator's, a
// declaration row the declared name's (the declarator/statement is rebuilt
// from the token stream). A hit whose slice does not verify its shape drops
// rather than patches.
// ---------------------------------------------------------------------------

/// `RemoveQuestionMark` over the reported type's `?` — the
/// `unnecessary_question_mark` row spans the `?` itself (the `Null?` /
/// `dynamic?` head), the `unnecessary_null_check_pattern` row the pattern
/// operator, and the `nullable_type_in_catch_clause` row the `name?` pair
/// (upstream `range.token(questionMark)` deletes the `?` alone in every
/// face; the span ends at it).
pub(crate) fn drop_type_question(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    if slice == "?" {
        return Some((input.range.start, 1, String::new()));
    }
    if slice.ends_with('?') && !slice[..slice.len() - 1].contains('?') {
        return Some((input.range.end - 1, 1, String::new()));
    }
    None
}

/// `RemoveNonNullAssertion` over the reported `!` — the expression face's
/// `range.entity(bangToken)` (the `!` alone) and the pattern face's
/// `startStart(bang, bang.next)` (the `!` plus its trivia run). The
/// `pattern` flag picks the producer's shape per row.
pub(crate) fn drop_bang(input: &FixInput<'_>, pattern: bool) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    if slice != "!" {
        return None;
    }
    if !pattern {
        return Some((input.range.start, 1, String::new()));
    }
    // The pattern face deletes the token plus the trivia run to the next
    // real token (comments ride `next`'s precedingComments edge).
    let start = utf16_offset_to_byte(text, input.range.start);
    let run = trivia_run(text.get(start + 1..)?);
    Some((
        input.range.start,
        1 + u32::try_from(run).ok()?,
        String::new(),
    ))
}

pub(crate) fn drop_bang_expression(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    drop_bang(input, false)
}

pub(crate) fn drop_bang_pattern(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    drop_bang(input, true)
}

/// `ReplaceWithNotNullAware`: the reported null-aware operator becomes its
/// non-aware form — `?.` → `.`, `?..` → `..`, and on the index face the
/// `?[` span's `?` alone goes (upstream `range.token(question)` deletes the
/// question, the `[` stays — `range.token(operator)` replaces the others).
/// The span slices to the operator exactly; any other text refuses.
pub(crate) fn not_null_aware_operator(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let replacement = match slice {
        "?." => ".",
        "?.." => "..",
        "?[" => return Some((input.range.start, 1, String::new())),
        "...?" => "...",
        _ => return None,
    };
    Some((
        input.range.start,
        u32::try_from(slice.len()).ok()?,
        replacement.to_owned(),
    ))
}

/// `type_check_with_null`: the reported `x is Null` / `x is! Null` becomes
/// `x == null` / `x != null` — the official `UseEqEqNull`/`UseNotEqNull`
/// producers append the comparison after the operand; the span here covers
/// the whole check, so the rewrite replaces the ` is Null` / ` is! Null`
/// tail in place (the operand's own text survives untouched).
pub(crate) fn is_null_to_eq_null(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let trimmed = slice.trim_end();
    let (head, eq) = if let Some(head) = trimmed.strip_suffix("is! Null") {
        (head, "!=")
    } else if let Some(head) = trimmed.strip_suffix("is Null") {
        (head, "==")
    } else {
        return None;
    };
    let head = head.trim_end();
    if head.is_empty() {
        return None;
    }
    let cut = input.range.start + utf16_count(head);
    Some((
        cut,
        input.range.start + u32::try_from(trimmed.len()).ok()? - cut,
        format!(" {eq} null"),
    ))
}

/// `ReplaceNewWithConst`: the reported `new` becomes `const` — the
/// `non_const_call_to_literal_constructor` row spans the whole `new`-led
/// creation; the keyword rides its head.
pub(crate) fn new_to_const(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if !slice.starts_with("new ") && slice != "new" {
        return None;
    }
    Some((input.range.start, 3, "const".to_owned()))
}

/// `RemoveConst` over the report's enclosing `const` — the
/// `non_constant_list_element` / `non_constant_map_element` /
/// `non_constant_set_element` / `const_eval_method_invocation` rows report
/// inside the `const` literal or creation the keyword heads (upstream
/// `_RemoveConst`'s `ExpressionImpl` arm resolves the `constantContext`'s
/// keyword). The token stream walks back from the hit to the depth-0
/// `const` heading the construct; the deletion runs `startStart(const,
/// const.next)` — trivia included (the family shares the
/// `RemoveUnnecessaryConst` deletion shape).
pub(crate) fn drop_enclosing_const(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _last) = hit_tokens(tokens, &input.range)?;
    // The literal's (or argument list's) own opener is the first
    // `[`/`{`/`(` reached walking back at depth 0 — inner groups jump
    // over their matching closer, so a `const` inside the literal never
    // surfaces.
    let mut cursor = first;
    let open = loop {
        let index = cursor.checked_sub(1)?;
        match kind_of(tokens, index)? {
            // The `const` heading the reported construct itself
            // (`const m()` — the invocation span follows the keyword).
            TokenKind::Keyword(Keyword::Const) => {
                let start16 = tokens.get(index)?.utf16_offset;
                return remove_keyword_across_comments(text, start16, "const");
            }
            TokenKind::CloseCurly | TokenKind::CloseSquare | TokenKind::CloseParen => {
                cursor = matching_begin(tokens, index)?;
            }
            TokenKind::OpenSquare | TokenKind::OpenCurly | TokenKind::OpenParen => break index,
            TokenKind::Semicolon | TokenKind::Eof => return None,
            _ => cursor = index,
        }
    };
    // The `const` heads the opener — `const [`, `const <int>[`, or the
    // creation's `const C(` where the walk crossed the name. A `<…>`
    // group or a name chain may sit between.
    let mut cursor = open;
    loop {
        let index = cursor.checked_sub(1)?;
        match kind_of(tokens, index)? {
            TokenKind::Keyword(Keyword::Const) => {
                let start16 = tokens.get(index)?.utf16_offset;
                return remove_keyword_across_comments(text, start16, "const");
            }
            TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt => {
                cursor = angle_group_start(tokens, index)?;
            }
            TokenKind::Identifier | TokenKind::Period => cursor = index,
            _ => return None,
        }
    }
}

/// `unnecessary_cast`: the ` as T` tail drops — the official
/// `RemoveUnnecessaryCast` deletes `endEnd(operand, asExpression)`; the
/// report spans the whole cast expression, so the cut is the ` as` run at
/// its tail (the deepest `as` at depth 0 binds last).
pub(crate) fn drop_as_cast(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    // The last depth-0 ` as ` in the span is the cast the code reports.
    // String literals and comments cannot carry the two-letter word at a
    // byte boundary we accept here — the span comes from the semantic
    // layer, so the `as` inside it is real.
    let mut cut = None;
    let bytes = slice.as_bytes();
    let mut i = 0usize;
    while i + 4 <= bytes.len() {
        if bytes[i] == b'a' && bytes[i + 1] == b's' {
            let before_ok = i == 0 || !is_identifier_char(bytes[i - 1] as char);
            let after_ok = !is_identifier_char(bytes[i + 2] as char);
            if before_ok && after_ok {
                cut = Some(i);
            }
        }
        i += 1;
    }
    let at = cut?;
    // The deletion runs from the whitespace before `as` through the type's
    // end (the span's own end).
    let mut lead = at;
    while lead > 0 && matches!(bytes[lead - 1], b' ' | b'\t') {
        lead -= 1;
    }
    let offset = input.range.start + utf16_count(&slice[..lead]);
    Some((offset, input.range.end - offset, String::new()))
}

/// `unnecessary_wildcard_pattern`: the `_` operand of a `&&` pattern goes
/// with its operator — a left operand cuts `startStart(parent,
/// rightOperand)` (the `_` through the `&&`), a right operand cuts
/// `endEnd(leftOperand, parent)` (the `&&` through the `_`; official
/// `RemoveUnnecessaryWildcardPattern`). The report spans the `_` itself;
/// parenthesized wraps ride inside it.
pub(crate) fn drop_wildcard_and_operand(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    let mut inner = slice.trim();
    while inner.starts_with('(') && inner.ends_with(')') {
        inner = inner[1..inner.len() - 1].trim();
    }
    if inner != "_" {
        return None;
    }
    let start = utf16_offset_to_byte(text, input.range.start);
    let end = utf16_offset_to_byte(text, input.range.end);
    if let Some(op) = text[..start].trim_end().strip_suffix("&&") {
        // Right operand: `endEnd(leftOperand, parent)` — the cut starts at
        // the left operand's own end, before the `&&` gap.
        let op16 = utf16_count(text[..op.len()].trim_end());
        return Some((op16, input.range.end - op16, String::new()));
    }
    let after = text[end..].trim_start();
    if let Some(with_op) = after.strip_prefix("&&") {
        // Left operand: cut the span through the `&&` and the run to the
        // next operand (`startStart(node, nextOperand)`).
        let gap = text[end..].len() - after.len();
        let trail = with_op.len() - with_op.trim_start().len();
        let tail = end + gap + 2 + trail;
        let length = utf16_count(&text[start..tail]);
        return Some((input.range.start, length, String::new()));
    }
    None
}

/// `wrong_number_of_type_arguments_constructor`: the misplaced `<…>` group
/// after a constructor's named segment moves onto the class name —
/// `C.named<int>()` → `C<int>.named()` (official `MoveTypeArgumentsToClass`
/// — its insertion-plus-deletion folds into the one contiguous replacement
/// the segment already is). The report spans the `<…>` group. A class name
/// already carrying type arguments refuses — the official's own guard.
pub(crate) fn move_type_args_to_class(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let lt = token_starting_at(tokens, input.range.start)?;
    if kind_of(tokens, lt)? != TokenKind::Lt {
        return None;
    }
    let gt = angle_group_end(tokens, lt)?;
    // The `<…>` follows `.ctor` — walk back over the constructor name and
    // the dot to the class identifier. A `<…>` already after it is the
    // official producer's own refuse shape.
    let ctor = lt.checked_sub(1)?;
    if !matches!(kind_of(tokens, ctor)?, TokenKind::Identifier) {
        return None;
    }
    if kind_of(tokens, ctor - 1)? != TokenKind::Period {
        return None;
    }
    let class = ctor - 2;
    if !matches!(kind_of(tokens, class)?, TokenKind::Identifier) {
        return None;
    }
    let args_end = utf16_end(tokens, text, gt)?;
    let class_end = utf16_end(tokens, text, class)?;
    let args = slice16(text, &(input.range.start..args_end))?;
    Some((
        class_end,
        args_end.checked_sub(class_end)?,
        format!("{args}.{}", tokens.lexeme(text, ctor)),
    ))
}

/// `RemoveNameFromDeclarationClause`: the reported name leaves its clause —
/// the whole clause when it is the only name (official
/// `range.deletionRange(clause)`), the name plus one adjacent comma
/// otherwise (`range.nodeInList`). `extends` drops the clause wholesale;
/// `implements`/`with`/`on` keep a lone name only when it is alone.
pub(crate) fn drop_clause_name(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _last) = hit_tokens(tokens, &input.range)?;
    // The reported name is one identifier (a prefixed `a.B` name spans two
    // — the producer drops the whole NamedType either way). The clause
    // keyword sits behind it: `extends`, `implements`, `with`, or `on`.
    let clause_kw = {
        let mut cursor = first;
        loop {
            let index = cursor.checked_sub(1)?;
            match kind_of(tokens, index)? {
                TokenKind::Keyword(
                    Keyword::Extends | Keyword::Implements | Keyword::With | Keyword::On,
                ) => break index,
                TokenKind::Comma | TokenKind::Identifier | TokenKind::Period => cursor = index,
                TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt => {
                    cursor = angle_group_start(tokens, index)?;
                }
                TokenKind::Question => cursor = index,
                _ => return None,
            }
        }
    };
    // The clause's name list: the dotted/generic names after the keyword,
    // comma-separated. A lone name drops the whole clause; a member of a
    // list drops itself with one adjacent comma (`nodeInList`).
    let name_end = |start: usize| -> Option<usize> {
        let mut tail = start;
        loop {
            match kind_of(tokens, tail + 1) {
                Some(TokenKind::Period) => tail += 2,
                Some(TokenKind::Lt) => tail = angle_group_end(tokens, tail + 1)?,
                _ => return Some(tail),
            }
        }
    };
    let mut count = 0usize;
    let mut scan = clause_kw + 1;
    loop {
        match kind_of(tokens, scan) {
            Some(TokenKind::Identifier | TokenKind::Keyword(_)) => count += 1,
            _ => break,
        }
        scan = name_end(scan)? + 1;
        if kind_of(tokens, scan) == Some(TokenKind::Comma) {
            scan += 1;
            continue;
        }
        break;
    }
    if count == 1 {
        // The whole clause goes — the keyword through the name's end.
        let start = utf16_end(tokens, text, clause_kw.checked_sub(1)?)?;
        let end = utf16_end(tokens, text, name_end(first)?)?;
        return Some((start, end.checked_sub(start)?, String::new()));
    }
    // A member of the list: `nodeInList` — a non-last name cuts
    // `startStart(node, next)` — through the next name's own start, comma
    // and gap included — the last name cuts `endEnd(previous, node)`.
    let end_tok = name_end(first)?;
    if kind_of(tokens, end_tok + 1) == Some(TokenKind::Comma) {
        let start = tokens.get(first)?.utf16_offset;
        let end = tokens.get(end_tok + 2)?.utf16_offset;
        return Some((start, end.checked_sub(start)?, String::new()));
    }
    // The last name: the preceding comma goes with it.
    let comma = {
        let mut c = first.checked_sub(1)?;
        while kind_of(tokens, c) == Some(TokenKind::Period)
            || matches!(
                kind_of(tokens, c),
                Some(TokenKind::Identifier | TokenKind::Keyword(_))
            )
            || matches!(
                kind_of(tokens, c),
                Some(TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt)
            )
        {
            if matches!(
                kind_of(tokens, c),
                Some(TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt)
            ) {
                c = angle_group_start(tokens, c)?;
            }
            c = c.checked_sub(1)?;
        }
        if kind_of(tokens, c) == Some(TokenKind::Comma) {
            c
        } else {
            return None;
        }
    };
    // `endEnd(previous, node)`: from the previous name's end — the gap
    // before its comma rides — through this name's end.
    let start = utf16_end(tokens, text, comma.checked_sub(1)?)?;
    let end = utf16_end(tokens, text, end_tok)?;
    Some((start, end.checked_sub(start)?, String::new()))
}

/// `duplicate_hidden_name` / `duplicate_shown_name` / `undefined_hidden_name` /
/// `undefined_shown_name`: the reported name leaves its `show`/`hide`
/// combinator (official `RemoveNameFromCombinator`'s
/// `rangeForNameInCombinator`). A listed name cuts `startStart(name, next)`
/// when it is not last and `endEnd(previous, name)` when it is; the clause's
/// only name takes the whole combinator down (`rangeForCombinator` — the
/// previous directive token's end through the clause's end, or the
/// neighboring combinator's edge when the directive carries several). The
/// report anchors the name token.
pub(crate) fn drop_combinator_name(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    // The combinator keyword sits behind the reported name across its
    // comma-separated siblings; the walk stops at the directive head.
    let keyword = {
        let mut cursor = first;
        loop {
            cursor = cursor.checked_sub(1)?;
            match kind_of(tokens, cursor)? {
                TokenKind::Keyword(Keyword::Show | Keyword::Hide) => break cursor,
                TokenKind::Identifier
                | TokenKind::Comma
                | TokenKind::Keyword(_)
                | TokenKind::String => {}
                TokenKind::CloseParen => cursor = matching_begin(tokens, cursor)?,
                _ => return None,
            }
        }
    };
    // The clause's name list: comma-separated names after the keyword, in
    // written order, with the reported name's position.
    let mut count = 0usize;
    let mut hit_index = None;
    let mut scan = keyword;
    let mut clause_last = keyword;
    loop {
        match kind_of(tokens, scan + 1)? {
            TokenKind::Identifier | TokenKind::Keyword(_) => {
                scan += 1;
                if scan == first {
                    hit_index = Some(count);
                }
                count += 1;
                clause_last = scan;
                if kind_of(tokens, scan + 1) == Some(TokenKind::Comma) {
                    scan += 1;
                    continue;
                }
                break;
            }
            _ => break,
        }
    }
    let hit_index = hit_index?;
    // Shape verification over the owning directive: behind the clause the
    // walk may cross only the directive's own tokens before its head
    // keyword, and past the clause end only further combinator keywords to
    // the `;` — `next_combinator` is the clause's right neighbor when one
    // stands there.
    let mut cursor = keyword;
    loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::Keyword(Keyword::Import | Keyword::Export) => break,
            TokenKind::Keyword(Keyword::Show | Keyword::Hide)
            | TokenKind::Identifier
            | TokenKind::Comma
            | TokenKind::Keyword(_)
            | TokenKind::String => {}
            TokenKind::CloseParen => cursor = matching_begin(tokens, cursor)?,
            _ => return None,
        }
    }
    let mut next_combinator = None;
    cursor = clause_last;
    loop {
        cursor += 1;
        match kind_of(tokens, cursor)? {
            TokenKind::Keyword(Keyword::Show | Keyword::Hide) => {
                next_combinator.get_or_insert(cursor);
            }
            TokenKind::Semicolon | TokenKind::Eof => break,
            _ => return None,
        }
    }
    // `endEnd(previous, last)`: the previous token's end through the last
    // token's end — the gap between them rides.
    let end_end = |previous: usize, last: usize| -> Option<(u32, u32, String)> {
        let start16 = utf16_end(tokens, text, previous)?;
        let end16 = utf16_end(tokens, text, last)?;
        Some((start16, end16.checked_sub(start16)?, String::new()))
    };
    // `startStart(first, last)`: the first token's start through the last
    // token's start.
    let start_start = |first: usize, last: usize| -> Option<(u32, u32, String)> {
        let start16 = tokens.get(first)?.utf16_offset;
        let end16 = tokens.get(last)?.utf16_offset;
        Some((start16, end16.checked_sub(start16)?, String::new()))
    };
    if count == 1 {
        // The whole combinator goes: `endEnd(previousToken, combinator)`
        // when it is the directive's only or last one — the previous
        // combinator's end is the token before this keyword then — and
        // `startStart(combinator, next)` before a following one.
        match next_combinator {
            None => end_end(keyword - 1, clause_last),
            Some(next) => start_start(keyword, next),
        }
    } else if hit_index + 1 < count {
        // Not the last name: `startStart(name, next)` — the next name's
        // own start bounds the cut, comma and gap included.
        start_start(first, first + 2)
    } else {
        // The last name: `endEnd(previous, name)` — the preceding name's
        // end through this name's end.
        end_end(first - 2, first)
    }
}

/// `override_on_non_overriding_member`: the `@override` annotation leaves —
/// the `@` through the trivia run to the next real token, stopping at that
/// token's attached comments (official `RemoveAnnotation`'s
/// `startStart(annotation, followingToken.precedingComments ?? followingToken)`
/// deletion over the member's metadata). The report anchors the member's
/// name; the walk back ends at the previous member's end.
pub(crate) fn remove_override_annotation(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    let at = {
        let mut cursor = first;
        loop {
            cursor = cursor.checked_sub(1)?;
            match kind_of(tokens, cursor)? {
                TokenKind::At if word_at(tokens, text, cursor + 1, "override") => break cursor,
                TokenKind::Semicolon
                | TokenKind::OpenCurly
                | TokenKind::CloseCurly
                | TokenKind::Eof => {
                    return None;
                }
                _ => {}
            }
        }
    };
    // The annotation's end token: a bare `@override` or one with an
    // argument list (`@override()`).
    let end_token = if kind_of(tokens, at + 2) == Some(TokenKind::OpenParen) {
        tokens.matching_end(at + 2)?
    } else {
        at + 1
    };
    let next = end_token + 1;
    if kind_of(tokens, next)? == TokenKind::Eof {
        return None;
    }
    let ann_end = token_end(tokens.get(end_token)?);
    let next_start = tokens.get(next)?.byte_offset as usize;
    // The run between two real tokens is trivia — whitespace and comments
    // only — so the first `/` is the attached comments' start, where the
    // official deletion stops.
    let cut = text
        .get(ann_end..next_start)?
        .find('/')
        .map_or(next_start, |i| ann_end + i);
    let start16 = tokens.get(at)?.utf16_offset;
    let cut16 = utf16_count(&text[..cut]);
    Some((start16, cut16.checked_sub(start16)?, String::new()))
}

/// `invocation_of_non_function_expression`: the `()` after the non-function
/// callee goes (official `RemoveParenthesesInGetterInvocation` — the parent
/// `FunctionExpressionInvocation`'s `range.node(argumentList)` deletion). The
/// report anchors the callee expression; a trailing type-argument group rides
/// it (`f<int>()`).
pub(crate) fn drop_getter_invocation_parens(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (_, mut last) = hit_tokens(tokens, &input.range)?;
    if matches!(
        kind_of(tokens, last)?,
        TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt
    ) {
        last = angle_group_start(tokens, last)?;
    }
    let open = last + 1;
    if kind_of(tokens, open)? != TokenKind::OpenParen {
        return None;
    }
    let close = tokens.matching_end(open)?;
    let start = tokens.get(open)?.utf16_offset;
    let end = utf16_end(tokens, text, close)?;
    Some((start, end.checked_sub(start)?, String::new()))
}

/// `missing_default_value_for_parameter`: `required ` lands at the
/// parameter's head (official `AddRequiredKeyword` — the insertion at the
/// parameter's first token after its metadata). A redundant `@required`
/// annotation folds into the replacement when it stands last in the
/// metadata (the official delete-then-insert is one contiguous span there);
/// annotations after it make the two edits disjoint and refuse. The
/// named-parameter face: the group opener must be `{` — the positional
/// shapes the shared registry name covers are `MakeVariableNullable`'s legs
/// and stay absent. The report anchors the parameter's name.
pub(crate) fn add_required_keyword(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    // The parameter head: walk back over the parameter's own tokens —
    // metadata with argument groups, modifiers, type — to the enclosing
    // group's boundary.
    let mut cursor = first;
    let boundary = loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                cursor = matching_begin(tokens, cursor)?;
            }
            TokenKind::Comma
            | TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly => break cursor,
            TokenKind::Eof => return None,
            _ => {}
        }
    };
    if kind_of(tokens, boundary)? != TokenKind::OpenCurly {
        return None;
    }
    // The metadata run: whole annotations from the boundary, then the
    // parameter's own first token. The walk recognizes the annotation
    // shapes (`@name`, `@name()`, `@p.name`, `@p.name<T>()`); anything else
    // ends the run.
    let annotation_end = |at: usize| -> Option<usize> {
        let mut cursor = at + 1;
        if kind_of(tokens, cursor + 1)? == TokenKind::Period {
            cursor += 2;
        }
        if kind_of(tokens, cursor + 1)? == TokenKind::Lt {
            cursor = tokens.matching_end(cursor + 1)?;
        }
        if kind_of(tokens, cursor + 1)? == TokenKind::OpenParen {
            cursor = tokens.matching_end(cursor + 1)?;
        }
        Some(cursor)
    };
    let mut scan = boundary;
    let mut required_at = None;
    loop {
        let next = scan + 1;
        if kind_of(tokens, next)? != TokenKind::At {
            break;
        }
        if word_at(tokens, text, next + 1, "required") {
            required_at = Some(next);
        }
        scan = annotation_end(next)?;
    }
    // The parameter's own first token — already `required` is the shape the
    // diagnostic cannot fire on.
    let head = scan + 1;
    if word_at(tokens, text, head, "required") {
        return None;
    }
    let insert_at = tokens.get(head)?.utf16_offset;
    let Some(at) = required_at else {
        return Some((insert_at, 0, "required ".to_owned()));
    };
    // The `@required` deletion folds in only when it stands last in the
    // metadata: its deletion end is then the insertion point.
    let end_token = annotation_end(at)?;
    if end_token + 1 != head {
        return None;
    }
    let start = tokens.get(at)?.utf16_offset;
    Some((start, insert_at.checked_sub(start)?, "required ".to_owned()))
}

/// `unreachable_switch_case` / `unreachable_switch_default`: the member's
/// lines go — the `case`/`default` head through its statements' end (the
/// official `RemoveDeadCode` `SwitchMember` arm deletes the member's
/// `deletionRange`; a previous member falling through keeps the statements
/// — the row's own head is the probe). The report anchors the `case` /
/// `default` keyword.
pub(crate) fn drop_switch_member(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let head = token_starting_at(tokens, input.range.start)?;
    match kind_of(tokens, head)? {
        TokenKind::Keyword(Keyword::Case | Keyword::Default) => {}
        _ => return None,
    }
    // The member's end: the next `case`/`default`/`}` at depth 0 — the
    // member's own `:`/`=>` opens its body, and the body's statements run
    // to the next member head or the switch's `}`.
    let mut cursor = head;
    let end = loop {
        cursor += 1;
        match kind_of(tokens, cursor)? {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                // A `{` at depth 0 in the member head position is a block
                // statement of the body — keep walking; the next case
                // keyword still ends the member.
                cursor = tokens.matching_end(cursor)?;
            }
            // The member ends before the switch's own `}` or the next
            // member head either way.
            TokenKind::CloseCurly | TokenKind::Keyword(Keyword::Case | Keyword::Default) => {
                break cursor;
            }
            TokenKind::Eof => return None,
            _ => {}
        }
    };
    // `case`/`default` head line through the line before the next head (or
    // the switch's `}`) — the lines the member occupies.
    let line_start = {
        let byte = utf16_offset_to_byte(text, input.range.start);
        text[..byte].rfind('\n').map_or(0, |i| i + 1)
    };
    let end_byte = utf16_offset_to_byte(
        text,
        if kind_of(tokens, end) == Some(TokenKind::CloseCurly)
            || matches!(
                kind_of(tokens, end),
                Some(TokenKind::Keyword(Keyword::Case | Keyword::Default))
            )
        {
            // The member ends before this token — the previous token's end.
            utf16_end(tokens, text, end.checked_sub(1)?)?
        } else {
            utf16_end(tokens, text, end)?
        },
    );
    let line_end = text[end_byte..]
        .find('\n')
        .map_or(text.len(), |i| end_byte + i);
    let (offset, length) = cut_line(text, line_start, line_end);
    Some((offset, length, String::new()))
}

/// `dead_code_on_catch_subtype`: the reported catch clause goes whole — the
/// official `RemoveDeadCode`'s `CatchClause` arm deletes
/// `endEnd(previous, clause)`, where `previous` is the try block or the
/// prior catch clause; the span lands on the clause's `on`/`catch` head.
pub(crate) fn drop_dead_catch(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let head = token_starting_at(tokens, input.range.start)?;
    // The clause head is `on` or `catch`; the clause runs through its
    // body's `}`.
    if !matches!(
        kind_of(tokens, head)?,
        TokenKind::Keyword(Keyword::On | Keyword::Catch)
    ) {
        return None;
    }
    // Find the clause body's `{`: the first depth-0 `{` after the head.
    let mut cursor = head;
    let body_open = loop {
        match kind_of(tokens, cursor)? {
            TokenKind::OpenCurly => break cursor,
            TokenKind::OpenParen | TokenKind::OpenSquare => {
                cursor = tokens.matching_end(cursor)?;
            }
            TokenKind::Eof | TokenKind::Semicolon => return None,
            _ => {}
        }
        cursor += 1;
    };
    let body_close = tokens.matching_end(body_open)?;
    // `endEnd(previous, clause)`: the previous sibling's end — the try
    // block's or a prior catch's `}` — through the clause's own `}`.
    let prev_end = utf16_end(tokens, text, head.checked_sub(1)?)?;
    let end = utf16_end(tokens, text, body_close)?;
    Some((prev_end, end.checked_sub(prev_end)?, String::new()))
}

/// `dead_null_aware_expression`: the dead right operand of a `??`/`??=`
/// goes — `endEnd(left, right)` on the binary face (the `?? rhs` tail), or
/// the whole expression statement on the `??=` bare-statement face
/// (official `RemoveDeadIfNull`). The report spans the right operand.
pub(crate) fn drop_dead_if_null(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _last) = hit_tokens(tokens, &input.range)?;
    // The `??`/`??=` sits before the right operand at depth 0.
    let mut cursor = first;
    let op = loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::QuestionQuestion | TokenKind::QuestionQuestionEq => break cursor,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                cursor = matching_begin(tokens, cursor)?;
            }
            TokenKind::Semicolon | TokenKind::Eof => return None,
            _ => {}
        }
    };
    if kind_of(tokens, op) == Some(TokenKind::QuestionQuestion) {
        // `endEnd(leftOperand, node)` — the cut starts at the left
        // operand's own end, before the `??` gap.
        let start = utf16_end(tokens, text, op.checked_sub(1)?)?;
        return Some((start, input.range.end.checked_sub(start)?, String::new()));
    }
    // `??=` — the official face deletes the whole statement when the
    // assignee is a bare identifier; otherwise `endEnd(lhs, rhs)`.
    let mut head = op;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev)? {
            TokenKind::Identifier | TokenKind::Keyword(_) | TokenKind::Period => head = prev,
            TokenKind::CloseSquare | TokenKind::CloseParen | TokenKind::CloseCurly => {
                head = matching_begin(tokens, prev)?;
            }
            _ => break,
        }
    }
    let assignee_text = span_over(text, tokens, head, op - 1)?;
    let assignee = slice16(text, &(assignee_text.0..assignee_text.0 + assignee_text.1))?;
    if !assignee.chars().all(is_identifier_char) || assignee.is_empty() {
        // Not a bare identifier — `endEnd(lhs, rhs)`: from the left side's
        // own end through the operand.
        let start = utf16_end(tokens, text, op.checked_sub(1)?)?;
        return Some((start, input.range.end.checked_sub(start)?, String::new()));
    }
    // Bare-identifier statement: the whole line range goes.
    drop_lines_range(text, assignee_text.0, input.range.end).map(|(o, l)| (o, l, String::new()))
}

/// `dead_code`: the reported dead interval goes — the official
/// `RemoveDeadCode` cuts `getLinesRange` when the interval heads a
/// statement run (a whole-line deletion), and `endEnd(leftOperand, node)`
/// when it starts mid-line on a short-cut operator's right operand
/// (`true || dead` — the operator rides the span's head and the cut
/// begins at the live operand's own end).
pub(crate) fn drop_dead_code(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    let end = utf16_offset_to_byte(text, input.range.end);
    if start >= end || end > text.len() {
        return None;
    }
    let line_head = text[..start].rfind('\n').map_or(0, |i| i + 1);
    if text[line_head..start].trim().is_empty() {
        // The interval heads its line — a statement run's lines-range.
        let (offset, length) = cut_line(
            text,
            line_head,
            text[end..].find('\n').map_or(text.len(), |i| end + i),
        );
        return Some((offset, length, String::new()));
    }
    // A mid-line head is the dead right operand's operator — the cut
    // starts at the left operand's end (`endEnd`), the token ending at or
    // before the span's own start.
    let tokens = input.tokens?;
    let mut cursor = token_starting_at(tokens, input.range.start)?;
    if !matches!(
        kind_of(tokens, cursor)?,
        TokenKind::AmpersandAmpersand | TokenKind::BarBar | TokenKind::QuestionQuestion
    ) {
        return None;
    }
    cursor = cursor.checked_sub(1)?;
    // Step back over the operand's own closers to its last real token —
    // `endEnd` reads the operand's end, and a parenthesized operand ends
    // at its `)`; the operand boundary is the token right before the
    // operator.
    let cut_start = utf16_end(tokens, text, cursor)?;
    Some((
        cut_start,
        input.range.end.checked_sub(cut_start)?,
        String::new(),
    ))
}

/// `unused_element`: the declared local function's whole declaration goes
/// (official `RemoveUnusedElement`'s lines-range deletion); the report
/// spans the name, so the head walks back to the declaration's first token
/// — return type included — and the tail runs through the body's `}`.
pub(crate) fn drop_unused_element(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let name = token_starting_at(tokens, input.range.start)?;
    if !matches!(
        kind_of(tokens, name)?,
        TokenKind::Identifier | TokenKind::Keyword(_)
    ) {
        return None;
    }
    // The declaration head: the previous `;`, `}`, or `{` bounds the
    // statement run — the declaration's first token.
    let mut head = name;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev)? {
            TokenKind::Semicolon | TokenKind::OpenCurly | TokenKind::CloseCurly => break,
            TokenKind::CloseParen | TokenKind::CloseSquare => {
                // A `)` behind the name belongs to an earlier construct —
                // a function declaration's own parameter list follows the
                // name, not before it.
                head = prev;
            }
            _ => head = prev,
        }
    }
    // The declaration's tail: the body's `}` (or a `;` for a declaration
    // without a body — a local function always carries a body). The name's
    // own `(` is the first one forward — no group sits between the name
    // and its parameter list.
    let mut params = name;
    let params = loop {
        params += 1;
        match kind_of(tokens, params)? {
            TokenKind::OpenParen => break params,
            // Generic parameter lists and `=>` bodies precede it.
            TokenKind::Semicolon | TokenKind::Eof => return None,
            _ => {}
        }
    };
    let params_close = tokens.matching_end(params)?;
    let mut body_open = params_close;
    let body_open = loop {
        body_open += 1;
        match kind_of(tokens, body_open)? {
            TokenKind::OpenCurly | TokenKind::Semicolon => break body_open,
            TokenKind::Eof => return None,
            _ => {}
        }
    };
    let end = if kind_of(tokens, body_open) == Some(TokenKind::OpenCurly) {
        tokens.matching_end(body_open)?
    } else {
        body_open
    };
    let head16 = tokens.get(head)?.utf16_offset;
    let end16 = utf16_end(tokens, text, end)?;
    let (offset, length) = drop_lines_range(text, head16, end16)?;
    Some((offset, length, String::new()))
}

/// `unused_field`: the reported field declaration's line goes — the
/// official `RemoveUnusedField`'s lines-range deletion. The report spans
/// the field's name; the declarator's own span (with its initializer and
/// one adjacent comma on a multi-declarator list) is rebuilt from the
/// tokens.
pub(crate) fn drop_unused_field(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let name = token_starting_at(tokens, input.range.start)?;
    if !matches!(kind_of(tokens, name)?, TokenKind::Identifier) {
        return None;
    }
    // The declarator's tail: `;` or `,` at depth 0.
    let mut tail = name;
    loop {
        match kind_of(tokens, tail)? {
            TokenKind::Semicolon => break,
            TokenKind::Comma => break,
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                tail = tokens.matching_end(tail)?;
            }
            TokenKind::Eof => return None,
            _ => {}
        }
        tail += 1;
    }
    // The declaration head: the first token after the previous `;`/`{`/`}`.
    let mut head = name;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev)? {
            TokenKind::Semicolon | TokenKind::OpenCurly | TokenKind::CloseCurly => break,
            _ => head = prev,
        }
    }
    if kind_of(tokens, tail) == Some(TokenKind::Comma) {
        // A non-last declarator: itself through the next declarator's
        // start goes — the official's `nodeInList` face (`startStart(node,
        // next)`). The list's modifiers and type stay with the survivors.
        let start = tokens.get(name)?.utf16_offset;
        let end = tokens.get(tail + 1)?.utf16_offset;
        return Some((start, end.checked_sub(start)?, String::new()));
    }
    if name > head && kind_of(tokens, name - 1) == Some(TokenKind::Comma) {
        // The last declarator of a multi-declarator list: `endEnd` of the
        // previous declarator through this one — the preceding comma's
        // gap rides with it.
        let start = utf16_end(tokens, text, name.checked_sub(2)?)?;
        let end = utf16_end(tokens, text, tail.checked_sub(1)?)?;
        return Some((start, end.checked_sub(start)?, String::new()));
    }
    // A lone declarator: the whole declaration's lines go.
    let head16 = tokens.get(head)?.utf16_offset;
    let end16 = utf16_end(tokens, text, tail)?;
    let (offset, length) = drop_lines_range(text, head16, end16)?;
    Some((offset, length, String::new()))
}

/// `unused_element_parameter`: the reported parameter leaves its list —
/// the official `RemoveUnusedParameter`'s faces: a lone parameter drops
/// the list's interior (`endStart(lparen, rparen)`), the first parameter
/// drops itself plus its comma (`startStart(parameter, following)`), the
/// lone member inside `[`/`{` drops with the delimiters, and the plain
/// case drops `endEnd(preceding, parameter)`.
pub(crate) fn drop_unused_parameter(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let name = token_starting_at(tokens, input.range.start)?;
    if !matches!(kind_of(tokens, name)?, TokenKind::Identifier) {
        return None;
    }
    // The enclosing parameter list's `(`: the nearest open paren before the
    // name whose group is still open at it.
    let mut open = None;
    let mut cursor = name;
    while let Some(index) = cursor.checked_sub(1) {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen => {
                open = Some(index);
                break;
            }
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                cursor = matching_begin(tokens, index)?;
                continue;
            }
            TokenKind::Semicolon | TokenKind::OpenCurly => break,
            _ => {}
        }
        cursor = index;
    }
    let open = open?;
    let close = tokens.matching_end(open)?;
    // The parameter's own extent: from its first token (type/modifiers
    // included) to its last — the depth-0 `,`/`]`/`}`/`)` bounds it.
    let mut first = name;
    while let Some(prev) = first.checked_sub(1) {
        if prev <= open {
            break;
        }
        match kind_of(tokens, prev)? {
            TokenKind::Comma | TokenKind::OpenSquare | TokenKind::OpenCurly => break,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                first = matching_begin(tokens, prev)?;
            }
            _ => first = prev,
        }
    }
    let mut last = name;
    loop {
        match kind_of(tokens, last + 1)? {
            TokenKind::Comma
            | TokenKind::CloseSquare
            | TokenKind::CloseCurly
            | TokenKind::CloseParen => break,
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                last = tokens.matching_end(last + 1)?;
            }
            TokenKind::Eof => return None,
            _ => last += 1,
        }
    }
    let is_delimiter = |i: usize| {
        matches!(
            kind_of(tokens, i),
            Some(
                TokenKind::OpenSquare
                    | TokenKind::OpenCurly
                    | TokenKind::CloseSquare
                    | TokenKind::CloseCurly
            )
        )
    };
    // The sibling parameter boundary: a `,` or the closer right after the
    // parameter's last token. No comma and no `[`/`{` delimiter at this
    // level means the parameter is the list's only member.
    let after = last + 1;
    let only_in_list = first == open + 1
        && kind_of(tokens, after) == Some(TokenKind::CloseParen)
        && !(open + 1..after)
            .any(|i| kind_of(tokens, i) == Some(TokenKind::Comma) || is_delimiter(i));
    if only_in_list {
        let start = utf16_end(tokens, text, open)?;
        let end16 = tokens.get(close)?.utf16_offset;
        return Some((start, end16.checked_sub(start)?, String::new()));
    }
    let prev_is_delim = first > open + 1 && is_delimiter(first - 1);
    if first == open + 1 || prev_is_delim {
        // First in its group: `param ,` goes — the comma's end through.
        if kind_of(tokens, after) == Some(TokenKind::Comma) {
            let start = tokens.get(first)?.utf16_offset;
            let end = utf16_end(tokens, text, after)?;
            return Some((start, end.checked_sub(start)?, String::new()));
        }
        // The lone member inside `[`/`{`: the delimiters ride the cut.
        if prev_is_delim && is_delimiter(after) {
            let start = utf16_end(tokens, text, first - 1)?;
            let end16 = tokens.get(after)?.utf16_offset;
            return Some((start, end16.checked_sub(start)?, String::new()));
        }
        return None;
    }
    // The plain case: `endEnd(preceding, parameter)` — from the previous
    // parameter's own end through this one's end.
    let mut prev = first - 1;
    if kind_of(tokens, prev) == Some(TokenKind::Comma) {
        prev = prev.checked_sub(1)?;
        // A `]`/`}`/`(` is a boundary, not a sibling parameter — the comma
        // before it belongs to this parameter's own cut.
        if is_delimiter(prev) || prev <= open {
            let start = tokens.get(prev + 1)?.utf16_offset;
            let end = utf16_end(tokens, text, last)?;
            return Some((start, end.checked_sub(start)?, String::new()));
        }
    }
    let prev_end = utf16_end(tokens, text, prev)?;
    let end = utf16_end(tokens, text, last)?;
    Some((prev_end, end.checked_sub(prev_end)?, String::new()))
}

/// `body_might_complete_normally_nullable`: `return null;` lands inside
/// the reported block — the official `AddReturnNull` insertion at the last
/// statement's end, or at the block's offset + 1 when it is empty. The
/// report spans the function/method declaration's head; the body's `{` is
/// rebuilt from the tokens.
pub(crate) fn add_return_null(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _last) = hit_tokens(tokens, &input.range)?;
    // The body's `{`: the first depth-0 `{` after the declaration head.
    let mut cursor = first;
    let body_open = loop {
        match kind_of(tokens, cursor)? {
            TokenKind::OpenCurly => break cursor,
            TokenKind::OpenParen | TokenKind::OpenSquare => {
                cursor = tokens.matching_end(cursor)?;
            }
            TokenKind::Semicolon | TokenKind::Eof | TokenKind::Function => return None,
            _ => {}
        }
        cursor += 1;
    };
    let body_close = tokens.matching_end(body_open)?;
    // The last statement before `}` — the insertion sits at its end; an
    // empty block inserts at `{` + 1 with the surrounding line's prefix.
    let eol = if text.contains("\r\n") { "\r\n" } else { "\n" };
    let open_end16 = utf16_end(tokens, text, body_open)?;
    let close_start16 = tokens.get(body_close)?.utf16_offset;
    // Statements between the braces?
    let has_statements = (body_open + 1..body_close).any(|i| {
        !matches!(kind_of(tokens, i), Some(TokenKind::Eof))
            && tokens.get(i).is_some_and(|t| t.byte_len > 0)
    });
    if has_statements {
        let last_end = utf16_end(tokens, text, body_close.checked_sub(1)?)?;
        // `utils.getNodePrefix(lastStatement)` — the last statement's own
        // line indent, reused for the new line.
        let indent = {
            let byte = utf16_offset_to_byte(text, last_end);
            let line_start = text[..byte].rfind('\n').map_or(0, |i| i + 1);
            let line = &text[line_start..byte];
            line[..line.len() - line.trim_start().len()].to_owned()
        };
        return Some((last_end, 0, format!("{eol}{indent}return null;")));
    }
    // Empty block: insert at `{` + 1 with the block's own line prefix plus
    // one indent level, and the close's line prefix after the statement.
    let open_byte = utf16_offset_to_byte(text, tokens.get(body_open)?.utf16_offset);
    let block_line_start = text[..open_byte].rfind('\n').map_or(0, |i| i + 1);
    let prefix: String = text[block_line_start..open_byte]
        .chars()
        .take_while(|c| c.is_whitespace())
        .collect();
    let one_indent = "  ";
    let _ = close_start16;
    Some((
        open_end16,
        0,
        format!("{eol}{prefix}{one_indent}return null;{eol}{prefix}"),
    ))
}

/// `unnecessary_null_comparison` / `unnecessary_nan_comparison` /
/// `unnecessary_type_check`: the reported comparison drops out of its
/// `&&`/`||` chain — official `RemoveComparison`'s operand-drop arm. The
/// chain operator's leg selects on the verdict polarity the message
/// carries (`always 'true'` chains on `&&`, `always 'false'` on `||`); a
/// non-last operand cuts `startStart(node, nextOperand)`, the last cuts
/// `endEnd(leftOperand, node)`. The `if`/`assert`/`conditional` parent
/// arms rewrite a wider construct and stay unserved.
pub(crate) fn drop_comparison_operand(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    // The verdict polarity lives in the message's `'true'`/`'false'`
    // display.
    let chain_op = if input.message.contains("'true'") {
        TokenKind::AmpersandAmpersand
    } else if input.message.contains("'false'") {
        TokenKind::BarBar
    } else {
        return None;
    };
    chain_operand_drop(input, chain_op)
}

/// `avoid_null_checks_in_equality_operators`: the reported null check
/// drops its `&&` flank — the official `RemoveComparison` hardcodes
/// `_conditionIsTrue` for this diagnostic, so only the `&&` chain arm of
/// [`drop_comparison_operand`] applies (the `||` face, the assert/if/?:
/// parents, and the `?.` face's not-null-aware rewrite are absent legs).
pub(crate) fn equality_null_operand(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    chain_operand_drop(input, TokenKind::AmpersandAmpersand)
}

/// The shared operand cut of `RemoveComparison`'s binary-expression arm:
/// the hit span is one operand of an `&&`/`||` chain — a non-last
/// operand cuts `startStart(node, nextOperand)`, the last operand cuts
/// `endEnd(prevOperand, node)`.
fn chain_operand_drop(input: &FixInput<'_>, chain_op: TokenKind) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    // A non-last operand: the same chain operator follows the span — the
    // cut runs to the next operand's own start (`startStart(node,
    // nextOperand)`).
    if kind_of(tokens, last + 1) == Some(chain_op) {
        let end = tokens.get(last + 2)?.utf16_offset;
        return Some((
            input.range.start,
            end.checked_sub(input.range.start)?,
            String::new(),
        ));
    }
    // The last operand: the chain operator precedes the span — the cut
    // runs from the previous operand's end (the operator's own start
    // minus its gap reads the same boundary).
    if first > 0 && kind_of(tokens, first - 1) == Some(chain_op) {
        let start = utf16_end(tokens, text, first - 2)?;
        return Some((start, input.range.end.checked_sub(start)?, String::new()));
    }
    None
}

// ---------------------------------------------------------------------------
// Semantic source: the null-check family
//
// The three nullable-value codes the engine emits, served against the
// official `AddNullCheck` producer (upstream Dart SDK source,
// pkg/analysis_server/lib/src/services/correction/fix_internal.dart). The
// edit inserts the non-null assertion at the producer's target expression
// or rewrites the chain's null-aware operator to its `!` form; the paren
// wrap below postfix precedence folds its two insertions into one
// whole-run replacement. The producer's assignability gate reads resolved
// types; this face reads the same gate off the diagnostic's message,
// which carries both type displays — the fix is offered only where the
// promoted `from` display is the `to` display, the nullable-only mismatch
// the gate serves.
// ---------------------------------------------------------------------------

/// The message-carried assignability gate: the pair of quoted type
/// displays behind `prefix`, accepted only when `from` reads as `to` plus
/// the trailing `?` — promote-to-non-null assignability, provable from
/// the displays alone.
fn promotable_pair(message: &str, prefix: &str) -> Option<()> {
    const MID: &str = " can't be assigned to ";
    // The prefix ends at the from-display's opening quote; the closing
    // quote bounds `from`, and the `to` display sits inside the next
    // quote pair behind the midriff (`a variable of type` /
    // `the parameter type`).
    let rest = message.strip_prefix(prefix)?;
    let from_end = rest.find('\'')?;
    let from = &rest[..from_end];
    let tail = rest.get(from_end + 1..)?;
    let mid = tail.find(MID)?;
    let after = tail.get(mid + MID.len()..)?;
    let to = after.get(after.find('\'')? + 1..)?;
    let to_end = to.find('\'')?;
    (from.strip_suffix('?')? == &to[..to_end]).then_some(())
}

/// The chain scan of a token run: a pure member chain (`primary
/// selector*` over `.`, `?.`, `?..`, postfix `!`, calls, indexes, and
/// generic-invocation type arguments) — `Chain` carries the rightmost
/// null-aware operator the official `_hasNullAware` walk returns;
/// anything else is `NotAChain`.
enum ChainScan {
    Chain { null_aware: Option<usize> },
    NotAChain,
}

fn scan_chain(tokens: &TokenTable, first: usize, last: usize) -> ChainScan {
    scan_chain_inner(tokens, first, last).unwrap_or(ChainScan::NotAChain)
}

/// The `Option`-shaped body of [`scan_chain`]: `None` is not-a-chain.
fn scan_chain_inner(tokens: &TokenTable, first: usize, last: usize) -> Option<ChainScan> {
    // The chain head: an identifier, a literal, one balanced group, or
    // one of the keywords that may stand as an expression's head
    // (`await`, `switch`, `const`, `throw` sit below postfix precedence
    // and take the paren wrap, never the chain).
    let mut cursor = match kind_of(tokens, first) {
        Some(
            TokenKind::Identifier
            | TokenKind::Int
            | TokenKind::Double
            | TokenKind::Hexadecimal
            | TokenKind::String,
        ) => first + 1,
        Some(TokenKind::Keyword(
            Keyword::This | Keyword::Super | Keyword::True | Keyword::False | Keyword::Null,
        )) => first + 1,
        Some(TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly) => {
            tokens.matching_end(first)? + 1
        }
        _ => return Some(ChainScan::NotAChain),
    };
    let mut null_aware = None;
    loop {
        if cursor > last {
            return Some(ChainScan::Chain { null_aware });
        }
        match kind_of(tokens, cursor)? {
            TokenKind::Period => {
                expect_member_name(tokens, cursor + 1)?;
                cursor += 2;
            }
            TokenKind::QuestionPeriod | TokenKind::QuestionPeriodPeriod => {
                expect_member_name(tokens, cursor + 1)?;
                null_aware = Some(cursor);
                cursor += 2;
            }
            // The null-aware index `?[…]` — the scanner splits the `?`.
            TokenKind::Question if kind_of(tokens, cursor + 1)? == TokenKind::OpenSquare => {
                null_aware = Some(cursor);
                cursor = tokens.matching_end(cursor + 1)? + 1;
            }
            TokenKind::Bang => cursor += 1,
            TokenKind::OpenParen | TokenKind::OpenSquare => {
                cursor = tokens.matching_end(cursor)? + 1;
            }
            // Generic invocation type arguments: `<…>` and the call that
            // must follow it.
            TokenKind::Lt => {
                let close = angle_group_end(tokens, cursor)?;
                if kind_of(tokens, close + 1)? != TokenKind::OpenParen {
                    return Some(ChainScan::NotAChain);
                }
                cursor = tokens.matching_end(close + 1)? + 1;
            }
            _ => return Some(ChainScan::NotAChain),
        }
    }
}

/// The property name a member operator must stand before (`a.new` keeps
/// the contextual keyword slot).
fn expect_member_name(tokens: &TokenTable, index: usize) -> Option<()> {
    matches!(
        kind_of(tokens, index)?,
        TokenKind::Identifier | TokenKind::Keyword(_)
    )
    .then_some(())
}

/// The replace face: the chain's null-aware operator goes to its `!` form
/// (the official `!${lexeme.substring(1)}` rewrite — `?.` → `!.`,
/// `?..` → `!..`, `?[` → `![`).
fn replace_null_aware(tokens: &TokenTable, text: &str, op: usize) -> Option<(u32, u32, String)> {
    let token = tokens.get(op)?;
    let replacement = match token.kind {
        TokenKind::QuestionPeriod | TokenKind::QuestionPeriodPeriod => {
            format!("!{}", &tokens.lexeme(text, op)[1..])
        }
        TokenKind::Question => "!".to_owned(),
        _ => return None,
    };
    Some((
        token.utf16_offset,
        utf16_count(tokens.lexeme(text, op)),
        replacement,
    ))
}

/// The append face: `!` lands at the target run's end; a run whose
/// precedence sits below postfix (anything but one member chain or one
/// balanced group) wraps in parentheses — the official producer's two
/// insertions folded into one whole-run replacement.
fn append_bang(input: &FixInput<'_>, first: usize, last: usize) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (start16, length16) = span_over(text, tokens, first, last)?;
    if matches!(scan_chain(tokens, first, last), ChainScan::Chain { .. }) {
        return Some((start16 + length16, 0, "!".to_owned()));
    }
    let slice = slice16(text, &(start16..start16 + length16))?;
    Some((start16, length16, format!("({slice})!")))
}

/// The shared target face: a run carrying the chain's null-aware operator
/// rewrites it, everything else takes the append face.
fn null_check_target(
    input: &FixInput<'_>,
    first: usize,
    last: usize,
) -> Option<(u32, u32, String)> {
    if let ChainScan::Chain {
        null_aware: Some(op),
    } = scan_chain(input.tokens?, first, last)
    {
        return replace_null_aware(input.tokens?, input.text, op);
    }
    append_bang(input, first, last)
}

/// The outermost depth-0 operator of a condition run — the binary tree's
/// root, rightmost of the loosest precedence among the ternary `?`, `??`,
/// `||`, `&&`, and `as` (left-associative roots sit rightmost). `None`
/// when none stands.
/// Whether a depth-0 `:` follows in `from..=last` — the mark that splits
/// a ternary `?` from a nullable type's `?` (as in `x as bool?`, whose
/// `?` is no operator at all).
fn has_depth0_colon(tokens: &TokenTable, from: usize, last: usize) -> Option<bool> {
    let mut depth = 0u32;
    for index in from..=last {
        match tokens.get(index)?.kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Colon if depth == 0 => return Some(true),
            _ => {}
        }
    }
    Some(false)
}

fn condition_root(
    tokens: &TokenTable,
    first: usize,
    last: usize,
) -> Option<(u8, TokenKind, usize)> {
    let mut best: Option<(u8, TokenKind, usize)> = None;
    let mut depth = 0u32;
    for index in first..=last {
        let token = tokens.get(index)?;
        match token.kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
        if depth != 0 {
            continue;
        }
        // A bare `?` is the ternary — the null-aware and `??` spellings
        // are their own token kinds, and `?[` the null-aware index. A `?`
        // with no depth-0 `:` behind it is a nullable type's (a ternary
        // always carries its colon), never an operator root.
        let (prec, kind) = match token.kind {
            TokenKind::Question
                if kind_of(tokens, index + 1)? != TokenKind::OpenSquare
                    && has_depth0_colon(tokens, index + 1, last)? =>
            {
                (1, TokenKind::Question)
            }
            TokenKind::QuestionQuestion => (2, TokenKind::QuestionQuestion),
            TokenKind::BarBar => (3, TokenKind::BarBar),
            TokenKind::AmpersandAmpersand => (4, TokenKind::AmpersandAmpersand),
            TokenKind::Keyword(Keyword::As) => (5, TokenKind::Keyword(Keyword::As)),
            _ => continue,
        };
        if best.is_none_or(|(bp, _, bi)| prec < bp || (prec == bp && index > bi)) {
            best = Some((prec, kind, index));
        }
    }
    best
}

/// `unchecked_use_of_nullable_value`: the official `AddNullCheck` over the
/// engine's condition face — the bare identifier condition, the
/// outermost `&&`/`||` root's left operand, and the `as` inner expression
/// take the producer's target (`!` at the target's end, or the chain's
/// null-aware operator rewritten); a `??` or ternary root resolves no
/// target in the official descent, and neither does any other shape (a
/// property-access condition among them).
pub(crate) fn null_check_condition(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if let ChainScan::Chain {
        null_aware: Some(op),
    } = scan_chain(tokens, first, last)
    {
        return replace_null_aware(tokens, input.text, op);
    }
    if first == last && kind_of(tokens, first)? == TokenKind::Identifier {
        return null_check_target(input, first, last);
    }
    let (_, kind, index) = condition_root(tokens, first, last)?;
    match kind {
        TokenKind::AmpersandAmpersand | TokenKind::BarBar | TokenKind::Keyword(Keyword::As) => {
            null_check_target(input, first, index.checked_sub(1)?)
        }
        _ => None,
    }
}

/// `invalid_assignment`: the official `AddNullCheck` assignment face —
/// the `!` lands at the right-hand side's end (wrapped below postfix
/// precedence) or the chain's null-aware operator goes `!`-form, gated on
/// the message's type-display pair. A right-hand side that is one
/// balanced group stays unfixed: the official fix reaches it only on the
/// statement-assignment face, which the row cannot tell apart from the
/// declaration face. The official kinds whose edits need resolved types
/// (`AddExplicitCast`, `ChangeTypeAnnotation`, `MakeVariableNullable`,
/// `AddAwait`, `AddMissingClosureParameters`) have no edit here.
pub(crate) fn null_check_assignment(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    promotable_pair(input.message, "A value of type '")?;
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if let ChainScan::Chain {
        null_aware: Some(op),
    } = scan_chain(tokens, first, last)
    {
        return replace_null_aware(tokens, text, op);
    }
    if kind_of(tokens, first)? == TokenKind::OpenParen && tokens.matching_end(first)? == last {
        return None;
    }
    append_bang(input, first, last)
}

/// `argument_type_not_assignable`: the official `AddNullCheck` argument
/// face, the same message gate — a bare-identifier argument takes the `!`
/// after it, an argument that is one member chain rewrites its
/// null-aware operator, and every other argument shape resolves no target
/// in the official descent (property-access and call arguments among
/// them).
pub(crate) fn null_check_argument(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    promotable_pair(input.message, "The argument type '")?;
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if let ChainScan::Chain {
        null_aware: Some(op),
    } = scan_chain(tokens, first, last)
    {
        return replace_null_aware(tokens, text, op);
    }
    if first == last && kind_of(tokens, first)? == TokenKind::Identifier {
        return append_bang(input, first, last);
    }
    None
}

// ---------------------------------------------------------------------------
// Token-verified rewrites
//
// The structural rewrites rebuild their replacement from the token
// stream: keyword and operator positions are quote-safe only there (a
// naive text scan would rewrite `'is'` or split on the `+` inside a
// string). Every rewriter re-verifies the shape its rule reports before
// composing — an unverifiable hit drops, never patches on faith.
// ---------------------------------------------------------------------------

/// The `[first, last]` token-index window of a hit range. Only real
/// tokens count — the scanner-recovery tail (the phantom bracket pair
/// behind the `[]` index token, `Eof`) is zero-width and unsorted, so a
/// binary search over the stream cannot close the window.
fn hit_tokens(tokens: &TokenTable, range: &core::ops::Range<u32>) -> Option<(usize, usize)> {
    let mut first = None;
    let mut last = None;
    for index in 0..tokens.as_slice().len() {
        let token = tokens.get(index)?;
        if token.byte_len == 0 || token.utf16_offset < range.start {
            continue;
        }
        if token.utf16_offset >= range.end {
            break;
        }
        if first.is_none() {
            first = Some(index);
        }
        last = Some(index);
    }
    Some((first?, last?))
}

/// The UTF-16 `[offset, length)` covering tokens `first..=last`.
fn span_over(text: &str, tokens: &TokenTable, first: usize, last: usize) -> Option<(u32, u32)> {
    let start = tokens.get(first)?.utf16_offset;
    let end = tokens.get(last)?.utf16_offset
        + u32::try_from(tokens.lexeme(text, last).encode_utf16().count()).ok()?;
    Some((start, end.checked_sub(start)?))
}

fn kind_of(tokens: &TokenTable, index: usize) -> Option<TokenKind> {
    tokens.get(index).map(|token| token.kind)
}

/// The token's byte-end position.
fn token_end(token: &dartq_scanner::Token) -> usize {
    token.byte_offset as usize + token.byte_len as usize
}

/// A word-shaped token with the exact lexeme (plain identifiers and
/// pseudo keywords both qualify — the scanner's split between
/// `Identifier` and contextual `Keyword` is contextual).
fn word_at(tokens: &TokenTable, text: &str, index: usize, word: &str) -> bool {
    matches!(
        kind_of(tokens, index),
        Some(TokenKind::Identifier | TokenKind::Keyword(_))
    ) && tokens.lexeme(text, index) == word
}

fn is_null_token(tokens: &TokenTable, index: usize) -> bool {
    kind_of(tokens, index) == Some(TokenKind::Keyword(Keyword::Null))
}

/// The first depth-0 token in `from..to` matching `pred`, over the `()`,
/// `[]`, `{}`, and `${}` nesting (`<` is not a group here — comparisons
/// and type arguments must not disturb the balance).
fn depth0_find(
    tokens: &TokenTable,
    text: &str,
    from: usize,
    to: usize,
    pred: impl Fn(TokenKind, &str) -> bool,
) -> Option<usize> {
    let mut depth = 0u32;
    for index in from..to {
        let token = tokens.get(index)?;
        match token.kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
        if depth == 0 && pred(token.kind, tokens.lexeme(text, index)) {
            return Some(index);
        }
    }
    None
}

/// Whether the token before `!(…)` lets the inner parentheses go: the
/// official face drops them when the `!` expression's parent binds looser
/// than relational — delimiters and statement heads, the assignment and
/// conditional families, the logical and equality operators, `is`/`as` —
/// and keeps them behind tighter-binding parents (selectors, prefix
/// operators, the relational and multiplicative arms).
fn paren_removable(kind: TokenKind) -> bool {
    match kind {
        TokenKind::Semicolon
        | TokenKind::OpenCurly
        | TokenKind::CloseCurly
        | TokenKind::OpenParen
        | TokenKind::OpenSquare
        | TokenKind::Comma
        | TokenKind::Colon
        | TokenKind::Question
        | TokenKind::Eq
        | TokenKind::PlusEq
        | TokenKind::MinusEq
        | TokenKind::StarEq
        | TokenKind::SlashEq
        | TokenKind::PercentEq
        | TokenKind::TildeSlashEq
        | TokenKind::LtLtEq
        | TokenKind::GtGtEq
        | TokenKind::GtGtGtEq
        | TokenKind::AmpersandEq
        | TokenKind::BarEq
        | TokenKind::CaretEq
        | TokenKind::QuestionQuestionEq
        | TokenKind::Function
        | TokenKind::AmpersandAmpersand
        | TokenKind::BarBar
        | TokenKind::QuestionQuestion
        | TokenKind::EqEq
        | TokenKind::BangEq => true,
        TokenKind::Keyword(kw) => matches!(
            kw,
            Keyword::Return
                | Keyword::Throw
                | Keyword::Yield
                | Keyword::Case
                | Keyword::In
                | Keyword::Else
                | Keyword::Do
                | Keyword::Is
                | Keyword::As
        ),
        _ => false,
    }
}

/// `!(x is T)` → `x is! T` (or `!(x is! T)` where the parentheses must
/// stay): the `!` goes and an `!` lands after the `is` — the official
/// `ConvertIntoIsNot` deletions and insertion folded into one
/// whole-span replacement.
pub(crate) fn is_not_operator(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if kind_of(tokens, first)? != TokenKind::Bang {
        return None;
    }
    let lparen = first + 1;
    if kind_of(tokens, lparen)? != TokenKind::OpenParen || tokens.matching_end(lparen)? != last {
        return None;
    }
    let is = depth0_find(tokens, text, lparen + 1, last, |kind, _| {
        kind == TokenKind::Keyword(Keyword::Is)
    })?;
    let is_end = token_end(tokens.get(is)?);
    let keep_parens = !first
        .checked_sub(1)
        .and_then(|index| tokens.get(index))
        .is_some_and(|prev| paren_removable(prev.kind));
    let (base, body_end) = if keep_parens {
        (token_end(tokens.get(first)?), token_end(tokens.get(last)?))
    } else {
        (
            token_end(tokens.get(lparen)?),
            tokens.get(last)?.byte_offset as usize,
        )
    };
    let body = &text[base..body_end];
    let at = is_end - base;
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((
        start16,
        length16,
        format!("{}!{}", &body[..at], &body[at..]),
    ))
}

/// The `(condition-op, non-null operand token range, then, else)` of a
/// null-check conditional — the shared read of the two null-aware
/// rewrites. The separators are the depth-0 `?` and `:` of the span.
type NullCheckParts = (
    TokenKind,
    core::ops::Range<usize>,
    core::ops::Range<usize>,
    core::ops::Range<usize>,
);

fn null_check_tokens(
    tokens: &TokenTable,
    text: &str,
    first: usize,
    last: usize,
) -> Option<NullCheckParts> {
    let question = depth0_find(tokens, text, first, last + 1, |kind, _| {
        kind == TokenKind::Question
    })?;
    // The conditional's own `:`: each depth-0 `?` after the first opens a
    // nested conditional (a bare conditional then-arm is legal), whose
    // `:` closes it before the outer's can appear.
    let mut depth = 0u32;
    let mut pending = 0u32;
    let mut colon = None;
    for index in question + 1..=last {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Question if depth == 0 => pending += 1,
            TokenKind::Colon if depth == 0 => {
                if pending == 0 {
                    colon = Some(index);
                    break;
                }
                pending -= 1;
            }
            _ => {}
        }
    }
    let colon = colon?;
    let op = depth0_find(tokens, text, first, question, |kind, _| {
        matches!(kind, TokenKind::EqEq | TokenKind::BangEq)
    })?;
    let operand = if is_null_token(tokens, op + 1) {
        first..op
    } else if op > first && is_null_token(tokens, op - 1) {
        op + 1..question
    } else {
        return None;
    };
    Some((
        kind_of(tokens, op)?,
        operand,
        question + 1..colon,
        colon + 1..last + 1,
    ))
}

/// The trimmed source text of a token range (an empty range is the empty
/// string).
fn token_text(tokens: &TokenTable, text: &str, range: core::ops::Range<usize>) -> Option<String> {
    if range.is_empty() {
        return Some(String::new());
    }
    let (start, length) = span_over(text, tokens, range.start, range.end - 1)?;
    text.get(utf16_offset_to_byte(text, start)..utf16_offset_to_byte(text, start + length))
        .map(str::trim)
        .map(str::to_owned)
}

/// Whether the token ranges hold the same lexeme sequence.
fn same_tokens(
    tokens: &TokenTable,
    text: &str,
    a: core::ops::Range<usize>,
    b: core::ops::Range<usize>,
) -> bool {
    a.len() == b.len()
        && !a.is_empty()
        && a.enumerate()
            .all(|(i, index)| tokens.lexeme(text, index) == tokens.lexeme(text, b.start + i))
}

/// `x == null ? a : x` → `x ?? a` (the official `ConvertToIfNull`
/// replacement text: nullable operand, `??`, default arm — parenthesized
/// when the arm is itself a bare conditional).
pub(crate) fn if_null_operators(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    let (op, operand, then_arm, else_arm) = null_check_tokens(tokens, text, first, last)?;
    let (nullable, default) = match op {
        TokenKind::EqEq => (else_arm, then_arm),
        _ => (then_arm, else_arm),
    };
    if !same_tokens(tokens, text, operand, nullable.clone()) {
        return None;
    }
    let default_text = token_text(tokens, text, default.clone())?;
    // A default whose precedence sits below `??` (a bare conditional —
    // the only such shape) needs its parentheses.
    let wrap = depth0_find(tokens, text, default.start, default.end, |kind, _| {
        kind == TokenKind::Question
    })
    .is_some();
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((
        start16,
        length16,
        format!(
            "{} ?? {}{}{}",
            token_text(tokens, text, nullable)?,
            if wrap { "(" } else { "" },
            default_text,
            if wrap { ")" } else { "" },
        ),
    ))
}

/// `x == null ? null : x.y` → `x?.y`: the arm's access chain peels back
/// to the null-check operand (the rule's own test, re-verified), the
/// peeled access goes null-aware — `.` becomes `?.`, a trailing `!`
/// becomes `?` (or vanishes when bare), an existing `?.` stays.
pub(crate) fn null_aware_operators(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    let (op, operand, then_arm, else_arm) = null_check_tokens(tokens, text, first, last)?;
    let result = match op {
        TokenKind::EqEq if is_null_token(tokens, then_arm.start) => else_arm,
        TokenKind::BangEq if is_null_token(tokens, else_arm.start) => then_arm,
        _ => return None,
    };
    let n = operand.len();
    if result.len() <= n
        || !same_tokens(
            tokens,
            text,
            operand.clone(),
            result.start..result.start + n,
        )
    {
        return None;
    }
    let receiver = token_text(tokens, text, operand)?;
    // The access right after the peeled receiver decides the rewrite.
    let after = result.start + n;
    let access = tokens.get(after)?;
    let arm_end = token_end(tokens.get(result.end - 1)?);
    let tail = &text[token_end(access)..arm_end];
    let rewritten = match access.kind {
        // The access token itself is excluded from `tail`: `.` and `?.`
        // both grow to `?.`, a trailing `!` becomes `?` (or vanishes when
        // nothing follows it).
        TokenKind::Period | TokenKind::QuestionPeriod => format!("{receiver}?.{tail}"),
        TokenKind::Bang => {
            if after + 1 == result.end {
                receiver
            } else {
                format!("{receiver}?{tail}")
            }
        }
        _ => return None,
    };
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((start16, length16, rewritten))
}

/// The value of the int literal at `index` (optionally negated by the
/// preceding `-`): decimal/hex with digit separators, the lint's own
/// `getIntValue` face.
fn int_literal_value(tokens: &TokenTable, text: &str, index: usize) -> Option<i64> {
    let (negative, at) = if kind_of(tokens, index) == Some(TokenKind::Minus) {
        (true, index + 1)
    } else {
        (false, index)
    };
    if kind_of(tokens, at) != Some(TokenKind::Int) {
        return None;
    }
    let lexeme = tokens.lexeme(text, at);
    let hex = lexeme.starts_with("0x") || lexeme.starts_with("0X");
    let digits: String = lexeme
        .trim_start_matches("0x")
        .trim_start_matches("0X")
        .chars()
        .filter(|&ch| ch != '_')
        .collect();
    i64::from_str_radix(&digits, if hex { 16 } else { 10 })
        .ok()
        .map(|value| if negative { -value } else { value })
}

/// The `indexOf` comparison rewrite (`x.indexOf(y) == -1` →
/// `!x.contains(y)`, the official `ConvertToContains`): the rewrite
/// matrix alone produces an edit — the always-true/false judgments get
/// none, exactly as the official producer returns without one.
pub(crate) fn contains_call(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    // The method-name `indexOf` is the last word followed by `(` (a
    // receiver's own `indexOf` call sits before it).
    let call = (first..last)
        .filter(|&index| word_at(tokens, text, index, "indexOf"))
        .rfind(|&index| kind_of(tokens, index + 1) == Some(TokenKind::OpenParen))?;
    let lparen = call + 1;
    let rparen = tokens.matching_end(lparen)?;
    // The start-index argument must be the literal 0 (the lint's own
    // gate) and is dropped from the rewrite.
    let comma = depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::Comma
    });
    let argument = match comma {
        Some(comma) => {
            let second = comma + 1..rparen;
            if second.len() != 1 || tokens.lexeme(text, second.start) != "0" {
                return None;
            }
            lparen + 1..comma
        }
        None => lparen + 1..rparen,
    };
    // The int literal sits on one side of the comparison operator; the
    // left-literal layout reads the operator with its operands swapped to
    // reach the matrix's `indexOf OP literal` layout.
    let left_literal = kind_of(tokens, first) == Some(TokenKind::Minus)
        || kind_of(tokens, first) == Some(TokenKind::Int);
    let is_comparison = |kind: Option<TokenKind>| {
        matches!(
            kind,
            Some(
                TokenKind::EqEq
                    | TokenKind::BangEq
                    | TokenKind::Lt
                    | TokenKind::LtEq
                    | TokenKind::Gt
                    | TokenKind::GtEq
            )
        )
    };
    let (value, effective, receiver_start) = if left_literal {
        // `-1 != x.indexOf(y)`: the operator sits after the literal, the
        // hit ends at the invocation.
        let op_index = if kind_of(tokens, first) == Some(TokenKind::Minus) {
            first + 2
        } else {
            first + 1
        };
        if !is_comparison(kind_of(tokens, op_index)) || rparen != last {
            return None;
        }
        let after_op = utf16_offset_to_byte(text, tokens.get(op_index + 1)?.utf16_offset);
        (
            int_literal_value(tokens, text, first)?,
            mirror_op(tokens.lexeme(text, op_index)).to_owned(),
            after_op,
        )
    } else {
        let op_index = rparen + 1;
        if op_index >= last || !is_comparison(kind_of(tokens, op_index)) {
            return None;
        }
        (
            int_literal_value(tokens, text, op_index + 1)?,
            tokens.lexeme(text, op_index).to_owned(),
            tokens.get(first)?.byte_offset as usize,
        )
    };
    let negated = match (value, effective.as_str()) {
        (-1, "==" | "<=") | (0, "<") => true,
        (-1, "!=" | ">") | (0, ">=") => false,
        _ => return None,
    };
    let argument_text = token_text(tokens, text, argument)?;
    let receiver = &text[receiver_start..tokens.get(call)?.byte_offset as usize];
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((
        start16,
        length16,
        format!(
            "{}{receiver}contains({argument_text})",
            if negated { "!" } else { "" }
        ),
    ))
}

/// The comparison operator read with its operands swapped (`a < b` ≡
/// `b > a`): the left-literal face canonicalizes to the matrix's layout.
fn mirror_op(op: &str) -> &str {
    match op {
        "<" => ">=",
        "<=" => ">",
        ">" => "<=",
        ">=" => "<",
        other => other,
    }
}

/// One merged interpolation component: a string literal's contents, a
/// bare identifier, or an arbitrary expression's source.
struct Component {
    text: String,
    identifier: bool,
}

pub(crate) fn compose_interpolation(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    // The chain's depth-0 `+` splits the operands.
    let mut operands: Vec<core::ops::Range<usize>> = Vec::new();
    let mut depth = 0u32;
    let mut start = first;
    for index in first..=last {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Plus if depth == 0 => {
                operands.push(start..index);
                start = index + 1;
            }
            _ => {}
        }
    }
    operands.push(start..last + 1);
    if operands.len() < 2 {
        return None;
    }
    let mut components = Vec::new();
    let mut style: Option<(u8, bool)> = None;
    for operand in operands {
        let (component, literal_style) = flatten_operand(tokens, text, operand.clone())?;
        match (style, literal_style) {
            (None, _) => style = literal_style,
            (Some(existing), Some(new)) if existing != new => return None,
            _ => {}
        }
        components.push(component);
    }
    let (quote, triple) = style?;
    let open = char::from(quote)
        .to_string()
        .repeat(if triple { 3 } else { 1 });
    // A bare identifier absorbs a following identifier-part head, so it
    // takes the braced form when the next component would continue it.
    let mut out = open.clone();
    for (index, component) in components.iter().enumerate() {
        let next_continues = components
            .get(index + 1)
            .and_then(|next| next.text.chars().next())
            .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '$');
        if component.identifier {
            if next_continues {
                out.push_str("${");
                out.push_str(&component.text);
                out.push('}');
            } else {
                out.push('$');
                out.push_str(&component.text);
            }
        } else {
            out.push_str(&component.text);
        }
    }
    out.push_str(&open);
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((start16, length16, out))
}

/// One operand of the `+` chain → its component (with the string style
/// when the operand is a literal). Adjacent strings flatten piece-wise,
/// `x.toString()` unwraps to `x`, parentheses unwrap — the official
/// `_extractComponentsInto` walk. Raw strings drop the whole fix.
fn flatten_operand(
    tokens: &TokenTable,
    text: &str,
    operand: core::ops::Range<usize>,
) -> Option<(Component, Option<(u8, bool)>)> {
    let first = operand.start;
    let last = operand.end - 1;
    match kind_of(tokens, first)? {
        TokenKind::String => {
            let lexeme = tokens.lexeme(text, first);
            if lexeme.starts_with('r') {
                return None;
            }
            let quote = *lexeme.as_bytes().first()?;
            // Adjacent strings: consecutive bare String tokens, each its
            // own literal piece — all sharing one quote style.
            let mut split = first;
            while split <= last && kind_of(tokens, split) == Some(TokenKind::String) {
                split += 1;
            }
            if split > last {
                let mut contents = String::new();
                for index in first..=last {
                    if string_style(tokens, text, index)?
                        != (quote, quote_is_triple(tokens, text, first)?)
                    {
                        return None;
                    }
                    contents.push_str(&segment_contents(tokens, text, index)?);
                }
                return Some((
                    Component {
                        text: contents,
                        identifier: false,
                    },
                    Some((quote, quote_is_triple(tokens, text, first)?)),
                ));
            }
            // An interpolated literal: `${…}` groups and segments to the
            // end, contents verbatim between the outer quote runs.
            let mut cursor = split;
            while cursor <= last {
                match kind_of(tokens, cursor)? {
                    TokenKind::String => cursor += 1,
                    TokenKind::StringInterpolationExpression => {
                        cursor = tokens.matching_end(cursor)? + 1;
                    }
                    _ => return None,
                }
            }
            let head = tokens.get(first)?.byte_offset as usize
                + quote_run(lexeme.as_bytes(), quote, false);
            let tail_lexeme = tokens.lexeme(text, last);
            let tail = tokens.get(last)?.byte_offset as usize + tail_lexeme.len()
                - quote_run(
                    tail_lexeme.as_bytes(),
                    *tail_lexeme.as_bytes().last()?,
                    true,
                );
            Some((
                Component {
                    text: text[head..tail].to_owned(),
                    identifier: false,
                },
                Some((quote, quote_run(lexeme.as_bytes(), quote, false) > 1)),
            ))
        }
        TokenKind::Identifier | TokenKind::Keyword(_) if first == last => Some((
            Component {
                text: tokens.lexeme(text, first).to_owned(),
                identifier: true,
            },
            None,
        )),
        _ => {
            // `x.toString()` unwraps to `x`; parentheses unwrap.
            if last >= first + 4
                && kind_of(tokens, last - 3) == Some(TokenKind::Period)
                && word_at(tokens, text, last - 2, "toString")
                && kind_of(tokens, last - 1) == Some(TokenKind::OpenParen)
                && kind_of(tokens, last) == Some(TokenKind::CloseParen)
            {
                return flatten_operand(tokens, text, first..last - 3);
            }
            if kind_of(tokens, first) == Some(TokenKind::OpenParen)
                && tokens.matching_end(first)? == last
            {
                return flatten_operand(tokens, text, first + 1..last);
            }
            let (start16, length16) = span_over(text, tokens, first, last)?;
            let slice = text.get(
                utf16_offset_to_byte(text, start16)..utf16_offset_to_byte(text, start16 + length16),
            )?;
            Some((
                Component {
                    text: slice.to_owned(),
                    identifier: false,
                },
                None,
            ))
        }
    }
}

/// The `(quote byte, is-triple)` style of a bare string segment.
fn string_style(tokens: &TokenTable, text: &str, index: usize) -> Option<(u8, bool)> {
    let _ = text;
    let lexeme = tokens.lexeme(text, index);
    let quote = if lexeme.starts_with('r') {
        *lexeme.as_bytes().get(1)?
    } else {
        *lexeme.as_bytes().first()?
    };
    Some((quote, quote_run(lexeme.as_bytes(), quote, false) > 1))
}

/// The triple-quote flag of the operand's head segment.
fn quote_is_triple(tokens: &TokenTable, text: &str, index: usize) -> Option<bool> {
    string_style(tokens, text, index).map(|(_, triple)| triple)
}

/// The contents of one bare string segment: the lexeme minus its outer
/// quote runs (escapes stay as written).
fn segment_contents(tokens: &TokenTable, text: &str, index: usize) -> Option<String> {
    let lexeme = tokens.lexeme(text, index);
    let quote = if lexeme.starts_with('r') {
        *lexeme.as_bytes().get(1)?
    } else {
        *lexeme.as_bytes().first()?
    };
    let lead = quote_run(lexeme.as_bytes(), quote, false);
    let trail = quote_run(lexeme.as_bytes(), quote, true);
    // The scanner's unterminated-string recovery emits a lexeme of pure
    // quote bytes (the synthetic closer is excluded) — the quote runs then
    // overlap and the slice would invert. Same posture as the raw-string
    // bail: the segment drops.
    if lead + trail > lexeme.len() {
        return None;
    }
    let start = tokens.get(index)?.byte_offset as usize;
    Some(text[start + lead..start + lexeme.len() - trail].to_owned())
}

/// `Map()` → `{}` (written type arguments ride along), `Set()` →
/// `<dynamic>{}` unless the context declares `Set`, `Set.from([…])` /
/// `Set.of([…])` and `[…].toSet()` → the set literal — the official
/// `ConvertToMapLiteral` / `ConvertToSetLiteral` replacements.
#[expect(clippy::too_many_lines)] // long diagnostic-table dispatch
pub(crate) fn collection_literal(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    // The `.toSet()` face: an optional type argument group, the list
    // literal, then `.toSet()`.
    let mut cursor = first;
    let mut head_args = String::new();
    if kind_of(tokens, cursor) == Some(TokenKind::Lt) {
        let close = tokens.matching_end(cursor)?;
        head_args = token_text(tokens, text, cursor..close + 1)?;
        cursor = close + 1;
    }
    // The `.toSet()` face: the target list literal — a `[…]` group, or
    // the scanner's single `[]` token for the empty literal — then
    // `.toSet()`.
    if matches!(
        kind_of(tokens, cursor),
        Some(TokenKind::OpenSquare | TokenKind::Index)
    ) {
        let (close, contents) = if kind_of(tokens, cursor) == Some(TokenKind::Index) {
            (cursor, String::new())
        } else {
            let close = tokens.matching_end(cursor)?;
            (close, token_text(tokens, text, cursor + 1..close)?)
        };
        if close + 4 == last
            && kind_of(tokens, close + 1) == Some(TokenKind::Period)
            && word_at(tokens, text, close + 2, "toSet")
            && kind_of(tokens, close + 3) == Some(TokenKind::OpenParen)
            && kind_of(tokens, last) == Some(TokenKind::CloseParen)
        {
            let unambiguous = !contents.is_empty() && !contents.starts_with("...");
            let prefix = if head_args.is_empty() && !unambiguous {
                "<dynamic>"
            } else {
                ""
            };
            let (start16, length16) = span_over(text, tokens, first, last)?;
            return Some((
                start16,
                length16,
                format!("{head_args}{prefix}{{{contents}}}"),
            ));
        }
        return None;
    }
    // The creation faces: the callee identifier (after an optional
    // `new`), its type arguments, then the constructor shape.
    let mut cursor = cursor.max(first);
    if kind_of(tokens, cursor) == Some(TokenKind::Keyword(Keyword::New)) {
        cursor += 1;
    }
    let name = tokens.lexeme(text, cursor).to_owned();
    if !matches!(
        kind_of(tokens, cursor),
        Some(TokenKind::Identifier | TokenKind::Keyword(_))
    ) || !matches!(
        name.as_str(),
        "Map" | "LinkedHashMap" | "Set" | "LinkedHashSet"
    ) {
        return None;
    }
    cursor += 1;
    // The written type arguments ride into the replacement, then the
    // constructor shape: `.from`/`.of` (the named face) or `(`.
    let mut ctor_args = String::new();
    if kind_of(tokens, cursor) == Some(TokenKind::Lt) {
        let close = tokens.matching_end(cursor)?;
        ctor_args = token_text(tokens, text, cursor..close + 1)?;
        cursor = close + 1;
    }
    let named = kind_of(tokens, cursor) == Some(TokenKind::Period)
        && (word_at(tokens, text, cursor + 1, "from") || word_at(tokens, text, cursor + 1, "of"));
    if named {
        cursor += 2;
    }
    if kind_of(tokens, cursor) != Some(TokenKind::OpenParen) {
        return None;
    }
    let close = tokens.matching_end(cursor)?;
    if !named {
        // The unnamed face: empty parentheses close the creation.
        if close != last || close != cursor + 1 {
            return None;
        }
        let prefix = match name.as_str() {
            "Set" | "LinkedHashSet"
                if !declares_set_context(tokens, text, first).unwrap_or(false) =>
            {
                "<dynamic>"
            }
            _ => "",
        };
        let (start16, length16) = span_over(text, tokens, first, last)?;
        return Some((start16, length16, format!("{ctor_args}{prefix}{{}}")));
    }
    // The single argument is a list literal — a `[…]` group or the
    // scanner's single `[]` token — and the argument list closes right
    // after it.
    let mut arg = cursor + 1;
    let mut list_args = String::new();
    if kind_of(tokens, arg) == Some(TokenKind::Lt) {
        let close = tokens.matching_end(arg)?;
        list_args = token_text(tokens, text, arg..close + 1)?;
        arg = close + 1;
    }
    let (close, elements) = match kind_of(tokens, arg) {
        Some(TokenKind::OpenSquare) => {
            let close = tokens.matching_end(arg)?;
            (close, token_text(tokens, text, arg + 1..close)?)
        }
        Some(TokenKind::Index) => (arg, String::new()),
        _ => return None,
    };
    if close + 1 != last || tokens.matching_end(cursor)? != last {
        return None;
    }
    let unambiguous = !elements.is_empty() && !elements.starts_with("...");
    let inferred = !ctor_args.is_empty()
        || !list_args.is_empty()
        || unambiguous
        || declares_set_context(tokens, text, first).unwrap_or(false);
    let prefix = if inferred { "" } else { "<dynamic>" };
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((
        start16,
        length16,
        format!("{ctor_args}{prefix}{{{elements}}}"),
    ))
}

/// Whether the creation sits in a declaration whose written type is
/// `Set` (`Set s = Set()`): the official inference face, read backwards
/// over the declaration shape `= name [type]`.
fn declares_set_context(tokens: &TokenTable, text: &str, first: usize) -> Option<bool> {
    let Some(at) = first
        .checked_sub(1)
        .filter(|&i| kind_of(tokens, i) == Some(TokenKind::Eq))
    else {
        return Some(false);
    };
    let Some(name) = at
        .checked_sub(1)
        .filter(|&i| kind_of(tokens, i) == Some(TokenKind::Identifier))
    else {
        return Some(false);
    };
    let mut cursor = name - 1;
    // Skip a type-argument group, then expect the type identifier.
    if matches!(
        kind_of(tokens, cursor),
        Some(TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt)
    ) {
        let mut depth = 0u32;
        loop {
            match kind_of(tokens, cursor)? {
                TokenKind::Gt => depth += 1,
                TokenKind::GtGt => depth += 2,
                TokenKind::GtGtGt => depth += 3,
                TokenKind::Lt => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
            cursor = cursor.checked_sub(1)?;
        }
        cursor = cursor.checked_sub(1)?;
    }
    Some(
        kind_of(tokens, cursor) == Some(TokenKind::Identifier)
            && tokens.lexeme(text, cursor) == "Set",
    )
}

/// `['a']..add(x)` → `['a', x]` (and the `addAll` literal form): the
/// cascade sections after the target compose into the literal — one
/// whole-tail replacement per cascade (the official insert-and-delete
/// pair folded; a section that is not `add`/`addAll` ends the tail and
/// stays put).
pub(crate) fn inlined_adds(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (name_index, _) = hit_tokens(tokens, range)?;
    let name = tokens.lexeme(text, name_index);
    if !matches!(name, "add" | "addAll")
        || kind_of(tokens, name_index + 1) != Some(TokenKind::OpenParen)
    {
        return None;
    }
    let lparen = name_index + 1;
    let rparen = tokens.matching_end(lparen)?;
    if depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::Comma
    })
    .is_some()
    {
        return None; // the official face takes exactly one argument
    }
    // Backwards: the cascade marker, then the target literal's `]`.
    match kind_of(tokens, name_index.checked_sub(1)?) {
        Some(TokenKind::PeriodPeriod | TokenKind::QuestionPeriodPeriod) => {}
        _ => return None,
    }
    let close_square = name_index - 2;
    // The target literal's `]`: a `[…]` group — or the scanner's single
    // `[]` token for the empty literal, its own opener and closer.
    let open_square = match kind_of(tokens, close_square) {
        Some(TokenKind::Index) => close_square,
        Some(TokenKind::CloseSquare) => {
            let mut depth = 0u32;
            let mut cursor = close_square;
            loop {
                cursor = cursor.checked_sub(1)?;
                match kind_of(tokens, cursor)? {
                    TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                        depth += 1;
                    }
                    TokenKind::OpenParen
                    | TokenKind::OpenCurly
                    | TokenKind::StringInterpolationExpression => depth = depth.checked_sub(1)?,
                    TokenKind::OpenSquare => {
                        if depth == 0 {
                            break cursor;
                        }
                        depth = depth.checked_sub(1)?;
                    }
                    _ => {}
                }
            }
        }
        _ => return None,
    };
    // The hit's own section opens the composition; the sections after it
    // follow while they are `add`/`addAll`.
    let target_nonempty = close_square > open_square + 1;
    let mut additions = vec![section_addition(tokens, text, name, lparen, rparen)?];
    let mut cursor = rparen;
    loop {
        let next = cursor + 1;
        if !matches!(
            kind_of(tokens, next),
            Some(TokenKind::PeriodPeriod | TokenKind::QuestionPeriodPeriod)
        ) {
            break;
        }
        let section = next + 1;
        let section_name = tokens.lexeme(text, section);
        if !matches!(section_name, "add" | "addAll")
            || kind_of(tokens, section + 1) != Some(TokenKind::OpenParen)
        {
            break;
        }
        let section_rparen = tokens.matching_end(section + 1)?;
        match section_addition(tokens, text, section_name, section + 1, section_rparen) {
            Some(addition) => {
                additions.push(addition);
                cursor = section_rparen;
            }
            None => break,
        }
    }
    let (start16, length16) = span_over(text, tokens, close_square, cursor)?;
    let joined = additions.join(", ");
    // The empty literal is one `[]` token: the whole literal is rewritten.
    let replacement = if close_square == open_square {
        format!("[{joined}]")
    } else {
        format!("{}{}]", if target_nonempty { ", " } else { "" }, joined)
    };
    Some((start16, length16, replacement))
}

/// The composed element source of one `add`/`addAll` section: the single
/// argument, or the list literal's elements for `addAll` (`None` when the
/// section is not the official face — multiple arguments, a non-literal
/// `addAll` argument, an empty one).
fn section_addition(
    tokens: &TokenTable,
    text: &str,
    name: &str,
    lparen: usize,
    rparen: usize,
) -> Option<String> {
    if depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::Comma
    })
    .is_some()
    {
        return None; // the official face takes exactly one argument
    }
    if name == "addAll" {
        if kind_of(tokens, lparen + 1) != Some(TokenKind::OpenSquare) {
            return None; // the spread rule's face, not ours
        }
        let sq = tokens.matching_end(lparen + 1)?;
        if sq + 1 != rparen {
            return None;
        }
        let elements = token_text(tokens, text, lparen + 2..sq)?;
        if elements.is_empty() {
            return None; // the official face returns without a fix here
        }
        Some(elements)
    } else {
        let argument = token_text(tokens, text, lparen + 1..rparen)?;
        if argument.is_empty() {
            return None;
        }
        Some(argument)
    }
}

/// `var f = () {};` → `void f() {}` (the official
/// `ConvertToFunctionDeclaration`, its resolution-free face): the
/// declaration prefix goes, the name keeps, the closure's parameters and
/// body follow the inferred-`void` return type (`Future<void>` under
/// `async`). Value-returning closures and expression bodies drop — their
/// return type is not derivable here.
pub(crate) fn function_declaration(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if kind_of(tokens, first) != Some(TokenKind::Identifier)
        || kind_of(tokens, first + 1) != Some(TokenKind::Eq)
        || kind_of(tokens, last + 1) != Some(TokenKind::Semicolon)
    {
        return None;
    }
    let name = tokens.lexeme(text, first);
    // The declaration prefix, walked backwards: `late`/`final`/`const`/
    // `var`, then the optional written type (dotted, nullable, with type
    // arguments) — a boundary that is not a statement edge drops the fix
    // (a sibling variable, a bare expression context).
    let mut cursor = first;
    while let Some(prev) = cursor
        .checked_sub(1)
        .and_then(|index| kind_of(tokens, index))
    {
        match prev {
            TokenKind::Question
            | TokenKind::Identifier
            | TokenKind::Keyword(
                Keyword::Final | Keyword::Const | Keyword::Var | Keyword::Late | Keyword::Function,
            ) => {}
            TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt => {
                let mut depth = 0u32;
                loop {
                    cursor -= 1;
                    match kind_of(tokens, cursor)? {
                        TokenKind::Gt => depth += 1,
                        TokenKind::GtGt => depth += 2,
                        TokenKind::GtGtGt => depth += 3,
                        TokenKind::Lt => {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        _ => {}
                    }
                }
            }
            _ => break,
        }
        cursor -= 1;
    }
    if let Some(boundary) = cursor.checked_sub(1)
        && !matches!(
            kind_of(tokens, boundary),
            Some(TokenKind::Semicolon | TokenKind::OpenCurly | TokenKind::CloseCurly)
        )
    {
        return None;
    }
    // The closure: the parameter list, an optional async marker after it,
    // then a block body without a value `return`.
    let scan = first + 2;
    if kind_of(tokens, scan) != Some(TokenKind::OpenParen) {
        return None;
    }
    let params_end = tokens.matching_end(scan)?;
    let mut return_type = "void ";
    let mut marker = params_end + 1;
    match kind_of(tokens, marker) {
        Some(TokenKind::Keyword(Keyword::Async)) => {
            return_type = "Future<void> ";
            marker += 1;
            if kind_of(tokens, marker) == Some(TokenKind::Star) {
                return None;
            }
        }
        Some(TokenKind::Keyword(Keyword::Sync)) => return None,
        _ => {}
    }
    if kind_of(tokens, marker) != Some(TokenKind::OpenCurly) {
        return None;
    }
    for index in first + 2..=last {
        if kind_of(tokens, index) == Some(TokenKind::Keyword(Keyword::Return))
            && kind_of(tokens, index + 1) != Some(TokenKind::Semicolon)
        {
            return None;
        }
    }
    let (start16, length16) = span_over(text, tokens, cursor, last + 1)?;
    let closure = &text
        [tokens.get(first + 2)?.byte_offset as usize..tokens.get(last + 1)?.byte_offset as usize];
    Some((start16, length16, format!("{return_type}{name}{closure}")))
}

// ---------------------------------------------------------------------------
// Breadth rewriters
//
// The table's mechanically-provable additions: each rewrites the span its
// diagnostic reports into the official producer's edit, re-verifying the
// reported shape first — an unverifiable hit drops, never patches on
// faith. Text-verified faces read the slice; structural faces read the
// token stream.
// ---------------------------------------------------------------------------

/// Whether the slice is an identifier shape: non-empty, not digit-led, all
/// Dart word characters (the drop-family rewrites' name proof).
fn word_shape(slice: &str) -> bool {
    let Some(first) = slice.chars().next() else {
        return false;
    };
    !first.is_ascii_digit()
        && slice
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$')
}

/// `empty_constructor_bodies`: the reported empty block is replaced with
/// `;` (the official `RemoveEmptyConstructorBody` replaces the body's
/// lines range with the semicolon, so `;` lands next to the parameter
/// list). The horizontal whitespace before `{` goes with it; a `{` that
/// opens its own line keeps the rest of that line (a trailing comment
/// survives where the official lines-range face would take it — a
/// cosmetic divergence left to the formatter). The `{…}` wrapper over an
/// empty interior is verified first — a comment inside is not this
/// rule's hit.
pub(crate) fn semicolon_body(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let range = &input.range;
    let inner = slice16(input.text, range)?
        .strip_prefix('{')?
        .strip_suffix('}')?;
    if !inner.trim_matches([' ', '\t', '\r', '\n']).is_empty() {
        return None;
    }
    let start = utf16_offset_to_byte(input.text, range.start);
    let head = input.text.get(..start)?;
    let ws = head.len() - head.trim_end_matches([' ', '\t']).len();
    let lead = u32::try_from(ws).ok()?;
    Some((
        range.start - lead,
        range.end - range.start + lead,
        ";".to_owned(),
    ))
}

/// `empty_statements`: two official faces. Alone on its line (the textual
/// shape of the official `RemoveEmptyStatement`'s `getLinesRange`
/// deletion) the whole line with its terminator goes; sharing a line with
/// other code, only the reported `;` goes — the lines range would take
/// the neighbors with it. A dangling construct body (`while (x) ;` — the
/// official `ReplaceWithBrackets` face, `parent is! Block`) becomes ` {}`
/// folded over the gap from the previous token, re-targeting the
/// construct at an empty block instead of the next statement.
pub(crate) fn drop_empty_statement(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    replace_exact(input.text, &input.range, ";", "")?;
    let tokens = input.tokens?;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if first != last {
        return None;
    }
    let start = utf16_offset_to_byte(input.text, input.range.start);
    let end = utf16_offset_to_byte(input.text, input.range.end);
    let line_start = input.text[..start].rfind('\n').map_or(0, |i| i + 1);
    let line_rest = input.text[end..].split(['\n', '\r']).next()?;
    if input.text[line_start..start]
        .trim_matches([' ', '\t'])
        .is_empty()
        && line_rest.trim_matches([' ', '\t']).is_empty()
    {
        // The cut carries the line's own terminator (the lines range'
        // end sits past the `\r\n` pair).
        let mut cut_end = end + line_rest.len();
        let rest_bytes = input.text.as_bytes();
        if rest_bytes.get(cut_end) == Some(&b'\r') {
            cut_end += 1;
        }
        if rest_bytes.get(cut_end) == Some(&b'\n') {
            cut_end += 1;
        }
        return Some((
            utf16_count(&input.text[..line_start]),
            utf16_count(&input.text[line_start..cut_end]),
            String::new(),
        ));
    }
    let head = input
        .text
        .get(..start)?
        .trim_end_matches([' ', '\t', '\r', '\n']);
    if head.ends_with(['{', '}', ';']) {
        return Some((
            input.range.start,
            input.range.end - input.range.start,
            String::new(),
        ));
    }
    // The brackets face: ` {}` replaces the gap plus the semicolon.
    let prev_end = token_end(tokens.get(first.checked_sub(1)?)?);
    Some((
        utf16_count(&input.text[..prev_end]),
        utf16_count(&input.text[prev_end..end]),
        " {}".to_owned(),
    ))
}

/// `use_rethrow_when_possible`: the reported `throw e` span is replaced
/// with `rethrow` (the official `UseRethrow` replaces the throw
/// expression). The `throw`-plus-one-identifier shape is verified first.
pub(crate) fn rethrow_span(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let range = &input.range;
    let rest = slice16(input.text, range)?.strip_prefix("throw")?;
    if !rest.starts_with([' ', '\t']) || !word_shape(rest.trim_matches([' ', '\t'])) {
        return None;
    }
    Some((range.start, range.end - range.start, "rethrow".to_owned()))
}

/// `prefer_is_not_empty`: the negated emptiness test loses its `!` and the
/// member gains the `Not` — `!x.isEmpty` → `x.isNotEmpty` (the official
/// `UseIsNotEmpty` deletes the operator and renames the property). The
/// `!…isEmpty` shape with the receiver's `.` before the name is verified
/// first.
pub(crate) fn is_not_empty_access(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let range = &input.range;
    let receiver = slice16(input.text, range)?
        .strip_prefix('!')?
        .strip_suffix("isEmpty")?;
    if !receiver.ends_with('.') {
        return None;
    }
    Some((
        range.start,
        range.end - range.start,
        format!("{receiver}isNotEmpty"),
    ))
}

/// `avoid_single_cascade_in_expression_statements`: the single section's
/// cascade operator becomes its `.`-equivalent (`..` → `.`, `?..` → `?.`;
/// the official `ReplaceCascadeWithDot` replaces the section's operator
/// token) — an index section keeps only the operator's null-aware prefix
/// (`..[0]` → `[0]`, `?..[0]` → `?[0]`, the official `_indexReplacement`).
/// The span's depth-0 cascade operator is the rewrite target — a nested
/// cascade inside the target expression never matches.
pub(crate) fn cascade_with_dot(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let mut depth = 0u32;
    let mut operator = None;
    for index in first..=last {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::PeriodPeriod | TokenKind::QuestionPeriodPeriod if depth == 0 => {
                operator = Some(index);
                break;
            }
            _ => {}
        }
    }
    let operator = operator?;
    let index_section = kind_of(tokens, operator + 1) == Some(TokenKind::OpenSquare);
    let dot = match (kind_of(tokens, operator)?, index_section) {
        (TokenKind::QuestionPeriodPeriod, true) => "?",
        (TokenKind::QuestionPeriodPeriod, false) => "?.",
        (_, true) => "",
        (_, false) => ".",
    };
    let (start16, length16) = span_over(text, tokens, first, last)?;
    let start = utf16_offset_to_byte(text, start16);
    let end = utf16_offset_to_byte(text, start16 + length16);
    let op_start = utf16_offset_to_byte(text, tokens.get(operator)?.utf16_offset);
    let op_end = token_end(tokens.get(operator)?);
    let mut replacement = String::with_capacity(end - start);
    replacement.push_str(text.get(start..op_start)?);
    replacement.push_str(dot);
    replacement.push_str(text.get(op_end..end)?);
    Some((start16, length16, replacement))
}

/// `unnecessary_to_list_in_spreads`: the reported `toList` name expands
/// back to its invocation and the whole `.toList(…)` leaves the spread
/// (the official `RemoveToList` deletes operator..argumentList). The
/// name, its `.` operator, and the argument list are verified against the
/// token stream; a null-aware `?.toList()` carries no `.` operator and
/// drops.
pub(crate) fn remove_to_list(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if first != last || !word_at(tokens, text, first, "toList") {
        return None;
    }
    let period = first.checked_sub(1)?;
    if kind_of(tokens, period)? != TokenKind::Period {
        return None;
    }
    let mut cursor = first + 1;
    if kind_of(tokens, cursor)? == TokenKind::Lt {
        cursor = tokens.matching_end(cursor)? + 1;
    }
    if kind_of(tokens, cursor)? != TokenKind::OpenParen {
        return None;
    }
    let rparen = tokens.matching_end(cursor)?;
    let (start16, length16) = span_over(text, tokens, period, rparen)?;
    Some((start16, length16, String::new()))
}

/// `prefer_is_empty`: the `length` comparison rewrites to the emptiness
/// getter (the official `ReplaceWithIsEmpty` matrix). The int literal
/// sits on one side of the depth-0 comparison, the `length` access on the
/// other; the replacement keeps everything through the access's period
/// (the official face keeps the receiver verbatim). The always-true/false
/// judgments the lint reports without a correction get no edit, exactly
/// as the official producer returns without one.
pub(crate) fn is_empty_call(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let op = depth0_find(tokens, text, first, last + 1, |kind, _| {
        matches!(
            kind,
            TokenKind::EqEq
                | TokenKind::BangEq
                | TokenKind::Lt
                | TokenKind::LtEq
                | TokenKind::Gt
                | TokenKind::GtEq
        )
    })?;
    // The literal run is exactly the literal (its leading `-` included);
    // the right-literal layout reads first, the official producer's order.
    let literal_run = |run: core::ops::Range<usize>| -> Option<i64> {
        let negative = kind_of(tokens, run.start) == Some(TokenKind::Minus);
        if run.len() != usize::from(negative) + 1 {
            return None;
        }
        int_literal_value(tokens, text, run.start)
    };
    let (value, access, literal_on_right) = if let Some(value) = literal_run(op + 1..last + 1) {
        (value, first..op, true)
    } else if let Some(value) = literal_run(first..op) {
        (value, op + 1..last + 1, false)
    } else {
        return None;
    };
    // The access ends `… . length` — a null-aware `?.` access has no
    // provable emptiness getter and drops.
    let length = access.end - 1;
    if length == access.start
        || !word_at(tokens, text, length, "length")
        || kind_of(tokens, length.checked_sub(1)?)? != TokenKind::Period
    {
        return None;
    }
    let getter = match (value, literal_on_right, tokens.lexeme(text, op)) {
        (0, true, "==" | "<=") | (1, true, "<") => "isEmpty",
        (0, true, ">" | "!=") | (1, true, ">=") => "isNotEmpty",
        (0, false, "==" | ">=") | (1, false, ">") => "isEmpty",
        (0, false, "<" | "!=") | (1, false, "<=") => "isNotEmpty",
        _ => return None,
    };
    let (start16, length16) = span_over(text, tokens, first, last)?;
    let access_start = utf16_offset_to_byte(text, tokens.get(access.start)?.utf16_offset);
    let length_start = utf16_offset_to_byte(text, tokens.get(length)?.utf16_offset);
    let receiver = text.get(access_start..length_start)?;
    Some((start16, length16, format!("{receiver}{getter}")))
}

/// Whether the token run is an identifier chain — `a`, `a.b`, `a.b.c` —
/// the assignable-target shape the conditional-assignment rewrite keeps
/// (`this`/`super` receivers, index and invocation targets are refused).
fn is_identifier_chain(tokens: &TokenTable, run: core::ops::Range<usize>) -> bool {
    !run.is_empty()
        && run.len() % 2 == 1
        && (0..run.len()).all(|offset| {
            let kind = kind_of(tokens, run.start + offset);
            if offset % 2 == 0 {
                matches!(kind, Some(TokenKind::Identifier))
            } else {
                kind == Some(TokenKind::Period)
            }
        })
}

/// `prefer_conditional_assignment`: the null-check `if` becomes the
/// null-aware assignment (`if (a == null) a = b;` → `a ??= b;` — the
/// official `ReplaceWithConditionalAssignment` replaces the whole
/// statement). The condition's depth-0 `==` splits the checked operand
/// from the `null` literal (either order), and the then arm is one
/// `operand = value` statement, bare or single-statement block; the
/// operand must be an identifier chain matching the assignment's target.
/// A dangling `else` refuses the bare arm — the rewrite never absorbs it.
pub(crate) fn conditional_assignment(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if !word_at(tokens, text, first, "if") {
        return None;
    }
    let lparen = first + 1;
    if kind_of(tokens, lparen)? != TokenKind::OpenParen {
        return None;
    }
    let rparen = tokens.matching_end(lparen)?;
    let eq = depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::EqEq
    })?;
    let operand = if is_null_token(tokens, eq + 1) && eq + 2 == rparen {
        lparen + 1..eq
    } else if eq == lparen + 2 && is_null_token(tokens, eq - 1) {
        eq + 1..rparen
    } else {
        return None;
    };
    if !is_identifier_chain(tokens, operand.clone()) {
        return None;
    }
    // The then arm: a bare expression statement ending at the span's `;`
    // (the first depth-0 `;` from the arm on is the final token — no
    // `else` precedes), or a single-statement block: the `}` ends the
    // span, the statement's `;` sits right behind it, and no other `;`
    // separates the braces — exactly one statement.
    let statement = match kind_of(tokens, rparen + 1)? {
        TokenKind::OpenCurly => {
            let close = tokens.matching_end(rparen + 1)?;
            if close != last || kind_of(tokens, close - 1)? != TokenKind::Semicolon {
                return None;
            }
            if depth0_find(tokens, text, rparen + 2, close - 1, |kind, _| {
                kind == TokenKind::Semicolon
            })
            .is_some()
            {
                return None;
            }
            rparen + 2..close - 1
        }
        _ if kind_of(tokens, last)? == TokenKind::Semicolon => {
            if depth0_find(tokens, text, rparen + 1, last + 1, |kind, _| {
                kind == TokenKind::Semicolon
            }) != Some(last)
            {
                return None;
            }
            rparen + 1..last
        }
        _ => return None,
    };
    let eq_assign = depth0_find(tokens, text, statement.start, statement.end, |kind, _| {
        kind == TokenKind::Eq
    })?;
    let rhs = eq_assign + 1..statement.end;
    if rhs.is_empty() || !same_tokens(tokens, text, operand.clone(), statement.start..eq_assign) {
        return None;
    }
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((
        start16,
        length16,
        format!(
            "{} ??= {};",
            token_text(tokens, text, operand)?,
            token_text(tokens, text, rhs)?,
        ),
    ))
}

/// The shared deletion face of a construct reported over its whole span
/// (`unnecessary_breaks`, `unnecessary_library_directive`): the official
/// producers delete the construct's lines range — alone on its line (or
/// lines), the cut takes the line(s) through the terminator (the
/// [`remove_null_aware_assignment`]-shaped whole-line face); sharing a
/// line with a sibling, the cut takes exactly the reported span plus its
/// leading horizontal whitespace, the same-line deletion face of
/// [`drop_import_directive`].
fn drop_span_statement(text: &str, range: &core::ops::Range<u32>) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, range.start);
    let end = utf16_offset_to_byte(text, range.end);
    if let Some((line_start, line_end)) = line_bounds(text, start, end)
        && text[line_start..start]
            .bytes()
            .all(|b| matches!(b, b' ' | b'\t' | b'\r'))
        && text[end..line_end]
            .bytes()
            .all(|b| matches!(b, b' ' | b'\t' | b'\r'))
    {
        let (offset, length) = cut_line(text, line_start, line_end);
        return Some((offset, length, String::new()));
    }
    let ws = text[..start].len() - text[..start].trim_end_matches([' ', '\t']).len();
    let lead = u32::try_from(ws).ok()?;
    Some((
        range.start - lead,
        range.end - range.start + lead,
        String::new(),
    ))
}

/// `unnecessary_breaks`: the trailing `break;` of a multi-statement case
/// leaves (the official `RemoveBreak` deletes the statement's lines
/// range, [`drop_span_statement`]'s shape). The reported statement span
/// must slice to `break` + whitespace + `;` before anything is cut.
pub(crate) fn drop_break_statement(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let body = slice.trim_matches([' ', '\t']);
    if body != "break;" {
        return None;
    }
    drop_span_statement(input.text, &input.range)
}

/// `unnecessary_library_directive`: the bare `library` directive's line
/// leaves (the official `RemoveUnnecessaryLibraryDirective` deletes the
/// directive's lines range, [`drop_span_statement`]'s shape). The span
/// must slice to the `library …;` directive before anything is cut.
pub(crate) fn drop_library_directive(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let trimmed = slice.trim_matches([' ', '\t', '\r', '\n']);
    if !trimmed.starts_with("library")
        || trimmed[7..].starts_with(|c: char| c.is_ascii_alphanumeric() || c == '_' || c == '$')
        || !trimmed.ends_with(';')
    {
        return None;
    }
    drop_span_statement(input.text, &input.range)
}

/// `unnecessary_parenthesis`: the two parentheses leave and the inner
/// expression keeps verbatim (the official `RemoveUnnecessaryParentheses`
/// deletes the paren tokens). The span's first and last tokens must be
/// the matching `(`/`)` pair — a drifted hit over anything else drops.
pub(crate) fn drop_parentheses(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if kind_of(tokens, first)? != TokenKind::OpenParen || tokens.matching_end(first)? != last {
        return None;
    }
    let inner = text.get(
        utf16_offset_to_byte(text, range.start + 1)..utf16_offset_to_byte(text, range.end - 1),
    )?;
    // The whole span goes to the inner text: one edit carries both
    // deletions (the official `RemoveParentheses` deletes the two paren
    // tokens).
    Some((range.start, range.end - range.start, inner.to_owned()))
}

/// `unnecessary_null_checks`: the `!` leaves (the official
/// `RemoveNonNullAssertion` deletes the bang token). The reported span is
/// either the bare `!` operator or the whole postfix spelling ending in
/// it — both verify before the deletion.
pub(crate) fn drop_non_null_assertion(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let range = &input.range;
    if slice16(input.text, range)? == "!" {
        return Some((range.start, 1, String::new()));
    }
    if !slice16(input.text, range)?.ends_with('!') {
        return None;
    }
    Some((range.end - 1, 1, String::new()))
}

/// `eol_at_end_of_file`: a missing newline is inserted at the text end
/// and a trailing newline run collapses to one (the official
/// `AddEolAtEndOfFile` insertion / replacement — the replacement always
/// spells one `\n`, never a `\r\n` pair). The report anchors the trimmed
/// end; the fix reads the tail itself.
pub(crate) fn add_eol(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    if text.ends_with("\n\n") || text.ends_with("\r\r") || text.ends_with("\r\n\r\n") {
        let run_start = text.trim_end_matches(['\n', '\r']).len();
        return Some((
            utf16_count(&text[..run_start]),
            utf16_count(&text[run_start..]),
            "\n".to_owned(),
        ));
    }
    if text.ends_with('\n') || text.ends_with('\r') {
        return None; // exactly one newline — the shape the lint never reports
    }
    Some((utf16_count(text), 0, "\n".to_owned()))
}

/// `noop_primitive_operations`: the typed-invocation face — `.name(…)`,
/// `?..name(…)` leaves its receiver (the official `RemoveInvocation`
/// deletes operator..argumentList; the adjacent-strings face reports a
/// literal and gets no edit there, mirrored by the name-shape refusal).
/// The reported span is the method-name token; the operator run and the
/// argument list are verified against the token stream.
pub(crate) fn remove_invocation(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if first != last
        || !matches!(
            kind_of(tokens, first)?,
            TokenKind::Identifier | TokenKind::Keyword(_)
        )
    {
        return None;
    }
    let op = first.checked_sub(1)?;
    if !matches!(
        kind_of(tokens, op)?,
        TokenKind::Period
            | TokenKind::QuestionPeriod
            | TokenKind::PeriodPeriod
            | TokenKind::QuestionPeriodPeriod
    ) {
        return None;
    }
    let mut cursor = first + 1;
    if kind_of(tokens, cursor)? == TokenKind::Lt {
        cursor = tokens.matching_end(cursor)? + 1;
    }
    if kind_of(tokens, cursor)? != TokenKind::OpenParen {
        return None;
    }
    let rparen = tokens.matching_end(cursor)?;
    let (start16, length16) = span_over(text, tokens, op, rparen)?;
    Some((start16, length16, String::new()))
}

/// `unnecessary_unawaited`: the bare `unawaited(…)` wrapper leaves its
/// argument verbatim (the official `RemoveUnawaited` deletes the name
/// through the left parenthesis and the right parenthesis — the argument
/// text is never touched). The rule only reports bare invocations, so
/// the name is the span head and no operator precedes it.
pub(crate) fn remove_unawaited(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if first != last || tokens.lexeme(text, first) != "unawaited" {
        return None;
    }
    let mut cursor = first + 1;
    if kind_of(tokens, cursor)? == TokenKind::Lt {
        cursor = tokens.matching_end(cursor)? + 1;
    }
    if kind_of(tokens, cursor)? != TokenKind::OpenParen {
        return None;
    }
    let rparen = tokens.matching_end(cursor)?;
    let inner =
        text.get(token_end(tokens.get(cursor)?)..tokens.get(rparen)?.byte_offset as usize)?;
    let (start16, length16) = span_over(text, tokens, first, rparen)?;
    Some((start16, length16, inner.to_owned()))
}

/// `unnecessary_final`: the reported `final` keyword either leaves (a
/// written type follows — the official `ReplaceFinalWithVar`'s
/// `RemoveUnnecessaryFinal` face) or becomes `var` (a pattern
/// declaration or a typeless variable — the `ReplaceFinalWithVar` face).
/// The head walk after the keyword reads which shape follows: an
/// identifier-chain head (`int`, `core.int`, `List<int>`, `int?`,
/// `int Function(int)`, a record type group) followed by another
/// identifier word is the type; anything ending at `=`, `,`, `;`, `in`,
/// or a pattern opener (`(`-group, `[`, `{`) is the name/pattern. A
/// verdict the walk cannot read drops the fix.
pub(crate) fn final_to_var(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if first != last || kind_of(tokens, first)? != TokenKind::Keyword(Keyword::Final) {
        return None;
    }
    let mut cursor = first + 1;
    // The type head: identifier chains with type arguments, nullability,
    // dotted names, `Function` suffixes, and record groups.
    if matches!(kind_of(tokens, cursor)?, TokenKind::Identifier)
        || word_at(tokens, text, cursor, "Function")
    {
        cursor += 1;
        loop {
            match kind_of(tokens, cursor)? {
                TokenKind::Period => cursor += 1,
                TokenKind::Lt => cursor = tokens.matching_end(cursor)? + 1,
                TokenKind::Question => cursor += 1,
                TokenKind::Keyword(Keyword::Function) => {
                    cursor += 1;
                    if kind_of(tokens, cursor)? == TokenKind::OpenParen {
                        cursor = tokens.matching_end(cursor)? + 1;
                    }
                }
                _ => break,
            }
            if matches!(kind_of(tokens, cursor)?, TokenKind::Identifier) {
                cursor += 1;
            } else if word_at(tokens, text, cursor, "Function") {
                cursor += 1;
            } else {
                break;
            }
        }
    } else if kind_of(tokens, cursor)? == TokenKind::OpenParen {
        cursor = tokens.matching_end(cursor)? + 1;
        if kind_of(tokens, cursor)? == TokenKind::Question {
            cursor += 1;
        }
    }
    // The verdict token: another identifier word means the walked head was
    // a written type (`final int x`); a name terminator or a pattern
    // opener means the head was the name itself (`final x`, `final (a, b)
    // = pair`).
    let typed = match kind_of(tokens, cursor)? {
        TokenKind::Identifier => tokens.lexeme(text, cursor) != "in",
        TokenKind::Keyword(Keyword::Function) => true,
        _ => false,
    };
    let replacement = if typed { "" } else { "var" };
    // The typed face deletes the keyword with its trailing horizontal
    // whitespace (the official `range.startStart` deletion, line-bounded);
    // the var face replaces the keyword token alone (the official
    // `range.token` replacement — the following whitespace stays).
    let (start, end16) = if typed {
        let keyword_end = token_end(tokens.get(first)?);
        let tail = text.get(keyword_end..)?;
        let ws = tail.len() - tail.trim_start_matches([' ', '\t']).len();
        (range.start, utf16_count(&text[..keyword_end + ws]))
    } else {
        (range.start, range.end)
    };
    Some((start, end16 - start, replacement.to_owned()))
}

/// `prefer_const_declarations`: the `final` of a constant-initialized
/// declaration becomes `const`, and each initializer-head `const`
/// keyword deletes (the official `ReplaceFinalWithConst`'s keyword
/// replacement plus the per-initializer const deletions folded into one
/// whole-span replacement: `final x = const [1];` → `const x = [1];`).
/// The span must open with the `final` keyword.
///
/// A `const` deletes only where the official producer serves the
/// initializer shape — a `const`-headed typed literal (`[`, `{`, `<`),
/// dot shorthand (`.x(...)`), or instance creation (`A(...)`) that IS the
/// declarator's whole initializer (a `const (` record literal, a
/// `const [1] as T` cast, or a `const` under a nested `=` keeps its
/// keyword — upstream reads `initializer.constKeyword` off those three
/// node kinds alone; upstream Dart SDK source,
/// pkg/analysis_server/lib/src/services/correction/dart/replace_final_with_const.dart).
/// The deletion is `startStart(const, const.next)`: the trivia run —
/// whitespace AND comments — to the next real token.
pub(crate) fn final_with_const(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if kind_of(tokens, first)? != TokenKind::Keyword(Keyword::Final) {
        return None;
    }
    let end = utf16_offset_to_byte(text, range.end);
    let final_end = token_end(tokens.get(first)?);
    let mut out = String::with_capacity(end - final_end);
    out.push_str("const");
    let mut cursor = final_end;
    let mut depth = 0u32;
    // `name_pos`: a declarator name is expected — true at the list head
    // and after each depth-0 `,`; a depth-0 `=` in name position opens an
    // initializer and arms `after_eq` for the `const` check (an `=`
    // inside the initializer — a nested assignment — never arms it).
    let mut name_pos = true;
    let mut after_eq = false;
    let mut index = first + 1;
    while index <= last {
        let token = tokens.get(index)?;
        match token.kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Keyword(Keyword::Const) if depth == 0 && after_eq => {
                if !const_head_is_served(tokens, index + 1, last)? {
                    after_eq = false;
                    index += 1;
                    continue;
                }
                // `startStart(constToken, constToken.next!)` — the next
                // real token's own start; comments and newlines in the
                // trivia run go with the keyword.
                let at = token.byte_offset as usize;
                out.push_str(text.get(cursor..at)?);
                cursor = tokens.get(index + 1)?.byte_offset as usize;
                after_eq = false;
                index += 1;
                continue;
            }
            TokenKind::Comma if depth == 0 => {
                name_pos = true;
                after_eq = false;
            }
            TokenKind::Eq if depth == 0 => {
                after_eq = name_pos;
                name_pos = false;
            }
            _ if depth == 0 => after_eq = false,
            _ => {}
        }
        index += 1;
    }
    out.push_str(text.get(cursor..end)?);
    Some((range.start, range.end - range.start, out))
}

/// Whether the `const` at `const_index` heads an initializer the official
/// `ReplaceFinalWithConst` serves — a typed literal (`[`, `{`, `<`), a
/// dot shorthand or an instance creation (a name chain landing on `(`),
/// ending the declarator (the next depth-0 token is `,` or the span
/// closes). Anything else — a record literal `const (…)`, a `const`
/// prefix of a wider expression, a name reference — keeps the keyword.
fn const_head_is_served(tokens: &TokenTable, head: usize, last: usize) -> Option<bool> {
    let mut cursor = head;
    // A typed literal's bracket heads the initializer outright; the
    // type-argument form `const <T>[`/`{` resolves its `<>` group first
    // and still needs the bracket (a `const <T>(…)` is a record literal —
    // not served).
    if matches!(
        kind_of(tokens, cursor)?,
        TokenKind::OpenSquare | TokenKind::OpenCurly | TokenKind::Lt
    ) {
        if kind_of(tokens, cursor)? == TokenKind::Lt {
            cursor = tokens.matching_end(cursor)? + 1;
        }
        if !matches!(
            kind_of(tokens, cursor)?,
            TokenKind::OpenSquare | TokenKind::OpenCurly
        ) {
            return Some(false);
        }
        cursor = tokens.matching_end(cursor)? + 1;
    } else {
        // A creation's name chain — `A`, `A.b`, `A<int>.b`, `.b` — must
        // land on the argument list's `(` (a bare `(` opens a record
        // literal instead, which the producer never touches).
        let mut named = false;
        loop {
            match kind_of(tokens, cursor)? {
                TokenKind::Identifier
                | TokenKind::Keyword(_)
                | TokenKind::Period
                | TokenKind::Question => {
                    named = true;
                    cursor += 1;
                }
                TokenKind::Lt => {
                    named = true;
                    cursor = tokens.matching_end(cursor)? + 1;
                }
                _ => break,
            }
        }
        if !named || kind_of(tokens, cursor)? != TokenKind::OpenParen {
            return Some(false);
        }
        cursor = tokens.matching_end(cursor)? + 1;
    }
    // The initializer must close the declarator: the next depth-0 token
    // is `,`, `;`, or the span's own end (a wider expression — `as`,
    // `?.`, a binary arm — keeps the keyword).
    if cursor > last {
        return Some(true);
    }
    Some(matches!(
        kind_of(tokens, cursor)?,
        TokenKind::Comma | TokenKind::Semicolon
    ))
}

/// The `[` or `(` opener of the closing `]`/`)` at `close`, walking back
/// over the balanced interior — the reverse of [`TokenTable::matching_end`].
fn matching_begin(tokens: &TokenTable, close: usize) -> Option<usize> {
    let open = match kind_of(tokens, close)? {
        TokenKind::CloseParen => TokenKind::OpenParen,
        TokenKind::CloseSquare => TokenKind::OpenSquare,
        TokenKind::CloseCurly => TokenKind::OpenCurly,
        _ => return None,
    };
    let mut depth = 0u32;
    let mut cursor = close;
    loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            kind if kind == open && depth == 0 => return Some(cursor),
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => depth += 1,
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
    }
}

/// The end token index of the statement starting at `start` — the
/// structural walk behind the control-body wrap (the official producers
/// read the AST statement node; the fix row carries the head token, so
/// the statement shape is rebuilt from the token stream). Structured
/// heads recurse into their arms; everything else ends at its first
/// depth-0 `;`. Every step consumes tokens, so the walk is bounded by the
/// stream; a shape it cannot read drops (`None`).
fn statement_end(tokens: &TokenTable, text: &str, start: usize) -> Option<usize> {
    match kind_of(tokens, start)? {
        TokenKind::Keyword(Keyword::If) => {
            let rparen = skip_group(tokens, start + 1, TokenKind::OpenParen)?;
            let then_end = statement_end(tokens, text, rparen + 1)?;
            if word_at(tokens, text, then_end + 1, "else") {
                statement_end(tokens, text, then_end + 2)
            } else {
                Some(then_end)
            }
        }
        TokenKind::Keyword(Keyword::While | Keyword::For) => {
            let rparen = skip_group(tokens, start + 1, TokenKind::OpenParen)?;
            statement_end(tokens, text, rparen + 1)
        }
        TokenKind::Keyword(Keyword::Do) => {
            let body_end = statement_end(tokens, text, start + 1)?;
            if !word_at(tokens, text, body_end + 1, "while") {
                return None;
            }
            let rparen = skip_group(tokens, body_end + 2, TokenKind::OpenParen)?;
            match kind_of(tokens, rparen + 1)? {
                TokenKind::Semicolon => Some(rparen + 1),
                _ => None,
            }
        }
        TokenKind::Keyword(Keyword::Switch) => {
            let rparen = skip_group(tokens, start + 1, TokenKind::OpenParen)?;
            skip_group(tokens, rparen + 1, TokenKind::OpenCurly)
        }
        TokenKind::Keyword(Keyword::Try) => {
            let mut end = skip_group(tokens, start + 1, TokenKind::OpenCurly)?;
            loop {
                let next = end + 1;
                if word_at(tokens, text, next, "on") || word_at(tokens, text, next, "catch") {
                    let mut cursor = next + 1;
                    if kind_of(tokens, cursor)? == TokenKind::OpenParen {
                        cursor = tokens.matching_end(cursor)? + 1;
                    }
                    end = skip_group(tokens, cursor, TokenKind::OpenCurly)?;
                } else if kind_of(tokens, next)? == TokenKind::Keyword(Keyword::Finally) {
                    end = skip_group(tokens, next + 1, TokenKind::OpenCurly)?;
                } else {
                    return Some(end);
                }
            }
        }
        TokenKind::OpenCurly => tokens.matching_end(start),
        // Expression, declaration, return, break, label — the statement
        // ends at its first depth-0 `;`.
        _ => {
            let mut depth = 0u32;
            let mut cursor = start;
            loop {
                match kind_of(tokens, cursor)? {
                    TokenKind::OpenParen
                    | TokenKind::OpenSquare
                    | TokenKind::OpenCurly
                    | TokenKind::StringInterpolationExpression => depth += 1,
                    TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                        depth = depth.checked_sub(1)?;
                    }
                    TokenKind::Semicolon if depth == 0 => return Some(cursor),
                    _ => {}
                }
                cursor += 1;
            }
        }
    }
}

/// The matching closer of the group opener at `at` (the opener kind is
/// verified, not assumed).
fn skip_group(tokens: &TokenTable, at: usize, open: TokenKind) -> Option<usize> {
    if kind_of(tokens, at)? != open {
        return None;
    }
    tokens.matching_end(at)
}

/// The `on` keyword ending an `on Type` face whose type run closes just
/// before `cursor` — the generics and the dotted identifier name walk
/// back; `None` when the run does not open at `on`.
fn on_type_start(tokens: &TokenTable, text: &str, mut cursor: usize) -> Option<usize> {
    if matches!(
        kind_of(tokens, cursor)?,
        TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt
    ) {
        let mut depth = 0u32;
        loop {
            match kind_of(tokens, cursor)? {
                TokenKind::Gt => depth += 1,
                TokenKind::GtGt => depth += 2,
                TokenKind::GtGtGt => depth += 3,
                TokenKind::Lt => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
            cursor = cursor.checked_sub(1)?;
        }
    }
    loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::Identifier | TokenKind::Period => {}
            _ => break,
        }
    }
    word_at(tokens, text, cursor, "on").then_some(cursor)
}

/// `curly_braces_in_flow_control_structures`: the reported non-block body
/// statement is wrapped in a brace block — `{\n<indent>` opens before it,
/// `\n<prefix}>` closes after it (the official `UseCurlyBraces`
/// insertions folded into one whole-body replacement; the body text and
/// any trailing same-line comment keep verbatim inside).
pub(crate) fn curly_braces_body(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    wrap_control_body(input, false)
}

/// `always_put_control_body_on_new_line`: the reported span is the body's
/// head token — the statement end is rebuilt first, then the same wrap
/// the official `UseCurlyBraces` lands (its `nonBulk` face for this
/// lint).
pub(crate) fn curly_braces_head(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    wrap_control_body(input, true)
}

/// The shared control-body wrap. The body must follow `)`, `else`, or
/// `do` (the control head the rules report at), must not already be a
/// block, and its line prefix — the control keyword's line prefix — must
/// be whitespace only; anything else drops.
fn wrap_control_body(input: &FixInput<'_>, expand_head: bool) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if kind_of(tokens, first)? == TokenKind::OpenCurly {
        return None; // block bodies are never wrapped
    }
    let last = if expand_head {
        statement_end(tokens, text, first)?
    } else {
        last
    };
    let anchor = first.checked_sub(1)?;
    let control_head = match kind_of(tokens, anchor)? {
        TokenKind::CloseParen => {
            let lparen = matching_begin(tokens, anchor)?;
            lparen.checked_sub(1)?
        }
        TokenKind::Keyword(Keyword::Else | Keyword::Do) => anchor,
        _ => return None,
    };
    let head_byte = tokens.get(control_head)?.byte_offset as usize;
    let line_start = text[..head_byte].rfind('\n').map_or(0, |i| i + 1);
    let prefix = text.get(line_start..head_byte)?;
    if !prefix.bytes().all(|b| matches!(b, b' ' | b'\t')) {
        return None;
    }
    let indent = format!("{prefix}  ");
    // A comment sharing the body's line rides inside the block (the
    // official `_endAfterComments` face); a block comment that does not
    // close on the line drops the fix.
    let mut body_end = token_end(tokens.get(last)?);
    let line_end = text[body_end..]
        .find('\n')
        .map_or(text.len(), |i| body_end + i);
    let tail = text[body_end..line_end].trim_matches([' ', '\t', '\r']);
    if tail.starts_with("//") {
        body_end = line_end;
    } else if tail.starts_with("/*") {
        body_end = text[body_end..line_end]
            .find("*/")
            .map(|i| body_end + i + 2)?;
    }
    let start16 = tokens.get(first)?.utf16_offset;
    let end16 = utf16_count(&text[..body_end]);
    let inner = text.get(utf16_offset_to_byte(text, start16)..body_end)?;
    Some((
        start16,
        end16 - start16,
        format!("{{\n{indent}{inner}\n{prefix}}}"),
    ))
}

/// `empty_catches`: the reported empty block's whole catch clause leaves
/// (the official `RemoveEmptyCatch` deletes the catch clause's lines
/// range) — but only where the official offers the fix at all: the try
/// must keep a handler after the cut (another catch clause or a
/// `finally`). The clause is rebuilt backwards from the reported block:
/// the `(…)` parameter group with its `catch` keyword, or the `on` type
/// face; the try gate reads the balanced block before the clause and the
/// clauses after it.
pub(crate) fn remove_empty_catch(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if kind_of(tokens, first)? != TokenKind::OpenCurly || tokens.matching_end(first)? != last {
        return None;
    }
    // The clause start: `catch (…)` — the parameter group and its
    // keyword — or `on Type` — the type's identifier run with its dots
    // and type arguments, over the `on` keyword; an `on Type catch (…)`
    // face opens at the `on` (the official deletes the whole CatchClause
    // node).
    let cursor = first.checked_sub(1)?;
    let clause_start = match kind_of(tokens, cursor)? {
        TokenKind::CloseParen => {
            let lparen = matching_begin(tokens, cursor)?;
            let keyword = lparen.checked_sub(1)?;
            if !word_at(tokens, text, keyword, "catch") {
                return None;
            }
            match keyword.checked_sub(1) {
                Some(back)
                    if matches!(
                        kind_of(tokens, back),
                        Some(TokenKind::Identifier)
                            | Some(TokenKind::Gt)
                            | Some(TokenKind::GtGt)
                            | Some(TokenKind::GtGtGt)
                    ) =>
                {
                    on_type_start(tokens, text, back)?
                }
                _ => keyword,
            }
        }
        _ => on_type_start(tokens, text, cursor)?,
    };
    // The try gate: a balanced `}` block directly before the clause means
    // a sibling catch clause keeps the try covered; at the first clause
    // (the walk lands on the `try` keyword) a sibling (`catch`/`on`/
    // `finally`) must follow this one.
    let mut before = clause_start.checked_sub(1)?;
    while kind_of(tokens, before)? == TokenKind::CloseCurly {
        before = matching_begin(tokens, before)?.checked_sub(1)?;
    }
    let has_sibling = if word_at(tokens, text, before, "try") {
        let next = last + 1;
        word_at(tokens, text, next, "catch")
            || word_at(tokens, text, next, "on")
            || kind_of(tokens, next)? == TokenKind::Keyword(Keyword::Finally)
    } else {
        true
    };
    if !has_sibling {
        return None;
    }
    // The deletion: the clause alone on its line(s) takes them through
    // the terminator; otherwise exactly the clause plus its leading
    // horizontal whitespace.
    let clause_start16 = tokens.get(clause_start)?.utf16_offset;
    let end16 = utf16_count(&text[..token_end(tokens.get(last)?)]);
    if let Some((line_start, line_end)) = line_bounds(
        text,
        utf16_offset_to_byte(text, clause_start16),
        token_end(tokens.get(last)?),
    ) {
        if text[line_start..utf16_offset_to_byte(text, clause_start16)]
            .bytes()
            .all(|b| matches!(b, b' ' | b'\t' | b'\r'))
            && text[token_end(tokens.get(last)?)..line_end]
                .bytes()
                .all(|b| matches!(b, b' ' | b'\t' | b'\r'))
        {
            let (cut_start, _) = cut_line(text, line_start, line_end);
            let eol = if text[line_end..].starts_with("\r\n") {
                2
            } else {
                usize::from(text[line_end..].starts_with('\n'))
            };
            return Some((
                cut_start,
                utf16_count(&text[line_start..token_end(tokens.get(last)?) + eol]),
                String::new(),
            ));
        }
    }
    let head_ws = text[..utf16_offset_to_byte(text, clause_start16)].len()
        - text[..utf16_offset_to_byte(text, clause_start16)]
            .trim_end_matches([' ', '\t'])
            .len();
    let lead = u32::try_from(head_ws).ok()?;
    Some((
        clause_start16 - lead,
        end16 - clause_start16 + lead,
        String::new(),
    ))
}

/// `prefer_single_quotes`: the double-quoted literal's quote runs become
/// single (the official `ConvertToSingleQuotes` — the same machinery as
/// [`convert_quotes`], direction pinned).
pub(crate) fn convert_to_single_quotes(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    convert_quotes(tokens, text, range, Some(true))
}

/// `prefer_double_quotes`: the single-quoted literal's quote runs become
/// double (the official `ConvertToDoubleQuotes`).
pub(crate) fn convert_to_double_quotes(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
) -> Option<(u32, u32, String)> {
    convert_quotes(tokens, text, range, Some(false))
}

/// `avoid_escaping_inner_quotes`: the outer quote moves to the character
/// the value escaped (the official `ConvertQuotes` — the direction reads
/// off the literal: `'a\'b'` → `"a'b"`, `"a\"b"` → `'a"b'`).
pub(crate) fn convert_inner_quotes(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    convert_quotes(input.tokens?, input.text, &input.range, None)
}

/// The quote-run swap behind the three quote rules: the outer quote runs
/// (single or triple, matched head and tail) re-spell to the target quote
/// and every string segment's escapes re-balance — an unescaped target
/// quote gains its backslash, an escaped old quote loses it (the official
/// `_fixBackslashesForQuotes` walk); interpolation groups ride verbatim.
/// A raw simple literal keeps its prefix only when the content cannot
/// collide with the new quote; any other raw shape drops.
fn convert_quotes(
    tokens: &TokenTable,
    text: &str,
    range: &core::ops::Range<u32>,
    to_single: Option<bool>,
) -> Option<(u32, u32, String)> {
    let (first, last) = hit_tokens(tokens, range)?;
    if kind_of(tokens, first)? != TokenKind::String || kind_of(tokens, last)? != TokenKind::String {
        return None;
    }
    let head = tokens.lexeme(text, first);
    let raw = head.starts_with('r');
    let raw_skip = usize::from(raw);
    let quote = *head.as_bytes().get(raw_skip)?;
    if quote != b'\'' && quote != b'"' {
        return None;
    }
    let lead = head[raw_skip..].bytes().take_while(|&b| b == quote).count();
    let tail = tokens.lexeme(text, last);
    let trail = tail.bytes().rev().take_while(|&b| b == quote).count();
    if lead != trail || !matches!(lead, 1..=3) {
        return None;
    }
    let target = match to_single {
        Some(true) => b'\'',
        Some(false) => b'"',
        None if quote == b'\'' => b'"',
        None => b'\'',
    };
    if target == quote {
        return None;
    }
    if raw {
        // A raw literal cannot interpolate, so first == last here; the
        // prefix keeps only when the contents stay unambiguous under the
        // new quote (the official `_canKeepAsRaw`) — otherwise the fix
        // drops rather than re-spelling a non-raw escape set.
        let content = head.get(raw_skip + lead..head.len() - trail)?;
        let triple: String = std::iter::repeat(target as char).take(3).collect();
        if content.ends_with(target as char) || content.contains(&triple) {
            return None;
        }
        let mut out = String::with_capacity(head.len() + 2);
        out.push('r');
        for _ in 0..lead {
            out.push(target as char);
        }
        out.push_str(content);
        for _ in 0..lead {
            out.push(target as char);
        }
        return Some((range.start, range.end - range.start, out));
    }
    let multiline = lead == 3;
    let mut out = String::with_capacity(tail.len() + head.len());
    for _ in 0..lead {
        out.push(target as char);
    }
    let mut index = first;
    while index <= last {
        match kind_of(tokens, index)? {
            TokenKind::String => {
                if index != first && index != last {
                    return None; // one literal's extent holds two segments at most
                }
                let segment = tokens.lexeme(text, index);
                let lead_cut = if index == first { lead } else { 0 };
                let trail_cut = if index == last { trail } else { 0 };
                let content = segment.get(lead_cut..segment.len() - trail_cut)?;
                push_converted(&mut out, content, quote, target, multiline, index == last);
                index += 1;
            }
            TokenKind::StringInterpolationIdentifier => {
                out.push_str(tokens.lexeme(text, index));
                index += 1;
            }
            TokenKind::StringInterpolationExpression => {
                let close = tokens.matching_end(index)?;
                let start = tokens.get(index)?.byte_offset as usize;
                out.push_str(text.get(start..token_end(tokens.get(close)?))?);
                index = close + 1;
            }
            _ => return None,
        }
    }
    for _ in 0..trail {
        out.push(target as char);
    }
    Some((range.start, range.end - range.start, out))
}

/// One segment's contents under the quote swap — the official
/// `_fixBackslashesForQuotes` walk: an unescaped target quote gains its
/// backslash (multiline literals only every third of a run, and always
/// the final character of the closing segment), an escaped old quote
/// loses its backslash, every other spelling rides verbatim.
fn push_converted(
    out: &mut String,
    content: &str,
    old: u8,
    new: u8,
    multiline: bool,
    string_end: bool,
) {
    let chars: Vec<char> = content.chars().collect();
    let mut escaping = false;
    let mut run = 0u32;
    for (index, &ch) in chars.iter().enumerate() {
        if ch as u32 == new as u32 {
            if escaping {
                escaping = false;
            } else if multiline {
                run += 1;
                if run == 3 {
                    run = 0;
                    out.push('\\');
                } else if string_end && index + 1 == chars.len() {
                    out.push('\\');
                }
            } else {
                out.push('\\');
            }
        } else {
            run = 0;
            if ch as u32 == old as u32 && escaping {
                out.pop();
                escaping = false;
            }
            escaping = ch == '\\' && !escaping;
        }
        out.push(ch);
    }
}

// ---------------------------------------------------------------------------
// Lint-face rewriters (the `FixSource::Lint` breadth)
//
// The F4 wave's rows: each mirrors one official quick-fix producer's edit
// shape (upstream Dart SDK source,
// pkg/analysis_server/lib/src/services/correction/dart/*, keyed through the
// lint registry of fix_internal.dart); the official producers read the
// resolved AST node under the report, these rebuild the same shape from the
// report span and the token stream, and drop where the shape does not
// verify. Producers whose edits need element, type, or import facts have no
// row (the fix_table module docs carry the ledger).
// ---------------------------------------------------------------------------

/// Whether the token range carries any depth-0 operator whose precedence
/// sits below the position a rewrite binds at (`!`, `||`/`&&`, `~/`,
/// `.call`) — the textual read of the official producers' `needsParens`
/// gates: comparisons, arithmetic, logic, null-coalesce, conditional,
/// assignment, cascade, and the `is`/`as` tests all qualify; a pure
/// postfix chain never does.
fn binds_loose(tokens: &TokenTable, range: core::ops::Range<usize>) -> bool {
    let mut depth = 0u32;
    for index in range {
        let Some(kind) = kind_of(tokens, index) else {
            return true;
        };
        match kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1).unwrap_or(0);
            }
            _ if depth == 0 => {
                if matches!(
                    kind,
                    TokenKind::Eq
                        | TokenKind::EqEq
                        | TokenKind::BangEq
                        | TokenKind::Lt
                        | TokenKind::LtEq
                        | TokenKind::Gt
                        | TokenKind::GtEq
                        | TokenKind::Plus
                        | TokenKind::Minus
                        | TokenKind::Star
                        | TokenKind::Slash
                        | TokenKind::Percent
                        | TokenKind::TildeSlash
                        | TokenKind::Ampersand
                        | TokenKind::Bar
                        | TokenKind::Caret
                        | TokenKind::LtLt
                        | TokenKind::GtGt
                        | TokenKind::GtGtGt
                        | TokenKind::AmpersandAmpersand
                        | TokenKind::BarBar
                        | TokenKind::QuestionQuestion
                        | TokenKind::Question
                        | TokenKind::PlusEq
                        | TokenKind::MinusEq
                        | TokenKind::StarEq
                        | TokenKind::SlashEq
                        | TokenKind::PercentEq
                        | TokenKind::TildeSlashEq
                        | TokenKind::AmpersandEq
                        | TokenKind::BarEq
                        | TokenKind::CaretEq
                        | TokenKind::LtLtEq
                        | TokenKind::GtGtEq
                        | TokenKind::GtGtGtEq
                        | TokenKind::QuestionQuestionEq
                        | TokenKind::PeriodPeriod
                        | TokenKind::QuestionPeriodPeriod
                        | TokenKind::Keyword(Keyword::Is)
                        | TokenKind::Keyword(Keyword::As)
                ) {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

/// The `(question, colon)` split of a conditional's token range — the
/// depth-0 `?` and its matching `:` (each deeper `?` opens a nested
/// conditional whose `:` closes it first).
fn ternary_split(
    tokens: &TokenTable,
    text: &str,
    first: usize,
    last: usize,
) -> Option<(usize, usize)> {
    let question = depth0_find(tokens, text, first, last + 1, |kind, _| {
        kind == TokenKind::Question
    })?;
    let mut depth = 0u32;
    let mut pending = 0u32;
    for index in question + 1..=last {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Question if depth == 0 => pending += 1,
            TokenKind::Colon if depth == 0 => {
                if pending == 0 {
                    return Some((question, index));
                }
                pending -= 1;
            }
            _ => {}
        }
    }
    None
}

/// A single-token `true`/`false` literal and its value, or `None`.
fn bool_literal(tokens: &TokenTable, text: &str, index: usize) -> Option<bool> {
    if index != 0 && !matches!(kind_of(tokens, index), Some(TokenKind::Keyword(_))) {
        return None;
    }
    match tokens.lexeme(text, index) {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

/// `!` + optional parentheses around the text of a token range — the
/// negation face the boolean rewrites share (`needsParens` read by
/// [`binds_loose`]).
fn bang_wrapped(tokens: &TokenTable, text: &str, range: core::ops::Range<usize>) -> Option<String> {
    let body = token_text(tokens, text, range.clone())?;
    Some(if binds_loose(tokens, range) {
        format!("!({body})")
    } else {
        format!("!{body}")
    })
}

/// `annotate_overrides` / `annotate_redeclares`: `@override` / `@redeclare`
/// lands on its own line before the member's first attached line — the
/// official `AddOverride` / `AddRedeclare` replacement at the member's
/// begin token, doc comments included. The member block is walked up over
/// its annotation and doc-comment lines (plain `//` trailing comments
/// belong to the previous member and stop the walk).
/// The start of the line before `byte`, read past the byte's own line
/// terminator — the walk-back read the member-head helpers share (`byte`
/// sits just past a line's `\n`, and searching `text[..byte]` unguarded
/// would find that terminator and strand the walk on an empty line).
fn line_start_before(text: &str, byte: usize) -> usize {
    let mut bounded = byte;
    if bounded > 0 && text.as_bytes()[bounded - 1] == b'\n' {
        bounded -= 1;
        if bounded > 0 && text.as_bytes()[bounded - 1] == b'\r' {
            bounded -= 1;
        }
    }
    text[..bounded].rfind('\n').map_or(0, |i| i + 1)
}

fn add_member_annotation(input: &FixInput<'_>, name: &str) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    // The annotation rides the member's own line: the official
    // `AddOverride` anchors the member's begin token — the first real
    // token, below any doc comment — and carries the member's indent
    // (upstream add_override_test.dart `test_method_with_doc_comment`).
    let line_start = text[..start].rfind('\n').map_or(0, |i| i + 1);
    let indent = &text[line_start..line_indent_end(text, line_start)];
    Some((
        utf16_count(&text[..line_start]),
        0,
        format!("{indent}{name}\n"),
    ))
}

/// The `annotate_overrides` entry: `@override` (the official `AddOverride`).
pub(crate) fn annotate_overrides_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    add_member_annotation(input, "@override")
}

/// The `annotate_redeclares` entry: `@redeclare` (the official
/// `AddRedeclare`).
pub(crate) fn annotate_redeclares_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    add_member_annotation(input, "@redeclare")
}

/// The end of the line's leading whitespace at `byte`.
fn line_indent_end(text: &str, byte: usize) -> usize {
    byte + text[byte..].len() - text[byte..].trim_start_matches([' ', '\t']).len()
}

/// `async_return_with_no_await`: `await ` lands before the returned
/// expression, after the whitespace run (the official `AddAwait.return_`'s
/// expression insertion; the lint reports at the `return` keyword or `=>`).
pub(crate) fn await_return_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if slice != "return" && slice != "=>" {
        return None;
    }
    let rest = input
        .text
        .get(utf16_offset_to_byte(input.text, input.range.end)..)?;
    if rest.trim_start().starts_with([';', ')']) {
        return None;
    }
    let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
    let at = input.range.end + u32::try_from(ws).ok()?;
    Some((at, 0, "await ".to_owned()))
}

/// The type-deletion face of `RemoveTypeAnnotation.other` over a
/// parameter-position type (`avoid_annotating_with_dynamic`,
/// `avoid_return_types_on_setters`, `avoid_types_on_closure_parameters`,
/// `type_init_formals`): the reported type goes with the whitespace run to
/// the next token (`range.startStart(type, next)`).
pub(crate) fn remove_reported_type(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let first = slice.chars().next()?;
    if !(first.is_ascii_alphabetic() || first == '_' || first == '$' || first == '<') {
        return None;
    }
    remove_keyword(input.text, input.range.start, slice)
}

/// `omit_local_variable_types` / `omit_obvious_local_variable_types` /
/// `omit_obvious_property_types`: the written type becomes `var` (the
/// official `ReplaceWithVar`), or the type-through-name gap does when the
/// list carries several declarators (the official `RemoveTypeAnnotation`
/// declaration-list face). A type with type arguments drops — the official
/// moves `<…>` into the initializer as a second edit — and so does a
/// `{…}` initializer (the official ambiguity guard: `var x = {}` changes
/// the literal's meaning).
pub(crate) fn omit_type_with_var(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    if slice.is_empty()
        || slice
            .chars()
            .any(|c| matches!(c, ',' | '=' | ';' | '<' | '>' | '(' | ')'))
    {
        return None;
    }
    let rest = text.get(utf16_offset_to_byte(text, input.range.end)..)?;
    let after_ws = rest.trim_start_matches([' ', '\t']);
    let name_len = after_ws
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '$')
        .map(char::len_utf8)
        .sum::<usize>();
    if name_len == 0 {
        return None;
    }
    let after_name = after_ws[name_len..].trim_start_matches([' ', '\t']);
    if after_name.starts_with('=') {
        let initializer = after_name[1..].trim_start_matches([' ', '\t']);
        if initializer.starts_with('{') {
            return None;
        }
        return Some((
            input.range.start,
            input.range.end - input.range.start,
            "var".to_owned(),
        ));
    }
    if after_name.starts_with(',') {
        // Multi-declarator: `var ` replaces the type plus the whitespace
        // before the first name.
        let cut_bytes = rest.len() - after_ws.len()
            + name_len
            + (after_ws[name_len..].len() - after_name.len());
        let start = utf16_offset_to_byte(text, input.range.start);
        let end = utf16_offset_to_byte(text, input.range.end);
        return Some((
            input.range.start,
            utf16_count(text.get(start..end + cut_bytes)?),
            "var ".to_owned(),
        ));
    }
    if after_name.starts_with("in") && !after_name[2..].starts_with(is_identifier_char) {
        return Some((
            input.range.start,
            input.range.end - input.range.start,
            "var".to_owned(),
        ));
    }
    None
}

/// `prefer_final_locals` / `prefer_final_fields`: the reported `var`
/// keyword becomes `final` (the official `MakeFinal` keyword face), the
/// written type gains `final ` (the type face). A multi-variable list
/// drops — the official bails unless the list holds exactly one variable.
pub(crate) fn make_declaration_final(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    if slice == "var" {
        return single_declarator_follows(text, input.range.end).then_some((
            input.range.start,
            3,
            "final".to_owned(),
        ));
    }
    if !slice.is_empty() && slice.chars().next()?.is_ascii_alphabetic() {
        return single_declarator_follows(text, input.range.end).then_some((
            input.range.start,
            0,
            "final ".to_owned(),
        ));
    }
    None
}

/// Whether `name =` (one declarator with an initializer) follows the
/// declaration's keyword or type — the official `MakeFinal` single-variable
/// gate, read textually (`name in` — the for-each shape — also passes).
fn single_declarator_follows(text: &str, end16: u32) -> bool {
    let Some(rest) = text.get(utf16_offset_to_byte(text, end16)..) else {
        return false;
    };
    let after_ws = rest.trim_start_matches([' ', '\t']);
    let name_len = after_ws
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '_' || *c == '$')
        .count();
    if name_len == 0 {
        return false;
    }
    let after_name = after_ws[name_len..].trim_start_matches([' ', '\t']);
    after_name
        .starts_with(['=', ','])
        .then(|| !after_name.starts_with(','))
        == Some(true)
        || after_name.starts_with("in") && !after_name[2..].starts_with(is_identifier_char)
}

/// `prefer_final_parameters` / `prefer_final_in_for_each`: `final ` lands
/// at the parameter's (or for-each variable's) first content token; a
/// leading `var` swaps to `final` and a `covariant` modifier keeps its
/// head position (the official `MakeFinal` faces).
pub(crate) fn make_parameter_final(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if slice == "var" {
        // The for-each variable's reported keyword swaps whole (the
        // official `MakeFinal`: `for (var e …)` becomes `final e`).
        return Some((input.range.start, 3, "final".to_owned()));
    }
    if let Some(rest) = slice.strip_prefix("var ")
        && !rest.starts_with(is_identifier_char)
    {
        return Some((input.range.start, 3, "final".to_owned()));
    }
    if let Some(rest) = slice.strip_prefix("covariant")
        && rest.starts_with([' ', '\t'])
    {
        let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
        let at = input.range.start + u32::try_from(9 + ws).ok()?;
        return Some((at, 0, "final ".to_owned()));
    }
    let first = slice.chars().next()?;
    if first.is_ascii_alphabetic() || first == '_' || first == '$' {
        return Some((input.range.start, 0, "final ".to_owned()));
    }
    None
}

/// `prefer_const_constructors` / `prefer_const_constructors_in_immutables`
/// / `prefer_const_literals_to_create_immutables`: `const ` lands before
/// the reported creation or literal (the official `AddConst` insert face),
/// and a `new` keyword swaps to `const` (the official
/// `ReplaceNewWithConst`). Inner depth-0 `const` keywords fold out in the
/// same replacement (the official `_ConstRangeFinder` deletions).
pub(crate) fn add_const_prefix(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    if let Some(rest) = slice.strip_prefix("new") {
        if rest.starts_with(is_identifier_char) {
            return None;
        }
        let ws = rest.len() - rest.trim_start_matches([' ', '\t']).len();
        return Some((
            input.range.start,
            3 + u32::try_from(ws).ok()?,
            "const ".to_owned(),
        ));
    }
    let first = slice.chars().next()?;
    if !(first.is_ascii_alphabetic()
        || first == '_'
        || first == '$'
        || first == '<'
        || first == '('
        || first == '[')
    {
        return None;
    }
    // Inner `const` keywords fold out (the official producer deletes them
    // while inserting the outer one); the span is rebuilt from its tokens.
    let tokens = input.tokens?;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let mut depth = 0u32;
    let mut inner = Vec::new();
    for index in first..=last {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Keyword(Keyword::Const) if depth == 0 && index > first => {
                inner.push(index);
            }
            _ => {}
        }
    }
    if inner.is_empty() {
        return Some((input.range.start, 0, "const ".to_owned()));
    }
    let (start16, length16) = span_over(text, tokens, first, last)?;
    let start = utf16_offset_to_byte(text, start16);
    let end = utf16_offset_to_byte(text, start16 + length16);
    let mut rebuilt = String::from("const ");
    let mut cursor = start;
    for index in inner {
        let keyword_start = utf16_offset_to_byte(text, tokens.get(index)?.utf16_offset);
        let keyword_end = token_end(tokens.get(index)?);
        rebuilt.push_str(text.get(cursor..keyword_start)?);
        let rest = text.get(keyword_end..end)?;
        rebuilt.push_str(rest.trim_start_matches([' ', '\t']));
        cursor = keyword_end + rest.len() - rest.trim_start_matches([' ', '\t']).len();
    }
    rebuilt.push_str(text.get(cursor..end)?);
    Some((start16, length16, rebuilt))
}

/// `prefer_void_to_null`: the reported `null`/`Null` type display becomes
/// `void` (the official `ReplaceNullWithVoid` replaces the diagnostic
/// span).
pub(crate) fn replace_null_with_void(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if !slice.ends_with("null") && !slice.ends_with("Null") {
        return None;
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        "void".to_owned(),
    ))
}

/// `prefer_int_literals`: the integral double literal loses its fraction
/// (`1.0` → `1` — the official `ConvertToIntLiteral` deletes from the
/// decimal point) or is rewritten whole when an exponent carries the value
/// (`1.0e2` → `100`, the official's `$intValue` face; a value outside the
/// int range drops).
pub(crate) fn double_to_int_literal(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if slice.is_empty()
        || !slice
            .chars()
            .all(|c| c.is_ascii_digit() || matches!(c, '.' | 'e' | 'E' | '+' | '-'))
    {
        return None;
    }
    if !slice.contains(['e', 'E']) {
        let dot = slice.find('.')?;
        if slice[dot + 1..].chars().all(|c| c.is_ascii_digit()) {
            return Some((
                input.range.start + u32::try_from(dot).ok()?,
                u32::try_from(slice.len() - dot).ok()?,
                String::new(),
            ));
        }
        return None;
    }
    let value = slice.parse::<f64>().ok()?;
    if value.fract() != 0.0 || value.abs() >= 9.223_372_036_854_776e18 {
        return None;
    }
    let int = value as i64;
    Some((
        input.range.start,
        input.range.end - input.range.start,
        int.to_string(),
    ))
}

/// `future_sync_value`: the reported `value` selector renames to
/// `syncValue` (the official `ReplaceWithSyncValue` replaces the covering
/// node's range with the name).
pub(crate) fn sync_value_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    if slice16(input.text, &input.range)? != "value" {
        return None;
    }
    Some((input.range.start, 5, "syncValue".to_owned()))
}

/// `implicit_call_tearoffs`: `.call` lands after the reported expression,
/// parenthesized when its precedence sits below postfix (the official
/// `AddExplicitCall`).
pub(crate) fn add_explicit_call_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let slice = slice16(text, &input.range)?;
    let wrap = binds_loose(tokens, first..last + 1);
    Some((
        input.range.start,
        input.range.end - input.range.start,
        if wrap {
            format!("({slice}).call")
        } else {
            format!("{slice}.call")
        },
    ))
}

/// `leading_newlines_in_multiline_strings`: the line terminator lands
/// right after the (optionally raw) opening triple quote (the official
/// `AddLeadingNewlineToString` inserts at the literal's contents offset).
pub(crate) fn add_leading_newline(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let skip = slice
        .strip_prefix("r'''")
        .or_else(|| slice.strip_prefix("r\"\"\""))
        .map(|_| 4u32)
        .or_else(|| slice.strip_prefix("'''").map(|_| 3u32))
        .or_else(|| slice.strip_prefix("\"\"\"").map(|_| 3u32))?;
    Some((input.range.start + skip, 0, "\n".to_owned()))
}

/// `unnecessary_ignore`: the ignore comment's line goes (the official
/// `RemoveComment` deletes the comment's lines range — [`drop_span_statement`]'s
/// shape).
pub(crate) fn remove_ignore_comment(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if !slice.starts_with("//") || !slice.contains("ignore") {
        return None;
    }
    drop_span_statement(input.text, &input.range)
}

/// `unnecessary_library_name`: the name between the `library` keyword and
/// its `;` goes (the official `RemoveLibraryName` deletes keyword-end
/// through semicolon-start).
pub(crate) fn drop_library_name(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    let head = text.get(..start)?.trim_end_matches([' ', '\t']);
    if !head.ends_with("library") {
        return None;
    }
    let before = &head[..head.len() - 7];
    if before.ends_with(is_identifier_char) {
        return None;
    }
    Some((
        u32::try_from(utf16_count(head)).ok()?,
        input.range.end - u32::try_from(utf16_count(head)).ok()?,
        String::new(),
    ))
}

/// `unnecessary_raw_strings`: the `r` prefix of the reported literal goes
/// (the official `RemoveUnnecessaryRawString` deletes the one character).
pub(crate) fn remove_raw_prefix(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    if !matches!(slice.as_bytes().first(), Some(b'r'))
        || !matches!(slice.as_bytes().get(1), Some(b'\'' | b'"'))
    {
        return None;
    }
    Some((input.range.start, 1, String::new()))
}

/// `use_raw_strings`: the literal becomes raw with the backslashes of its
/// contents gone (the official `ConvertToRawString` inserts `r` and
/// deletes each backslash — folded into one whole-literal replacement).
/// An escape outside the `\\`/`\$` pair the lint admits refuses the fix.
pub(crate) fn convert_to_raw_string_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let quote = *slice.as_bytes().first()?;
    if !matches!(quote, b'\'' | b'"') {
        return None;
    }
    if slice.as_bytes().last() != Some(&quote) || slice.len() < 2 {
        return None;
    }
    let contents = &slice[1..slice.len() - 1];
    let mut rebuilt = String::with_capacity(contents.len() + 2);
    rebuilt.push('r');
    rebuilt.push(quote as char);
    let mut chars = contents.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            // One backslash leaves per escape; the escaped character
            // keeps (the official `ConvertToRawString`'s per-backslash
            // deletions — `\\` and `\$` read verbatim in a raw string).
            let escaped = chars.next()?;
            if !matches!(escaped, '\\' | '$') {
                return None;
            }
            rebuilt.push(escaped);
            continue;
        }
        rebuilt.push(c);
    }
    rebuilt.push(quote as char);
    Some((
        input.range.start,
        input.range.end - input.range.start,
        rebuilt,
    ))
}

/// `slash_for_doc_comments`: the `/** … */` block comment is rebuilt as
/// `///` lines (the official `ConvertDocumentationIntoLine` state machine:
/// first line's `/**` stripped, `*` rail lines trimmed, a pure `*/`
/// terminator ends the block, the comment's own indentation prefixes every
/// emitted line).
pub(crate) fn doc_comment_to_line(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    if !slice.starts_with("/**") || !slice.ends_with("*/") {
        return None;
    }
    let start = utf16_offset_to_byte(text, input.range.start);
    let prefix = &text[text[..start].rfind('\n').map_or(0, |i| i + 1)..start];
    let eol = if slice.contains("\r\n") { "\r\n" } else { "\n" };
    let mut out = String::new();
    let mut line_prefix = String::new();
    for (position, line) in slice.split(eol).enumerate() {
        if position == 0 {
            let body = line.strip_prefix("/**")?.trim();
            let body = body.strip_suffix("*/").map_or(body, str::trim);
            if body.is_empty() {
                continue;
            }
            out.push_str("/// ");
            out.push_str(body);
            line_prefix = format!("{eol}{prefix}");
        } else {
            let trimmed = line.trim();
            if trimmed.ends_with("*/") && trimmed[..trimmed.len() - 2].chars().all(|c| c == '*') {
                break;
            }
            let body = if let Some(rest) = trimmed.strip_prefix('*') {
                rest
            } else if trimmed.is_empty() {
                ""
            } else {
                // Everything inside `/**` and `*/` is documentation, even
                // when the line is not prefixed with a `*`.
                trimmed
            };
            let body = body.strip_suffix("*/").map_or(body, str::trim_end);
            out.push_str(&line_prefix);
            out.push_str("///");
            out.push_str(body);
            line_prefix = format!("{eol}{prefix}");
        }
    }
    if out.is_empty() {
        return None;
    }
    Some((input.range.start, input.range.end - input.range.start, out))
}

/// `flutter_style_todos`: the comment lexeme is rebuilt in the flutter
/// TODO shape — one leading `// ` space, `TODO` upper-cased at index 3,
/// the author's `)` closed by `: `, stray later `TODO`s back-ticked
/// (the official `ConvertToFlutterStyleTodo` pipeline); a rebuilt comment
/// that still fails the lint's expected shape refuses the fix.
pub(crate) fn flutter_style_todo(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let mut content = slice16(input.text, &input.range)?.to_owned();
    if let Some(rest) = content.strip_prefix("///") {
        content = format!("/{rest}");
    }
    let mut todo_index = content.find("TODO").or_else(|| content.find("todo"))?;
    if todo_index > 3 && content[3..todo_index].trim().is_empty() {
        content.replace_range(3..todo_index, "");
        todo_index = 3;
    }
    if !content.starts_with("// ") {
        content = content.replacen("//", "// ", 1);
    }
    if todo_index == 3 && content.len() > 7 && content[7..].starts_with(' ') {
        content.replace_range(7..8, "");
    }
    if todo_index == 3 {
        let colon_index = content.find(')').map_or(0, |at| at + 1);
        if content.len() > colon_index && !content[colon_index..].starts_with(':') {
            content = content.replacen(')', "):", 1);
        }
    }
    if let Some(rest) = content.strip_prefix("// todo") {
        content = format!("// TODO{rest}");
    }
    // Stray `TODO`s in the message body gain back ticks (after the head).
    let mut rebuilt = String::with_capacity(content.len());
    let bytes = content.as_bytes();
    let mut cursor = 0;
    while cursor + 4 <= bytes.len() {
        if content[cursor..].len() >= 4 && content[cursor..cursor + 4].eq_ignore_ascii_case("TODO")
        {
            if cursor > 4 {
                rebuilt.push('`');
                rebuilt.push_str(&content[cursor..cursor + 4]);
                rebuilt.push('`');
            } else {
                rebuilt.push_str(&content[cursor..cursor + 4]);
            }
            cursor += 4;
        } else {
            rebuilt.push(content[cursor..].chars().next()?);
            cursor += content[cursor..].chars().next()?.len_utf8();
        }
    }
    rebuilt.push_str(&content[cursor..]);
    // The official gate: the comment must still read as a TODO comment and
    // not as an already-styled one.
    if !todo_comment_head(&rebuilt) || flutter_todo_styled(&rebuilt) {
        return None;
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        rebuilt,
    ))
}

/// The lint's `_todoRegExp`: `//+` `ws*` `TODO` + word boundary
/// (case-insensitive).
fn todo_comment_head(content: &str) -> bool {
    let rest = content.trim_start_matches('/');
    if rest.len() == content.len() {
        return false;
    }
    let rest = rest.trim_start_matches([' ', '\t']);
    rest.get(..4)
        .is_some_and(|head| head.eq_ignore_ascii_case("TODO"))
        && !rest[4..].starts_with(|c: char| c.is_ascii_alphanumeric() || c == '_')
}

/// The lint's `_todoExpectedRegExp`: `//` `ws*` `TODO(author): `.
fn flutter_todo_styled(content: &str) -> bool {
    let Some(rest) = content.strip_prefix("//") else {
        return false;
    };
    let rest = rest.trim_start_matches([' ', '\t']);
    let Some(rest) = rest.strip_prefix("TODO(") else {
        return false;
    };
    let mut chars = rest.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !first.is_ascii_alphanumeric() {
        return false;
    }
    let mut consumed = first.len_utf8();
    for c in chars {
        if c == ')' {
            return rest[consumed + 1..].starts_with("): ");
        }
        if !(c.is_ascii_alphanumeric() || c == '-' || c == '.') {
            return false;
        }
        consumed += c.len_utf8();
    }
    false
}

/// `avoid_returning_null_for_void`: the `null` between the `return` (or
/// `=>`) and its terminator goes — `return null;` becomes `return;`, the
/// expression-body `=> null` becomes `{}` (the official
/// `RemoveReturnedValue`'s two faces).
pub(crate) fn remove_returned_value(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    let end = utf16_offset_to_byte(text, input.range.end);
    if text.get(start..end)? != "null" {
        return None;
    }
    let head = text.get(..start)?.trim_end_matches([' ', '\t']);
    if let Some(rest) = head.strip_suffix("=>") {
        if rest.ends_with(is_identifier_char) {
            return None;
        }
        return Some((
            u32::try_from(utf16_count(head) - 2).ok()?,
            input.range.end - u32::try_from(utf16_count(head) - 2).ok()?,
            "{}".to_owned(),
        ));
    }
    if head.ends_with("return") && !head[..head.len() - 6].ends_with(is_identifier_char) {
        return Some((
            u32::try_from(utf16_count(head)).ok()?,
            input.range.end - u32::try_from(utf16_count(head)).ok()?,
            String::new(),
        ));
    }
    None
}

/// `avoid_void_async`: the `void` return type spelled right before the
/// reported function name becomes `Future<void>` (the official
/// `ReplaceReturnTypeFuture` replaces the annotation).
pub(crate) fn return_type_future(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    let head = text.get(..start)?.trim_end_matches([' ', '\t']);
    let rest = head.strip_suffix("void")?;
    if rest.ends_with(is_identifier_char) {
        return None;
    }
    let at = u32::try_from(utf16_count(head) - 4).ok()?;
    Some((at, 4, "Future<void>".to_owned()))
}

/// `avoid_print`: the reported `print` selector expands to its invocation
/// and the statement's line content goes (the official `RemovePrint`'s
/// lines-range face; content after the invocation on the same line keeps
/// everything but the invocation itself, [`drop_span_statement`]'s shape).
pub(crate) fn remove_print_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if first != last || !word_at(tokens, text, first, "print") {
        return None;
    }
    if kind_of(tokens, first + 1)? != TokenKind::OpenParen {
        return None;
    }
    let rparen = tokens.matching_end(first + 1)?;
    let mut after = rparen + 1;
    if kind_of(tokens, after) == Some(TokenKind::Semicolon) {
        after += 1;
    } else {
        after = rparen + 1;
    }
    let (start16, length16) = span_over(text, tokens, first, after - 1)?;
    drop_span_statement(text, &(start16..start16 + length16))
}

/// `cast_nullable_to_non_nullable`: the `!` lands after the cast's operand
/// (the official `AddNullCheck.withoutAssignabilityCheck`'s as-expression
/// face — the cast itself stays).
pub(crate) fn cast_null_check(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let as_token = depth0_find(tokens, text, first, last + 1, |kind, _| {
        kind == TokenKind::Keyword(Keyword::As)
    })?;
    if as_token == first {
        return None;
    }
    append_bang(input, first, as_token - 1)
}

/// `combinators_ordering`: the reported combinator's names are rebuilt in
/// sorted order (the official `SortCombinators` replaces each name with
/// the sorted name at its position — folded into one combinator
/// replacement; the sort is the official `List.sort` byte order).
pub(crate) fn sort_combinator_names(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let (keyword, names_raw) = slice.split_once([' ', '\t'])?;
    if keyword != "show" && keyword != "hide" {
        return None;
    }
    let mut names: Vec<&str> = names_raw.split(',').map(str::trim).collect();
    if names.len() < 2 || names.iter().any(|name| !word_shape(name)) {
        return None;
    }
    names.sort_unstable();
    let rebuilt = format!("{keyword} {}", names.join(", "));
    if rebuilt == slice {
        return None;
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        rebuilt,
    ))
}

/// `dangling_library_doc_comments`: a leading doc comment with nothing but
/// whitespace before it gains the explicit `library;` after its block (the
/// official `MoveDocCommentToLibraryDirective`'s in-place face); the
/// relocation face (comment below other directives, metadata unions) is a
/// second edit and is not served.
pub(crate) fn add_library_directive_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    if !text.get(..start)?.trim().is_empty() {
        return None;
    }
    // `library;` lands after the comment line's terminator (the official
    // insertion sits at the lines range' end, past the `\r\n` pair).
    let end = utf16_offset_to_byte(text, input.range.end);
    let rest = text.get(end..)?;
    let (at, insertion) = match rest.find('\n') {
        Some(i) => (end + i + 1, "library;\n"),
        None => (text.len(), "\nlibrary;"),
    };
    Some((utf16_count(&text[..at]), 0, insertion.to_owned()))
}

/// `library_annotations`: a leading annotation with nothing but whitespace
/// before it gains the explicit `library;` beneath itself (the official
/// `MoveAnnotationToLibraryDirective`'s in-place face folded into one
/// whole-annotation replacement; the relocation face is a second edit and
/// is not served). The replacement ends at the directive — the
/// annotation's own line terminator stays in the untouched text and
/// closes the inserted line, so no blank line opens between the two.
pub(crate) fn annotation_library_directive_entry(
    input: &FixInput<'_>,
) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    if !text.get(..start)?.trim().is_empty() {
        return None;
    }
    let slice = slice16(text, &input.range)?;
    Some((
        input.range.start,
        input.range.end - input.range.start,
        format!("{slice}\nlibrary;"),
    ))
}

/// `no_duplicate_case_values`: the duplicate case clause leaves — the case
/// head alone when the previous clause's statements fall through into it
/// (the official `RemoveDuplicateCase`'s `startEnd(node, colon)` face), the
/// whole clause with its statements when the previous member has
/// statements of its own (the `range.node(node)` face).
pub(crate) fn remove_duplicate_case(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (hit, hit_last) = hit_tokens(tokens, &input.range)?;
    // Walk back to the clause's `case` keyword (the report sits on the
    // duplicated value expression).
    let mut case = hit;
    while case > 0 && !word_at(tokens, text, case, "case") {
        case -= 1;
    }
    if case == 0 && !word_at(tokens, text, case, "case") {
        return None;
    }
    // The clause's `:` follows the value's last token (the bound is
    // exclusive — one past it).
    let colon = depth0_find(tokens, text, case, hit_last + 2, |kind, _| {
        kind == TokenKind::Colon
    })?;
    // The previous clause: the nearest `case`/`default` keyword or the
    // switch body's `{` behind this one.
    let mut previous = None;
    let mut index = case;
    while index > 0 {
        index -= 1;
        let kind = kind_of(tokens, index)?;
        if matches!(kind, TokenKind::OpenCurly) {
            previous = Some(index);
            break;
        }
        if word_at(tokens, text, index, "case") || word_at(tokens, text, index, "default") {
            // The previous clause's colon: the first depth-0 `:` after it.
            let previous_colon = depth0_find(tokens, text, index, case, |kind, _| {
                kind == TokenKind::Colon
            })?;
            previous = Some(previous_colon);
            break;
        }
    }
    let previous = previous?;
    // Statements between the previous clause's colon (or the body `{`) and
    // this clause keep this clause's statements attached to it: the head
    // alone goes; an empty gap takes the whole clause.
    let previous_holds_statements = depth0_find(tokens, text, previous + 1, case, |kind, _| {
        kind == TokenKind::Semicolon
    })
    .is_some();
    let (start, length) = if previous_holds_statements {
        // Whole clause: from `case` through the last statement before the
        // next clause keyword or the body's `}`.
        let mut end = colon;
        let mut cursor = colon + 1;
        let mut depth = 0u32;
        while cursor < tokens.as_slice().len() {
            match kind_of(tokens, cursor)? {
                TokenKind::OpenParen
                | TokenKind::OpenSquare
                | TokenKind::OpenCurly
                | TokenKind::StringInterpolationExpression => depth += 1,
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                _ if depth == 0
                    && (word_at(tokens, text, cursor, "case")
                        || word_at(tokens, text, cursor, "default")) =>
                {
                    break;
                }
                _ if depth == 0 && kind_of(tokens, cursor)? == TokenKind::Semicolon => {
                    end = cursor;
                }
                _ => {}
            }
            cursor += 1;
        }
        let (a, b) = span_over(text, tokens, case, end)?;
        drop_lines_range(text, a, a + b)?
    } else {
        let (a, b) = span_over(text, tokens, case, colon)?;
        drop_lines_range(text, a, a + b)?
    };
    Some((start, length, String::new()))
}

/// The whole-line cut of `[start, end)` — every line the span touches
/// loses its content and terminator (the official `getLinesRange`
/// deletion face for multi-line constructs).
fn drop_lines_range(text: &str, start16: u32, end16: u32) -> Option<(u32, u32)> {
    let start = utf16_offset_to_byte(text, start16);
    let end = utf16_offset_to_byte(text, end16);
    let line_start = text[..start].rfind('\n').map_or(0, |i| i + 1);
    let line_end = text[end..].find('\n').map_or(text.len(), |i| end + i);
    Some(cut_line(text, line_start, line_end))
}

/// `unnecessary_overrides`: the reported member's line block goes — the
/// lines the declaration occupies, annotations and doc comment with it
/// (the official `RemoveMethodDeclaration` deletes the member's lines
/// range). The member's end is rebuilt from the token stream: through the
/// parameter list and body block, or to the `;` / `=>` statement's
/// semicolon.
pub(crate) fn remove_override_member(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (mut cursor, _) = hit_tokens(tokens, &input.range)?;
    let end;
    loop {
        match kind_of(tokens, cursor)? {
            TokenKind::OpenParen => cursor = tokens.matching_end(cursor)? + 1,
            TokenKind::OpenCurly => {
                end = tokens.matching_end(cursor)?;
                break;
            }
            TokenKind::Semicolon => {
                end = cursor;
                break;
            }
            // `=> expr;` — the member ends at its statement's `;`.
            TokenKind::Function => {
                end = depth0_find(
                    tokens,
                    text,
                    cursor + 1,
                    tokens.as_slice().len(),
                    |kind, _| kind == TokenKind::Semicolon,
                )?;
                break;
            }
            TokenKind::Eof => return None,
            _ => cursor += 1,
        }
    }
    let member_start = member_block_start(text, input.range.start);
    let end_byte = token_end(tokens.get(end)?);
    let line_end = text[end_byte..]
        .find('\n')
        .map_or(text.len(), |i| end_byte + i);
    let (offset, length) = cut_line(text, member_start, line_end);
    Some((offset, length, String::new()))
}

/// `use_if_null_to_convert_nulls_to_bools`: the `bool?`-vs-null comparison
/// becomes the null-aware fallback (`x == null` → `x ?? false`, `x != null`
/// → `x ?? true`; the official `ConvertToIfNull.useToConvertNullsToBools`
/// replaces the comparison, parenthesized when the parent binds tighter
/// than `??`).
pub(crate) fn if_null_bools(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let op = depth0_find(tokens, text, first, last + 1, |kind, _| {
        matches!(kind, TokenKind::EqEq | TokenKind::BangEq)
    })?;
    let (left, right) = (first..op, op + 1..last + 1);
    let nullable = if !is_bool_literal_pair(tokens, text, left.clone()) {
        left
    } else if !is_bool_literal_pair(tokens, text, right.clone()) {
        right
    } else {
        return None;
    };
    let value = if kind_of(tokens, op)? == TokenKind::EqEq {
        "false"
    } else {
        "true"
    };
    let mut rebuilt = format!("{} ?? {value}", token_text(tokens, text, nullable)?,);
    // Outer parentheses when the comparison's parent binds tighter than
    // `??`: an operator-flanked span keeps its parens.
    let before = text
        .get(..utf16_offset_to_byte(text, input.range.start))?
        .trim_end();
    let after = text
        .get(utf16_offset_to_byte(text, input.range.end)..)?
        .trim_start();
    let followed_by_operator = after
        .chars()
        .next()
        .is_some_and(|c| "+-*/%<>=!&|^?~".contains(c));
    let preceded_by_operator = match before.chars().last() {
        // A lone `=` is the assignment — it binds below `??` and needs no
        // parens; a compound or comparison `=` rides an operator run and
        // keeps them.
        Some('=') => before
            .chars()
            .rev()
            .nth(1)
            .is_some_and(|c| "+-*/%<>=!&|^?~".contains(c)),
        Some(c) => "+-*/%<>=!&|^?~".contains(c),
        None => false,
    };
    if followed_by_operator || preceded_by_operator {
        rebuilt = format!("({rebuilt})");
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        rebuilt,
    ))
}

/// Whether the token range is exactly one `true`/`false` literal.
fn is_bool_literal_pair(tokens: &TokenTable, text: &str, range: core::ops::Range<usize>) -> bool {
    range.len() == 1 && bool_literal(tokens, text, range.start).is_some()
}

/// The start of the member's attached line block: the reported span's line
/// walked up over annotation and doc-comment lines (the official lines
/// range covers the declaration's begin token, docs included). Lines
/// inside a `/* … */` block comment ride too — a continuation line needn't
/// open with `*` (the walk tracks an unclosed `/*` region so a
/// `/*\n  text\n*/` comment moves whole).
fn member_block_start(text: &str, start16: u32) -> usize {
    let start = utf16_offset_to_byte(text, start16);
    let mut block_start = text[..start].rfind('\n').map_or(0, |i| i + 1);
    // `in_block` marks accepted lines already inside a `/*` region — the
    // next failure must be the comment's `/*` head line.
    let mut in_block = false;
    loop {
        let head_end = text[..block_start]
            .trim_end_matches([' ', '\t', '\r'])
            .len();
        let line_start = line_start_before(text, head_end);
        let trimmed = text[line_start..head_end].trim_start();
        if trimmed.starts_with('@')
            || trimmed.starts_with("///")
            || trimmed.starts_with("/**")
            || trimmed.starts_with('*')
        {
            block_start = line_start;
            continue;
        }
        if in_block {
            // Mid-comment walk: the `/*` head line ends the region; lines
            // above it (`///` docs, `@` annotations) keep walking.
            if trimmed.starts_with("/*") {
                block_start = line_start;
                in_block = false;
                continue;
            }
            return block_start;
        }
        // A line inside an unclosed `/*` region rides the comment — the
        // source before it holds a `/*` with no matching `*/` yet.
        let before = &text[..line_start];
        let opens = before.rfind("/*");
        let closes = before.rfind("*/");
        if opens.is_some_and(|o| closes.is_none_or(|c| c < o)) {
            block_start = line_start;
            in_block = true;
            continue;
        }
        return block_start;
    }
}

/// `use_null_aware_elements`: the null-check if-element becomes the
/// null-aware element — `if (x != null) x` → `?x`, the spread
/// `...?x`, the bang element `x!` loses its operator (the official
/// `ConvertNullCheckToNullAwareElementOrEntry`'s element faces; the
/// map-entry faces need the canonical-element resolution and are not
/// served).
pub(crate) fn null_aware_element(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if !word_at(tokens, text, first, "if") {
        return None;
    }
    let lparen = first + 1;
    let rparen = tokens.matching_end(lparen)?;
    if depth0_find(tokens, text, rparen + 1, last + 1, |kind, lexeme| {
        kind == TokenKind::Keyword(Keyword::Else) || lexeme == "case"
    })
    .is_some()
    {
        return None;
    }
    let op = depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        matches!(kind, TokenKind::EqEq | TokenKind::BangEq)
    })?;
    if depth0_find(tokens, text, op + 1, rparen, |kind, _| {
        matches!(kind, TokenKind::EqEq | TokenKind::BangEq)
    })
    .is_some()
    {
        return None;
    }
    let checked = if is_null_token(tokens, op + 1) {
        lparen + 1..op
    } else if op > lparen + 1 && is_null_token(tokens, op - 1) {
        op + 1..rparen
    } else {
        return None;
    };
    if checked.len() != 1 {
        return None;
    }
    // The then element: the checked identifier bare, spread, or
    // bang-postfixed.
    let element = rparen + 1..last + 1;
    let (spread, head) = match kind_of(tokens, element.start)? {
        TokenKind::PeriodPeriodPeriod => (true, element.start + 1),
        _ => (false, element.start),
    };
    let bang = element.end > head + 1
        && kind_of(tokens, element.end - 1) == Some(TokenKind::Bang)
        && kind_of(tokens, element.end - 2) != Some(TokenKind::Bang);
    let operand = if bang {
        head..element.end - 1
    } else {
        head..element.end
    };
    let name = tokens.lexeme(text, checked.start).to_owned();
    if !same_tokens(tokens, text, checked, operand) {
        return None;
    }
    let marker = if spread { "...?" } else { "?" };
    Some((
        input.range.start,
        input.range.end - input.range.start,
        format!("{marker}{name}"),
    ))
}

/// `use_truncating_division`: the parenthesized division's `.truncate()`
/// wrapper folds into the `~/` operator — `(a / b).truncate()` →
/// `a ~/ b` (or `(a ~/ b)` when the surrounding context binds at
/// multiplicative strength or tighter; the official
/// `UseEffectiveIntegerDivision`'s two faces).
pub(crate) fn truncating_division(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if kind_of(tokens, first)? != TokenKind::OpenParen || last < first + 4 {
        return None;
    }
    let lparen = first;
    let rparen = tokens.matching_end(lparen)?;
    // `… . truncate ( )` must close the span exactly.
    if rparen + 4 != last
        || kind_of(tokens, rparen + 1)? != TokenKind::Period
        || tokens.lexeme(text, rparen + 2) != "truncate"
        || kind_of(tokens, rparen + 3)? != TokenKind::OpenParen
        || kind_of(tokens, rparen + 4)? != TokenKind::CloseParen
    {
        return None;
    }
    // The parenthesized target's depth-0 operator is a plain `/`; a `~/`
    // or a looser operator sharing the group is not this rewrite's shape.
    let slash = depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::Slash
    })?;
    if depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        matches!(
            kind,
            TokenKind::Question | TokenKind::Eq | TokenKind::Semicolon
        )
    })
    .is_some()
    {
        return None;
    }
    let head = token_text(tokens, text, lparen + 1..slash)?;
    let tail = token_text(tokens, text, slash + 1..rparen)?;
    let mut rebuilt = format!("{head} ~/ {tail}");
    // The wrapper parens survive only when the context binds at
    // multiplicative strength or tighter (the official's parent-precedence
    // gate): a multiplicative follower or a selector/call/index suffix
    // keeps them, as does a unary minus before; anything delimiter- or
    // lower-precedence-flanked drops them.
    let before = text
        .get(..utf16_offset_to_byte(text, input.range.start))?
        .trim_end();
    let after = text
        .get(utf16_offset_to_byte(text, input.range.end)..)?
        .trim_start();
    let unary_minus = before.ends_with('-')
        && !before.ends_with(|c: char| c.is_alphanumeric() || "_)]".contains(c));
    if after.starts_with(['*', '/', '%', '.', '(', '[']) || unary_minus {
        rebuilt = format!("({rebuilt})");
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        rebuilt,
    ))
}

/// The analyzer's binary-operator precedence (`Precedence`), or `None` for
/// tokens that never bind an expression — the boundary read the operand
/// walks use (`a + b` belongs to `a + b == true`, a `,` never does).
fn binary_precedence(kind: TokenKind) -> Option<u8> {
    Some(match kind {
        TokenKind::Eq
        | TokenKind::PlusEq
        | TokenKind::MinusEq
        | TokenKind::StarEq
        | TokenKind::SlashEq
        | TokenKind::PercentEq
        | TokenKind::TildeSlashEq
        | TokenKind::AmpersandEq
        | TokenKind::BarEq
        | TokenKind::CaretEq
        | TokenKind::LtLtEq
        | TokenKind::GtGtEq
        | TokenKind::GtGtGtEq
        | TokenKind::QuestionQuestionEq => 1,
        TokenKind::PeriodPeriod | TokenKind::QuestionPeriodPeriod => 2,
        TokenKind::Question => 3,
        TokenKind::QuestionQuestion => 4,
        TokenKind::BarBar => 5,
        TokenKind::AmpersandAmpersand => 6,
        TokenKind::EqEq | TokenKind::BangEq => 7,
        TokenKind::Lt
        | TokenKind::LtEq
        | TokenKind::Gt
        | TokenKind::GtEq
        | TokenKind::Keyword(Keyword::Is)
        | TokenKind::Keyword(Keyword::As) => 8,
        TokenKind::Bar => 9,
        TokenKind::Caret => 10,
        TokenKind::Ampersand => 11,
        TokenKind::LtLt | TokenKind::GtGt | TokenKind::GtGtGt => 12,
        TokenKind::Plus | TokenKind::Minus => 13,
        TokenKind::Star | TokenKind::Slash | TokenKind::Percent | TokenKind::TildeSlash => 14,
        _ => return None,
    })
}

/// Whether the token range carries a depth-0 operator binding at `max`
/// precedence or tighter — the official `needsParens(operator)` read
/// (`Precedence.forTokenType`).
fn binds_at_or_below(tokens: &TokenTable, range: core::ops::Range<usize>, max: u8) -> bool {
    let mut depth = 0u32;
    for index in range {
        let Some(kind) = kind_of(tokens, index) else {
            return true;
        };
        match kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1).unwrap_or(0);
            }
            _ if depth == 0 && binary_precedence(kind).is_some_and(|p| p <= max) => return true,
            _ => {}
        }
    }
    false
}

/// Whether the kind is one of the logic operators (`|`, `||`, `&`, `&&`)
/// whose literal operand the official `isPositiveCase` treats as an
/// identity candidate.
fn is_bool_logic(kind: TokenKind) -> bool {
    matches!(
        kind,
        TokenKind::Bar | TokenKind::BarBar | TokenKind::Ampersand | TokenKind::AmpersandAmpersand
    )
}

/// `no_literal_bool_comparisons`: the comparison keeps its non-literal
/// operand — negated when the literal's value survives the flip (`x ==
/// false` → `!x`), untouched otherwise (`x == true` → `x`), and an
/// identity operand (`x || true`, `x && false`) keeps the literal (the
/// official `ConvertToBooleanExpression`'s binary faces, parenthesized by
/// the operand's own precedence).
pub(crate) fn bool_comparison(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (literal, _) = hit_tokens(tokens, &input.range)?;
    let value = bool_literal(tokens, text, literal)?;
    let op = if kind_of(tokens, literal.wrapping_sub(1)).is_some_and(is_comparison_kind) {
        (literal - 1, false)
    } else if kind_of(tokens, literal + 1).is_some_and(is_comparison_kind) {
        (literal + 1, true)
    } else {
        return None;
    };
    let mine = binary_precedence(kind_of(tokens, op.0)?)?;
    // The other operand reaches the first separator, enclosing-delimiter
    // edge, or looser operator on the far side of the comparison.
    let other = if op.1 {
        let mut depth = 0u32;
        let mut end = op.0;
        let mut index = op.0;
        loop {
            index += 1;
            match kind_of(tokens, index)? {
                TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => depth += 1,
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                TokenKind::Comma | TokenKind::Semicolon | TokenKind::Colon if depth == 0 => break,
                kind if depth == 0 && binary_precedence(kind).is_some_and(|p| p < mine) => break,
                _ => {}
            }
            end = index;
        }
        if end == op.0 {
            return None;
        }
        op.0 + 1..end + 1
    } else {
        let mut depth = 0u32;
        let mut start = op.0;
        let mut index = op.0;
        while index > 0 {
            index -= 1;
            match kind_of(tokens, index)? {
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                    depth += 1
                }
                TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                TokenKind::Comma | TokenKind::Semicolon | TokenKind::Colon if depth == 0 => break,
                kind if depth == 0 && binary_precedence(kind).is_some_and(|p| p < mine) => break,
                _ => {}
            }
            start = index;
        }
        if start == op.0 {
            return None;
        }
        start..op.0
    };
    let op_kind = kind_of(tokens, op.0)?;
    // `x || true` / `x && false` keep the literal; everything else keeps
    // the operand (negated unless the comparison is already positive).
    let identity = (value && matches!(op_kind, TokenKind::Bar | TokenKind::BarBar))
        || (!value
            && matches!(
                op_kind,
                TokenKind::Ampersand | TokenKind::AmpersandAmpersand
            ));
    let (span_first, span_last) = if literal < other.start {
        (literal, other.end - 1)
    } else {
        (other.start, literal)
    };
    let (start, length) = span_over(text, tokens, span_first, span_last)?;
    let replacement = if identity {
        tokens.lexeme(text, literal).to_owned()
    } else {
        let positive = match op_kind {
            TokenKind::EqEq => value,
            TokenKind::BangEq | TokenKind::Caret => !value,
            TokenKind::Bar
            | TokenKind::BarBar
            | TokenKind::Ampersand
            | TokenKind::AmpersandAmpersand => true,
            _ => return None,
        };
        if !positive {
            bang_wrapped(tokens, text, other)?
        } else if binds_loose(tokens, other.clone()) {
            format!("({})", token_text(tokens, text, other.clone())?)
        } else {
            token_text(tokens, text, other)?
        }
    };
    Some((start, length, replacement))
}

/// The comparison operators the rewrite anchors on: the equality family
/// (precedence 7) and the logic operators.
fn is_comparison_kind(kind: TokenKind) -> bool {
    binary_precedence(kind) == Some(7) || is_bool_logic(kind)
}

/// `avoid_bool_literals_in_conditional_expressions`: the conditional
/// flattens to a boolean expression (the official
/// `ConvertToBooleanExpression`'s conditional faces): equal arms keep one
/// literal, an arm literal folds into `||`/`&&` with the condition
/// negated when the arm was `false`, and `c ? false : true` becomes the
/// negated condition — each part parenthesized by the official
/// `needsParens` gates.
pub(crate) fn bool_conditional(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let (question, colon) = ternary_split(tokens, text, first, last)?;
    let cond = first..question;
    let then_arm = question + 1..colon;
    let else_arm = colon + 1..last + 1;
    let then_value = (then_arm.len() == 1).then(|| bool_literal(tokens, text, then_arm.start))?;
    let else_value = (else_arm.len() == 1).then(|| bool_literal(tokens, text, else_arm.start))?;
    let whole = (input.range.start, input.range.end - input.range.start);
    match (then_value, else_value) {
        (Some(tv), Some(ev)) => {
            if tv == ev {
                // `c ? t : t` keeps the then literal.
                let lit = tokens.lexeme(text, then_arm.start).to_owned();
                Some((whole.0, whole.1, lit))
            } else {
                // `c ? t : e` keeps the condition — the bang rides inside
                // the parens here (the official `bangBeforeParens: false`).
                let body = token_text(tokens, text, cond.clone())?;
                let negated = !tv && ev;
                let s = match (binds_loose(tokens, cond.clone()), negated) {
                    (true, true) => format!("!({body})"),
                    (true, false) => format!("({body})"),
                    (false, true) => format!("!{body}"),
                    (false, false) => body,
                };
                Some((whole.0, whole.1, s))
            }
        }
        (Some(tv), None) => {
            // `c ? t : y` folds the then literal into `||`/`&&`.
            let (op, op_prec) = if tv { ("||", 5u8) } else { ("&&", 6) };
            let negated = !tv;
            let cond_text = token_text(tokens, text, cond.clone())?;
            let cond_part = if negated {
                if binds_loose(tokens, cond.clone()) {
                    format!("!({cond_text})")
                } else {
                    format!("!{cond_text}")
                }
            } else if binds_at_or_below(tokens, cond.clone(), op_prec) {
                format!("({cond_text})")
            } else {
                cond_text
            };
            let else_text = token_text(tokens, text, else_arm.clone())?;
            let else_part = if binds_at_or_below(tokens, else_arm, op_prec) {
                format!("({else_text})")
            } else {
                else_text
            };
            Some((whole.0, whole.1, format!("{cond_part} {op} {else_part}")))
        }
        (None, Some(ev)) => {
            // `c ? x : t` folds the else literal into `||`/`&&`.
            let (op, op_prec) = if ev { ("||", 5u8) } else { ("&&", 6) };
            let negated = ev;
            let cond_text = token_text(tokens, text, cond.clone())?;
            let cond_part = if negated {
                if binds_loose(tokens, cond.clone()) {
                    format!("!({cond_text})")
                } else {
                    format!("!{cond_text}")
                }
            } else if binds_at_or_below(tokens, cond.clone(), op_prec) {
                format!("({cond_text})")
            } else {
                cond_text
            };
            let then_text = token_text(tokens, text, then_arm.clone())?;
            let then_part = if binds_at_or_below(tokens, then_arm, op_prec) {
                format!("({then_text})")
            } else {
                then_text
            };
            Some((whole.0, whole.1, format!("{cond_part} {op} {then_part}")))
        }
        (None, None) => None,
    }
}

/// `prefer_if_elements_to_conditional_expressions`: the conditional becomes
/// an if-element in place — `[a, c ? t : e]` → `[a, if (c) t else e]`
/// (the official `ConvertConditionalExpressionToIfElement` writes the
/// unparenthesized branches into the reported element; only list/set
/// element positions serve, never a map entry or an argument).
pub(crate) fn conditional_to_if_element(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    let (question, colon) = ternary_split(tokens, text, first, last)?;
    let start_b = utf16_offset_to_byte(text, input.range.start);
    let end_b = utf16_offset_to_byte(text, input.range.end);
    let before = text.get(..start_b)?.trim_end();
    let after = text.get(end_b..)?.trim_start();
    // The reported element's neighbours: a list/set element, an if-element
    // branch, or a for-element body opens at `[`/`{`/`,`/`)` and closes at
    // `,`/`]`/`}` — a spread, a map separator, or an argument never does.
    if !matches!(before.as_bytes().last(), Some(b'[' | b'{' | b',' | b')')) {
        return None;
    }
    if !matches!(after.as_bytes().first(), Some(b',' | b']' | b'}')) {
        return None;
    }
    let unparen = |mut a: usize, mut b: usize| -> (usize, usize) {
        while b > a + 1
            && kind_of(tokens, a) == Some(TokenKind::OpenParen)
            && kind_of(tokens, b) == Some(TokenKind::CloseParen)
            && tokens.matching_end(a) == Some(b)
        {
            a += 1;
            b -= 1;
        }
        (a, b)
    };
    let (cf, cl) = unparen(first, question - 1);
    let (tf, tl) = unparen(question + 1, colon - 1);
    let (ef, el) = unparen(colon + 1, last);
    let cond = token_text(tokens, text, cf..cl + 1)?;
    let then = token_text(tokens, text, tf..tl + 1)?;
    let els = token_text(tokens, text, ef..el + 1)?;
    Some((
        input.range.start,
        input.range.end - input.range.start,
        format!("if ({cond}) {then} else {els}"),
    ))
}

/// `use_full_hex_values_for_flutter_colors`: the short hex literal is
/// padded to eight digits — plain literals re-render from the value
/// (`0xFF` → `0x000000ff`), separator-carrying literals pad in place and
/// the `aa_bb_cc` triplet shape gains a `00_` group (the official
/// `ReplaceWithEightDigitHex`'s three faces; the prefix case is kept).
pub(crate) fn eight_digit_hex(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let slice = slice16(input.text, &input.range)?;
    let prefix = if let Some(rest) = slice.strip_prefix("0x") {
        ("0x", rest)
    } else if let Some(rest) = slice.strip_prefix("0X") {
        ("0X", rest)
    } else {
        return None;
    };
    let digits_raw = prefix.1;
    let stripped: String = digits_raw.chars().filter(|c| *c != '_').collect();
    if stripped.is_empty() || !stripped.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let body = if digits_raw.contains('_') {
        let triplet = digits_raw.len() == 8
            && digits_raw.bytes().enumerate().all(|(i, b)| match i {
                2 | 5 => b == b'_',
                _ => b.is_ascii_hexdigit(),
            });
        if triplet {
            format!("00_{digits_raw}")
        } else {
            let pad = 8usize.checked_sub(stripped.len())?;
            format!("{}{digits_raw}", "0".repeat(pad))
        }
    } else {
        let value = u64::from_str_radix(&stripped, 16).ok()?;
        format!("{value:08x}")
    };
    Some((
        input.range.start,
        input.range.end - input.range.start,
        format!("{}{}", prefix.0, body),
    ))
}

/// The first token at or after the UTF-16 `offset` — the width-0 report
/// positions (`start..start` at a name) resolve through here.
fn token_at(tokens: &TokenTable, offset: u32) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = tokens.as_slice().len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        if tokens.get(mid)?.utf16_offset < offset {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    (lo < tokens.as_slice().len()).then_some(lo)
}

/// Whether the token's lexeme opens like an identifier (words, including
/// contextual keywords and type names).
fn wordish(tokens: &TokenTable, text: &str, index: usize) -> bool {
    tokens
        .lexeme(text, index)
        .chars()
        .next()
        .is_some_and(is_identifier_char)
}

/// Whether the parameter segment at `[start, end)` reads as a typed one —
/// more than one token (type + name), or a function-typed suffix the
/// official `_allParametersHaveTypes` exempts. A single bare word refuses
/// (the old-form name-only parameter the conversion cannot express).
fn parameter_typed(tokens: &TokenTable, text: &str, start: usize, end: usize) -> Option<bool> {
    if start >= end {
        return None;
    }
    let mut depth = 0u32;
    let mut group = false;
    let mut count = 0usize;
    for index in start..end {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                depth += 1;
                if depth == 1 && kind_of(tokens, index) == Some(TokenKind::OpenParen) {
                    group = true;
                }
            }
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ if depth == 0 => count += 1,
            _ => {}
        }
    }
    Some(group || count > 1 || count == 1 && !wordish(tokens, text, start))
}

/// `prefer_generic_function_type_aliases`: the old-form `typedef` (no `=`)
/// rebuilds as a generic function type — `typedef void F<T>(int x);` →
/// `typedef F<T> = void Function(int x);` — the name and written tail
/// carried verbatim (the official `ConvertToGenericFunctionSyntax`'s alias
/// face over `[typedef.next, semicolon)`; an untyped parameter refuses).
pub(crate) fn generic_alias_syntax(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let first = token_at(tokens, input.range.start)?;
    // The `typedef` keyword walks back over an optional return type
    // (`typedef void F(…)`); anything else between refuses.
    let mut typedef = first;
    loop {
        if typedef == 0 {
            return None;
        }
        if tokens.lexeme(text, typedef - 1) == "typedef" {
            break;
        }
        typedef -= 1;
        match kind_of(tokens, typedef)? {
            TokenKind::Question
            | TokenKind::Lt
            | TokenKind::Gt
            | TokenKind::GtGt
            | TokenKind::GtGtGt
            | TokenKind::Period => {}
            kind if matches!(kind, TokenKind::Keyword(_)) || wordish(tokens, text, typedef) => {}
            _ => return None,
        }
        if first - typedef > 16 {
            return None;
        }
    }
    // The name carries optional type parameters, then the parameter list
    // closes straight into the `;` (the written tail is verbatim).
    let mut tp_end = first;
    if kind_of(tokens, first + 1) == Some(TokenKind::Lt) {
        let mut angle = 0u32;
        let mut index = first + 1;
        loop {
            match kind_of(tokens, index)? {
                TokenKind::Lt => angle += 1,
                TokenKind::Gt => angle -= 1,
                TokenKind::GtGt => angle -= 2,
                TokenKind::GtGtGt => angle -= 3,
                _ => {}
            }
            if angle == 0 {
                tp_end = index;
                break;
            }
            index += 1;
        }
    }
    if kind_of(tokens, tp_end + 1)? != TokenKind::OpenParen {
        return None;
    }
    let params_open = tp_end + 1;
    let params_close = tokens.matching_end(params_open)?;
    if kind_of(tokens, params_close + 1)? != TokenKind::Semicolon {
        return None;
    }
    // Every parameter reads as typed (the official gate).
    let mut start = params_open + 1;
    let mut typed = true;
    let mut index = params_open + 1;
    loop {
        match kind_of(tokens, index)? {
            TokenKind::Comma if depth_of(tokens, params_open + 1, index)? == 0 => {
                typed &= parameter_typed(tokens, text, start, index)?;
                start = index + 1;
            }
            TokenKind::Semicolon => break,
            _ => {}
        }
        index += 1;
    }
    typed &= parameter_typed(tokens, text, start, params_close)?;
    if !typed {
        return None;
    }
    // `{name}{<T>} = {returnType }Function{parameters}` over the written
    // tail.
    let name = token_text(tokens, text, first..tp_end + 1)?;
    let return_type = if typedef == first {
        String::new()
    } else {
        format!("{} ", token_text(tokens, text, typedef..first)?)
    };
    let parameters = token_text(tokens, text, params_open..params_close + 1)?;
    // The written tail from the `typedef` walk's landing token — the
    // return type's first token when one is spelled, the name otherwise
    // (`[typedef.next, semicolon)`).
    let (start, length) = span_over(text, tokens, typedef, params_close)?;
    Some((
        start,
        length,
        format!("{name} = {return_type}Function{parameters}"),
    ))
}

/// The group depth reached at `index`, scanning forward from `from` —
/// the comma classifier the parameter gate splits on.
fn depth_of(tokens: &TokenTable, from: usize, index: usize) -> Option<u32> {
    let mut depth = 0u32;
    for at in from..index {
        match kind_of(tokens, at)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
    }
    Some(depth)
}

/// `use_function_type_syntax_for_parameters`: the old-style function-typed
/// parameter rebuilds as a `Function`-typed one — `void cb(int x)` →
/// `void Function(int x) cb`, `required covariant this.cb()?` kept in
/// order (the official `ConvertToGenericFunctionSyntax`'s parameter face
/// over the whole parameter; an untyped inner parameter refuses).
pub(crate) fn function_type_syntax(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (mut first, last) = hit_tokens(tokens, &input.range)?;
    // Leading modifiers and receiver prefixes, in their written order.
    let mut required = false;
    let mut covariant = false;
    loop {
        match tokens.lexeme(text, first) {
            "required" if !required && !covariant => {
                required = true;
                first += 1;
            }
            "covariant" if !covariant => {
                covariant = true;
                first += 1;
            }
            _ => break,
        }
    }
    let mut prefix = "";
    if (tokens.lexeme(text, first) == "this" || tokens.lexeme(text, first) == "super")
        && kind_of(tokens, first + 1) == Some(TokenKind::Period)
    {
        prefix = if tokens.lexeme(text, first) == "this" {
            "this."
        } else {
            "super."
        };
        first += 2;
    }
    // The suffix group closes at `last`, optionally `?`-null-marked.
    let body_end = if kind_of(tokens, last) == Some(TokenKind::Question) {
        last - 1
    } else {
        last
    };
    if kind_of(tokens, body_end)? != TokenKind::CloseParen {
        return None;
    }
    // The matching `(` walks back over the group body only.
    let mut depth = 0u32;
    let mut open = None;
    let mut index = body_end;
    while index > first {
        index -= 1;
        match kind_of(tokens, index)? {
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => depth += 1,
            TokenKind::OpenParen => {
                if depth == 0 {
                    open = Some(index);
                    break;
                }
                depth -= 1;
            }
            TokenKind::OpenSquare | TokenKind::OpenCurly => {
                if depth == 0 {
                    return None;
                }
                depth -= 1;
            }
            _ => {}
        }
    }
    let open = open?;
    // Optional type parameters sit between the name and the group.
    let mut name_idx = open - 1;
    if kind_of(tokens, name_idx)? == TokenKind::Gt {
        let mut angle = 0i32;
        loop {
            match kind_of(tokens, name_idx)? {
                TokenKind::Gt => angle += 1,
                TokenKind::GtGt => angle += 2,
                TokenKind::GtGtGt => angle += 3,
                TokenKind::Lt => angle -= 1,
                _ => {}
            }
            if angle == 0 {
                break;
            }
            name_idx -= 1;
        }
        name_idx -= 1;
    }
    if !wordish(tokens, text, name_idx) || name_idx < first {
        return None;
    }
    // The inner parameters all read as typed (the official gate).
    let mut start = open + 1;
    let mut typed = true;
    let mut index = open + 1;
    while index < body_end {
        if kind_of(tokens, index) == Some(TokenKind::Comma)
            && depth_of(tokens, open + 1, index)? == 0
        {
            typed &= parameter_typed(tokens, text, start, index)?;
            start = index + 1;
        }
        index += 1;
    }
    typed &= parameter_typed(tokens, text, start, body_end)?;
    if !typed {
        return None;
    }
    // `{required }{covariant }{returnType }Function{<T>}{(params)}{?} {this.|super.}{name}`.
    let return_type = if name_idx > first {
        format!("{} ", token_text(tokens, text, first..name_idx)?)
    } else {
        String::new()
    };
    let has_tp = matches!(kind_of(tokens, name_idx + 1), Some(TokenKind::Lt));
    let type_params = if has_tp {
        token_text(tokens, text, name_idx + 1..open)?
    } else {
        String::new()
    };
    let parameters = token_text(tokens, text, open..body_end + 1)?;
    let question = if body_end != last { "?" } else { "" };
    let name = tokens.lexeme(text, name_idx).to_owned();
    let head = format!(
        "{}{}{}Function{type_params}{parameters}{question} ",
        if required { "required " } else { "" },
        if covariant { "covariant " } else { "" },
        return_type,
    );
    Some((
        input.range.start,
        input.range.end - input.range.start,
        format!("{head}{prefix}{name}"),
    ))
}

/// `require_trailing_commas`: the comma lands right after the group's last
/// item — the token before the reported closer, whose end is the insertion
/// point (the official `AddTrailingComma` inserts at `lastNode.end`,
/// comments and all).
pub(crate) fn add_missing_trailing_comma(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    match kind_of(tokens, first)? {
        TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {}
        _ => return None,
    }
    match kind_of(tokens, first.checked_sub(1)?)? {
        // An empty group has no last item; an existing comma never reports.
        TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly | TokenKind::Comma => {
            return None;
        }
        _ => {}
    }
    let (start, length) = span_over(text, tokens, first - 1, first - 1)?;
    Some((start + length, 0, ",".to_owned()))
}

/// `avoid_multiple_declarations_per_line`: the declaration list splits —
/// each declarator gains `;` plus a same-indent copy of the modifiers and
/// type (the official `SplitMultipleDeclarations` between-declarator
/// replacements, folded over the written span; comments, metadata, and
/// `for`-part lists refuse).
pub(crate) fn split_declarations(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (hit, _) = hit_tokens(tokens, &input.range)?;
    // The statement's first token: back past initializers and separators
    // to the boundary (`;`, a block edge); a bare `(` means a `for`-part
    // list, which never splits.
    let mut depth = 0u32;
    let mut stmt = hit;
    while stmt > 0 {
        stmt -= 1;
        match kind_of(tokens, stmt)? {
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => depth += 1,
            TokenKind::OpenParen | TokenKind::OpenSquare => {
                if depth == 0 {
                    return None;
                }
                depth -= 1;
            }
            TokenKind::OpenCurly | TokenKind::Semicolon if depth == 0 => break,
            TokenKind::OpenCurly | TokenKind::Semicolon => depth -= 1,
            _ => {}
        }
    }
    stmt += 1;
    // The list runs to its depth-0 `;`, splitting at depth-0 commas.
    let mut commas = Vec::new();
    depth = 0;
    let mut index = stmt;
    let semi = loop {
        match kind_of(tokens, index)? {
            TokenKind::Semicolon if depth == 0 => break index,
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::Comma if depth == 0 => commas.push(index),
            _ => {}
        }
        index += 1;
    };
    if commas.is_empty() || commas[0] >= hit {
        return None;
    }
    // The first declarator's name ends the head: the token before the
    // first separator-or-initializer marker.
    let mut marker = stmt;
    loop {
        match kind_of(tokens, marker)? {
            TokenKind::Comma | TokenKind::Eq => break,
            TokenKind::Semicolon => return None,
            _ => {}
        }
        marker += 1;
    }
    if marker == stmt || !wordish(tokens, text, marker - 1) {
        return None;
    }
    let name_b = utf16_offset_to_byte(text, tokens.get(marker - 1)?.utf16_offset);
    let head_b = utf16_offset_to_byte(text, tokens.get(stmt)?.utf16_offset);
    if name_b <= head_b {
        return None;
    }
    // Comments anywhere in the written span refuse (the official
    // preceding-comments gate, read over the whole list).
    let semi_b = utf16_offset_to_byte(text, tokens.get(semi)?.utf16_offset);
    let span = text.get(head_b..semi_b)?;
    if span.contains("//") || span.contains("/*") {
        return None;
    }
    // The split text: the written head and first declarator stay verbatim
    // (up to the first separator); every further declarator gains `;`, the
    // line indent, and a verbatim copy of the head.
    let indent_start = text[..head_b].rfind('\n').map_or(0, |i| i + 1);
    let indent = &text[indent_start..head_b];
    if !indent.bytes().all(|b| matches!(b, b' ' | b'\t')) {
        return None;
    }
    let eol = {
        let nl = text
            .get(semi_b..)?
            .find('\n')
            .map_or(semi_b, |i| semi_b + i);
        if nl > 0 && text.as_bytes().get(nl - 1) == Some(&b'\r') {
            "\r\n"
        } else {
            "\n"
        }
    };
    let head_raw = text
        .get(head_b..name_b)?
        .trim_end_matches([' ', '\t'])
        .to_owned();
    let mut rebuilt = text
        .get(head_b..utf16_offset_to_byte(text, tokens.get(commas[0])?.utf16_offset))?
        .trim_end()
        .to_owned();
    for window in commas.windows(2) {
        let seg_b = utf16_offset_to_byte(text, tokens.get(window[0] + 1)?.utf16_offset);
        let seg_end = utf16_offset_to_byte(text, tokens.get(window[1])?.utf16_offset);
        let seg = text.get(seg_b..seg_end)?.trim();
        if seg.is_empty() || !seg.chars().next().is_some_and(is_identifier_char) {
            return None;
        }
        rebuilt.push_str(&format!(";{eol}{indent}{head_raw} {seg}"));
    }
    let last_seg_b =
        utf16_offset_to_byte(text, tokens.get(commas[commas.len() - 1] + 1)?.utf16_offset);
    let tail = text
        .get(last_seg_b..utf16_offset_to_byte(text, tokens.get(semi)?.utf16_offset))?
        .trim();
    if tail.is_empty() || !tail.chars().next().is_some_and(is_identifier_char) {
        return None;
    }
    rebuilt.push_str(&format!(";{eol}{indent}{head_raw} {tail}"));
    let start = tokens.get(stmt)?.utf16_offset;
    Some((start, tokens.get(semi)?.utf16_offset - start, rebuilt))
}

/// Which list the removed item sits in — arguments read a `name:` step-up
/// and never meet delimiters; parameters walk back over their type run and
/// meet the `[…]`/`{…}` groups.
#[derive(Clone, Copy)]
enum ItemMode {
    Argument,
    Parameter,
}

/// The shared list-item removal (the official `RemoveArgument`'s
/// `nodeInList` face and `RemoveUnusedParameter`'s parameter faces): the
/// item goes with one adjacent comma — the comma before it among kind
/// peers, the comma after it when it opens the list — and the first item
/// in a `[…]`/`{…}` group takes the delimiters with it when it is also the
/// last (an optional `this.x` field formal additionally folds its default
/// into a fresh initializer when the constructor has none).
fn remove_listed_item(input: &FixInput<'_>, mode: ItemMode) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (mut first, last) = hit_tokens(tokens, &input.range)?;
    if matches!(mode, ItemMode::Argument)
        && first >= 3
        && kind_of(tokens, first - 1) == Some(TokenKind::Colon)
        && wordish(tokens, text, first - 2)
        && matches!(
            kind_of(tokens, first - 3),
            Some(TokenKind::OpenParen | TokenKind::Comma)
        )
    {
        // `stepUpNamedExpression`: the whole `name: value` is the argument.
        first -= 2;
    }
    if matches!(mode, ItemMode::Parameter) && first == last && wordish(tokens, text, first) {
        // The reported name walks back over its type run (`covariant
        // List<int>? x`, `this.x`).
        while first > 0 {
            match kind_of(tokens, first - 1)? {
                TokenKind::Question | TokenKind::Period => first -= 1,
                TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt => {
                    let mut angle = 0i32;
                    loop {
                        first -= 1;
                        if first == 0 {
                            return None;
                        }
                        match kind_of(tokens, first)? {
                            TokenKind::Gt => angle += 1,
                            TokenKind::GtGt => angle += 2,
                            TokenKind::GtGtGt => angle += 3,
                            TokenKind::Lt => {
                                angle -= 1;
                                if angle == 0 {
                                    break;
                                }
                            }
                            _ => {}
                        }
                    }
                }
                kind if wordish(tokens, text, first - 1)
                    || matches!(kind, TokenKind::Keyword(_)) =>
                {
                    first -= 1;
                }
                _ => break,
            }
        }
    }
    // Back to the previous comma, the delimiter opening, or the list's `(`.
    let mut depth = 0u32;
    let mut prev_comma = None;
    let mut delimiter = None;
    let mut paren = None;
    let mut index = first;
    while index > 0 {
        index -= 1;
        match kind_of(tokens, index)? {
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => depth += 1,
            TokenKind::OpenSquare | TokenKind::OpenCurly if depth == 0 => {
                delimiter = Some(index);
                break;
            }
            TokenKind::Comma if depth == 0 => {
                prev_comma = Some(index);
                break;
            }
            TokenKind::OpenParen if depth == 0 => {
                paren = Some(index);
                break;
            }
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => depth -= 1,
            _ => {}
        }
    }
    // A delimiter before the previous comma makes that peer optional too.
    let mut prev_optional = false;
    if prev_comma.is_some() {
        let mut d = 0u32;
        loop {
            if index == 0 {
                return None;
            }
            index -= 1;
            match kind_of(tokens, index)? {
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => d += 1,
                TokenKind::OpenSquare | TokenKind::OpenCurly => {
                    if d == 0 {
                        prev_optional = true;
                        break;
                    }
                    d -= 1;
                }
                TokenKind::OpenParen => {
                    if d == 0 {
                        paren = Some(index);
                        break;
                    }
                    d -= 1;
                }
                _ => {}
            }
        }
    }
    // The item must sit inside a `(`-list; nothing past the gate reads it.
    let _paren = paren?;
    let item_optional = matches!(mode, ItemMode::Parameter)
        && (delimiter.is_some() || (prev_comma.is_some() && prev_optional));
    // Forward to the next boundary: the item's own groups ride in the
    // residual depth, the delimiters' closers are skipped, and the first
    // depth-0 comma or the list's `)` ends the scan.
    let mut depth = 0u32;
    for at in first..=last {
        match kind_of(tokens, at)? {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.saturating_sub(1);
            }
            _ => {}
        }
    }
    let mut next_comma = None;
    let mut closer = None;
    let mut index = last;
    loop {
        index += 1;
        match kind_of(tokens, index)? {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => depth += 1,
            TokenKind::CloseSquare | TokenKind::CloseCurly if depth == 0 && item_optional => {}
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                if depth == 0 {
                    closer = Some(index);
                    break;
                }
                depth -= 1;
            }
            TokenKind::Comma if depth == 0 => {
                next_comma = Some(index);
                break;
            }
            _ => {}
        }
    }
    let closer = closer?;
    let item_start = tokens.get(first)?.utf16_offset;
    let (span_start, span_len) = span_over(text, tokens, first, last)?;
    let item_end = span_start + span_len;
    let (start, length) = if let Some(pc) = prev_comma {
        let (prev_start, prev_len) = span_over(text, tokens, pc - 1, pc - 1)?;
        let prev_end = prev_start + prev_len;
        if item_optional && !prev_optional {
            match next_comma {
                // First optional item with a peer behind: delimiters stay.
                Some(nx) => (item_start, tokens.get(nx)?.utf16_offset - item_start),
                // Last inside the delimiters: they go with it (a trailing
                // comma before the `)` survives).
                None => {
                    let mut trailing = closer;
                    if kind_of(tokens, closer - 1) == Some(TokenKind::Comma) {
                        trailing = closer - 1;
                    }
                    (prev_end, tokens.get(trailing)?.utf16_offset - prev_end)
                }
            }
        } else {
            (prev_end, item_end - prev_end)
        }
    } else {
        match next_comma {
            Some(nx) => (item_start, tokens.get(nx)?.utf16_offset - item_start),
            // Sole item: when a delimiter wraps it, the delimiters go too.
            None => {
                let face = match delimiter {
                    Some(d) if item_optional => tokens.get(d)?.utf16_offset,
                    _ => item_start,
                };
                (face, tokens.get(closer)?.utf16_offset - face)
            }
        }
    };
    // An optional `this.x` formal folds its default into a fresh
    // initializer when the constructor carries none yet.
    if matches!(mode, ItemMode::Parameter)
        && item_optional
        && next_comma.is_none()
        && tokens.lexeme(text, first) == "this"
        && kind_of(tokens, first + 1) == Some(TokenKind::Period)
        && matches!(
            kind_of(tokens, closer + 1),
            Some(TokenKind::OpenCurly | TokenKind::Semicolon)
        )
    {
        let name = tokens.lexeme(text, first + 2);
        let default = match depth0_find(tokens, text, first, last + 1, |kind, _| {
            kind == TokenKind::Eq
        }) {
            Some(eq) => token_text(tokens, text, eq + 1..last + 1)?,
            None => "null".to_owned(),
        };
        let (closer_start, closer_len) = span_over(text, tokens, closer, closer)?;
        return Some((
            start,
            closer_start + closer_len - start,
            format!(") : {name} = {default}"),
        ));
    }
    Some((start, length, String::new()))
}

/// `avoid_redundant_argument_values`: the redundant argument leaves its
/// list (the official `RemoveArgument`).
pub(crate) fn remove_argument_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    remove_listed_item(input, ItemMode::Argument)
}

/// `avoid_unused_constructor_parameters`: the unused parameter leaves the
/// constructor's list (the official `RemoveUnusedParameter`).
pub(crate) fn remove_parameter_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    remove_listed_item(input, ItemMode::Parameter)
}

/// `prefer_iterable_whereType`: `x.where((e) => e is T)` becomes
/// `x.whereType<T>()` (the official `ConvertToWhereType` over the reported
/// method name: one parameter, an `=>` body or a single return whose `is`
/// test applies the parameter, and no `is!`).
pub(crate) fn where_type_entry(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    if !word_at(tokens, text, first, "where") {
        return None;
    }
    if kind_of(tokens, first + 1)? != TokenKind::OpenParen {
        return None;
    }
    let args_open = first + 1;
    let args_close = tokens.matching_end(args_open)?;
    // Exactly one argument: no depth-0 comma inside the list.
    if depth0_find(tokens, text, args_open + 1, args_close, |kind, _| {
        kind == TokenKind::Comma
    })
    .is_some()
    {
        return None;
    }
    // The argument is a function expression — `(params) => body` or
    // `(params) { return body; }` — whose parameter names the tested
    // expression.
    if kind_of(tokens, args_open + 1)? != TokenKind::OpenParen {
        return None;
    }
    let params_open = args_open + 1;
    let params_close = tokens.matching_end(params_open)?;
    if params_close + 1 >= args_close {
        return None;
    }
    if !wordish(tokens, text, params_close - 1) {
        return None;
    }
    let param_name = tokens.lexeme(text, params_close - 1);
    let (body_first, body_last) = if tokens.lexeme(text, params_close + 1) == "=>" {
        (params_close + 2, args_close - 1)
    } else if kind_of(tokens, params_close + 1)? == TokenKind::OpenCurly
        && tokens.lexeme(text, params_close + 2) == "return"
        && kind_of(tokens, args_close - 1)? == TokenKind::CloseCurly
        && kind_of(tokens, args_close - 2)? == TokenKind::Semicolon
    {
        (params_close + 3, args_close - 3)
    } else {
        return None;
    };
    if body_first > body_last
        || tokens.lexeme(text, body_first) != param_name
        || kind_of(tokens, body_first + 1)? != TokenKind::Keyword(Keyword::Is)
    {
        return None;
    }
    if kind_of(tokens, body_first + 2) == Some(TokenKind::Bang) {
        return None;
    }
    let ty = token_text(tokens, text, body_first + 2..body_last + 1)?;
    if ty.is_empty() {
        return None;
    }
    let (start, length) = span_over(text, tokens, first, args_close)?;
    Some((start, length, format!("whereType<{ty}>()")))
}

/// `avoid_types_as_parameter_names`: the reported catch-clause name `T`
/// converts the clause to `on T` — `catch (T)` → `on T`,
/// `catch (T, s)` → `on T catch (_, s)` (the official `ConvertToOnType`;
/// only the catch face serves — the formal-parameter and type-parameter
/// faces carry a different diagnostic code upstream and the producer
/// drops them).
pub(crate) fn catch_to_on_type(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if first != last || !wordish(tokens, text, first) {
        return None;
    }
    let name = tokens.lexeme(text, first);
    // Walk back: `(` then `catch`.
    let lparen = first.checked_sub(1)?;
    if kind_of(tokens, lparen) != Some(TokenKind::OpenParen) {
        return None;
    }
    let catch_kw = lparen.checked_sub(1)?;
    if kind_of(tokens, catch_kw) != Some(TokenKind::Keyword(Keyword::Catch)) {
        return None;
    }
    let rparen = tokens.matching_end(lparen)?;
    let next = first + 1;
    if next == rparen {
        // `catch (T)` — no stack-trace parameter.
        let (start16, length16) = span_over(text, tokens, catch_kw, rparen)?;
        return Some((start16, length16, format!("on {name}")));
    }
    // `catch (T, s)` — the comma sits at depth 0 between the name and the
    // stack-trace parameter; `startStart(catchKeyword,
    // stackTraceParameter)` keeps the parameter and `)` untouched.
    if kind_of(tokens, next) != Some(TokenKind::Comma) {
        return None;
    }
    let stack = next + 1;
    if stack >= rparen || !wordish(tokens, text, stack) || stack + 1 != rparen {
        return None;
    }
    let (start16, _) = span_over(text, tokens, catch_kw, first)?;
    let end16 = tokens.get(stack)?.utf16_offset;
    Some((
        start16,
        end16.checked_sub(start16)?,
        format!("on {name} catch (_, "),
    ))
}

/// `empty_container_bodies`: the reported `{}` pair (whitespace-only gap)
/// plus the gap before it fold into `;` — the official
/// `RemoveEmptyContainerBody` replaces `[prevToken.end, node.end)` with
/// `;`, the whitespace ride included.
pub(crate) fn drop_empty_container_body(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let slice = slice16(text, &input.range)?;
    let bytes = slice.as_bytes();
    if bytes.first() != Some(&b'{') || bytes.last() != Some(&b'}') {
        return None;
    }
    let inner = slice.get(1..slice.len() - 1)?;
    if !inner.chars().all(char::is_whitespace) {
        return None;
    }
    // `prevToken.end`: the last non-whitespace byte before the `{` — the
    // gap walks back over newlines too.
    let start_byte = utf16_offset_to_byte(text, input.range.start);
    let prefix = &text[..start_byte];
    let prev_end = prefix.trim_end().len();
    let end_byte = utf16_offset_to_byte(text, input.range.end);
    let start16 = byte_offset_to_utf16(text, prev_end);
    let length16 = byte_offset_to_utf16(text, end_byte).checked_sub(start16)?;
    Some((start16, length16, ";".to_owned()))
}

/// `prefer_spread_collections`: the `..addAll(arg)` section on a list
/// literal folds into one spread element — `...arg`, `...?x` for an
/// `x ?? []` argument, `if (c) ...t` for a `c ? t : []` conditional
/// (the official `ConvertAddAllToSpread` non-inline face; the list-literal
/// argument is `prefer_inlined_adds`'s face and never reaches this lint).
pub(crate) fn spread_addition(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (name_index, _) = hit_tokens(tokens, &input.range)?;
    if tokens.lexeme(text, name_index) != "addAll"
        || kind_of(tokens, name_index + 1) != Some(TokenKind::OpenParen)
    {
        return None;
    }
    let lparen = name_index + 1;
    let rparen = tokens.matching_end(lparen)?;
    if depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::Comma
    })
    .is_some()
    {
        return None; // the official face takes exactly one argument
    }
    // The argument is NOT a list literal (that face belongs to
    // `prefer_inlined_adds`); the lint's own gate guarantees it, and the
    // spread producer's `_computeElementText` reads the shape.
    if kind_of(tokens, lparen + 1) == Some(TokenKind::OpenSquare) {
        return None;
    }
    // Backwards: the cascade marker, then the target literal's `]`.
    match kind_of(tokens, name_index.checked_sub(1)?) {
        Some(TokenKind::PeriodPeriod | TokenKind::QuestionPeriodPeriod) => {}
        _ => return None,
    }
    let close_square = name_index - 2;
    let open_square = match kind_of(tokens, close_square) {
        Some(TokenKind::Index) => close_square,
        Some(TokenKind::CloseSquare) => {
            let mut depth = 0u32;
            let mut cursor = close_square;
            loop {
                cursor = cursor.checked_sub(1)?;
                match kind_of(tokens, cursor)? {
                    TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                        depth += 1;
                    }
                    TokenKind::OpenParen
                    | TokenKind::OpenCurly
                    | TokenKind::StringInterpolationExpression => depth = depth.checked_sub(1)?,
                    TokenKind::OpenSquare => {
                        if depth == 0 {
                            break cursor;
                        }
                        depth = depth.checked_sub(1)?;
                    }
                    _ => {}
                }
            }
        }
        _ => return None,
    };
    // `_computeElementText`: `a ?? []` → `...?a`; `c ? t : []` →
    // `if (c) ...t`; everything else → `...<arg>`.
    let element = spread_element_text(tokens, text, lparen + 1, rparen)?;
    let target_nonempty = close_square > open_square + 1;
    let (start16, length16) = span_over(text, tokens, close_square, rparen)?;
    let replacement = if close_square == open_square {
        // `[]..addAll(x)` — the single `[]` token rewrites whole.
        format!("[{element}]")
    } else {
        format!("{}{}]", if target_nonempty { ", " } else { "" }, element)
    };
    Some((start16, length16, replacement))
}

/// The composed spread-element source of the `addAll` argument at
/// `arg_start..arg_end` (`_computeElementText`): `x ?? []` → `...?x`,
/// `c ? t : []` → `if (c) ...t`, else `...<arg>`. The empty-list test
/// reads the literal's token shape (`[]`, `const []`, `<T>[]`).
fn spread_element_text(
    tokens: &TokenTable,
    text: &str,
    arg_start: usize,
    arg_end: usize,
) -> Option<String> {
    let argument = token_text(tokens, text, arg_start..arg_end)?;
    if argument.is_empty() {
        return None;
    }
    // `a ?? []` at depth 0.
    if let Some(op) = depth0_find(tokens, text, arg_start, arg_end, |kind, _| {
        kind == TokenKind::QuestionQuestion
    }) && empty_list_literal(tokens, op + 1, arg_end)
    {
        let left = token_text(tokens, text, arg_start..op)?;
        return Some(format!("...?{left}"));
    }
    // `c ? t : []` at depth 0.
    if let Some(question) = depth0_find(tokens, text, arg_start, arg_end, |kind, _| {
        kind == TokenKind::Question
    }) && let Some(colon) = depth0_find(tokens, text, question + 1, arg_end, |kind, _| {
        kind == TokenKind::Colon
    }) && empty_list_literal(tokens, colon + 1, arg_end)
    {
        let condition = token_text(tokens, text, arg_start..question)?;
        let then = token_text(tokens, text, question + 1..colon)?;
        return Some(format!("if ({condition}) ...{then}"));
    }
    Some(format!("...{argument}"))
}

/// The token range is exactly one empty list literal — `[]`, `<T>[]`, or
/// `const`/`const <T>` led (the official `isEmptyListLiteral` face).
fn empty_list_literal(tokens: &TokenTable, mut start: usize, end: usize) -> bool {
    if kind_of(tokens, start) == Some(TokenKind::Keyword(Keyword::Const)) {
        start += 1;
    }
    if kind_of(tokens, start) == Some(TokenKind::Lt) {
        let Some(close) = angle_group_end(tokens, start) else {
            return false;
        };
        start = close + 1;
    }
    kind_of(tokens, start) == Some(TokenKind::Index) && start + 1 == end
}

/// `simplify_variable_pattern`: the reported pattern-field name drops —
/// `isEven: var isEven` keeps `: var isEven` (the official
/// `RemoveUnnecessaryName` deletes `range.token(name)` — the name token
/// alone; the `:` and the variable pattern survive).
pub(crate) fn drop_pattern_field_name(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if first != last || !wordish(tokens, text, first) {
        return None;
    }
    // The field name sits immediately before its `:` — verify the pair,
    // and that the variable pattern's own name repeats it (`var`/`final`
    // then the same identifier).
    if kind_of(tokens, first + 1) != Some(TokenKind::Colon) {
        return None;
    }
    let name = tokens.lexeme(text, first);
    let mut cursor = first + 2;
    if matches!(tokens.lexeme(text, cursor), "var" | "final") {
        cursor += 1;
    }
    if tokens.lexeme(text, cursor) != name {
        return None;
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        String::new(),
    ))
}

/// `type_literal_in_constant_pattern`: the reported constant pattern
/// wraps in `const (…)` (the official `ConvertToConstantPattern`
/// insertions at `constantPattern.offset`/`end` folded into one
/// replacement — the first-listed producer in the registry pair wins).
pub(crate) fn const_pattern_literal(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let inner = slice16(input.text, &input.range)?;
    let inner = inner.trim();
    if inner.is_empty() || inner.starts_with("const") {
        return None;
    }
    // A type-literal shape: a dotted-identifier run, optional type
    // arguments, optional `?` tail. Anything wider (a real expression)
    // is not this lint's face.
    let bytes = inner.as_bytes();
    let mut pos = 0usize;
    loop {
        // One identifier segment.
        let id_start = pos;
        while pos < bytes.len() && is_identifier_char(bytes[pos] as char) {
            pos += 1;
        }
        if pos == id_start {
            return None;
        }
        if bytes[pos..].starts_with(b"<") {
            // Type arguments: balance `<`/`>` over the run.
            let mut depth = 0u32;
            let mut i = pos;
            while i < bytes.len() {
                match bytes[i] {
                    b'<' => depth += 1,
                    b'>' => {
                        depth = depth.checked_sub(1)?;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => {}
                }
                i += 1;
            }
            if depth != 0 {
                return None;
            }
            pos = i + 1;
        }
        if bytes[pos..].starts_with(b".") {
            pos += 1;
            continue;
        }
        break;
    }
    if bytes[pos..].starts_with(b"?") {
        pos += 1;
    }
    if pos != bytes.len() {
        return None;
    }
    let (start, length) = (input.range.start, input.range.end - input.range.start);
    Some((start, length, format!("const ({inner})")))
}

/// `unnecessary_lambdas`: the reported lambda reduces to its callee's
/// tear-off — `(x) => f(x)` → `f`, `(x) { return f(x); }` → `f`; a
/// `new`/`const`-marked creation or a dotted `C.name(...)` head appends
/// `.new` when the constructor is unnamed (the official
/// `ReplaceWithTearOff`). The bare `C(...)` single-name head is
/// ambiguous between function and unnamed-constructor calls and drops —
/// the invocation face writes `C`, the creation face `C.new`.
pub(crate) fn tear_off_lambda(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if kind_of(tokens, first) != Some(TokenKind::OpenParen) {
        return None;
    }
    let params_close = tokens.matching_end(first)?;
    // `=> expr` or `{ expr; }` / `{ return expr; }`.
    let (expr_first, expr_last) = match kind_of(tokens, params_close + 1)? {
        TokenKind::Function => (params_close + 2, last),
        TokenKind::OpenCurly => {
            let block_close = tokens.matching_end(params_close + 1)?;
            if block_close != last {
                return None;
            }
            let mut inner_first = params_close + 2;
            if kind_of(tokens, inner_first) == Some(TokenKind::Keyword(Keyword::Return)) {
                inner_first += 1;
            }
            // `{ return expr; }` — the `;` sits before `}`.
            if kind_of(tokens, block_close - 1) != Some(TokenKind::Semicolon) {
                return None;
            }
            (inner_first, block_close - 2)
        }
        _ => return None,
    };
    if expr_first > expr_last {
        return None;
    }
    // Unwrap outer parens of the expression (`unParenthesized`).
    let mut e_first = expr_first;
    let mut e_last = expr_last;
    while kind_of(tokens, e_first) == Some(TokenKind::OpenParen)
        && tokens.matching_end(e_first) == Some(e_last)
    {
        e_first += 1;
        e_last -= 1;
    }
    // The invocation's callee: the argument list's `(` walks back to the
    // callee end — the function text is `startEnd(expression,
    // expression.function)`, the creation's constructor name plus the
    // optional `.name`.
    let mut cursor = e_first;
    // Strip a leading `new`/`const` marker (creation keywords).
    let creation_keyword = matches!(
        kind_of(tokens, cursor),
        Some(TokenKind::Keyword(Keyword::New | Keyword::Const))
    );
    if creation_keyword {
        cursor += 1;
    }
    // Find the invocation's argument-list `(`: scan the callee run — a
    // dotted identifier chain, optional type arguments, then `(`.
    let callee_start = cursor;
    let mut head = cursor;
    loop {
        match kind_of(tokens, head)? {
            TokenKind::Identifier | TokenKind::Keyword(Keyword::This) => head += 1,
            TokenKind::Period => {
                head += 1;
                if kind_of(tokens, head)? != TokenKind::Identifier {
                    return None;
                }
                head += 1;
            }
            TokenKind::Lt => {
                // Explicit type arguments on the callee — the lint bails
                // on them (:285), so none should reach here; still,
                // keep the textual shape.
                head = angle_group_end(tokens, head)? + 1;
            }
            TokenKind::OpenParen => break,
            _ => return None,
        }
    }
    if head <= callee_start || head > e_last {
        return None;
    }
    let arg_open = head;
    let arg_close = tokens.matching_end(arg_open)?;
    if arg_close != e_last {
        return None;
    }
    let callee = token_text(tokens, text, callee_start..arg_open)?;
    if callee.is_empty() {
        return None;
    }
    // Distinguish the creation head from a plain invocation: a `new` or
    // `const` keyword marks it; a bare `C` single-segment head is
    // ambiguous and drops (the constructor face would append `.new`, the
    // invocation face would not).
    if !creation_keyword && !callee.contains('.') {
        return None;
    }
    let replacement = if creation_keyword && !callee.contains('.') {
        format!("{callee}.new")
    } else {
        callee
    };
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((start16, length16, replacement))
}

/// `unnecessary_primary_constructor_body`: the reported `this` keyword's
/// whole `PrimaryConstructorBody` — `this(...) ;` / `this(...) {}` /
/// `this(...) : inits;` — drops by its lines range (the official
/// `RemovePrimaryConstructorBody` deletes `getLinesRange(body)`).
pub(crate) fn drop_primary_constructor_body(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    if kind_of(tokens, first) != Some(TokenKind::Keyword(Keyword::This)) {
        return None;
    }
    // The body runs from `this` through its terminating `;` or `{}`
    // block — `this (params) ;`, `this (params) { }`, `this (params) :
    // x = e ;`. The trailing block is the end when no `;` follows.
    let end = statement_end(tokens, text, first).or_else(|| {
        // `this (params) {}` — no `;` after the block; walk the optional
        // parameter list and take the matching `}`.
        let mut cursor = first + 1;
        if kind_of(tokens, cursor) == Some(TokenKind::OpenParen) {
            cursor = tokens.matching_end(cursor)? + 1;
        }
        if kind_of(tokens, cursor) == Some(TokenKind::OpenCurly) {
            tokens.matching_end(cursor)
        } else {
            None
        }
    })?;
    let (start16, length16) = span_over(text, tokens, first, end)?;
    let (start, length) = drop_lines_range(text, start16, start16 + length16)?;
    Some((start, length, String::new()))
}

/// `unnecessary_type_name_in_constructor`: the reported type-name echo
/// drops with its `new`/`factory` keyword context — `C(...)` → `new()`,
/// `C.named(...)` → `new named(...)`, `C.new(...)` → `new()`,
/// `factory C.name(...)` → `factory name(...)` (the official
/// `RemoveTypeName` branches over `node.typeName`/`name`/`newKeyword`/
/// `factoryKeyword`).
pub(crate) fn drop_constructor_type_name(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    if !wordish(tokens, text, first) {
        return None;
    }
    // The constructor head: `typeName [ . name | . new ]` then `(`; a
    // `factory` or `new` keyword may precede the type name. The reported
    // identifier is the type name itself.
    let mut cursor = first;
    let mut name_token: Option<usize> = None;
    let mut period: Option<usize> = None;
    if kind_of(tokens, cursor + 1) == Some(TokenKind::Period) && wordish(tokens, text, cursor + 2) {
        period = Some(cursor + 1);
        name_token = Some(cursor + 2);
        cursor += 2;
    }
    if kind_of(tokens, cursor + 1) != Some(TokenKind::OpenParen) {
        return None;
    }
    // `newOrFactoryKeyword`: `factory` or `new` immediately before the
    // type name.
    let kw = first.checked_sub(1).and_then(|index| {
        let lexeme = tokens.lexeme(text, index);
        matches!(
            kind_of(tokens, index),
            Some(TokenKind::Keyword(Keyword::New))
        )
        .then_some(index)
        .or_else(|| (lexeme == "factory").then_some(index))
    });
    // The official `replacementEndToken`: `name` when it is `new` or
    // absent, else `period`.
    let end_token = match name_token {
        Some(name) if tokens.lexeme(text, name) == "new" => name,
        Some(_) => period?,
        None => first,
    };
    let (start16, length16) = span_over(text, tokens, first, end_token)?;
    let end16 = start16 + length16;
    if let Some(kw_index) = kw {
        // `factory`/`new` present: `endEnd(kw, end)` when the head is
        // unnamed and the keyword hugs the type name (`factory C()` →
        // `factory()` deletes the space too), else `startEnd(typeName,
        // end)` (official `RemoveTypeName`'s `name == null` gate).
        let kw_end = utf16_end(tokens, text, kw_index)?;
        let start = if name_token.is_none() && kw_end + 1 == input.range.start {
            kw_end
        } else {
            start16
        };
        return Some((start, end16.checked_sub(start)?, String::new()));
    }
    // No keyword: replace `[typeName.start, endToken.end)` — `new` when
    // the end token is an identifier, `new ` when it is the `.` (the
    // constructor name follows immediately).
    let replacement = if period.is_some() && name_token != Some(end_token) {
        "new "
    } else {
        "new"
    };
    Some((start16, length16, replacement.to_owned()))
}

/// `unrelated_type_equality_checks`: the reported `==`/`!=` becomes
/// `is`/`is!`; when the left operand is the `Type` literal the whole
/// binary reorders to `x is T` (the official `ReplaceWithIs` arms —
/// the left-literal arm reads the operand types' `Type` display off the
/// message).
pub(crate) fn equality_is_check(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if first != last {
        return None;
    }
    let operator = tokens.lexeme(text, first);
    let (is_op, bang) = match operator {
        "==" => ("is", ""),
        "!=" => ("is", "!"),
        _ => return None,
    };
    // The official producer edits only when an operand is a `TypeLiteral`
    // — the message's type display reads `Type` for that operand.
    let left_is_type = input.message.contains("the left operand ('Type')");
    let right_is_type = input.message.contains("the right operand ('Type')");
    if left_is_type {
        // `T == x` → `x is T` / `x is! T`: delete `T == `, append
        // ` is[!] T` after the right operand.
        let left_start = operand_start(tokens, first.checked_sub(1)?)?;
        let right_end = operand_end(tokens, first + 1)?;
        let left = token_text(tokens, text, left_start..first)?;
        let right = token_text(tokens, text, first + 1..right_end + 1)?;
        let (start16, length16) = span_over(text, tokens, left_start, right_end)?;
        return Some((start16, length16, format!("{right} {is_op}{bang} {left}")));
    }
    if !right_is_type {
        return None;
    }
    // `x == T` → `x is T` / `x is! T` — the operator alone rewrites.
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((start16, length16, format!("{is_op}{bang}")))
}

// ---------------------------------------------------------------------------
// Fix source: the engine's parser diagnostics
//
// The rewriters behind the table's `FixSource::Parser` rows (module docs).
// Each mirrors one official producer's edit shape (upstream Dart SDK
// source, pkg/analysis_server/lib/src/services/correction/dart/*); the
// official producers read the resolved AST node under the report, these
// rebuild the same shape from the report span and the token stream, and
// drop where the shape does not verify. Parser reports are token spans:
// the hit token is the token starting at the report offset.
// ---------------------------------------------------------------------------

/// The official `RemoveLexeme` deletion: the whole word `word` at the hit
/// start plus exactly one following UTF-16 unit — `[offset, offset +
/// word.length + 1)`, whatever the extra unit is (the producer deletes it
/// blind; at the end of the file only the word goes).
pub(crate) fn remove_lexeme(text: &str, offset16: u32, word: &str) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, offset16);
    let rest = text.get(start..)?.strip_prefix(word)?;
    if rest.starts_with(is_identifier_char) {
        return None;
    }
    let extra = rest.chars().next().map_or(0, char::len_utf16);
    let length = u32::try_from(word.len() + extra).ok()?;
    Some((offset16, length, String::new()))
}

/// The official `RemoveKeyword` deletion: the whole word `word` at the hit
/// start plus the whitespace run to the next token (newlines included); a
/// comment ends the run, as the producer stops at the next token's
/// preceding comment.
pub(crate) fn remove_keyword(text: &str, offset16: u32, word: &str) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, offset16);
    let rest = text.get(start..)?.strip_prefix(word)?;
    if rest.starts_with(is_identifier_char) {
        return None;
    }
    let ws = rest.len() - rest.trim_start_matches([' ', '\t', '\r', '\n']).len();
    let length = u32::try_from(word.len() + ws).ok()?;
    Some((offset16, length, String::new()))
}

/// The `startStart(keyword, keyword.next!)` deletion of the
/// `RemoveConst`/`RemoveLate`/`RemoveUnnecessaryConst` producers: the
/// whole word `word` at the hit start plus the trivia run to the next
/// real token — whitespace AND comments (comments ride the next token's
/// `precedingComments` edge, inside the span).
pub(crate) fn remove_keyword_across_comments(
    text: &str,
    offset16: u32,
    word: &str,
) -> Option<(u32, u32, String)> {
    let start = utf16_offset_to_byte(text, offset16);
    let rest = text.get(start..)?.strip_prefix(word)?;
    if rest.starts_with(is_identifier_char) {
        return None;
    }
    let run = trivia_run(rest);
    let length = u32::try_from(word.len() + run).ok()?;
    Some((offset16, length, String::new()))
}

/// The byte length of the trivia run heading `rest` — whitespace and
/// comments alternating to the next real token (a `//` comment ends at
/// its newline; `/* */` comments nest; an unterminated comment runs to
/// the end of the file).
fn trivia_run(rest: &str) -> usize {
    let bytes = rest.as_bytes();
    let mut at = 0usize;
    loop {
        while at < bytes.len() && matches!(bytes[at], b' ' | b'\t' | b'\r' | b'\n') {
            at += 1;
        }
        if bytes[at..].starts_with(b"//") {
            match bytes[at..].iter().position(|&b| b == b'\n') {
                Some(i) => at += i + 1,
                None => return bytes.len(),
            }
        } else if bytes[at..].starts_with(b"/*") {
            let mut depth = 1u32;
            let mut i = at + 2;
            while depth > 0 && i + 1 < bytes.len() {
                if bytes[i] == b'/' && bytes[i + 1] == b'*' {
                    depth += 1;
                    i += 2;
                } else if bytes[i] == b'*' && bytes[i + 1] == b'/' {
                    depth -= 1;
                    i += 2;
                } else {
                    i += 1;
                }
            }
            if depth > 0 {
                return bytes.len();
            }
            at = i;
        } else {
            return at;
        }
    }
}

/// An ASCII identifier character — the boundary test behind the
/// whole-word checks.
fn is_identifier_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '$'
}

/// `extraneous_modifier` / `duplicated_modifier` /
/// `variable_pattern_keyword_in_declaration_context`: the report span is
/// the offending keyword itself, whichever it is; it goes with one
/// following unit (official `RemoveLexeme.modifier` over the
/// message-named lexeme, `RemoveVar` over the report span — the same
/// deletion).
pub(crate) fn remove_hit_lexeme(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let word = slice16(input.text, &input.range)?;
    if word.is_empty() || !word.chars().all(|c| c.is_ascii_lowercase()) {
        return None;
    }
    remove_lexeme(input.text, input.range.start, word)
}

/// `abstract_class_member`: `abstract` goes with the whole whitespace run
/// behind it (official `RemoveAbstract`'s class-member leg: the keyword
/// plus one unit, then every whitespace unit — newlines included).
pub(crate) fn remove_abstract_member(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    let start = utf16_offset_to_byte(text, input.range.start);
    let rest = text.get(start..)?.strip_prefix("abstract")?;
    if rest.starts_with(is_identifier_char) {
        return None;
    }
    let mut chars = rest.chars();
    let mut taken = chars.next().map_or(0, char::len_utf8);
    taken += chars
        .take_while(|c| c.is_whitespace())
        .map(char::len_utf8)
        .sum::<usize>();
    let length = utf16_count(text.get(start..start + "abstract".len() + taken)?);
    Some((input.range.start, length, String::new()))
}

/// `invalid_inside_unary_pattern`: the reported inner pattern wraps in
/// parentheses — the official `SurroundWithParentheses` pair of
/// insertions folded into one whole-span replacement.
pub(crate) fn surround_with_parentheses(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let inner = slice16(input.text, &input.range)?;
    if inner.is_empty() {
        return None;
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        format!("({inner})"),
    ))
}

/// `wrong_separator_for_positional_parameter`: the `:` becomes `=`, with
/// a leading space when the colon touches the token before it (official
/// `ReplaceColonWithEquals`: `separator.offset == previous.end`).
pub(crate) fn colon_to_equals(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    if slice16(text, &input.range)? != ":" {
        return None;
    }
    let start = utf16_offset_to_byte(text, input.range.start);
    let touches = text[..start]
        .chars()
        .next_back()
        .is_some_and(|c| !matches!(c, ' ' | '\t' | '\r' | '\n'));
    let replacement = if touches { " =" } else { "=" };
    Some((input.range.start, 1, replacement.to_owned()))
}

/// The real token starting exactly at the UTF-16 `offset` — the parser
/// report's hit token (the zero-width recovery tail never qualifies).
fn token_starting_at(tokens: &TokenTable, offset: u32) -> Option<usize> {
    tokens
        .as_slice()
        .iter()
        .position(|token| token.byte_len > 0 && token.utf16_offset == offset)
}

/// The UTF-16 end offset of token `index`.
fn utf16_end(tokens: &TokenTable, text: &str, index: usize) -> Option<u32> {
    let token = tokens.get(index)?;
    Some(token.utf16_offset + utf16_count(tokens.lexeme(text, index)))
}

/// The `<` opening the type-argument group whose closer is at `close`
/// (`>`, `>>`, `>>>` all close; the nesting is counted by `>` units).
fn angle_group_start(tokens: &TokenTable, close: usize) -> Option<usize> {
    let mut depth = 0u32;
    let mut cursor = close;
    loop {
        match kind_of(tokens, cursor)? {
            TokenKind::Gt => depth += 1,
            TokenKind::GtGt => depth += 2,
            TokenKind::GtGtGt => depth += 3,
            TokenKind::Lt => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(cursor);
                }
            }
            TokenKind::Identifier | TokenKind::Period | TokenKind::Comma | TokenKind::Question => {}
            TokenKind::Keyword(Keyword::Void | Keyword::Dynamic) => {}
            _ => return None,
        }
        cursor = cursor.checked_sub(1)?;
    }
}

/// The `>`-family closer of the type-argument group opening at `open`
/// (`<`); `None` when the group does not close as plain type arguments.
fn angle_group_end(tokens: &TokenTable, open: usize) -> Option<usize> {
    if kind_of(tokens, open)? != TokenKind::Lt {
        return None;
    }
    let mut depth = 0i32;
    let mut cursor = open;
    loop {
        match kind_of(tokens, cursor)? {
            TokenKind::Lt => depth += 1,
            TokenKind::Gt => depth -= 1,
            TokenKind::GtGt => depth -= 2,
            TokenKind::GtGtGt => depth -= 3,
            TokenKind::Identifier | TokenKind::Period | TokenKind::Comma | TokenKind::Question => {}
            TokenKind::Keyword(Keyword::Void | Keyword::Dynamic) => {}
            _ => return None,
        }
        if depth <= 0 {
            return (depth == 0).then_some(cursor);
        }
        cursor += 1;
    }
}

/// The first depth-0 token at or after `from` for which `pred` holds, over
/// the `()`, `[]`, `{}` nesting — unlike [`depth0_find`], an opener itself
/// is offered to `pred` at the depth it stands on, so a body `{` is found
/// rather than entered.
fn depth0_scan(
    tokens: &TokenTable,
    from: usize,
    pred: impl Fn(TokenKind) -> bool,
) -> Option<usize> {
    let mut depth = 0u32;
    let mut cursor = from;
    loop {
        let kind = kind_of(tokens, cursor)?;
        if kind == TokenKind::Eof {
            return None;
        }
        if depth == 0 && pred(kind) {
            return Some(cursor);
        }
        match kind {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
        cursor += 1;
    }
}

/// `expected_token`: the official trio told apart by the quoted token the
/// message names — `InsertSemicolon` (`;` lands after the report, never
/// after an `await` identifier used outside `async`), `ReplaceWithArrow`
/// (a switch-expression case's `:` and the gap before it become ` =>`),
/// `InsertOnKeyword` (`on ` before the extended type, or before the
/// extension's name when the type is missing).
pub(crate) fn expected_token_fix(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let text = input.text;
    if input.message.contains("';'") {
        if slice16(text, &input.range)? == "await" {
            return None;
        }
        return Some((input.range.end, 0, ";".to_owned()));
    }
    let tokens = input.tokens?;
    let hit = token_starting_at(tokens, input.range.start)?;
    if input.message.contains("'=>'") {
        if kind_of(tokens, hit)? != TokenKind::Colon {
            return None;
        }
        let start = utf16_end(tokens, text, hit.checked_sub(1)?)?;
        let end = utf16_end(tokens, text, hit)?;
        return Some((start, end - start, " =>".to_owned()));
    }
    if input.message.contains("'on'") {
        if matches!(
            kind_of(tokens, hit)?,
            TokenKind::Identifier | TokenKind::Keyword(Keyword::Void | Keyword::Dynamic)
        ) {
            return Some((tokens.get(hit)?.utf16_offset, 0, "on ".to_owned()));
        }
        // The extended type is synthetic: the keyword lands before the
        // name, behind its type parameters.
        let mut name = hit.checked_sub(1)?;
        if matches!(
            kind_of(tokens, name)?,
            TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt
        ) {
            name = angle_group_start(tokens, name)?.checked_sub(1)?;
        }
        if kind_of(tokens, name)? != TokenKind::Identifier
            || kind_of(tokens, name.checked_sub(1)?)? != TokenKind::Keyword(Keyword::Extension)
        {
            return None;
        }
        return Some((tokens.get(name)?.utf16_offset, 0, "on ".to_owned()));
    }
    None
}

/// `extension_augmentation_has_on_clause`: the `on` clause goes from the
/// keyword through the body's opener (official `RemoveOnClause`:
/// `startStart(onClause, leftBracket-or-semicolon)`).
pub(crate) fn remove_on_clause(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let on = token_starting_at(tokens, input.range.start)?;
    if kind_of(tokens, on)? != TokenKind::Keyword(Keyword::On) {
        return None;
    }
    let body = depth0_scan(tokens, on + 1, |kind| {
        matches!(kind, TokenKind::OpenCurly | TokenKind::Semicolon)
    })?;
    let start = tokens.get(on)?.utf16_offset;
    let end = tokens.get(body)?.utf16_offset;
    Some((start, end.checked_sub(start)?, String::new()))
}

/// `getter_with_parameters`: the reported `(` through its `)` goes whole
/// (official `RemoveParametersInGetterDeclaration` over the kept
/// `FormalParameterList` node).
pub(crate) fn remove_getter_parameters(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let open = token_starting_at(tokens, input.range.start)?;
    let close = skip_group(tokens, open, TokenKind::OpenParen)?;
    let (start, length) = span_over(input.text, tokens, open, close)?;
    Some((start, length, String::new()))
}

/// `record_literal_one_positional_no_trailing_comma` /
/// `record_type_one_positional_no_trailing_comma`: `,` lands at the end
/// of the single field — the token before the reported `)` (official
/// `AddTrailingComma`: `fields.last.end`).
pub(crate) fn add_trailing_comma(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let close = token_starting_at(tokens, input.range.start)?;
    if kind_of(tokens, close)? != TokenKind::CloseParen {
        return None;
    }
    let field_end = close.checked_sub(1)?;
    if kind_of(tokens, field_end)? == TokenKind::OpenParen {
        return None;
    }
    Some((utf16_end(tokens, input.text, field_end)?, 0, ",".to_owned()))
}

/// `missing_typedef_parameters`: `()` lands at the end of the token before
/// the alias's `;` (official `AddEmptyArgumentList`: `endToken.previous.end`).
pub(crate) fn add_typedef_parameters(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let hit = token_starting_at(tokens, input.range.start)?;
    let semicolon = depth0_scan(tokens, hit, |kind| kind == TokenKind::Semicolon)?;
    let before = semicolon.checked_sub(1)?;
    if kind_of(tokens, before)? == TokenKind::Keyword(Keyword::Typedef) {
        return None;
    }
    Some((utf16_end(tokens, input.text, before)?, 0, "()".to_owned()))
}

/// `pattern_assignment_declares_variable`: the declared pattern's `var` /
/// `final` keyword plus one unit goes — the keyword stands before the
/// reported name, behind an optional type (official `RemoveVarKeyword`;
/// a typed pattern without a keyword has no edit).
pub(crate) fn remove_pattern_var_keyword(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let name = token_starting_at(tokens, input.range.start)?;
    let mut cursor = name.checked_sub(1)?;
    let keyword = |index: usize| {
        matches!(
            kind_of(tokens, index),
            Some(TokenKind::Keyword(Keyword::Var | Keyword::Final))
        )
    };
    if !keyword(cursor) {
        // Walk back over the type: `?`, the type arguments, the dotted name.
        if kind_of(tokens, cursor)? == TokenKind::Question {
            cursor = cursor.checked_sub(1)?;
        }
        if matches!(
            kind_of(tokens, cursor)?,
            TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt
        ) {
            cursor = angle_group_start(tokens, cursor)?.checked_sub(1)?;
        }
        if kind_of(tokens, cursor)? != TokenKind::Identifier {
            return None;
        }
        while cursor >= 2
            && kind_of(tokens, cursor - 1)? == TokenKind::Period
            && kind_of(tokens, cursor - 2)? == TokenKind::Identifier
        {
            cursor -= 2;
        }
        cursor = cursor.checked_sub(1)?;
        if !keyword(cursor) {
            return None;
        }
    }
    let token = tokens.get(cursor)?;
    remove_lexeme(text, token.utf16_offset, tokens.lexeme(text, cursor))
}

/// `unexpected_separator_in_number`: the literal is rebuilt without the
/// underscore runs that do not stand between two digits (official
/// `RemoveUnexpectedUnderscores`: a run survives only when a digit
/// precedes and follows it; hex digits count in a hex literal). The
/// scanner reports every illegal run at the literal's start, so the one
/// replacement covers them all.
pub(crate) fn remove_number_separators(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let literal = token_starting_at(tokens, input.range.start)?;
    let hex = match kind_of(tokens, literal)? {
        TokenKind::Int | TokenKind::Double => false,
        TokenKind::Hexadecimal => true,
        _ => return None,
    };
    let lexeme = tokens.lexeme(text, literal);
    let mut rebuilt = String::with_capacity(lexeme.len());
    let mut run = 0usize;
    let mut previous_is_digit = false;
    for byte in lexeme.bytes() {
        let is_digit = byte.is_ascii_digit() || (hex && byte.is_ascii_hexdigit());
        if byte == b'_' {
            run += 1;
            continue;
        }
        if run > 0 && is_digit && previous_is_digit {
            rebuilt.extend(std::iter::repeat_n('_', run));
        }
        run = 0;
        previous_is_digit = is_digit;
        rebuilt.push(char::from(byte));
    }
    if rebuilt == lexeme {
        return None;
    }
    let token = tokens.get(literal)?;
    Some((token.utf16_offset, utf16_count(lexeme), rebuilt))
}

/// `missing_function_body` / `static_getter_without_body` /
/// `static_setter_without_body`: the reported `;` body becomes the
/// official block — ` {`, a `// TODO: implement <name>` line, a
/// `throw UnimplementedError();` line unless the member's written return
/// type is `void` or the member is a setter, and the closing brace at
/// the declaration line's indentation (official
/// `ConvertIntoBlockBody.missingBody` over an `EmptyFunctionBody`: the
/// replacement runs from the token before the `;` through it; the
/// official reads the element's return type, which for an unwritten
/// return type is `dynamic` — an override-inferred `void` is the one
/// shape this written-type read does not see).
pub(crate) fn missing_body_block(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let semicolon = token_starting_at(tokens, input.range.start)?;
    if kind_of(tokens, semicolon)? != TokenKind::Semicolon {
        return None;
    }
    let before = semicolon.checked_sub(1)?;
    let (name, is_setter) = match kind_of(tokens, before)? {
        TokenKind::CloseParen => {
            let open = matching_begin(tokens, before)?;
            let mut name = open.checked_sub(1)?;
            if matches!(
                kind_of(tokens, name)?,
                TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt
            ) {
                name = angle_group_start(tokens, name)?.checked_sub(1)?;
            }
            let is_setter = name.checked_sub(1).is_some_and(|index| {
                kind_of(tokens, index) == Some(TokenKind::Keyword(Keyword::Set))
            });
            (name, is_setter)
        }
        TokenKind::Identifier => {
            if kind_of(tokens, before.checked_sub(1)?)? != TokenKind::Keyword(Keyword::Get) {
                return None;
            }
            (before, false)
        }
        _ => return None,
    };
    let mut display = tokens.lexeme(text, name).to_owned();
    if display.is_empty() {
        return None;
    }
    let head = name.checked_sub(1);
    let after_operator = head
        .is_some_and(|index| kind_of(tokens, index) == Some(TokenKind::Keyword(Keyword::Operator)));
    if after_operator && display == "-" && kind_of(tokens, name + 2)? == TokenKind::CloseParen {
        display = "unary-".to_owned();
    }
    // The written return type: the token before the name (behind a
    // getter's `get`); `void` alone reads as void.
    let type_token = match head {
        Some(index)
            if matches!(
                kind_of(tokens, index),
                Some(TokenKind::Keyword(Keyword::Get))
            ) =>
        {
            index.checked_sub(1)
        }
        Some(index) if after_operator => index.checked_sub(1),
        other => other,
    };
    let is_void = is_setter
        || type_token
            .is_some_and(|index| kind_of(tokens, index) == Some(TokenKind::Keyword(Keyword::Void)));
    // The declaration's first token: back over the head to the previous
    // member's end (or the file start) — its line carries the prefix.
    let mut first = name;
    while let Some(prev) = first.checked_sub(1) {
        match kind_of(tokens, prev)? {
            TokenKind::Semicolon | TokenKind::CloseCurly | TokenKind::OpenCurly => break,
            TokenKind::CloseParen | TokenKind::CloseSquare => first = matching_begin(tokens, prev)?,
            _ => first = prev,
        }
    }
    let prefix = line_indent(text, tokens.get(first)?.byte_offset as usize);
    let mut block = format!(" {{\n{prefix}  // TODO: implement {display}\n");
    if !is_void {
        block.push_str(&format!("{prefix}  throw UnimplementedError();\n"));
    }
    block.push_str(&format!("{prefix}}}"));
    let start = utf16_end(tokens, text, before)?;
    let end = utf16_end(tokens, text, semicolon)?;
    Some((start, end - start, block))
}

/// `extension_declares_constructor` / `mixin_declares_constructor`: the
/// constructor member goes from the end of the previous member (or the
/// body's `{`) through its own end token — `;` or the body's `}`
/// (official `RemoveConstructor`: `endEnd(previous.endToken ??
/// leftBracket, constructor.endToken)`); a `(` report is a primary
/// constructor, whose `(…)` goes alone.
pub(crate) fn remove_constructor(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let hit = token_starting_at(tokens, input.range.start)?;
    if kind_of(tokens, hit)? == TokenKind::OpenParen {
        let close = tokens.matching_end(hit)?;
        let (start, length) = span_over(text, tokens, hit, close)?;
        return Some((start, length, String::new()));
    }
    let open = depth0_scan(tokens, hit, |kind| kind == TokenKind::OpenParen)?;
    let close = tokens.matching_end(open)?;
    let end = match kind_of(tokens, close + 1)? {
        TokenKind::Semicolon => close + 1,
        TokenKind::OpenCurly => tokens.matching_end(close + 1)?,
        TokenKind::Function | TokenKind::Eq => {
            depth0_scan(tokens, close + 2, |kind| kind == TokenKind::Semicolon)?
        }
        TokenKind::Colon => initializer_list_end(tokens, close + 2)?,
        _ => return None,
    };
    let mut first = hit;
    loop {
        let prev = first.checked_sub(1)?;
        match kind_of(tokens, prev)? {
            TokenKind::Keyword(
                Keyword::Const | Keyword::Factory | Keyword::External | Keyword::Augment,
            )
            | TokenKind::Identifier
            | TokenKind::Period
            | TokenKind::At => first = prev,
            TokenKind::CloseParen => first = matching_begin(tokens, prev)?,
            TokenKind::Semicolon | TokenKind::CloseCurly | TokenKind::OpenCurly => break,
            _ => return None,
        }
    }
    let start = utf16_end(tokens, text, first.checked_sub(1)?)?;
    let end = utf16_end(tokens, text, end)?;
    Some((start, end.checked_sub(start)?, String::new()))
}

/// The end token of a constructor whose initializer list starts at
/// `from`: its `;`, or the `}` of the block body — a depth-0 `{` opens
/// the body unless it follows a token that can only precede a set/map
/// literal.
fn initializer_list_end(tokens: &TokenTable, from: usize) -> Option<usize> {
    let mut depth = 0u32;
    let mut cursor = from;
    loop {
        match kind_of(tokens, cursor)? {
            TokenKind::Eof => return None,
            TokenKind::OpenParen | TokenKind::OpenSquare => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare => depth = depth.checked_sub(1)?,
            TokenKind::Semicolon if depth == 0 => return Some(cursor),
            TokenKind::OpenCurly => {
                let literal = depth > 0
                    || matches!(
                        kind_of(tokens, cursor.checked_sub(1)?)?,
                        TokenKind::Eq
                            | TokenKind::Comma
                            | TokenKind::Colon
                            | TokenKind::Question
                            | TokenKind::QuestionQuestion
                            | TokenKind::Gt
                            | TokenKind::GtGt
                            | TokenKind::Keyword(Keyword::Const)
                    );
                let close = tokens.matching_end(cursor)?;
                if !literal {
                    return Some(close);
                }
                cursor = close;
            }
            _ => {}
        }
        cursor += 1;
    }
}

/// Whether `kind` is one of the binary operators a constant pattern's
/// expression parse consumes (bitwise-or precedence and tighter) — the
/// operators `invalid_constant_pattern_binary` reports.
fn is_constant_pattern_operator(kind: TokenKind) -> bool {
    matches!(
        kind,
        TokenKind::Bar
            | TokenKind::Caret
            | TokenKind::Ampersand
            | TokenKind::LtLt
            | TokenKind::GtGt
            | TokenKind::GtGtGt
            | TokenKind::Plus
            | TokenKind::Minus
            | TokenKind::Star
            | TokenKind::Slash
            | TokenKind::Percent
            | TokenKind::TildeSlash
    )
}

/// A single-token constant operand: a literal or a bare name.
fn is_constant_operand(kind: TokenKind) -> bool {
    matches!(
        kind,
        TokenKind::Identifier
            | TokenKind::Int
            | TokenKind::Double
            | TokenKind::Hexadecimal
            | TokenKind::String
            | TokenKind::Keyword(Keyword::True | Keyword::False | Keyword::Null)
    )
}

/// The first token of the dotted-name or literal operand ending at `at`
/// (a numeric literal takes a unary `-` that no operand precedes).
fn operand_start(tokens: &TokenTable, at: usize) -> Option<usize> {
    if !is_constant_operand(kind_of(tokens, at)?) {
        return None;
    }
    let mut start = at;
    if kind_of(tokens, at)? == TokenKind::Identifier {
        while start >= 2
            && kind_of(tokens, start - 1)? == TokenKind::Period
            && kind_of(tokens, start - 2)? == TokenKind::Identifier
        {
            start -= 2;
        }
    } else if matches!(
        kind_of(tokens, at)?,
        TokenKind::Int | TokenKind::Double | TokenKind::Hexadecimal
    ) && start >= 1
        && kind_of(tokens, start - 1)? == TokenKind::Minus
        && !start
            .checked_sub(2)
            .is_some_and(|index| kind_of(tokens, index).is_some_and(is_constant_operand))
    {
        start -= 1;
    }
    Some(start)
}

/// The last token of the dotted-name or literal operand starting at `at`
/// (a unary `-` takes its numeric literal).
fn operand_end(tokens: &TokenTable, at: usize) -> Option<usize> {
    let mut end = at;
    if kind_of(tokens, at)? == TokenKind::Minus {
        end += 1;
        if !matches!(
            kind_of(tokens, end)?,
            TokenKind::Int | TokenKind::Double | TokenKind::Hexadecimal
        ) {
            return None;
        }
        return Some(end);
    }
    if !is_constant_operand(kind_of(tokens, end)?) {
        return None;
    }
    if kind_of(tokens, end)? == TokenKind::Identifier {
        while kind_of(tokens, end + 1)? == TokenKind::Period
            && kind_of(tokens, end + 2)? == TokenKind::Identifier
        {
            end += 2;
        }
    }
    Some(end)
}

/// The `const` wrap of the pattern expression over tokens `first..=last`:
/// `const ` before an enclosing parenthesized pattern, else the span
/// replaced by `const (…)` (the official `AddConst` insertions folded
/// into one edit).
fn const_wrap(
    text: &str,
    tokens: &TokenTable,
    first: usize,
    last: usize,
) -> Option<(u32, u32, String)> {
    let parenthesized = first
        .checked_sub(1)
        .is_some_and(|index| kind_of(tokens, index) == Some(TokenKind::OpenParen))
        && kind_of(tokens, last + 1) == Some(TokenKind::CloseParen);
    if parenthesized {
        return Some((tokens.get(first - 1)?.utf16_offset, 0, "const ".to_owned()));
    }
    let (start, length) = span_over(text, tokens, first, last)?;
    let inner = slice16(text, &(start..start + length))?;
    Some((start, length, format!("const ({inner})")))
}

/// `invalid_constant_pattern_binary`: the reported operator's whole
/// operand chain — literals and dotted names joined by the operators the
/// constant parse consumes — wraps in `const (…)`, or `const ` lands
/// before an enclosing parenthesized pattern (official `AddConst`
/// binary-expression leg; an operand shape outside the chain grammar
/// drops).
pub(crate) fn const_pattern_binary(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let operator = token_starting_at(tokens, input.range.start)?;
    if !is_constant_pattern_operator(kind_of(tokens, operator)?) {
        return None;
    }
    let mut first = operand_start(tokens, operator.checked_sub(1)?)?;
    while first >= 2 && is_constant_pattern_operator(kind_of(tokens, first - 1)?) {
        first = operand_start(tokens, first - 2)?;
    }
    let mut last = operand_end(tokens, operator + 1)?;
    while is_constant_pattern_operator(kind_of(tokens, last + 1)?) {
        last = operand_end(tokens, last + 2)?;
    }
    const_wrap(input.text, tokens, first, last)
}

/// `invalid_constant_pattern_negation`: the `-` and its reported
/// non-numeric operand wrap in `const (…)` (official `AddConst`
/// prefix-expression leg).
pub(crate) fn const_pattern_negation(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let hit = token_starting_at(tokens, input.range.start)?;
    let anchor = if kind_of(tokens, hit)? == TokenKind::Period {
        hit.checked_sub(1)?
    } else {
        hit
    };
    let start = operand_start(tokens, anchor)?;
    let last = operand_end(tokens, start)?;
    let minus = start.checked_sub(1)?;
    if kind_of(tokens, minus)? != TokenKind::Minus {
        return None;
    }
    const_wrap(input.text, tokens, minus, last)
}

/// `invalid_constant_pattern_generic`: the type literal with its type
/// arguments wraps in `const (…)` when it is the whole case pattern
/// (`:` or `=>` follows), or `const ` lands before an enclosing
/// parenthesized pattern (official `AddConst` type-literal leg); a
/// guarded or nested pattern — where the official wraps the enclosing
/// node whole — gets no edit.
pub(crate) fn const_pattern_generic(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let lt = token_starting_at(tokens, input.range.start)?;
    let gt = angle_group_end(tokens, lt)?;
    let first = operand_start(tokens, lt.checked_sub(1)?)?;
    if kind_of(tokens, first)? != TokenKind::Identifier {
        return None;
    }
    match kind_of(tokens, gt + 1)? {
        TokenKind::Colon | TokenKind::Function => {}
        TokenKind::CloseParen
            if first
                .checked_sub(1)
                .is_some_and(|index| kind_of(tokens, index) == Some(TokenKind::OpenParen)) => {}
        _ => return None,
    }
    const_wrap(input.text, tokens, first, gt)
}

/// `use_named_constants`: the reported creation folds into the constant the
/// message names — the official `ReplaceWithNamedConstant` reads the
/// correction's quoted `{0}`; the lint's problem text carries the same
/// argument (`Use the constant 'C.zero' rather than …`), so the first
/// single-quoted run of the message is the replacement.
pub(crate) fn named_constant_reference(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let message = input.message;
    let open = message.find('\'')?;
    let close = message.get(open + 1..)?.find('\'')? + open + 1;
    let name = message.get(open + 1..close)?;
    if name.is_empty() {
        return None;
    }
    Some((
        input.range.start,
        input.range.end - input.range.start,
        name.to_owned(),
    ))
}

/// `unawaited_futures`: `await ` lands at the reported expression
/// statement's head — the official `AddAwait.unawaited` arm (`await ` at
/// the expression's offset, refused inside a cascade). The lint's own
/// gates already restrict reports to expression statements inside async
/// bodies, so the producer's convert-to-async arm never engages; the
/// `WrapInUnawaited` face (a `dart:async` import insertion) is not served.
///
/// The statement head is the token after the enclosing `;`/`{`/`}`/`:`
/// boundary — the lint only reports expression statements, so that head
/// is the expression's first token.
pub(crate) fn await_future_expression(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let selector = token_starting_at(tokens, input.range.start)?;
    // The statement's head: walk back to the statement boundary, group
    // interiors skipped (`{...}`/`(...)`/`[...]` tails inside the
    // expression never read as boundaries).
    let mut head = selector;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev) {
            Some(
                close @ (TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly),
            ) => {
                head = matching_open(tokens, prev, close)?;
            }
            Some(TokenKind::Semicolon | TokenKind::OpenCurly | TokenKind::Colon) => break,
            _ => head = prev,
        }
    }
    // The cascade gate (official `node is CascadeExpression` /
    // `node.parent?.parent is CascadeExpression` drops): a `..`/`?..`/
    // `...`/`...?` anywhere between the head and the selector at depth 0
    // puts the report inside a cascade section — the producer drops it.
    let mut depth = 0u32;
    for index in head..selector {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen
            | TokenKind::OpenSquare
            | TokenKind::OpenCurly
            | TokenKind::StringInterpolationExpression => depth += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                depth = depth.checked_sub(1)?;
            }
            TokenKind::PeriodPeriod
            | TokenKind::QuestionPeriodPeriod
            | TokenKind::PeriodPeriodPeriod
            | TokenKind::PeriodPeriodPeriodQuestion
                if depth == 0 =>
            {
                return None;
            }
            _ => {}
        }
    }
    let start16 = tokens.get(head)?.utf16_offset;
    Some((start16, 0, "await ".to_owned()))
}

/// Whether the block body at `brace` is a lambda's — upstream
/// `body.parent is FunctionExpression && parent.parent is! FunctionDeclaration`.
/// Token face: the token before the body's `async`-family tail is the
/// parameter list's `)`; a name (`f(`), an `operator` head, a getter's
/// identifier or a type-parameter list `f<T>(` ahead of its `(` makes the
/// body a declaration's. Anything else — `= (`, `, (`, `( (`, `return (`
/// — is a lambda.
fn body_is_lambda(tokens: &TokenTable, brace: usize) -> bool {
    let mut tail = brace;
    // The `async`/`sync` modifier words ride before `{` (a `*` tail never
    // reaches here — generators refused earlier).
    while let Some(prev) = tail.checked_sub(1) {
        match kind_of(tokens, prev) {
            Some(TokenKind::Keyword(Keyword::Async | Keyword::Sync)) => tail = prev,
            _ => break,
        }
    }
    let Some(prev) = tail.checked_sub(1) else {
        return false;
    };
    if kind_of(tokens, prev) != Some(TokenKind::CloseParen) {
        // A getter `int get x { }` — an identifier head, a declaration.
        return false;
    }
    let Some(open) = matching_open(tokens, prev, TokenKind::CloseParen) else {
        return false;
    };
    let Some(head) = open.checked_sub(1) else {
        return true; // `(` at file start — lambda either way
    };
    match kind_of(tokens, head) {
        Some(TokenKind::Identifier) => false,
        Some(TokenKind::Gt) => {
            // `f<T>() {}` declaration vs `<T>() {}` lambda — the token
            // before the angle group decides.
            match angle_group_start(tokens, head).and_then(|lt| lt.checked_sub(1)) {
                Some(before_lt) => {
                    !matches!(kind_of(tokens, before_lt), Some(TokenKind::Identifier))
                }
                None => true,
            }
        }
        // `operator ==(o) { }` — an operator head is a declaration.
        Some(_) => head
            .checked_sub(1)
            .and_then(|p| kind_of(tokens, p))
            .is_none_or(|kind| kind != TokenKind::Keyword(Keyword::Operator)),
        None => false,
    }
}

/// The begin-group index matching the close-group token at `close` — the
/// reverse walk `TokenTable::matching_end` answers forward.
fn matching_open(tokens: &TokenTable, close: usize, kind: TokenKind) -> Option<usize> {
    let opens = match kind {
        TokenKind::CloseParen => TokenKind::OpenParen,
        TokenKind::CloseSquare => TokenKind::OpenSquare,
        TokenKind::CloseCurly => TokenKind::OpenCurly,
        _ => return None,
    };
    let mut depth = 0u32;
    let mut cursor = close;
    loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => depth += 1,
            k if k == opens
                || (opens == TokenKind::OpenCurly
                    && k == TokenKind::StringInterpolationExpression) =>
            {
                if depth == 0 {
                    return Some(cursor);
                }
                depth -= 1;
            }
            // A different open kind closes its nested group; at depth 0 the
            // stream is unbalanced relative to `close`.
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                if depth == 0 {
                    return None;
                }
                depth -= 1;
            }
            _ => {}
        }
    }
}

/// `prefer_foreach`: the reported `for` statement folds into a `forEach`
/// tear-off — `for (var e in it) { f(e); }` → `it.forEach(f);` (the
/// official `ConvertToForEach`: the loop head through the iterable's start
/// goes, the iterable's tail through the invocation's start becomes
/// `.forEach(`, and the argument list through the statement's end becomes
/// `);`). The lint's own gates stand in for the producer's checks — the
/// declaration-form header, the single-argument body invocation, the
/// argument's identity as the loop variable.
pub(crate) fn for_each_tear_off(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    if kind_of(tokens, first)? != TokenKind::Keyword(Keyword::For) {
        return None;
    }
    let lparen = first + 1;
    if kind_of(tokens, lparen)? != TokenKind::OpenParen {
        return None;
    }
    let rparen = tokens.matching_end(lparen)?;
    // The iterable: the tokens between the `in` keyword and the header's
    // close — the head stays, everything after becomes `.forEach(`.
    let in_kw = depth0_find(tokens, text, lparen + 1, rparen, |kind, _| {
        kind == TokenKind::Keyword(Keyword::In)
    })?;
    if in_kw + 1 >= rparen {
        return None;
    }
    // The body: a single expression-statement invocation inside `{}` or
    // bare — `body` is the block or the statement itself.
    let mut cursor = rparen + 1;
    let braced = kind_of(tokens, cursor) == Some(TokenKind::OpenCurly);
    if braced {
        cursor += 1;
    }
    // The statement's invocation: `<target>.name(args)` or `name(args)` —
    // the argument list's open paren is the first depth-0 `(` inside the
    // statement (`depth0_find` counts the opener before testing, so the
    // group open itself needs a manual depth walk).
    let stmt_start = cursor;
    let stmt_end = depth0_find(tokens, text, cursor, tokens.len(), |kind, _| {
        kind == TokenKind::Semicolon
    })?;
    let mut invoke_paren = None;
    {
        let mut depth = 0u32;
        for index in stmt_start..stmt_end {
            match kind_of(tokens, index)? {
                TokenKind::OpenParen => {
                    if depth == 0 {
                        invoke_paren = Some(index);
                        break;
                    }
                    depth += 1;
                }
                TokenKind::OpenSquare | TokenKind::OpenCurly => depth += 1,
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                    depth = depth.checked_sub(1)?;
                }
                _ => {}
            }
        }
    }
    let invoke_paren = invoke_paren?;
    // The callee is the invocation minus its argument list — the whole
    // postfix chain (`obj.m(e)` → `obj.m`, `f(e)` → `f`). Walk back: the
    // callee name first (a `f<T>(` generic tail skipped), then each
    // `.`/`?.`/`!` link with the receiver atom behind it (a group tail or
    // a plain name).
    let mut invoke_start = invoke_paren.checked_sub(1)?; // the callee name
    if matches!(
        kind_of(tokens, invoke_start),
        Some(TokenKind::Gt | TokenKind::GtGt | TokenKind::GtGtGt)
    ) && let Some(lt) = angle_group_start(tokens, invoke_start)
    {
        invoke_start = lt.checked_sub(1)?;
    }
    loop {
        let prev = match invoke_start.checked_sub(1) {
            Some(i) if i >= stmt_start => i,
            _ => break,
        };
        if !matches!(
            kind_of(tokens, prev),
            Some(TokenKind::Period | TokenKind::QuestionPeriod | TokenKind::Bang)
        ) {
            break;
        }
        let atom = prev.checked_sub(1)?;
        if atom < stmt_start {
            return None;
        }
        invoke_start = match kind_of(tokens, atom)? {
            close @ (TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly) => {
                matching_open(tokens, atom, close)?
            }
            TokenKind::Identifier
            | TokenKind::Keyword(_)
            | TokenKind::Int
            | TokenKind::Double
            | TokenKind::Hexadecimal
            | TokenKind::String => atom,
            _ => return None,
        };
    }
    // The iterable's text and the invocation's callee text (the invocation
    // minus its argument list — the tear-off).
    let iterable = token_text(tokens, text, in_kw + 1..rparen)?;
    let callee = token_text(tokens, text, invoke_start..invoke_paren)?;
    let (start16, length16) = span_over(text, tokens, first, last)?;
    Some((start16, length16, format!("{iterable}.forEach({callee});")))
}

/// `prefer_expression_function_bodies`: the reported `{ return e; }` block
/// body folds into `=> e;` — the official `ConvertToExpressionFunctionBody`
/// replacement of the whole body, `async` keyword carried, comments riding
/// the `return`/`;`/`}` trivia preserved in order. The official gates the
/// lint cannot see are rebuilt: a generator body (`sync*`/`async*`) and a
/// non-factory constructor parent both refuse.
pub(crate) fn expression_function_body(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    // The report opens on the body `{` — the `async`/`sync` modifier words
    // ride the body's payload, outside its token range.
    let brace = token_starting_at(tokens, input.range.start)?;
    if kind_of(tokens, brace)? != TokenKind::OpenCurly {
        return None;
    }
    // The modifier words sit immediately before `{` — `async`, `sync`, or
    // either plus `*` (a generator never converts). They ride the parent's
    // payload outside the replaced span and stay put.
    if let Some(prev) = brace.checked_sub(1) {
        if kind_of(tokens, prev) == Some(TokenKind::Star) {
            return None; // `sync*`/`async*` — the official generator bail
        }
    }
    let close = tokens.matching_end(brace)?;
    // One statement inside: `return e;` or `e;` (the producer's
    // ReturnStatement and ExpressionStatement arms — the lint reports only
    // the `return` face, the ExpressionStatement arm is assist-side).
    let stmt_first = brace + 1;
    if stmt_first >= close {
        return None;
    }
    let (expr_start, expr_end) =
        if kind_of(tokens, stmt_first)? == TokenKind::Keyword(Keyword::Return) {
            let semi = depth0_find(tokens, text, stmt_first + 1, close, |kind, _| {
                kind == TokenKind::Semicolon
            })?;
            if semi + 1 != close || stmt_first + 1 == semi {
                return None;
            }
            (stmt_first + 1, semi)
        } else {
            let semi = depth0_find(tokens, text, stmt_first, close, |kind, _| {
                kind == TokenKind::Semicolon
            })?;
            if semi + 1 != close {
                return None;
            }
            (stmt_first, semi)
        };
    // The constructor gate: the body's parent is a constructor iff the
    // parameter list behind it belongs to a member named like the
    // enclosing class (`C(...)`, `C.name(...)`) or carries a `:`
    // initializer clause before the body — both token-visible.
    if is_constructor_body(tokens, text, brace) {
        return None;
    }
    // Comments ride the trivia between the `{`/`return`/expr/`;`/`}`
    // boundaries — reassemble them in the producer's write order:
    // comments before `return`/`e` lead, comments before `;`/`}` trail.
    let expr_text = slice16(
        text,
        &utf16_span_between(text, tokens, expr_start, expr_end),
    )?;
    let pre_return = trivia_text(text, token_end_byte(tokens, brace), tokens, stmt_first);
    let pre_expr = if kind_of(tokens, stmt_first)? == TokenKind::Keyword(Keyword::Return) {
        trivia_text(text, token_end_byte(tokens, stmt_first), tokens, expr_start)
    } else {
        String::new()
    };
    let pre_semi = trivia_text(text, token_end_byte(tokens, expr_end - 1), tokens, expr_end);
    let pre_close = trivia_text(text, token_end_byte(tokens, expr_end), tokens, close);
    let mut replacement = String::new();
    // The official write order: `=> `, then the comments before
    // `return`/the expression, then the expression, then the comments
    // before `;`/`}` — `;` rides last, and only when the body is a
    // declared function/method (a lambda's `=> e` never takes `;` —
    // upstream Dart SDK source, pkg/analysis_server/lib/src/services/
    // correction/dart/convert_to_expression_function_body.dart:96-127).
    replacement.push_str("=> ");
    for piece in [&pre_return, &pre_expr] {
        if !piece.is_empty() {
            replacement.push_str(piece);
            replacement.push(' ');
        }
    }
    replacement.push_str(expr_text.trim());
    if !pre_semi.is_empty() {
        replacement.push(' ');
        replacement.push_str(&pre_semi);
    }
    if !pre_close.is_empty() {
        if pre_semi.is_empty() {
            replacement.push(' ');
        }
        replacement.push_str(&pre_close);
    }
    // The `;` is the declaration's terminator — a lambda body (the token
    // before its parameter list isn't a declaration head: `= (`, `, (`,
    // `( (`…) writes no `;`.
    if !body_is_lambda(tokens, brace) {
        replacement.push(';');
    }
    // The rewrite covers `[brace, close]` — the body's token range (the
    // `async` word before it is the parent's payload, not ours).
    let (start16, length16) = span_over(text, tokens, brace, close)?;
    Some((start16, length16, replacement))
}

/// The byte offset at a token's end.
fn token_end_byte(tokens: &TokenTable, index: usize) -> usize {
    token_end(tokens.get(index).expect("token index"))
}

/// The comment text in `[byte_at, tokens[next].byte_offset)` — the trivia
/// run between two tokens, comments kept, whitespace dropped (each comment
/// emitted as `// …` or `/* … */` separated by spaces).
fn trivia_text(text: &str, byte_at: usize, tokens: &TokenTable, next: usize) -> String {
    let end = tokens
        .get(next)
        .map(|t| t.byte_offset as usize)
        .unwrap_or(text.len());
    let slice = text.get(byte_at..end).unwrap_or("");
    let mut out = String::new();
    let bytes = slice.as_bytes();
    let mut at = 0usize;
    while at < bytes.len() {
        if bytes[at..].starts_with(b"//") {
            let end = bytes[at..]
                .iter()
                .position(|&b| b == b'\n')
                .map_or(bytes.len(), |i| at + i);
            if !out.is_empty() {
                out.push(' ');
            }
            out.push_str(slice[at..end].trim_end());
            at = end;
        } else if bytes[at..].starts_with(b"/*") {
            let mut depth = 1u32;
            let mut i = at + 2;
            while depth > 0 && i + 1 < bytes.len() {
                if bytes[i] == b'/' && bytes[i + 1] == b'*' {
                    depth += 1;
                    i += 2;
                } else if bytes[i] == b'*' && bytes[i + 1] == b'/' {
                    depth -= 1;
                    i += 2;
                } else {
                    i += 1;
                }
            }
            let comment_end = if depth == 0 { i } else { bytes.len() };
            if !out.is_empty() {
                out.push(' ');
            }
            out.push_str(slice[at..comment_end].trim());
            at = comment_end;
        } else {
            at += 1;
        }
    }
    out
}

/// Whether the block `{` at `brace` is a constructor's body — the
/// declaration head before it reads `Name(...)`/`Name.x(...)` (the second
/// identifier dotted) or `Name<...>(...)` with no return type, or a `:`
/// initializer clause trails the parameter list. `factory`-led heads are
/// constructors too — the caller pairs this with the producer's own
/// `factoryKeyword == null` refusal (a `factory` head converts fine).
fn is_constructor_body(tokens: &TokenTable, text: &str, brace: usize) -> bool {
    // The member head ends at the body's `async` keyword or at `brace`
    // itself; the parameter list's `)` is the last `)` before it whose
    // group closes there — walk back to it. A `:` initializer clause
    // between `)` and the body is constructor-only.
    let mut tail = brace;
    while let Some(prev) = tail.checked_sub(1) {
        match kind_of(tokens, prev) {
            Some(TokenKind::CloseParen) => {
                let Some(open) = matching_open(tokens, prev, TokenKind::CloseParen) else {
                    return false;
                };
                tail = open;
                continue;
            }
            Some(TokenKind::Identifier | TokenKind::Keyword(_) | TokenKind::Comma) => {
                tail = prev;
                continue;
            }
            Some(TokenKind::Colon) => return true,
            Some(
                TokenKind::Semicolon
                | TokenKind::OpenCurly
                | TokenKind::CloseCurly
                | TokenKind::Function,
            ) => {
                return false;
            }
            _ => return false,
        }
    }
    // No `:` clause — the member's name precedes the parameter list's `(`;
    // a `Name.name` shape is a named constructor, a bare `Name` matching
    // the enclosing class is the unnamed one.
    let Some(close_paren) = tail
        .checked_sub(1)
        .filter(|&i| kind_of(tokens, i) == Some(TokenKind::CloseParen))
    else {
        return false;
    };
    let Some(open_paren) = matching_open(tokens, close_paren, TokenKind::CloseParen) else {
        return false;
    };
    let Some(name) = open_paren.checked_sub(1) else {
        return false;
    };
    if kind_of(tokens, name) != Some(TokenKind::Identifier)
        && !matches!(kind_of(tokens, name), Some(TokenKind::Keyword(_)))
    {
        return false;
    }
    // `Name.name(` — the dot-joined pair is a named constructor.
    if name >= 2 && kind_of(tokens, name - 1) == Some(TokenKind::Period) {
        return true;
    }
    // The bare-name face: a constructor iff the name is the enclosing
    // declaration's. The member head before the name is scanned for a
    // return type — one identifier or a qualified/generic type — and the
    // enclosing container's own name.
    if let Some(class_name) = enclosing_container_name(tokens, text, open_paren) {
        return tokens.lexeme(text, name) == class_name;
    }
    false
}

/// The name of the `class`/`enum`/`mixin`/`extension`/`extension type`
/// declaration whose body encloses token `at` — found by walking the
/// brace pairs out to the container's `{` and its header's name.
fn enclosing_container_name<'s>(tokens: &TokenTable, text: &'s str, at: usize) -> Option<&'s str> {
    // The enclosing `{`: the innermost begin-group opened before `at` and
    // closed after it.
    let mut depth = 0u32;
    let mut cursor = at;
    let container = loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::CloseCurly => depth += 1,
            TokenKind::OpenCurly => {
                if depth == 0 {
                    break cursor;
                }
                depth -= 1;
            }
            _ => {}
        }
    };
    // The container's head: `class Name`, `enum Name`, `mixin Name`,
    // `extension type Name`, `extension Name` — the keyword's next word
    // token (modifiers like `base`/`abstract` skipped) before `{`.
    let mut head = container;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev) {
            Some(TokenKind::Keyword(Keyword::Class | Keyword::Enum | Keyword::Mixin)) => {
                return Some(tokens.lexeme(text, head));
            }
            Some(TokenKind::Keyword(Keyword::Extension)) => {
                // `extension type Name(...)` — the name follows `type`.
                let mut name = head;
                while kind_of(tokens, name) == Some(TokenKind::Keyword(Keyword::Typedef))
                    || word_at(tokens, text, name, "type")
                {
                    name += 1;
                }
                return Some(tokens.lexeme(text, name));
            }
            Some(TokenKind::Semicolon | TokenKind::CloseCurly) => return None,
            _ => head = prev,
        }
    }
    None
}

/// The UTF-16 `[start, end)` covering token `first` through the byte-end
/// of `last`'s predecessor — the token range's span.
fn utf16_span_between(
    text: &str,
    tokens: &TokenTable,
    first: usize,
    last: usize,
) -> core::ops::Range<u32> {
    let start = tokens.get(first).map(|t| t.utf16_offset).unwrap_or(0);
    let end = last
        .checked_sub(1)
        .and_then(|i| utf16_end(tokens, text, i))
        .unwrap_or(start);
    start..end
}

/// `always_put_required_named_parameters_first`: every `required` named
/// parameter after the first optional named one moves ahead of it — the
/// official `MakeRequiredNamedParametersFirst` reorder, expressed here as
/// one replacement of the `{...}` group's interior: required segments
/// (with their comments) first, then the optional ones, each in its
/// original order.
pub(crate) fn required_named_parameters_first(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    // The named-parameters group: the `{` group enclosing the hit.
    let mut depth = 0u32;
    let mut cursor = first;
    let group_open = loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::CloseCurly | TokenKind::CloseParen | TokenKind::CloseSquare => depth += 1,
            TokenKind::OpenCurly => {
                if depth == 0 {
                    break cursor;
                }
                depth -= 1;
            }
            TokenKind::OpenParen | TokenKind::OpenSquare => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
    };
    let group_close = tokens.matching_end(group_open)?;
    // The parameter segments split at the group's depth-0 commas.
    let mut bounds = Vec::new();
    let mut start = group_open + 1;
    let mut d = 0u32;
    let mut trailing_comma = false;
    for index in (group_open + 1)..group_close {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => d += 1,
            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                d = d.checked_sub(1)?
            }
            TokenKind::Comma if d == 0 => {
                bounds.push((start, index));
                start = index + 1;
            }
            _ => {}
        }
    }
    if start < group_close {
        bounds.push((start, group_close));
    } else {
        // The last comma abuts `}` — a trailing comma the official edit
        // keeps.
        trailing_comma = true;
    }
    // A segment is `required` iff its first keyword reads it, or its
    // metadata carries `@required` (the lint's `metadata.hasRequired`
    // gate fires on it — upstream Dart SDK source,
    // pkg/linter/lib/src/rules/always_put_required_named_parameters_first.dart:59).
    // Metadata `@x` rides the segment head.
    let is_required = |range: (usize, usize)| -> Option<bool> {
        let mut i = range.0;
        while i < range.1 {
            match kind_of(tokens, i)? {
                TokenKind::At => {
                    // `@required`/`@required(...)`: the annotation's head
                    // word decides (`required` scans as a keyword, not an
                    // identifier); any other `@meta` is inert.
                    let annotation_required =
                        (matches!(kind_of(tokens, i + 1), Some(TokenKind::Identifier))
                            && tokens.lexeme(text, i + 1) == "required")
                            || kind_of(tokens, i + 1)
                                == Some(TokenKind::Keyword(Keyword::Required));
                    // `@a.b(...)`: the annotation runs over
                    // byte-adjacent `.`-chained words, then an argument
                    // list — a space-separated token ends it.
                    let mut j = i + 1;
                    while matches!(
                        kind_of(tokens, j),
                        Some(TokenKind::Identifier | TokenKind::Period | TokenKind::Keyword(_))
                    ) && token_end_byte(tokens, j - 1)
                        == tokens.get(j).map(|t| t.byte_offset as usize).unwrap_or(0)
                    {
                        j += 1;
                    }
                    if kind_of(tokens, j) == Some(TokenKind::OpenParen)
                        && token_end_byte(tokens, j - 1)
                            == tokens.get(j).map(|t| t.byte_offset as usize).unwrap_or(0)
                    {
                        j = tokens.matching_end(j)? + 1;
                    }
                    i = j;
                    if annotation_required {
                        return Some(true);
                    }
                }
                TokenKind::Keyword(Keyword::Required) => return Some(true),
                _ => return Some(false),
            }
        }
        None
    };
    let first_optional = bounds.iter().position(|&b| is_required(b) == Some(false))?;
    let mut moved = Vec::new();
    let mut kept = Vec::new();
    for (i, &b) in bounds.iter().enumerate() {
        if i > first_optional && is_required(b) == Some(true) {
            moved.push(b);
        } else {
            kept.push(b);
        }
    }
    if moved.is_empty() {
        return None;
    }
    // The reported parameter must be the first offending one — the
    // official producer fires only on it.
    if moved
        .first()
        .is_none_or(|&b| !(first >= b.0 && first < b.1))
    {
        return None;
    }
    // Rebuild: kept order with the moved segments inserted where the
    // first optional sat — the group's whole interior rewrites.
    let mut interior = String::new();
    let mut ordered = Vec::new();
    for &b in &kept {
        if b == bounds[first_optional] {
            ordered.extend_from_slice(&moved);
        }
        ordered.push(b);
    }
    if kept.iter().all(|&b| b != bounds[first_optional]) {
        ordered.extend_from_slice(&moved);
    }
    for (i, &b) in ordered.iter().enumerate() {
        // A segment's comments ride with it — the trivia between the
        // boundary token (the preceding `,`, or `{` for the head segment)
        // and its first token re-emits ahead of the segment text (the
        // official moves `nodeWithComments` ranges — upstream Dart SDK
        // source, pkg/analysis_server/lib/src/services/correction/dart/
        // make_required_named_parameters_first.dart:60-73).
        let boundary = if bounds.first().is_some_and(|&f| f == b) {
            group_open
        } else {
            b.0 - 1 // the comma ending the previous segment
        };
        let comments = trivia_text(text, token_end_byte(tokens, boundary), tokens, b.0);
        if i > 0 {
            interior.push_str(", ");
        }
        if !comments.is_empty() {
            interior.push_str(&comments);
            interior.push(' ');
        }
        interior.push_str(segment_text(text, tokens, b).trim());
    }
    if trailing_comma {
        interior.push(',');
    }
    // The rewrite starts at the head segment's comments — the official
    // anchors at `firstComments?.offset ?? firstParameter.offset`, so the
    // moved parameters land ahead of them rather than erasing the trivia.
    let head_start_byte = {
        let trivia_start = token_end_byte(tokens, group_open);
        let first_byte = tokens.get(bounds[0].0)?.byte_offset as usize;
        let trivia = &text[trivia_start..first_byte];
        // The head parameter's first comment token — `/*` or `//`,
        // whichever leads (upstream `firstComments?.offset`).
        [trivia.find("/*"), trivia.find("//")]
            .into_iter()
            .flatten()
            .min()
            .map_or(first_byte, |rel| trivia_start + rel)
    };
    let start16 = utf16_count(&text[..head_start_byte]);
    let end16 = tokens.get(group_close)?.utf16_offset;
    Some((start16, end16.checked_sub(start16)?, interior))
}

/// The raw source text of a token-index range (comments and trivia
/// preserved verbatim).
fn segment_text(text: &str, tokens: &TokenTable, range: (usize, usize)) -> String {
    let start = tokens
        .get(range.0)
        .map(|t| t.byte_offset as usize)
        .unwrap_or(0);
    let end = range
        .1
        .checked_sub(1)
        .and_then(|i| tokens.get(i))
        .map(|t| token_end(t))
        .unwrap_or(start);
    text.get(start..end).unwrap_or("").to_owned()
}

/// The `{`/`}` token pair of the class-like body enclosing token `at`
/// — the innermost `{` opened before `at` and closed after it that heads
/// a `class`/`enum`/`mixin`/`extension`/`extension type` declaration
/// (distinguished from a function body by the `class`-family keyword in
/// its header).
fn enclosing_class_body(tokens: &TokenTable, at: usize) -> Option<(usize, usize)> {
    let mut depth = 0u32;
    let mut cursor = at;
    let body = loop {
        cursor = cursor.checked_sub(1)?;
        match kind_of(tokens, cursor)? {
            TokenKind::CloseCurly => depth += 1,
            TokenKind::OpenCurly => {
                if depth == 0 {
                    break cursor;
                }
                depth -= 1;
            }
            _ => {}
        }
    };
    // Confirm the `{` heads a class-like declaration: scan its header for
    // the keyword.
    let mut head = body;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev) {
            Some(TokenKind::Keyword(
                Keyword::Class | Keyword::Enum | Keyword::Mixin | Keyword::Extension,
            )) => return Some((body, tokens.matching_end(body)?)),
            Some(TokenKind::Semicolon | TokenKind::CloseCurly) => return None,
            _ => head = prev,
        }
    }
    None
}

/// The member boundaries inside a class-like body: `(start, end)` token
/// pairs — each member's first and last token (doc comments and metadata
/// ride the gap, matching the official `nodeWithComments` read on move).
/// `members` splits `[from, close)` at its depth-0 member ends (`;` fields
/// and `}`-closed bodies, `=>`-arrow members end at `;`).
fn class_members(tokens: &TokenTable, from: usize, close: usize) -> Vec<(usize, usize)> {
    let mut members = Vec::new();
    let mut start = from;
    let mut cursor = from;
    while cursor < close {
        match kind_of(tokens, cursor).unwrap_or(TokenKind::Eof) {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::Lt => {
                // Parameter/type groups ride the member head.
                if let Some(end) = tokens.matching_end(cursor) {
                    cursor = end;
                }
            }
            TokenKind::OpenCurly => {
                // A member body (`{ ... }`) ends the member.
                if let Some(end) = tokens.matching_end(cursor) {
                    members.push((start, end + 1));
                    start = end + 1;
                    cursor = end;
                }
            }
            TokenKind::Semicolon => {
                members.push((start, cursor + 1));
                start = cursor + 1;
            }
            TokenKind::Eof => break,
            _ => {}
        }
        cursor += 1;
    }
    if start < close {
        members.push((start, close));
    }
    members
}

/// `sort_constructors_first`: the reported constructor moves to the head
/// of its class body — the official `SortConstructorFirst` relocation:
/// `[insertion, ctor_end)` becomes `newlineAndIndent + ctorText +
/// blankLineSeparator + (the members that stood before the ctor)`. The
/// insertion point is the class `{`'s end; for an enum it is just after
/// the constant list's `;` (or the last constant). `ctorText` is the
/// member's full source — doc comments and metadata ride it (the official
/// `nodeWithComments` range).
pub(crate) fn constructor_first(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    let (body_open, body_close) = enclosing_class_body(tokens, first)?;
    // The insertion offset: the class `{`'s end; for an enum the constant
    // list's `;` end (or the `{` when no `;` stands). These are byte
    // positions inside trivia — the official's `leftBracket.end` /
    // `semicolon.end`.
    let (insertion_byte, members_from, enum_body) = if is_enum_body(tokens, body_open) {
        let mut semi = None;
        let mut d = 0u32;
        for index in body_open + 1..body_close {
            match kind_of(tokens, index)? {
                TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => d += 1,
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                    d = d.checked_sub(1)?;
                }
                TokenKind::Semicolon if d == 0 => {
                    semi = Some(index);
                    break;
                }
                _ => {}
            }
        }
        match semi {
            Some(s) => (token_end_byte(tokens, s), s + 1, true),
            None => (token_end_byte(tokens, body_open), body_open + 1, true),
        }
    } else {
        (token_end_byte(tokens, body_open), body_open + 1, false)
    };
    let members = class_members(tokens, members_from, body_close);
    let target_idx = members.iter().position(|&(s, e)| first >= s && first < e)?;
    if target_idx == 0 {
        return None; // already first — no edit the official would offer.
    }
    let target = members[target_idx];
    // The gap `[prev_member_end, node_with_comments_start)` is separator
    // whitespace — its last newline plus indentation becomes the relocated
    // member's leading line break; `nodeWithComments` runs from the
    // leading comment block, the plain member head otherwise.
    let prev_member_end = member_end_byte(text, tokens, members[target_idx - 1].1 - 1);
    // The official `nodeWithComments` range starts at the comment/node's own
    // offset — the leading indentation of the block's first line rides the
    // gap, not the moved text.
    let block_start = member_block_start(text, tokens.get(target.0)?.utf16_offset);
    let moved_start = block_start
        + text[block_start..]
            .find(|c: char| !matches!(c, ' ' | '\t'))
            .unwrap_or(0);
    let gap = text.get(prev_member_end..moved_start).unwrap_or("");
    let newline_indent = match gap.rfind('\n') {
        Some(i) => &gap[i..],
        None => gap,
    };
    let moved_end = member_end_byte(text, tokens, target.1 - 1);
    let moved = text.get(moved_start..moved_end)?;
    // A blank line between the previous member and the constructor was
    // its separator — it re-lands after the relocated member unless a
    // blank line already follows the insertion point.
    let had_blank = gap.matches('\n').count() > 1;
    let after = text.get(insertion_byte..moved_start).unwrap_or("");
    let already_blank_after = {
        // The line after `insertion_byte` is blank from it through the
        // next newline, and the following line is empty (the official
        // `_hasBlankLineAfter`).
        let line_rest = after.split('\n').next().unwrap_or("");
        let next_line = after
            .split('\n')
            .nth(1)
            .map(|s| s.trim().is_empty())
            .unwrap_or(false);
        line_rest.trim().is_empty() && next_line
    };
    let blank_sep = if had_blank && !already_blank_after {
        "\n"
    } else {
        ""
    };
    let leading_blank = if enum_body && had_blank { "\n" } else { "" };
    // One rewrite over `[insertion_byte, ctor_end)`: the deleted
    // `[prev_member_end, ctor_end)` text re-lands at the head, the members
    // that stood before it unchanged between.
    let middle = text.get(insertion_byte..prev_member_end)?;
    let start16 = utf16_count(&text[..insertion_byte]);
    let end16 = utf16_count(&text[..moved_end]);
    Some((
        start16,
        end16.checked_sub(start16)?,
        format!("{leading_blank}{newline_indent}{moved}{blank_sep}{middle}"),
    ))
}

/// Whether the class-body `{` at `open` heads an `enum` declaration.
fn is_enum_body(tokens: &TokenTable, open: usize) -> bool {
    let mut head = open;
    while let Some(prev) = head.checked_sub(1) {
        match kind_of(tokens, prev) {
            Some(TokenKind::Keyword(Keyword::Enum)) => return true,
            Some(TokenKind::Keyword(Keyword::Class | Keyword::Mixin | Keyword::Extension)) => {
                return false;
            }
            Some(TokenKind::Semicolon | TokenKind::CloseCurly) => return false,
            _ => head = prev,
        }
    }
    false
}

/// A member's first-token byte offset.
fn member_start_byte(_text: &str, tokens: &TokenTable, index: usize) -> usize {
    tokens
        .get(index)
        .map(|t| t.byte_offset as usize)
        .unwrap_or(0)
}

/// A member's last-token byte end.
fn member_end_byte(_text: &str, tokens: &TokenTable, index: usize) -> usize {
    tokens.get(index).map(token_end).unwrap_or(0)
}

/// `sort_unnamed_constructors_first`: the reported unnamed/`new`
/// constructor moves ahead of the first constructor in its class body —
/// the official `SortUnnamedConstructorFirst` move of the `[prevMember.end,
/// ctor.end)` range (the gap before the member rides with it) to just
/// after the member that precedes the first constructor (or the body's
/// head / enum `;` when the first constructor leads).
pub(crate) fn unnamed_constructor_first(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, _) = hit_tokens(tokens, &input.range)?;
    let (body_open, body_close) = enclosing_class_body(tokens, first)?;
    // The insertion offset when the first constructor leads the body: the
    // official `topOfBodyOffset` — the `{`'s end for a class, the constant
    // list's `;` end (or the `{`'s end when no `;` stands) for an enum.
    let (top_of_body, members_from) = if is_enum_body(tokens, body_open) {
        let mut semi = None;
        let mut d = 0u32;
        for index in body_open + 1..body_close {
            match kind_of(tokens, index)? {
                TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => d += 1,
                TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
                    d = d.checked_sub(1)?;
                }
                TokenKind::Semicolon if d == 0 => {
                    semi = Some(index);
                    break;
                }
                _ => {}
            }
        }
        match semi {
            Some(s) => (token_end_byte(tokens, s), s + 1),
            None => (token_end_byte(tokens, body_open), body_open + 1),
        }
    } else {
        (token_end_byte(tokens, body_open), body_open + 1)
    };
    let members = class_members(tokens, members_from, body_close);
    let target_idx = members.iter().position(|&(s, e)| first >= s && first < e)?;
    if !is_unnamed_constructor(tokens, text, members[target_idx]) {
        return None;
    }
    // The first constructor in member order — the unnamed one must land
    // ahead of it. The predicate is gated on the enclosing container's
    // name (the official `whereType<ConstructorDeclaration>` filter):
    // `Identifier (`/`Identifier . Identifier (` also matches a
    // return-type-less method `helper() {}`/`Other.name() {}`.
    let class_name = enclosing_container_name(tokens, text, first)?;
    let first_ctor = members
        .iter()
        .position(|&m| is_constructor_member(tokens, text, m, class_name))?;
    if target_idx == first_ctor {
        return None;
    }
    // The insertion offset: the member before the first constructor's end
    // — or the body's head when the first constructor leads.
    let insertion_byte = if first_ctor == 0 {
        top_of_body
    } else {
        member_end_byte(text, tokens, members[first_ctor - 1].1 - 1)
    };
    let prev_end = member_end_byte(text, tokens, members[target_idx - 1].1 - 1);
    let ctor_end = member_end_byte(text, tokens, members[target_idx].1 - 1);
    let moved = text.get(prev_end..ctor_end)?;
    let middle = text.get(insertion_byte..prev_end)?;
    let region_start16 = utf16_count(&text[..insertion_byte]);
    let region_end16 = utf16_count(&text[..ctor_end]);
    Some((
        region_start16,
        region_end16.checked_sub(region_start16)?,
        format!("{moved}{middle}"),
    ))
}

/// Whether the member range is a constructor declaration — a `factory`
/// keyword or a `Name(`/`Name.name(` head whose `Name` is the enclosing
/// container's own (the official `whereType<ConstructorDeclaration>`);
/// any other identifier-headed member is a return-type-less method.
fn is_constructor_member(
    tokens: &TokenTable,
    text: &str,
    member: (usize, usize),
    class_name: &str,
) -> bool {
    let (s, e) = member;
    let mut i = s;
    // Leading keywords (`const`, `factory`, `external`, metadata already
    // folded into the gap by `class_members`).
    while i < e
        && matches!(
            kind_of(tokens, i),
            Some(TokenKind::Keyword(
                Keyword::Const | Keyword::Factory | Keyword::External | Keyword::Static
            ))
        )
    {
        i += 1;
    }
    if i >= e || !matches!(kind_of(tokens, i), Some(TokenKind::Identifier)) {
        return false;
    }
    // The head's first identifier must be the container's name — a
    // `helper()`/`Other.named()` face is a method, not a constructor.
    if tokens.lexeme(text, i) != class_name {
        return false;
    }
    let mut j = i + 1;
    if kind_of(tokens, j) == Some(TokenKind::Period) {
        j += 1;
        // `C.new(` — `new` scans as a keyword; every other named face is
        // a plain identifier.
        if !matches!(
            kind_of(tokens, j),
            Some(TokenKind::Identifier | TokenKind::Keyword(Keyword::New))
        ) {
            return false;
        }
        j += 1;
    }
    kind_of(tokens, j) == Some(TokenKind::OpenParen)
}

/// Whether the member range is an unnamed (`Name(`/`Name.new(`)
/// constructor — the official `name == null || name.lexeme == 'new'`
/// read.
fn is_unnamed_constructor(tokens: &TokenTable, text: &str, member: (usize, usize)) -> bool {
    let (s, e) = member;
    let mut i = s;
    // Skip leading keywords (`const`, `factory`, `external`).
    while i < e
        && matches!(
            kind_of(tokens, i),
            Some(TokenKind::Keyword(
                Keyword::Const | Keyword::Factory | Keyword::External
            ))
        )
    {
        i += 1;
    }
    if i >= e || !matches!(kind_of(tokens, i), Some(TokenKind::Identifier)) {
        return false;
    }
    match kind_of(tokens, i + 1) {
        Some(TokenKind::OpenParen) => true,
        Some(TokenKind::Period) => word_at(tokens, text, i + 2, "new"),
        _ => false,
    }
}

/// `unnecessary_getters_setters`: the trivial getter/setter pair folds back
/// into the field it wraps — the official `MakeFieldPublic` deletes the
/// getter and the setter member ranges and renames the `_x` field to `x`.
/// One span rewrite over the class body: inside the span covering the
/// three members, the getter and setter ranges drop and the field's
/// `_name` token becomes `name`; interleaved members keep their text.
pub(crate) fn field_public(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    // The hit is width-0 on the getter's name token.
    let name = token_starting_at(tokens, input.range.start)?;
    let getter_name = tokens.lexeme(text, name);
    let (body_open, body_close) = enclosing_class_body(tokens, name)?;
    let members = class_members(tokens, body_open + 1, body_close);
    // The getter member covers the name and carries `get`.
    let getter_idx = members.iter().position(|&(s, e)| name >= s && name < e)?;
    if !member_has_keyword(tokens, members[getter_idx], Keyword::Get) {
        return None;
    }
    // The sibling setter `set name` and the `_name` field member.
    let setter_idx = members.iter().position(|&m| {
        member_has_keyword(tokens, m, Keyword::Set)
            && member_name(tokens, text, m) == Some(getter_name)
    })?;
    let field_name = format!("_{getter_name}");
    let field_idx = members.iter().position(|&m| {
        !member_has_keyword(tokens, m, Keyword::Get)
            && !member_has_keyword(tokens, m, Keyword::Set)
            && member_declares_name(tokens, text, m, &field_name)
    });
    // The renamed token: the field's `_name` inside the field member — or,
    // when no field member stands, the declaring `final`/`var _name`
    // parameter of the class's primary-constructor head (upstream Dart SDK
    // source, pkg/analysis_server/lib/src/services/correction/dart/
    // make_field_public.dart:73-77,160-175).
    let (name_byte, name_end) = match field_idx {
        Some(field_idx) => {
            let f = members[field_idx];
            let name_tok = (f.0..f.1).find(|&i| {
                matches!(kind_of(tokens, i), Some(TokenKind::Identifier))
                    && tokens.lexeme(text, i) == field_name
                    && matches!(
                        kind_of(tokens, i + 1),
                        Some(TokenKind::Semicolon | TokenKind::Eq | TokenKind::Comma)
                    )
            })?;
            let start = tokens.get(name_tok)?.byte_offset as usize;
            (start, start + field_name.len())
        }
        None => {
            let name_tok = primary_ctor_declaring_param(tokens, text, body_open, &field_name)?;
            let start = tokens.get(name_tok)?.byte_offset as usize;
            (start, start + field_name.len())
        }
    };
    // The official `_deleteMembers` runs over member indices: a contiguous
    // removed run at index 0 deletes `[members[0].start, members[upper+1].start)`
    // — or whole lines when the run swallows every member — and any other
    // run deletes `[prevMember.end, lastRemoved.end)`; getter and setter
    // group under `IndexRange.contiguousSubRanges`.
    let mut removed = vec![getter_idx, setter_idx];
    removed.sort_unstable();
    let mut groups: Vec<(usize, usize)> = Vec::new();
    for &idx in &removed {
        if let Some(last) = groups.last_mut()
            && idx == last.1 + 1
        {
            last.1 = idx;
            continue;
        }
        groups.push((idx, idx));
    }
    let mut spans = Vec::with_capacity(groups.len());
    for (lo_idx, hi_idx) in groups {
        let span = if lo_idx == 0 && hi_idx == members.len() - 1 {
            // Whole lines from the first to the last removed member.
            let start = line_start_before(text, member_start_byte(text, tokens, members[lo_idx].0));
            let mut end = member_end_byte(text, tokens, members[hi_idx].1 - 1);
            if let Some(rel) = text.get(end..).and_then(|t| t.find('\n')) {
                end += rel + 1;
            }
            (start, end)
        } else if lo_idx == 0 {
            (
                member_start_byte(text, tokens, members[lo_idx].0),
                member_start_byte(text, tokens, members[hi_idx + 1].0),
            )
        } else {
            (
                member_end_byte(text, tokens, members[lo_idx - 1].1 - 1),
                member_end_byte(text, tokens, members[hi_idx].1 - 1),
            )
        };
        spans.push(span);
    }
    let lo = spans.iter().map(|s| s.0).min()?.min(name_byte);
    let hi = spans.iter().map(|s| s.1).max()?.max(name_end);
    if !(lo <= name_byte && name_end <= hi) {
        return None;
    }
    // Rebuild `[lo, hi)`: the dropped spans leave, the field's `_name`
    // becomes `name`, and every other byte stays.
    let mut rebuilt = String::new();
    let mut at = lo;
    for &(ds, de) in &spans {
        if de <= at || ds >= hi {
            continue;
        }
        push_with_rename(&mut rebuilt, text, at..ds, name_byte, name_end, getter_name);
        at = de;
    }
    push_with_rename(&mut rebuilt, text, at..hi, name_byte, name_end, getter_name);
    let start16 = utf16_count(&text[..lo]);
    let len16 = utf16_count(&text[lo..hi]);
    Some((start16, len16, rebuilt))
}

/// Appends `text[range]` to `out`, replacing the `[name, name_end)` byte
/// span with `rename` when it lands inside.
fn push_with_rename(
    out: &mut String,
    text: &str,
    range: core::ops::Range<usize>,
    name: usize,
    name_end: usize,
    rename: &str,
) {
    if range.start <= name && name_end <= range.end {
        out.push_str(&text[range.start..name]);
        out.push_str(rename);
        out.push_str(&text[name_end..range.end]);
    } else {
        out.push_str(text.get(range).unwrap_or(""));
    }
}

/// Whether the member range carries keyword `kw` anywhere in it.
fn member_has_keyword(tokens: &TokenTable, member: (usize, usize), kw: Keyword) -> bool {
    (member.0..member.1).any(|i| kind_of(tokens, i) == Some(TokenKind::Keyword(kw)))
}

/// The declared name a `get`/`set`/method member carries — the identifier
/// immediately before its `(` parameter list or its `=>`/`{`/`;`
/// terminator.
fn member_name<'s>(tokens: &TokenTable, text: &'s str, member: (usize, usize)) -> Option<&'s str> {
    let (s, e) = member;
    for i in s..e {
        match kind_of(tokens, i) {
            Some(TokenKind::OpenParen) => {
                // The token right before `(` is the member name; a `get`/`set`
                // keyword may precede it (`set name(`), the type before that.
                let name = i.checked_sub(1)?;
                return if matches!(kind_of(tokens, name), Some(TokenKind::Identifier)) {
                    Some(tokens.lexeme(text, name))
                } else {
                    None
                };
            }
            Some(TokenKind::Function | TokenKind::Semicolon | TokenKind::OpenCurly) => {
                // `get name =>`, `get name {`, `type name;` — the identifier
                // right before the terminator is the name.
                let mut name = i.checked_sub(1)?;
                while name > s
                    && matches!(
                        kind_of(tokens, name),
                        Some(
                            TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly
                        )
                    )
                {
                    name = name.checked_sub(1)?;
                }
                return if matches!(kind_of(tokens, name), Some(TokenKind::Identifier)) {
                    Some(tokens.lexeme(text, name))
                } else {
                    None
                };
            }
            _ => {}
        }
    }
    None
}

/// The `_name` token of a declaring `final`/`var` parameter in the
/// primary-constructor head of the class whose body opens at `body_open`
/// — `class C(final int _x)` / `class C<T>.name(var _x)`. The parameter
/// list is the `(` group after the class name's `<T>`/`.name` tail; a
/// parameter declares when its segment carries `final`/`var` (upstream
/// `isDeclaringParameter` — the `finalOrVarKeyword` read).
fn primary_ctor_declaring_param(
    tokens: &TokenTable,
    text: &str,
    body_open: usize,
    name: &str,
) -> Option<usize> {
    // The `class` keyword heading the body (modifiers ride before it).
    let mut head = body_open;
    let class_kw = loop {
        head = head.checked_sub(1)?;
        match kind_of(tokens, head)? {
            TokenKind::Keyword(Keyword::Class) => break head,
            TokenKind::Semicolon | TokenKind::CloseCurly | TokenKind::OpenCurly => return None,
            _ => {}
        }
    };
    // After `class`: the name, then an optional `<T>` type-parameter group
    // and `.name` ctor selector, then the parameter list's `(`.
    let mut i = class_kw + 1;
    if !matches!(kind_of(tokens, i), Some(TokenKind::Identifier)) {
        return None;
    }
    i += 1;
    if kind_of(tokens, i) == Some(TokenKind::Lt) {
        i = angle_group_end(tokens, i)? + 1;
    }
    if kind_of(tokens, i) == Some(TokenKind::Period) {
        i += 1;
        if !matches!(
            kind_of(tokens, i),
            Some(TokenKind::Identifier | TokenKind::Keyword(Keyword::New))
        ) {
            return None;
        }
        i += 1;
    }
    if kind_of(tokens, i) != Some(TokenKind::OpenParen) {
        return None;
    }
    let group_close = tokens.matching_end(i)?;
    if group_close > body_open {
        return None;
    }
    let mut seg_start = i + 1;
    let mut depth = 0u32;
    let mut cursor = i + 1;
    while cursor <= group_close {
        let kind = if cursor == group_close {
            // The group's own `)` ends the last segment.
            Some(TokenKind::Comma)
        } else {
            kind_of(tokens, cursor)
        };
        match kind? {
            TokenKind::Comma | TokenKind::Semicolon if depth == 0 => {
                // Segment `[seg_start, cursor)` — a `final`/`var` keyword
                // makes it a declaring parameter (upstream
                // `isDeclaringParameter`); its `_name` identifier is the
                // token to rename.
                let mut declares = false;
                for j in seg_start..cursor {
                    match kind_of(tokens, j) {
                        Some(TokenKind::Keyword(Keyword::Final | Keyword::Var)) => {
                            declares = true;
                        }
                        Some(TokenKind::Identifier)
                            if declares && tokens.lexeme(text, j) == name =>
                        {
                            return Some(j);
                        }
                        _ => {}
                    }
                }
                seg_start = cursor + 1;
            }
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly | TokenKind::Lt => {
                depth += 1
            }
            TokenKind::CloseParen
            | TokenKind::CloseSquare
            | TokenKind::CloseCurly
            | TokenKind::Gt => {
                depth = depth.checked_sub(1)?;
            }
            _ => {}
        }
        cursor += 1;
    }
    None
}
/// official `member is FieldDeclaration` + `member.fields.variables` scan
/// (upstream Dart SDK source,
/// pkg/analysis_server/lib/src/services/correction/dart/make_field_public.dart:61-67).
/// The token face of a field declaration: the member ends at a depth-0
/// `;` with no `(`/`{`/`=>` ahead of the declared name — a method's
/// `_x = 1;` body or `void m() => _x;` never qualifies.
fn member_declares_name(
    tokens: &TokenTable,
    text: &str,
    member: (usize, usize),
    name: &str,
) -> bool {
    let (s, e) = member;
    // A field declaration's last token is the `;` ending it.
    if kind_of(tokens, e - 1) != Some(TokenKind::Semicolon) {
        return false;
    }
    let mut depth = 0u32;
    for i in s..e {
        match kind_of(tokens, i) {
            Some(TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::Lt) => depth += 1,
            Some(TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::Gt) => {
                depth = depth.saturating_sub(1);
            }
            // A `(`/`{`/`=>` at depth 0 before the name is a parameter
            // list, a body, or an arrow — never a field declaration.
            Some(TokenKind::OpenCurly | TokenKind::Function) if depth == 0 => return false,
            Some(TokenKind::Identifier) if depth == 0 && tokens.lexeme(text, i) == name => {
                return matches!(
                    kind_of(tokens, i + 1),
                    Some(TokenKind::Semicolon | TokenKind::Eq | TokenKind::Comma)
                );
            }
            _ => {}
        }
    }
    false
}

/// `cascade_invocations`: the reported run of statements on one receiver
/// folds into cascades — `x = C(); x.f(); x.g();` becomes
/// `x = C()..f()..g();` (the official `ConvertToCascade`: each later
/// statement's `target`/`operator` collapses to `..`, the previous
/// statement's `;` drops, and an assignment's initializer wraps in parens
/// when it binds below postfix).
///
/// The report covers statements 2..n of the run; the producer also
/// touches statement 1 — the target's declaration or first use — which
/// the token walk recovers as the statement right before the span.
pub(crate) fn cascade_merge(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let (first, last) = hit_tokens(tokens, &input.range)?;
    // The reported statements: the `;`-terminated runs inside the span,
    // group interiors skipped (a lambda body's `;` never splits).
    let mut runs = Vec::new();
    let mut start = first;
    let mut index = first;
    while index <= last {
        match kind_of(tokens, index)? {
            TokenKind::OpenParen | TokenKind::OpenSquare | TokenKind::OpenCurly => {
                index = tokens.matching_end(index)?;
            }
            TokenKind::Semicolon => {
                runs.push((start, index));
                start = index + 1;
            }
            _ => {}
        }
        index += 1;
    }
    if runs.is_empty() {
        return None;
    }
    // The anchor statement — the one right before the report (the
    // producer's `statements[indexOf(firstCascadeStatement) - 1]`): the
    // token run ending at the `;`/`}`/`{`/`:` preceding the span.
    let mut boundary = first;
    let anchor_end = loop {
        match boundary.checked_sub(1).and_then(|p| kind_of(tokens, p)) {
            Some(TokenKind::Semicolon) => break boundary - 1,
            Some(TokenKind::OpenCurly | TokenKind::CloseCurly | TokenKind::Colon) | None => {
                return None;
            }
            _ => boundary -= 1,
        }
    };
    let mut anchor_start = anchor_end;
    // A `:` walking back is a boundary only as a label/case terminator — a
    // conditional's `:` pairs with a `?` earlier in the same statement.
    // Parked colons stack; each `?` pops its nearest pair, and any colon
    // left when the walk ends is the real boundary.
    let mut colons: Vec<usize> = Vec::new();
    while let Some(p) = anchor_start.checked_sub(1) {
        match kind_of(tokens, p)? {
            TokenKind::Semicolon | TokenKind::OpenCurly => break,
            // A `}`/`)`/`]` closing the anchor's tail (a lambda or
            // collection literal: `var f = () { … };`) jumps to its
            // matching open — the statement's real start sits earlier.
            close @ (TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly) => {
                anchor_start = matching_open(tokens, p, close)?;
            }
            TokenKind::Colon => {
                colons.push(p);
                anchor_start = p;
            }
            TokenKind::Question if !colons.is_empty() => {
                colons.pop();
                anchor_start = p;
            }
            _ => anchor_start = p,
        }
    }
    if let Some(&colon) = colons.last() {
        // The nearest unpaired `:` — the anchor statement begins after it.
        anchor_start = colon + 1;
    }
    // The anchor's own face: a `var x = …;`/`x = …;` declaration or
    // assignment keeps its text (its initializer may wrap in parens); an
    // expression statement `x.f();` collapses its `.` to `..`; a cascade
    // `x..f();` keeps. `switch`/`case` labels end at `:` — the boundary
    // walk already accepts it.
    let anchor_body = (anchor_start, anchor_end); // tokens [start, semi)
    let mut out = String::new();
    // The anchor text — `[anchor_start, anchor_end)` (excluding `;`).
    let a_s = tokens.get(anchor_body.0)?.byte_offset as usize;
    let a_e = token_end(tokens.get(anchor_body.1 - 1)?);
    let mut anchor_text = text.get(a_s..a_e)?.to_owned();
    // The initializer-parens arm: a `=` assignment/declaration whose RHS
    // binds below postfix wraps (`x = a ? b : c` → `x = (a ? b : c)`).
    if let Some(eq) = depth0_find(tokens, text, anchor_body.0, anchor_body.1, |kind, _| {
        kind == TokenKind::Eq
    }) {
        let rhs_s = eq + 1;
        let rhs_e = anchor_body.1;
        let low = rhs_s < rhs_e
            && (depth0_find(tokens, text, rhs_s, rhs_e, |kind, _| {
                matches!(
                    kind,
                    TokenKind::QuestionQuestion
                        | TokenKind::Question
                        | TokenKind::AmpersandAmpersand
                        | TokenKind::BarBar
                        | TokenKind::EqEq
                        | TokenKind::BangEq
                        | TokenKind::Lt
                        | TokenKind::Gt
                        | TokenKind::LtEq
                        | TokenKind::GtEq
                        | TokenKind::Ampersand
                        | TokenKind::Bar
                        | TokenKind::Caret
                        | TokenKind::Keyword(Keyword::As | Keyword::Is)
                )
            })
            .is_some()
                || matches!(
                    kind_of(tokens, rhs_s),
                    Some(TokenKind::Bang | TokenKind::Minus | TokenKind::Tilde)
                ));
        if low {
            let ps = tokens.get(rhs_s)?.byte_offset as usize - a_s;
            let pe = token_end(tokens.get(rhs_e - 1)?) - a_s;
            anchor_text = format!(
                "{}({}){}",
                &anchor_text[..ps],
                &anchor_text[ps..pe],
                &anchor_text[pe..]
            );
        }
        // The `x.f = v` lhs arm: a `PrefixedIdentifier` left side doubles
        // its `.` (the official `previousOperator` insertion for an
        // `ExpressionStatement` anchor — `x.f = 0; x.g = 1;` becomes
        // `x..f = 0..g = 1;`).
        if let Some(op) = cascade_operator(tokens, text, anchor_body.0, eq, true) {
            let dot = tokens.get(op)?.byte_offset as usize - a_s;
            anchor_text.insert(dot, '.');
        }
    } else if let Some(op) = cascade_operator(tokens, text, anchor_body.0, anchor_body.1, false) {
        // An expression-statement anchor (`x.f();`) doubles its operator.
        let dot = tokens.get(op)?.byte_offset as usize - a_s;
        anchor_text.insert(dot, '.');
    }
    out.push_str(&anchor_text);
    // Each later statement: the receiver text drops, the `.`/`?..`
    // operator doubles (`..`/`?..`), the previous `;` goes (the trivia
    // between it and the statement start survives — the official deletes
    // the `;` alone), and the selector tail (`f(args)` / `f = v`) stays.
    let mut prev_semi_end = token_end(tokens.get(anchor_body.1)?);
    for &(s, e) in &runs {
        let op = cascade_operator(tokens, text, s, e, false)?;
        // The trivia run between the previous `;` and this statement's
        // first token (`\n  `, comments) rides along.
        out.push_str(
            text.get(prev_semi_end..tokens.get(s)?.byte_offset as usize)
                .unwrap_or(""),
        );
        // The selector text: from the operator's end through the
        // statement's last real token.
        let op_end = token_end(tokens.get(op)?);
        let stmt_end = token_end(tokens.get(e - 1)?);
        let sel = text.get(op_end..stmt_end).unwrap_or("");
        match kind_of(tokens, op)? {
            TokenKind::Period | TokenKind::PeriodPeriod => out.push_str(".."),
            TokenKind::QuestionPeriodPeriod => out.push_str("?.."),
            _ => return None,
        }
        out.push_str(sel);
        prev_semi_end = token_end(tokens.get(e)?);
    }
    out.push(';');
    let start16 = tokens.get(anchor_start)?.utf16_offset;
    let end16 = utf16_end(tokens, text, runs.last()?.1)?;
    Some((start16, end16.checked_sub(start16)?, out))
}

/// The `.`-family token splitting a statement `recv.sel…` into receiver
/// and selector — the `.`/`..`/`?..` immediately before the selector
/// identifier: for an invocation the identifier right before the
/// outermost `(`; for an assignment the identifier right before `=`;
/// for a bare run (`bare_lhs_ok` — the anchor's `x.f = v` left side) the
/// run's last identifier.
fn cascade_operator(
    tokens: &TokenTable,
    text: &str,
    s: usize,
    e: usize,
    bare_lhs_ok: bool,
) -> Option<usize> {
    if s >= e {
        return None;
    }
    // The statement's last token (before `;` — `e` is the `;` index).
    let last = e.checked_sub(1)?;
    let selector_name;
    match kind_of(tokens, last)? {
        TokenKind::CloseParen | TokenKind::CloseSquare | TokenKind::CloseCurly => {
            // `recv.sel(args)` / `recv[…].sel(…)` — the selector name is
            // the identifier right before the matching open of the last
            // group (through `args`), with generic `<…>` tails skipped.
            let close_kind = kind_of(tokens, last)?;
            let open = matching_open(tokens, last, close_kind)?;
            let mut name = open.checked_sub(1)?;
            if kind_of(tokens, name) == Some(TokenKind::Gt) {
                let lt = angle_group_start(tokens, name)?;
                name = lt.checked_sub(1)?;
            }
            selector_name = name;
        }
        _ => {
            // `recv.sel = v` / `recv.sel` — scan back over the `=` tail to
            // the selector name: the last identifier before a top-level
            // `=` (or the last identifier when none stands).
            let mut name;
            if let Some(eq) = depth0_find(tokens, text, s, e, |kind, _| kind == TokenKind::Eq) {
                // The lhs is `[s, eq)`; the selector name is its last
                // identifier.
                let mut i = eq;
                loop {
                    i = i.checked_sub(1)?;
                    if i < s {
                        return None;
                    }
                    if matches!(kind_of(tokens, i), Some(TokenKind::Identifier)) {
                        name = i;
                        break;
                    }
                    match kind_of(tokens, i)? {
                        TokenKind::CloseParen | TokenKind::CloseSquare => {
                            let open = matching_open(tokens, i, kind_of(tokens, i)?)?;
                            i = open;
                        }
                        _ => {}
                    }
                    if i <= s {
                        return None;
                    }
                }
            } else {
                // A bare `recv.sel` run — either a `PropertyAccess`
                // statement (refused: the official `_getTargetAndOperator`
                // only takes invocations, cascade sections and
                // `prefixed = v` assignments) or a `recv.sel` left side
                // whose `=` the caller clipped at `e` (the anchor's
                // `PrefixedIdentifier` arm — the last identifier *is* the
                // selector).
                if !bare_lhs_ok {
                    return None;
                }
                name = last;
                while !matches!(kind_of(tokens, name), Some(TokenKind::Identifier)) {
                    name = name.checked_sub(1)?;
                    if name < s {
                        return None;
                    }
                }
            }
            selector_name = name;
        }
    }
    // The operator is the `.`-family token right before the selector name.
    let op = selector_name.checked_sub(1)?;
    match kind_of(tokens, op)? {
        TokenKind::Period | TokenKind::PeriodPeriod | TokenKind::QuestionPeriodPeriod => {}
        _ => return None,
    }
    // The receiver `[s, op)` must stand as a bare simple identifier —
    // the upstream gates: `MethodInvocation.target` is a
    // `SimpleIdentifier` for the lint to have fired, and the assignment
    // arm takes `lhs is PrefixedIdentifier` whose `prefix` is that
    // identifier.
    if op != s + 1 || kind_of(tokens, s)? != TokenKind::Identifier {
        return None;
    }
    Some(op)
}

/// `avoid_private_typedef_functions`: the private typedef folds into its
/// one use site — the official `InlineTypedef` deletes the typedef's line
/// and writes `R Function(params)` at the single `NamedType` reference.
/// The report spans the typedef's name; the single in-file use is located
/// as the lone `_Name` identifier outside the declaration (every such
/// token is a `NamedType` — a private typedef's name only ever reads in
/// type position). A zero- or multi-use file drops the fix, exactly the
/// official's `finder.count != 1` refusal.
pub(crate) fn inline_typedef(input: &FixInput<'_>) -> Option<(u32, u32, String)> {
    let tokens = input.tokens?;
    let text = input.text;
    let name_idx = token_starting_at(tokens, input.range.start)?;
    let name = tokens.lexeme(text, name_idx);
    if !name.starts_with('_') {
        return None;
    }
    // The typedef declaration: `typedef R _F(params);` (FunctionTypeAlias)
    // or `typedef _F = R Function(params);` (GenericTypeAlias without its
    // own type params). Locate the `typedef` keyword behind the name.
    let mut head = name_idx;
    let typedef_kw = loop {
        match kind_of(tokens, head)? {
            TokenKind::Keyword(Keyword::Typedef) => break head,
            TokenKind::Semicolon | TokenKind::OpenCurly | TokenKind::CloseCurly => return None,
            _ => {
                head = head.checked_sub(1)?;
            }
        }
    };
    // The declaration's end: its `;`.
    let decl_end = depth0_find(tokens, text, typedef_kw, tokens.len(), |kind, _| {
        kind == TokenKind::Semicolon
    })?;
    // The replacement text: `R Function<…>(params)` — the pieces read off
    // the two syntax faces.
    let (ret, tparams, params) = typedef_signature(tokens, text, typedef_kw, name_idx, decl_end)?;
    // The lone in-file use: an identifier `_F` outside `[typedef_kw,
    // decl_end]`, not preceded by `.` (a prefixed `p._F` names another
    // declaration). Only `NamedType` positions count (the official
    // `_ReferenceFinder` visits `NamedType` alone — upstream Dart SDK
    // source, pkg/analysis_server/lib/src/services/correction/dart/
    // inline_typedef.dart:145-161): `show`/`hide` combinator names,
    // `@` annotation heads and string-interpolation identifiers never
    // resolve to the typedef.
    let mut uses = Vec::new();
    // Open `${` interpolation group ends (they nest); a token inside one
    // is string content, not a `NamedType`.
    let mut interp_ends: Vec<usize> = Vec::new();
    for i in 0..tokens.len() {
        while interp_ends.last().is_some_and(|&end| i >= end) {
            interp_ends.pop();
        }
        match kind_of(tokens, i) {
            Some(TokenKind::StringInterpolationExpression) => {
                if let Some(end) = tokens.matching_end(i) {
                    interp_ends.push(end);
                }
                continue;
            }
            _ => {}
        }
        if !interp_ends.is_empty() || (i >= typedef_kw && i <= decl_end) {
            continue;
        }
        if matches!(kind_of(tokens, i), Some(TokenKind::Identifier))
            && tokens.lexeme(text, i) == name
            && !matches!(kind_of(tokens, i.wrapping_sub(1)), Some(TokenKind::Period))
            && (i == 0 || !matches!(kind_of(tokens, i - 1), Some(TokenKind::Period)))
            && (i == 0
                || !matches!(
                    kind_of(tokens, i - 1),
                    Some(TokenKind::At | TokenKind::StringInterpolationIdentifier)
                ))
            && !in_combinator_list(tokens, i)
        {
            uses.push(i);
        }
    }
    if uses.len() != 1 {
        return None;
    }
    let use_idx = uses[0];
    // The use's full span covers a trailing `<typeArgs>` when written.
    let mut use_end_idx = use_idx;
    if kind_of(tokens, use_idx + 1) == Some(TokenKind::Lt) {
        // `F<…>` — the angle group ends the NamedType.
        let gt = angle_group_end(tokens, use_idx + 1)?;
        use_end_idx = gt;
    }
    let mut replacement = String::new();
    if let Some(r) = ret {
        replacement.push_str(&r);
        replacement.push(' ');
    }
    replacement.push_str("Function");
    if let Some(t) = tparams {
        replacement.push_str(&t);
    }
    replacement.push('(');
    replacement.push_str(&params);
    replacement.push(')');
    // The two sites: declaration span and use span — one contiguous
    // replacement over `[min, max)` splicing both (the declaration's whole
    // line block drops; the use becomes the Function type).
    let decl_start_byte = {
        // line start of the `typedef` keyword
        let kw_byte = tokens.get(typedef_kw)?.byte_offset as usize;
        text[..kw_byte].rfind('\n').map_or(0, |i| i + 1)
    };
    let decl_end_byte = {
        let semi_end = token_end(tokens.get(decl_end)?);
        text[semi_end..]
            .find('\n')
            .map_or(text.len(), |i| semi_end + i + 1)
    };
    let use_start = tokens.get(use_idx)?.byte_offset as usize;
    let use_end = token_end(tokens.get(use_end_idx)?);
    if decl_start_byte < use_start {
        // `[decl_line_start, use_end)` → `"" + middle + replacement`
        let middle = text.get(decl_end_byte..use_start).unwrap_or("");
        let start16 = utf16_count(&text[..decl_start_byte]);
        let end16 = utf16_count(&text[..use_end]);
        return Some((
            start16,
            end16.checked_sub(start16)?,
            format!("{middle}{replacement}"),
        ));
    }
    if use_end < decl_start_byte {
        let middle = text.get(use_end..decl_start_byte).unwrap_or("");
        let start16 = utf16_count(&text[..use_start]);
        let decl_line_end16 = utf16_count(&text[..decl_end_byte]);
        return Some((
            start16,
            decl_line_end16.checked_sub(start16)?,
            format!("{replacement}{middle}"),
        ));
    }
    None
}

/// Whether the identifier at `i` sits in an `import`/`export` `show`/`hide`
/// combinator list — the walk back over `Identifier`/`Comma` lands on the
/// combinator keyword (a `NamedType` never reads there). The keyword only
/// counts when it trails the directive head — a string literal (the URI)
/// or an `as`/`deferred` prefix — so `f(show, x)` argument lists never
/// match.
fn in_combinator_list(tokens: &TokenTable, mut i: usize) -> bool {
    loop {
        match i.checked_sub(1).and_then(|p| kind_of(tokens, p)) {
            Some(TokenKind::Identifier | TokenKind::Comma) => i -= 1,
            Some(TokenKind::Keyword(Keyword::Show | Keyword::Hide)) => {
                return i
                    .checked_sub(2)
                    .and_then(|p| kind_of(tokens, p))
                    .is_some_and(|kind| {
                        matches!(
                            kind,
                            TokenKind::String
                                | TokenKind::Identifier
                                | TokenKind::Keyword(Keyword::As | Keyword::Deferred)
                        )
                    });
            }
            _ => return false,
        }
    }
}

/// The typedef declaration's `R Function(params)` pieces over
/// `[typedef_kw, decl_end)`: (return type text, type-parameter list text,
/// parameter list text) — the two syntax faces (`typedef R F(params);`
/// and `typedef F = R Function(params);`).
fn typedef_signature(
    tokens: &TokenTable,
    text: &str,
    typedef_kw: usize,
    name_idx: usize,
    decl_end: usize,
) -> Option<(Option<String>, Option<String>, String)> {
    // GenericTypeAlias face: `typedef F = R Function(params);` — the `=`
    // after the name leads the aliased type.
    if let Some(eq) = depth0_find(tokens, text, name_idx, decl_end, |kind, _| {
        kind == TokenKind::Eq
    }) {
        // A `typedef F<T> = …` face is refused upstream (typeParameters on
        // the typedef itself).
        if kind_of(tokens, name_idx + 1) == Some(TokenKind::Lt) {
            return None;
        }
        // `R Function(params)` — find `Function` and its `(`.
        let mut i = eq + 1;
        let mut ret = None;
        if !word_at(tokens, text, i, "Function") {
            // collect the return type up to `Function`.
            let mut j = i;
            while j < decl_end && !word_at(tokens, text, j, "Function") {
                j += 1;
            }
            ret = Some(token_text(tokens, text, i..j)?);
            i = j;
        }
        if !word_at(tokens, text, i, "Function") {
            return None;
        }
        let mut k = i + 1;
        // `<T>` after `Function`.
        let mut tparams = None;
        if kind_of(tokens, k) == Some(TokenKind::Lt) {
            let gt = angle_group_end(tokens, k)?;
            tparams = Some(token_text(tokens, text, k..gt + 1)?);
            k = gt + 1;
        }
        if kind_of(tokens, k) != Some(TokenKind::OpenParen) {
            return None;
        }
        let cp = tokens.matching_end(k)?;
        let params = params_text(tokens, text, k + 1..cp)?;
        return Some((ret, tparams, params));
    }
    // FunctionTypeAlias face: `typedef R? F(params);` — return type is
    // `[typedef_kw+1, name_idx)`, params the group after the name.
    let ret = {
        let t = token_text(tokens, text, typedef_kw + 1..name_idx)?
            .trim()
            .to_owned();
        (!t.is_empty()).then_some(t)
    };
    // `<T>` on the typedef name itself.
    let mut k = name_idx + 1;
    let mut tparams = None;
    if kind_of(tokens, k) == Some(TokenKind::Lt) {
        let gt = angle_group_end(tokens, k)?;
        tparams = Some(token_text(tokens, text, k..gt + 1)?);
        k = gt + 1;
    }
    if kind_of(tokens, k) != Some(TokenKind::OpenParen) {
        return None;
    }
    let cp = tokens.matching_end(k)?;
    let params = params_text(tokens, text, k + 1..cp)?;
    Some((ret, tparams, params))
}

/// The parameter-list interior text — verbatim except a trailing comma,
/// which the official parameter-by-parameter rebuild drops.
fn params_text(tokens: &TokenTable, text: &str, range: core::ops::Range<usize>) -> Option<String> {
    let mut end = range.end;
    if end > range.start && kind_of(tokens, end - 1)? == TokenKind::Comma {
        end -= 1;
    }
    token_text(tokens, text, range.start..end).map(|s| s.trim().to_owned())
}

// ---------------------------------------------------------------------------
// Ignore-diagnostic fixes
//
// The three text-surgery producers the official registry registers for
// every diagnostic (upstream Dart SDK source, pkg/analysis_server_plugin,
// ignore_diagnostic.dart): `// ignore:` on the line before the hit,
// `// ignore_for_file:` beside the file's header, and an
// `analyzer: errors: <code>: ignore` entry in the governing
// analysis_options.yaml. Each offered row is an anchored insertion (or
// options-file edit) the caller can apply like any other edit.
// ---------------------------------------------------------------------------

/// The `// ignore: <code>` row for the diagnostic at `range`: spliced
/// into the previous line's ignore comment when one is there (the new
/// code first, the official insertion point), else inserted above the
/// hit's line at the line's own indentation. The first line inserts at
/// the file head.
pub fn ignore_line_fix(
    code: &'static str,
    range: core::ops::Range<u32>,
    text: &str,
    lines: &LineIndex,
) -> Option<RuleFix> {
    let (line, _) = lines.line_col_utf16(text, range.start);
    let starts = byte_line_starts(text);
    let index = line as usize - 1; // 0-based; the report line always exists
    let comment = format!("// ignore: {code}");
    let (at, insertion) = if index == 0 {
        (0, format!("{comment}\n"))
    } else if index < starts.len() {
        let prev_start = starts[index - 1];
        let line_start = starts[index];
        let prev_line = text.get(prev_start..line_start)?;
        if is_ignore_comment(prev_line.trim_start()) {
            let colon = prev_line.find(':')?;
            (prev_start + colon + 1, format!(" {code},"))
        } else {
            (
                line_start,
                format!("{}{comment}\n", line_indent(text, line_start)),
            )
        }
    } else {
        return None;
    };
    let offset = u32::try_from(utf16_count(&text[..at])).ok()?;
    Some(RuleFix {
        rule: code,
        message: format!("Ignore '{code}' for this line"),
        source: BUILTIN_IGNORE_SOURCE,
        edit: anchored_edit(text, lines, offset, 0, &insertion),
    })
}

/// The `// ignore_for_file: <code>` row: spliced into an existing
/// `ignore_for_file` comment in the leading region (the new code first),
/// else inserted after the last blank line of the header (or before the
/// first code line, its attached doc comments and annotations included)
/// — the official `IgnoreDiagnosticInFile` walk over the line stream.
pub fn ignore_file_fix(code: &'static str, text: &str, lines: &LineIndex) -> Option<RuleFix> {
    let starts = byte_line_starts(text);
    let comment = format!("// ignore_for_file: {code}");
    enum Spot {
        Splice(usize),
        Line {
            at: usize,
            before: bool,
            after: bool,
        },
    }
    let spot = if starts.len() == 1 {
        Spot::Line {
            at: 0,
            before: false,
            after: true,
        }
    } else {
        let mut last_blank: Option<usize> = None;
        let mut walked: Option<usize> = None;
        let mut found: Option<Spot> = None;
        for index in 0..starts.len() - 1 {
            let line_start = starts[index];
            let line_text = text.get(line_start..starts[index + 1])?;
            walked = Some(line_start);
            let trimmed = line_text.trim();
            if is_ignore_for_file_comment(trimmed) {
                let colon = line_text.find(':')?;
                found = Some(Spot::Splice(line_start + colon + 1));
                break;
            }
            if trimmed.is_empty() {
                last_blank = Some(line_start);
            } else if trimmed.starts_with("#!") || trimmed.starts_with("//") {
                // Header comments ride above the insertion point.
            } else {
                // First code line: its attached doc comments and
                // annotations precede the insertion (the official
                // `documentationComment ?? node` face).
                let mut at = line_start;
                let mut back = index;
                while back > 0 {
                    let prev = text.get(starts[back - 1]..starts[back])?.trim_start();
                    if prev.starts_with("///") || prev.starts_with("/**") || prev.starts_with('@') {
                        at = starts[back - 1];
                        back -= 1;
                    } else {
                        break;
                    }
                }
                found = Some(Spot::Line {
                    at,
                    before: false,
                    after: true,
                });
                break;
            }
        }
        match found {
            Some(spot) => spot,
            None => match last_blank {
                Some(blank) => Spot::Line {
                    at: blank,
                    before: true,
                    after: false,
                },
                None => Spot::Line {
                    at: walked.unwrap_or(0),
                    before: false,
                    after: true,
                },
            },
        }
    };
    let (at, insertion) = match spot {
        Spot::Splice(at) => (at, format!(" {code},")),
        Spot::Line { at, before, after } => {
            let mut insertion = String::new();
            if before {
                insertion.push('\n');
            }
            insertion.push_str(line_indent(text, at));
            insertion.push_str(&comment);
            insertion.push('\n');
            if after {
                insertion.push('\n');
            }
            (at, insertion)
        }
    };
    let offset = u32::try_from(utf16_count(&text[..at])).ok()?;
    Some(RuleFix {
        rule: code,
        message: format!("Ignore '{code}' for the whole file"),
        source: BUILTIN_IGNORE_SOURCE,
        edit: anchored_edit(text, lines, offset, 0, &insertion),
    })
}

/// The line-start byte offsets of `text` (the last line carries its start
/// whether or not a terminator closes the file).
fn byte_line_starts(text: &str) -> Vec<usize> {
    let mut starts = vec![0usize];
    for (index, byte) in text.bytes().enumerate() {
        if byte == b'\n' {
            starts.push(index + 1);
        }
    }
    starts
}

/// The whitespace run opening the line containing `at` (the official
/// `linePrefix` face — the line's own indentation, not the text before
/// `at`).
fn line_indent(text: &str, at: usize) -> &str {
    let line_start = text[..at].rfind('\n').map_or(0, |i| i + 1);
    let line = &text[line_start..];
    let end = line
        .find(|c: char| !matches!(c, ' ' | '\t'))
        .unwrap_or(line.len());
    &line[..end]
}

/// Whether the trimmed line is an ignore comment (`//` — more slashes
/// allowed — then whitespace, then `ignore:`; the official
/// `IgnoreInfo.isIgnoreComment` shape).
fn is_ignore_comment(trimmed: &str) -> bool {
    let rest = trimmed
        .trim_start_matches('/')
        .trim_start_matches([' ', '\t']);
    trimmed.starts_with("//") && rest.starts_with("ignore:")
}

/// Whether the trimmed line is an `ignore_for_file` comment (the official
/// `IgnoreInfo.isIgnoreForFileComment` shape — exactly two slashes).
fn is_ignore_for_file_comment(trimmed: &str) -> bool {
    trimmed.starts_with("//")
        && trimmed[2..]
            .trim_start_matches([' ', '\t'])
            .starts_with("ignore_for_file:")
}

/// The analysis-options face of the ignore trio: the edit (UTF-16
/// offset/length/replacement) that lands `analyzer: errors: <code>:
/// ignore` in `text`, the official `IgnoreDiagnosticInAnalysisOptionsFile`
/// shapes — a root mapping grows the missing `analyzer`/`errors` section
/// at its block end with the block's own indentation, an existing
/// `errors` mapping grows or re-spells the code key, a non-mapping
/// document is replaced whole, and anything the surgery cannot prove
/// (malformed YAML, a non-mapping `analyzer` or `errors`) drops.
pub fn ignore_options_edit(code: &str, text: &str) -> Option<(u32, u32, String)> {
    let entry = format!("{code}: ignore");
    let Ok(Yaml::Mapping(root)) = serde_yaml::from_str::<Yaml>(text) else {
        // The official replaces the non-mapping document whole.
        return Some((
            0,
            utf16_count(text),
            format!("analyzer:\n  errors:\n    {entry}\n"),
        ));
    };
    match root.get("analyzer") {
        None => {
            let mut insertion = String::new();
            if !text.is_empty() && !text.ends_with('\n') {
                insertion.push('\n');
            }
            insertion.push_str("analyzer:\n  errors:\n    ");
            insertion.push_str(&entry);
            insertion.push('\n');
            Some((utf16_count(text), 0, insertion))
        }
        Some(analyzer) if matches!(analyzer, Yaml::Mapping(_)) => {
            match analyzer.get("errors") {
                None => {
                    let (key_line, _) = yaml_key_line(text, "analyzer:", 0, text.len())?;
                    let (at, child_indent) = yaml_block_end(text, key_line, 0);
                    let indent = " ".repeat(child_indent);
                    Some((
                        u32::try_from(utf16_count(&text[..at])).ok()?,
                        0,
                        format!("{indent}errors:\n{indent}  {entry}\n"),
                    ))
                }
                Some(errors) if matches!(errors, Yaml::Mapping(_)) => {
                    let (key_line, _) = yaml_key_line(text, "analyzer:", 0, text.len())?;
                    let (_, child_indent) = yaml_block_end(text, key_line, 0);
                    let (errors_line, errors_indent) =
                        yaml_key_line(text, "errors:", child_indent, text.len())?;
                    let (errors_end, code_indent) =
                        yaml_block_end(text, errors_line, errors_indent);
                    // An existing code key re-spells its value in place; a
                    // missing one appends to the errors block.
                    let existing =
                        yaml_key_line(text, &format!("{code}:"), code_indent, errors_end)
                            .map(|(at, _)| at);
                    if let Some(at) = existing {
                        let line_end = text[at..].find('\n').map_or(text.len(), |i| at + i);
                        let colon = text[at..line_end].find(':')?;
                        return Some((
                            u32::try_from(utf16_count(&text[..at + colon + 1])).ok()?,
                            u32::try_from(utf16_count(&text[at + colon + 1..line_end])).ok()?,
                            " ignore".to_owned(),
                        ));
                    }
                    let indent = " ".repeat(code_indent);
                    Some((
                        u32::try_from(utf16_count(&text[..errors_end])).ok()?,
                        0,
                        format!("{indent}{entry}\n"),
                    ))
                }
                Some(_) => None,
            }
        }
        Some(_) => None,
    }
}

/// The byte offset and indentation of the first line under `until` whose
/// content starts with `key` at exactly `indent` columns (`None` when
/// absent).
fn yaml_key_line(text: &str, key: &str, indent: usize, until: usize) -> Option<(usize, usize)> {
    let mut cursor = 0usize;
    while cursor < until && cursor < text.len() {
        let line_end = text[cursor..].find('\n').map_or(text.len(), |i| cursor + i);
        let line_text = &text[cursor..line_end];
        let trimmed = line_text.trim_start();
        if line_text.len() - trimmed.len() == indent && trimmed.starts_with(key) {
            return Some((cursor, indent));
        }
        cursor = line_end + 1;
    }
    None
}

/// The insertion point of a child under the block opened at `key_line`
/// (indentation `key_indent`): the first non-blank, non-comment line at
/// or below the block's indentation ends the block; the block's existing
/// child indentation wins over the two-column default.
fn yaml_block_end(text: &str, key_line: usize, key_indent: usize) -> (usize, usize) {
    let mut at = text[key_line..]
        .find('\n')
        .map_or(text.len(), |i| key_line + i + 1);
    let mut child_indent = None;
    while at < text.len() {
        let line_end = text[at..].find('\n').map_or(text.len(), |i| at + i);
        let line_text = &text[at..line_end];
        let trimmed = line_text.trim_start();
        if !trimmed.is_empty() && !trimmed.starts_with('#') {
            let indent = line_text.len() - trimmed.len();
            if indent <= key_indent {
                break;
            }
            child_indent = child_indent.or(Some(indent));
        }
        at = line_end + 1;
        if line_end == text.len() {
            break;
        }
    }
    (at.min(text.len()), child_indent.unwrap_or(key_indent + 2))
}

// ---------------------------------------------------------------------------
// Document
// ---------------------------------------------------------------------------

/// The anchor object: `line`/`column` plus the context flanks; empty
/// context strings are omitted.
fn anchor_json(anchor: &Anchor) -> serde_json::Map<String, serde_json::Value> {
    let mut json = serde_json::Map::new();
    json.insert("line".into(), anchor.line.into());
    json.insert("column".into(), anchor.column.into());
    if !anchor.context_before.is_empty() {
        json.insert(
            "context_before".into(),
            anchor.context_before.clone().into(),
        );
    }
    if !anchor.context_after.is_empty() {
        json.insert("context_after".into(), anchor.context_after.clone().into());
    }
    json
}

/// One edit row at its locator floor: offset/length/replacement plus the
/// provenance tag — the red line the patch rows never drop (the minimal
/// tier trims prose and convenience, never location).
fn edit_floor(edit: &Edit, source: &str) -> serde_json::Map<String, serde_json::Value> {
    let mut row = serde_json::Map::new();
    row.insert("offset".into(), edit.offset.into());
    row.insert("length".into(), edit.length.into());
    row.insert("replacement".into(), edit.replacement.clone().into());
    row.insert("source".into(), source.into());
    row
}

/// The document for one file — `file`, `schema_version`, and the
/// `edits`: the built-in rows first, then each plugin change's edits
/// flattened in change order, every row carrying its provenance tag
/// (`builtin-lint`, or the plugin's manifest name). Empty context strings
/// are omitted; the anchor rides compact and full, the full tier
/// adds the row's human name (`rule` for built-in rows, `message` +
/// `priority` for plugin rows). Files without rows never enter a set.
/// This is the proposal shape — the dry-run and daemon faces answer it
/// verbatim; the apply run's record is [`patch_json_applied`].
#[must_use]
pub fn patch_json(set: &FileFixSet, verbosity: Verbosity) -> serde_json::Value {
    patch_document(set, verbosity, None)
}

/// The apply-mode record of [`patch_json`]: the same document with every
/// row tagged `"outcome": "applied" | "stale"` and the document-level
/// `"summary"` counts (`{"applied": N, "stale": M}`) — an all-stale run
/// writes nothing yet stays legible to the machine consumer without
/// scanning rows. `outcomes` is [`apply`]'s answer, one entry per row in
/// this document's row order.
#[must_use]
pub fn patch_json_applied(
    set: &FileFixSet,
    verbosity: Verbosity,
    outcomes: &[EditOutcome],
) -> serde_json::Value {
    patch_document(set, verbosity, Some(outcomes))
}

/// The shared builder behind both faces: `Some(outcomes)` renders the
/// apply record (per-row outcome + summary), `None` the bare proposal.
fn patch_document(
    set: &FileFixSet,
    verbosity: Verbosity,
    outcomes: Option<&[EditOutcome]>,
) -> serde_json::Value {
    let anchored = verbosity != Verbosity::Minimal;
    let mut labels = outcomes.iter().flat_map(|outcomes| outcomes.iter());
    let mut edits = Vec::new();
    for fix in &set.fixes {
        let mut row = edit_floor(&fix.edit, fix.source);
        if anchored {
            row.insert("anchor".into(), anchor_json(&fix.edit.anchor).into());
        }
        if verbosity == Verbosity::Full {
            row.insert("rule".into(), fix.rule.into());
            row.insert("message".into(), fix.message.clone().into());
        }
        if let Some(outcome) = labels.next() {
            row.insert("outcome".into(), outcome_label(outcome).into());
        }
        edits.push(serde_json::Value::Object(row));
    }
    for fix in &set.plugin {
        for edit in &fix.edits {
            let mut row = edit_floor(edit, &fix.plugin);
            if anchored {
                row.insert("anchor".into(), anchor_json(&edit.anchor).into());
            }
            if verbosity == Verbosity::Full {
                row.insert("message".into(), fix.message.clone().into());
                row.insert("priority".into(), fix.priority.into());
            }
            if let Some(outcome) = labels.next() {
                row.insert("outcome".into(), outcome_label(outcome).into());
            }
            edits.push(serde_json::Value::Object(row));
        }
    }
    let mut document = serde_json::json!({
        "file": set.path,
        "schema_version": SCHEMA_VERSION,
        "edits": edits,
    });
    if let Some(outcomes) = outcomes {
        let applied = outcomes
            .iter()
            .filter(|outcome| **outcome == EditOutcome::Applied)
            .count();
        let summary = serde_json::json!({ "applied": applied, "stale": outcomes.len() - applied });
        document
            .as_object_mut()
            .expect("patch document object")
            .insert("summary".into(), summary);
    }
    document
}

/// The outcome's JSON label.
fn outcome_label(outcome: &EditOutcome) -> &'static str {
    match outcome {
        EditOutcome::Applied => "applied",
        EditOutcome::Stale => "stale",
    }
}

/// The assists document for one file: the plugin changes in priority
/// order, each carrying its provenance (`source`), title, priority, and
/// anchored edits (the anchor drops at the minimal tier); the hosts that
/// could not serve the request answer in `errors` (omitted when empty).
///
/// # Panics
///
/// Panics if a constructed assist row is not a JSON object — impossible
/// by construction (`json!` builds the object literal); the expect pins
/// that invariant.
#[must_use]
pub fn assists_json(answer: &AssistAnswer, verbosity: Verbosity) -> serde_json::Value {
    let anchored = verbosity != Verbosity::Minimal;
    let assists: Vec<serde_json::Value> = answer
        .assists
        .iter()
        .map(|fix| {
            let edits: Vec<serde_json::Value> = fix
                .edits
                .iter()
                .map(|edit| {
                    let mut row = serde_json::Value::Object(edit_floor(edit, &fix.plugin));
                    if anchored {
                        row["anchor"] = anchor_json(&edit.anchor).into();
                    }
                    row
                })
                .collect();
            let mut row = serde_json::json!({
                "message": fix.message,
                "source": fix.plugin,
                "priority": fix.priority,
                "edits": edits,
            });
            if verbosity == Verbosity::Minimal {
                row.as_object_mut()
                    .expect("assists row object")
                    .remove("priority");
            }
            row
        })
        .collect();
    let mut document = serde_json::json!({
        "file": answer.file,
        "schema_version": SCHEMA_VERSION,
        "assists": assists,
    });
    if !answer.errors.is_empty() {
        document["errors"] = serde_json::json!(
            answer
                .errors
                .iter()
                .map(|error| serde_json::json!({
                    "plugin": error.plugin,
                    "message": error.message,
                }))
                .collect::<Vec<_>>()
        );
    }
    document
}

/// The provenance tag of every built-in assist row: the location-directed
/// producers below (the mirror of [`BUILTIN_SOURCE`] on the assist face;
/// plugin rows keep the plugin's manifest name).
pub const BUILTIN_ASSIST_SOURCE: &str = "builtin-assist";

/// The evidence one built-in assist producer reads: the file text, the
/// request selection (`[offset, offset + length)` in UTF-16), and the
/// parsed unit substrate (token stream plus the arena tree) built once per
/// request. Engine-free by charter: every guard verifies against the
/// text, the tokens, or the tree, and a shape that does not verify drops
/// the assist rather than approximating it.
pub struct AssistContext<'a> {
    pub text: &'a str,
    pub selection: core::ops::Range<u32>,
    pub tokens: &'a TokenTable,
    pub ast: &'a SyntaxTable,
    /// The unit's semantic query face — mounted by the resolved transport
    /// (the `run_with_semantics` arm; the rust-analyzer assist precedent
    /// of consuming sema), `None` under the engine-free dispatch. A
    /// producer reading it stays silent when unmounted: fewer assists,
    /// never an approximated one.
    pub semantics: Option<&'a dartq_semantic::Analysis<'a>>,
}

impl AssistContext<'_> {
    /// The mounted semantic face (the `Check::semantics` arm), `None`
    /// under the engine-free dispatch.
    #[must_use]
    pub fn semantics(&self) -> Option<&dartq_semantic::Analysis<'_>> {
        self.semantics
    }
}

/// One built-in assist producer: the upstream `dart.assist.*` kind id and
/// title, the upstream `DartAssistKindPriority` number (lower sorts first,
/// the [`PluginFix::priority`] convention), and the edit producer — `None`
/// drops the assist (the official self-guarding dispatch: every generator
/// runs at every request and declines where its covering node does not
/// apply; upstream Dart SDK source,
/// pkg/analysis_server_plugin/lib/src/correction/assist_processor.dart).
struct AssistSpec {
    kind: &'static str,
    title: &'static str,
    priority: i32,
    produce: fn(&AssistContext<'_>) -> Option<Vec<(u32, u32, String)>>,
}

/// The built-in producer table, in kind order (stable within a priority —
/// the dispatch's deterministic order). Each row's producer mirrors its
