    fn assist_surround_block_rows() {
        let source = "main() {\n  print(1);\n  print(2);\n}\n";
        assert_surround(
            source,
            "print(1)",
            "print(2);",
            "Surround with block",
            "main() {\n  {\n    print(1);\n    print(2);\n  }\n}\n",
        );
    }

